// Define the PacketInfo structure
typedef struct PacketInfo {
    void* payload;
    size_t length;
    struct PacketInfo* next;
} PacketInfo;

// Function to process a variable number of network packets
void process_packets(int num_packets, ...) {
    // Calculate total memory required (simplified for demonstration)
    size_t avg_payload_size = 1024; // Example average payload size
    size_t total_memory_required = num_packets * avg_payload_size;

    // Check for integer overflow
    if ((num_packets != 0) && (total_memory_required / num_packets != avg_payload_size)) {
        fprintf(stderr, "Integer overflow detected!\n");
        return;
    }

    // Allocate memory for the linked list of PacketInfo structures
    PacketInfo* head = NULL;
    PacketInfo** current = &head;

    va_list args;
    va_start(args, num_packets);
    for (int i = 0; i < num_packets; ++i) {
        size_t packet_length = va_arg(args, size_t);
        *current = (PacketInfo*)malloc(sizeof(PacketInfo));
        if (*current == NULL) {
            fprintf(stderr, "Memory allocation failed!\n");
            va_end(args);
            free_list(head);
            return;
        }
        (*current)->payload = malloc(packet_length);
        if ((*current)->payload == NULL) {
            fprintf(stderr, "Payload memory allocation failed!\n");
            free_packet((*current));
            va_end(args);
            free_list(head);
            return;
        }
        (*current)->length = packet_length;
        (*current)->next = NULL;
        current = &(*current)->next;
    }
    va_end(args);

    // Process packets (placeholder for actual processing logic)
    PacketInfo* ptr = head;
    while (ptr != NULL) {
        printf("Processing packet with payload of size %zu\n", ptr->length);
        // Actual packet processing code here
        free_packet(ptr);
        ptr = ptr->next;
    }

    // Free all allocated memory
    free_list(head);
}

// Helper function to free a single PacketInfo structure
void free_packet(PacketInfo* packet) {
    if (packet != NULL) {
        free(packet->payload);
        free(packet);
    }
}

// Helper function to free the entire linked list of PacketInfo structures
void free_list(PacketInfo* head) {
    while (head != NULL) {
        PacketInfo* temp = head;
        head = head->next;
        free_packet(temp);
    }
}
