#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define RECORD_COUNT 512

typedef struct {
    int value;
} record;

long* offsetArray;
int* keyArray;
record* records;
int usedKeys[MAX_KEYS];
int recordCount = 0;
pthread_mutex_t lock;

void initializeArrays() {
    pthread_mutex_init(&lock, NULL);
    offsetArray = (long*)malloc(MAX_KEYS * sizeof(long));
    keyArray = (int*)malloc(MAX_KEYS * sizeof(int));
    records = (record*)malloc(RECORD_COUNT * sizeof(record));

    if (!offsetArray || !keyArray || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        usedKeys[i] = 0;
    }
}

void generateUniqueKeys() {
    srand(time(NULL));
    int key;

    while (recordCount < RECORD_COUNT) {
        pthread_mutex_lock(&lock);
        key = rand() % MAX_KEYS;

        if (!usedKeys[key]) {
            usedKeys[key] = 1;
            keyArray[recordCount] = key;
            recordCount++;
        }
        pthread_mutex_unlock(&lock);
    }
}

void generateRecords() {
    for (int i = 0; i < RECORD_COUNT; i++) {
        records[i].value = rand() % 1000 + 1;
    }
}

void cleanUp() {
    free(offsetArray);
    free(keyArray);
    free(records);
    pthread_mutex_destroy(&lock);
}

int main() {
    initializeArrays();
    generateUniqueKeys();
    generateRecords();

    // Simulate usage
    for (int i = 0; i < RECORD_COUNT; i++) {
        printf("Record %d: Key=%d, Value=%d\n", i, keyArray[i], records[i].value);
    }

    cleanUp();
    return 0;
}
