#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    char *file_path;
    int line_count;
} FileData;

typedef struct {
    int total_lines;
    pthread_mutex_t lock;
} LineCounter;

void* process_file(void* arg) {
    FileData *data = (FileData*)arg;
    FILE *file = fopen(data->file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    int line_count = 0;
    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        line_count++;
    }
    fclose(file);

    LineCounter *counter = malloc(sizeof(LineCounter));
    counter->total_lines = line_count;
    pthread_mutex_init(&counter->lock, NULL);

    pthread_mutex_lock(&counter->lock);
    // Simulate aggregation logic
    printf("Processed %s: %d lines\n", data->file_path, line_count);
    // In a real scenario, you would update the global counter here.
    pthread_mutex_unlock(&counter->lock);

    free(counter);
    return NULL;
}

void process_directory(const char *dir_path, LineCounter *counter) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char path[MAX_LINE_LENGTH];
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);

        struct stat file_stat;
        if (stat(path, &file_stat) != 0) {
            perror("Failed to get file stats");
            continue;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            process_directory(path, counter);
        } else {
            FileData data = { .file_path = strdup(path) };
            pthread_t thread;
            pthread_create(&thread, NULL, process_file, &data);
            pthread_join(thread, NULL);
            free(data.file_path);
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    LineCounter counter = { .total_lines = 0 };
    pthread_mutex_init(&counter.lock, NULL);

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            // Display usage information and examples
            printf("Usage: %s [options] file1 file2 ... | -d directory\n", argv[0]);
            printf("Options:\n");
            printf("  --help    display this message\n");
            printf("  -d dir     specify a directory to recursively include all files\n");
            printf("  -o output  specify an output file to write the results in CSV format\n");
            printf("  -v         enable verbose mode for detailed progress logs\n");
            return 0;
        } else if (strcmp(argv[i], "-d") == 0) {
            i++;
            process_directory(argv[i], &counter);
        } else {
            FileData data = { .file_path = strdup(argv[i]) };
            pthread_t thread;
            pthread_create(&thread, NULL, process_file, &data);
            pthread_join(thread, NULL);
            free(data.file_path);
        }
    }

    printf("Total lines processed: %d\n", counter.total_lines);

    pthread_mutex_destroy(&counter.lock);
    return 0;
}
