int process_file(const char *input_file, const char *output_file, const char *rules, int use_chunks, size_t max_chunk_size) {
    FILE *in = fopen(input_file, "rb");
    if (!in) {
        perror("Failed to open input file");
        return -1;
    }

    FILE *out = fopen(output_file, "wb");
    if (!out) {
        perror("Failed to open output file");
        fclose(in);
        return -1;
    }

    char buffer[BUFFER_SIZE];
    size_t read_size;

    if (use_chunks) {
        while ((read_size = fread(buffer, 1, max_chunk_size < BUFFER_SIZE ? max_chunk_size : BUFFER_SIZE, in)) > 0) {
            apply_transformations(buffer, read_size);
            fwrite(buffer, 1, read_size, out);
        }
    } else {
        while ((read_size = fread(buffer, 1, sizeof(buffer), in)) > 0) {
            apply_transformations(buffer, read_size);
            fwrite(buffer, 1, read_size, out);
        }
    }

    if (ferror(in)) {
        perror("Error reading from input file");
    } else if (ferror(out)) {
        perror("Error writing to output file");
    } else {
        printf("File processed successfully\n");
    }

    fclose(in);
    fclose(out);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules> <use_chunks> <max_chunk_size>\n", argv[0]);
        return -1;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];
    const char *rules = argv[3];
    int use_chunks = atoi(argv[4]);
    size_t max_chunk_size = (size_t)atol(argv[5]);

    if (use_chunks && max_chunk_size == 0) {
        fprintf(stderr, "Max chunk size must be greater than 0 when using chunks\n");
        return -1;
    }

    if (process_file(input_file, output_file, rules, use_chunks, max_chunk_size) != 0) {
        return -1;
    }

    return 0;
}
