    while ((scanf("%d%c", &num, &ch)) == 2 && ch == ' ') {
        // Continue reading numbers separated by spaces
    }
    return num;
}

void printLargest(int *arr, size_t size) {
    if (size > 0) {
        int max = arr[0];
        for (size_t i = 1; i < size; i++) {
            if (arr[i] > max) {
                max = arr[i];
            }
        }
        printf("Largest integer: %d\n", max);
    } else {
        printf("No integers provided.\n");
    }
}

int main() {
    int *numbers = NULL;
    size_t count = 0;

    while (1) {
        int num = readInt();
        if (num == EOF) {
            break;
        }
        numbers = realloc(numbers, (count + 1) * sizeof(int));
        if (numbers == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            freeArray(numbers);
            exit(1);
        }
        numbers[count++] = num;
    }

    printLargest(numbers, count);
    freeArray(numbers);

    return 0;
}
