import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.MessageDigest;
import java.util.Base64;

public class PacketProcessor {

    private static final String CIPHER_ALGORITHM = "AES";
    private static final String SIGNATURE_ALGORITHM = "SHA-256";

    public byte[] processPacket(byte[] packet, byte[] key, byte[] iv, boolean useEncryption) {
        try {
            if (useEncryption) {
                return encrypt(packet, key, iv);
            } else {
                return packet;
            }
        } catch (Exception e) {
            // Handle encryption errors
            return null;
        }
    }

    private byte[] encrypt(byte[] data, byte[] keyBytes, byte[] ivBytes) throws Exception {
        SecretKeySpec secretKey = new SecretKeySpec(keyBytes, CIPHER_ALGORITHM);
        IvParameterSpec ivSpec = new IvParameterSpec(ivBytes);
        Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM + "/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivSpec);
        return cipher.doFinal(data);
    }

    public boolean verifyPacket(byte[] packet, byte[] key, byte[] signature) {
        try {
            MessageDigest digest = MessageDigest.getInstance(SIGNATURE_ALGORITHM);
            byte[] hash = digest.digest(packet);
            byte[] receivedHash = Base64.getDecoder().decode(signature);
            return MessageDigest.isEqual(hash, receivedHash);
        } catch (Exception e) {
            // Handle signature verification errors
            return false;
        }
    }

    public static void main(String[] args) {
        PacketProcessor processor = new PacketProcessor();
        byte[] key = "0123456789abcdef".getBytes(); // Example key
        byte[] iv = "fedcba9876543210".getBytes(); // Example IV
        boolean useEncryption = true;

        byte[] packet = "Hello, World!".getBytes();
        byte[] signature = processor.signPacket(packet, key);

        if (processor.verifyPacket(packet, key, signature)) {
            byte[] processedPacket = processor.processPacket(packet, key, iv, useEncryption);
            // Process the packet further
        } else {
            System.out.println("Invalid packet signature.");
        }
    }

    private String signPacket(byte[] data, byte[] keyBytes) throws Exception {
        MessageDigest digest = MessageDigest.getInstance(SIGNATURE_ALGORITHM);
        digest.update(data);
        byte[] hash = digest.digest(keyBytes);
        return Base64.getEncoder().encodeToString(hash);
    }
}
```

This code provides a basic implementation of the packet processing module, supporting encryption and cryptographic signature verification. The `processPacket` method handles the selection of an appropriate cipher mode based on the `useEncryption` flag. The `encrypt` method uses AES-CBC for encryption, and the `signPacket` method generates a cryptographic signature using SHA-256. The `verifyPacket` method checks the authenticity of the packet using the provided signature.

In the `main` method, an example usage is demonstrated, including signing and verifying a packet. You can extend this implementation to support additional cipher modes and fallback scenarios as needed.']

