import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class PokemonReportGenerator {

    private static final Map<String, String> cache = new HashMap<>();
    private static final ObjectMapper objectMapper = new ObjectMapper();

    public static String generateReport(Pokemon pokemon) throws IOException {
        String report = "";
        report += "Name: " + pokemon.getName() + "\n";
        report += "Type: " + getType(pokemon.getType()) + "\n";
        report += "Strengths: " + getStrengths(pokemon.getWeaknesses()) + "\n";
        report += "Weaknesses: " + getWeaknesses(pokemon.getWeaknesses()) + "\n";
        report += "Resistances: " + getResistances(pokemon.getResistances()) + "\n";
        return report;
    }

    private static String getType(String type) throws IOException {
        if (!cache.containsKey(type)) {
            String url = "https://api.example.com/types/" + type;
            JsonNode response = objectMapper.readTree(new URL(url).openStream());
            cache.put(type, response.get("description").asText());
        }
        return cache.get(type);
    }

    private static String getStrengths(String[] weaknesses) throws IOException {
        StringBuilder strengths = new StringBuilder();
        for (String weakness : weaknesses) {
            String url = "https://api.example.com/weaknesses/" + weakness;
            JsonNode response = objectMapper.readTree(new URL(url).openStream());
            strengths.append(response.get("strength").asText()).append(", ");
        }
        return strengths.toString().trim();
    }

    private static String getWeaknesses(String[] weaknesses) throws IOException {
        StringBuilder weaknessesList = new StringBuilder();
        for (String weakness : weaknesses) {
            weaknessesList.append(weakness).append(", ");
        }
        return weaknessesList.toString().trim();
    }

    private static String getResistances(String[] resistances) throws IOException {
        StringBuilder resistancesList = new StringBuilder();
        for (String resistance : resistances) {
            String url = "https://api.example.com/resistances/" + resistance;
            JsonNode response = objectMapper.readTree(new URL(url).openStream());
            resistancesList.append(response.get("description").asText()).append(", ");
        }
        return resistancesList.toString().trim();
    }

}
