}

void free_crypto_library(CryptoLibrary* lib) {
    if (lib->hashes != NULL) {
        free(lib->hashes);
    }
    if (lib->ciphers != NULL) {
        free(lib->ciphers);
    }
    // Free the handle if necessary
    if (lib->free_handle != NULL && lib->handle != NULL) {
        lib->free_handle(lib->handle);
    }
    free(lib);
}

void* get_function_pointer(CryptoLibrary* lib, const char* name, int is_hash) {
    if (is_hash) {
        for (size_t i = 0; i < lib->num_hashes; ++i) {
            if (strcmp(lib->hashes[i].name, name) == 0) {
                return lib->hashes[i].hash_func();
            }
        }
    } else {
        for (size_t i = 0; i < lib->num_ciphers; ++i) {
            if (strcmp(lib->ciphers[i].name, name) == 0) {
                return lib->ciphers[i].cipher_func;
            }
        }
    }
    return NULL;
}

int main() {
    CryptoLibrary* crypto_lib = load_crypto_library();

    // Example usage
    EVP_MD* md5_hash = (EVP_MD*)get_function_pointer(crypto_lib, "md5", 1);
    if (md5_hash != NULL) {
        printf("MD5 hash function available.\n");
    }

    free_crypto_library(crypto_lib);

    return 0;
}
