#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    sem_t *sem;
    char *filename;
} SemaphoreData;

SemaphoreData* create_semaphore(int initial_value) {
    SemaphoreData *data = (SemaphoreData *)malloc(sizeof(SemaphoreData));
    data->filename = tempnam(NULL, "sem_");
    if (!data->filename) {
        perror("Failed to create temporary file for semaphore state");
        free(data);
        return NULL;
    }

    int fd = open(data->filename, O_RDWR | O_CREAT | O_EXCL, 0664);
    if (fd == -1) {
        perror("Failed to open temporary file for semaphore state");
        free(data->filename);
        free(data);
        return NULL;
    }

    data->sem = sem_open(data->filename, O_RDWR, 0664, initial_value);
    if (data->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        close(fd);
        unlink(data->filename);
        free(data->filename);
        free(data);
        return NULL;
    }

    if (ftruncate(fd, sizeof(int)) != 0) {
        perror("Failed to truncate file for semaphore state");
        sem_close(data->sem);
        sem_unlink(data->filename);
        close(fd);
        unlink(data->filename);
        free(data->filename);
        free(data);
        return NULL;
    }

    int *value = (int *)mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (value == MAP_FAILED) {
        perror("Failed to map file for semaphore state");
        sem_close(data->sem);
        sem_unlink(data->filename);
        close(fd);
        unlink(data->filename);
        free(data->filename);
        free(data);
        return NULL;
    }

    *value = initial_value;

    if (munmap(value, sizeof(int)) != 0) {
        perror("Failed to unmap file for semaphore state");
        sem_close(data->sem);
        sem_unlink(data->filename);
        close(fd);
        unlink(data->filename);
        free(data->filename);
        free(data);
        return NULL;
    }

    close(fd);

    return data;
}

void destroy_semaphore(SemaphoreData *data) {
    munmap((int *)mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, open(data->filename, O_RDWR), 0), sizeof(int));
    sem_close(data->sem);
    sem_unlink(data->filename);
    unlink(data->filename);
    free(data->filename);
    free(data);
}

void wait_semaphore(SemaphoreData *data) {
    if (sem_wait(data->sem) == -1) {
        perror("Failed to wait on semaphore");
        exit(EXIT_FAILURE);
    }
}

void signal_semaphore(SemaphoreData *data) {
    if (sem_post(data->sem) == -1) {
        perror("Failed to post on semaphore");
        exit(EXIT_FAILURE);
    }
}
