#include <iostream>
#include <vector>
#include <string>
#include <mutex>

struct DataEntry {
    std::string key;
    int value;
};

class DataManager {
private:
    std::vector<DataEntry> data;
    mutable std::mutex mtx;

public:
    void addAfterFirst(const std::string& target, const DataEntry& newEntry) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(data.begin(), data.end(), [&target](const DataEntry& entry) {
            return entry.key == target;
        });

        if (it != data.end()) {
            data.insert(it + 1, newEntry);
        } else {
            data.push_back(newEntry);
        }
    }

    void removeByIndex(size_t index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index < data.size()) {
            data.erase(data.begin() + index);
        }
    }

    size_t getSize() const {
        return data.size();
    }

    DataEntry getAt(size_t index) const {
        if (index < data.size()) {
            return data[index];
        } else {
            throw std::out_of_range("Index out of range");
        }
    }
};

int main() {
    DataManager manager;
    manager.addAfterFirst("target", {"key1", 42});
    manager.addAfterFirst("target", {"key2", 99});
    manager.removeByIndex(0);

    for (size_t i = 0; i < manager.getSize(); ++i) {
        auto entry = manager.getAt(i);
        std::cout << "Key: " << entry.key << ", Value: " << entry.value << std::endl;
    }

    return 0;
}
