        : tokenLength(tokenLength), rng(std::random_device{}()), dist(0, 126) {}

    Token generateToken() {
        std::lock_guard<std::mutex> lock(mutex);
        Token token;
        for (size_t i = 0; i < tokenLength; ++i) {
            token += static_cast<char>(dist(rng));
        }
        return token;
    }

private:
