package main

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/go-chi/jwtauth/v4"
	"github.com/golang-jwt/jwt/v4"
	"github.com/hashicorp/memberlist"
)

type Resource struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Value int    `json:"value"`
}

var (
	db      = make(map[string]Resource)
	memberList *memberlist.Memberlist
	authTokenAuth = jwtauth.New("HS256", []byte("secret"))
)

func main() {
	r := chi.NewRouter()
	r.Use(middleware.Logger, middleware.Recoverer, jwtMiddleware)

	r.Put("/resources/{id}", updateResource)

	http.ListenAndServe(":8080", r)
}

func jwtMiddleware(next http.Handler) http.Handler {
	return jwtauth.Verifier(authTokenAuth, func(token *jwt.Token) (interface{}, error) {
		return []byte("secret"), nil
	})(next)
}

func updateResource(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	var updatedResource Resource
	err := json.NewDecoder(r.Body).Decode(&updatedResource)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	resource, exists := db[id]
	if !exists {
		http.Error(w, "Resource not found", http.StatusNotFound)
		return
	}

	if resource.ID != updatedResource.ID {
		http.Error(w, "Invalid ID in request body", http.StatusBadRequest)
		return
	}

	db[id] = updatedResource

	// Log operation using distributed tracing or logging library
	logOperation(r.Context(), id)

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(updatedResource)
}

func logOperation(ctx context.Context, resourceID string) {
	// Implement logging mechanism with user ID, resource ID, and timestamp
	userID := ctx.Value("user_id").(string)
	log.Printf("User %s updated resource %s at %s", userID, resourceID, time.Now())
}
