using System;
using System.IO;
using System.Xml.XPath;
using System.Threading;

public class XmlParser
{
    private static string xmlDirectory = null;
    private static readonly object directoryLock = new object();

    public static XPathNavigator ParseXml(string xpathExpression)
    {
        if (xmlDirectory == null)
        {
            lock (directoryLock)
            {
                if (xmlDirectory == null)
                {
                    xmlDirectory = Environment.GetEnvironmentVariable("XML_DIR");
                    if (string.IsNullOrEmpty(xmlDirectory))
                    {
                        string tempDir = Path.Combine(Path.GetTempPath(), "XmlParser_" + DateTime.Now.ToString("yyyyMMddHHmmss"));
                        Directory.CreateDirectory(tempDir);
                        Environment.SetEnvironmentVariable("XML_DIR", tempDir, EnvironmentVariableTarget.User);
                        xmlDirectory = tempDir;
                    }
                }
            }
        }

        string xmlFilePath = Path.Combine(xmlDirectory, "data.xml");
        if (!File.Exists(xmlFilePath))
        {
            throw new FileNotFoundException("XML file not found.", xmlFilePath);
        }

        XPathDocument document = new XPathDocument(xmlFilePath);
        XPathNavigator navigator = document.CreateNavigator();

        try
        {
            navigator.Compile(xpathExpression); // Validate the XPath expression
        }
        catch (XPathException ex)
        {
            throw new ArgumentException("Invalid XPath expression.", ex);
        }

        return navigator.SelectSingleNode(xpathExpression);
    }
}
