    private readonly HttpClient _httpClient;
    private readonly ILogger<ContentUpdaterService> _logger;

    public ContentUpdaterService(HttpClient httpClient, ILogger<ContentUpdaterService> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            var userId = GetCurrentUserId(); // Implement this method to get the current user ID
            var actionType = "UpdateElement";
            var timestamp = DateTime.UtcNow;

            _logger.LogInformation($"User {userId} initiated {actionType} for page section {pageSectionId}, element {elementId} at {timestamp}");

            var sanitizedHtmlContent = SanitizeHtml(htmlContent);
            if (string.IsNullOrEmpty(sanitizedHtmlContent))
            {
                _logger.LogWarning($"Sanitization of HTML content failed for user {userId}");
                throw new InvalidOperationException("Invalid or empty HTML content");
            }

            var updateRequest = new ContentUpdateRequest
            {
                PageSectionId = pageSectionId,
                ElementId = elementId,
                HtmlContent = sanitizedHtmlContent
            };

            var response = await _httpClient.PostAsJsonAsync("/api/content/update", updateRequest);
            if (!response.IsSuccessStatusCode)
            {
                _logger.LogError($"Failed to update content for user {userId}: {response.ReasonPhrase}");
                throw new Exception("Failed to update element");
            }

            var result = await response.Content.ReadFromJsonAsync<ContentUpdateResult>();
            if (result.Success && !string.IsNullOrEmpty(result.ErrorMessage))
            {
                _logger.LogWarning($"Content update successful with message: {result.ErrorMessage}");
            }
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError($"Network error while updating content: {ex.Message}");
            throw;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error occurred while updating content");
            throw;
        }
    }

