import java.io.*;

public class ThemeCacheUtil {

    public static MoSTState loadThemeStateFromFile(String filePath) {
        File file = new File(filePath);
        if (!file.exists()) {
            return null;
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return null;
    }

    public static void recycleThemeBitmap(Bitmap bitmap) {
        if (bitmap != null && !bitmap.isRecycled()) {
            bitmap.recycle();
        }
    }

    public static String getDefaultThemeDirectory() {
        // Logic to get default theme directory
        return "/path/to/default/theme/directory";
    }

    public static Bitmap parsePNGFromCacheRoot(String cacheRoot) {
        File file = new File(cacheRoot, "theme.png");
        if (!file.exists()) {
            return null;
        }

        try (InputStream is = new FileInputStream(file)) {
            return BitmapFactory.decodeStream(is);
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
