const fs = require('fs').promises;
const path = require('path');

async function readFileInUserDirectory(userId, relativeFilePath) {
  const userDir = `/user/storage/${userId}`;

  // Validate the file path to prevent directory traversal
  const resolvedPath = path.resolve(userDir, relativeFilePath);
  if (!resolvedPath.startsWith(userDir)) {
    throw new Error('Invalid file access');
  }

  try {
    const data = await fs.readFile(resolvedPath, 'utf8');
    return data;
  } catch (error) {
    if (error.code === 'ENOENT') {
      throw new Error('File not found');
    } else if (error.code === 'EACCES' || error.code === 'EPERM') {
      throw new Error('Permission denied');
    }
    throw error; // Re-throw other I/O errors
  }
}

// Example usage:
(async () => {
  try {
    const userId = '12345';
    const filePath = 'documents/report.txt';
    const fileContent = await readFileInUserDirectory(userId, filePath);
    console.log(fileContent);
  } catch (error) {
    console.error('Error reading file:', error.message);
  }
})();
