const testManager = new TestManager(dependencyManager, 5);

const testCases = [
    { module: 'module1', testFunction: 'test1' },
    { module: 'module2', testFunction: 'test2' },
    // Add more test cases as needed
];

testManager.scaleConcurrently(testCases).then(results => {
    console.log('All tests completed:', results);
}).catch(error => {
    console.error('An error occurred:', error);
});
```

