const { EventEmitter } = require('events');
const fs = require('fs');
const path = require('path');

// Define a class for managing data ingestion
class DataIngestionService extends EventEmitter {
  constructor(options) {
    super();
    this.options = options;
    this.storageBackend = options.storageBackend || 'memory';
    this.processingPaused = false;
    this.lastProcessedData = null;
    this.serviceRunning = true;

    // Set up storage based on the configuration
    if (this.storageBackend === 'file') {
      this.storagePath = path.join(__dirname, 'data', 'processed_data.json');
      fs.mkdirSync(path.dirname(this.storagePath), { recursive: true });
    }
  }

  // Simulate data ingestion from a streaming source
  async ingestData(data) {
    if (this.processingPaused) return;

    try {
      const processed = this.processData(data);
      await this.storeData(processed);

      // Emit an event for successful data processing
      this.emit('dataProcessed', { data: processed });
    } catch (error) {
      console.error('Error processing data:', error);
    }
  }

  // Process incoming data (example implementation)
  processData(data) {
    return { ...data, timestamp: new Date() };
  }

  // Store processed data using the configured storage backend
  async storeData(data) {
    if (this.storageBackend === 'memory') {
      this.lastProcessedData = data;
    } else if (this.storageBackend === 'file') {
      await fs.promises.writeFile(this.storagePath, JSON.stringify([data], null, 2));
    }
  }

  // Pause the service and notify an external monitoring system
  pause() {
    this.processingPaused = true;

    setTimeout(() => {
      console.log('Service paused due to transient failure');
      this.emit('servicePaused', { timestamp: new Date() });
      this.serviceRunning = false;
    }, this.options.delayRanges.pause.min + Math.random() * (this.options.delayRanges.pause.max - this.options.delayRanges.pause.min));
  }

  // Resume the service
  resume() {
    if (!this.serviceRunning) {
      this.processingPaused = false;
      console.log('Service resumed');
      this.emit('serviceResumed', { timestamp: new Date() });
      this.serviceRunning = true;
    }
  }

  // Shutdown the service gracefully
  async shutdown() {
    if (this.storageBackend === 'file') {
      await fs.promises.writeFile(this.storagePath, JSON.stringify([this.lastProcessedData], null, 2));
    }
    console.log('Service shutting down');
    this.emit('serviceShutdown', { timestamp: new Date() });
  }
}

// Example usage
const serviceOptions = {
  storageBackend: 'file',
  delayRanges: {
    pause: {
      min: 1000,
      max: 5000
    },
    resume: {
      min: 2000,
      max: 6000
    }
  }
};

const dataIngestionService = new DataIngestionService(serviceOptions);

dataIngestionService.on('dataProcessed', (processedData) => {
  console.log('Data processed:', processedData);
});

dataIngestionService.on('servicePaused', () => {
  console.log('Service paused');
});

dataIngestionService.on('serviceResumed', () => {
  console.log('Service resumed');
});

dataIngestionService.on('serviceShutdown', () => {
  console.log('Service shutdown');
});

// Simulate data ingestion
setInterval(() => {
  const randomData = { id: Math.random(), value: Date.now() };
  dataIngestionService.ingestData(randomData);
}, 500);

setTimeout(() => {
  dataIngestionService.pause();
}, 10000);

setTimeout(() => {
  dataIngestionService.resume();
}, 20000);

setTimeout(() => {
  dataIngestionService.shutdown();
}, 30000);
```

