    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

class PacketProcessor {
public:
    void processPackets(int maxBytesPerPacket) {
        while (true) {
            std::string packet;
            if (!packetStream_.getPacket(packet)) {
                break; // No more packets available
            }

            std::vector<char> buffer(maxBytesPerPacket);
            size_t bytesToCopy = std::min(packet.size(), maxBytesPerPacket);

            for (size_t i = 0; i < bytesToCopy; ++i) {
                buffer[i] = packet[i];
            }

            // Process the buffer
            processBuffer(buffer, bytesToCopy);
        }
