// Function to dynamically load JavaScript files
function loadScripts(scripts) {
    return new Promise((resolve, reject) => {
        const promises = scripts.map(script => loadScript(script));
        Promise.all(promises)
            .then(results => resolve(results))
            .catch(error => reject(error));
    });
}

// Helper function to load a single script
function loadScript(url) {
    return new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = url;

        script.onload = () => resolve(`Script loaded: ${url}`);
        script.onerror = (error) => reject(new Error(`Failed to load script: ${url}`));

        document.head.appendChild(script);
    });
}

// Function to determine the optimal number of digits for file extension
function getOptimalDigits(filename) {
    const charCount = filename.length;
    if (charCount <= 10) return 3; // Example rule: Use 3 digits for shorter filenames
    if (charCount <= 20) return 4;
    return Math.floor(charCount / 5); // Example rule: Increase digits with longer filenames
}

// Example usage
