    'script1.js',
    'longerScriptFile2.js',
    'anotherOne3.js'
];

filenames.forEach((filename, index) => {
    const optimalDigits = getOptimalDigits(filename);
    const newFilename = filename.replace('.js', `.${optimalDigits}.js`);
    console.log(`Loading ${newFilename}`);
