import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class URLConnectorService {

    private static final Logger logger = LogManager.getLogger(URLConnectorService.class);

    public void connectToURL(String urlString, int timeout, String proxyHost, int proxyPort) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        if (connection instanceof HttpsURLConnection) {
            ((HttpsURLConnection) connection).setSSLSocketFactory(getSSLSocketFactory());
        }

        connection.setRequestMethod("GET");
        connection.setConnectTimeout(timeout);
        connection.setReadTimeout(timeout);

        if (proxyHost != null && proxyPort > 0) {
            connection.setProxy(new Proxy(Proxy.Type.HTTP, new InetSocketAddress(proxyHost, proxyPort)));
        }

        int responseCode = connection.getResponseCode();
        logger.info("Connected to URL: {}, Response Code: {}", url, responseCode);

        // Add logic to handle different response codes and data
