import java.util.concurrent.TimeUnit;

public class RemoteServiceManager {
    private static final int MAX_RETRIES = 5;
    private static final long RETRY_INTERVAL = 2000; // 2 seconds
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private boolean isRunning = false;

    public void startService() {
        if (isRunning) {
            System.out.println("Service is already running.");
            return;
        }

        int retries = 0;
        while (!isRunning && retries < MAX_RETRIES) {
            try {
                // Simulate service startup
                performServiceStartup();
                isRunning = true;
                logStatus("Service started successfully");
                break;
            } catch (Exception e) {
                retries++;
                if (retries < MAX_RETRIES) {
                    long delay = RETRY_INTERVAL * retries;
                    scheduler.schedule(this::startService, delay, TimeUnit.MILLISECONDS);
                    logStatus(String.format("Attempt %d failed. Retrying in %d ms", retries, delay));
                } else {
                    logStatus("Failed to start service after maximum retries");
                }
            }
        }
    }

    public void stopService() {
        if (!isRunning) {
            System.out.println("Service is not running.");
            return;
        }

        // Simulate service shutdown
        performServiceShutdown();
        isRunning = false;
        logStatus("Service stopped successfully");
    }

    private void performServiceStartup() throws Exception {
        // Placeholder for actual service startup logic
