use reqwest::{ClientBuilder, RequestBuilder, Result};
use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use chrono::{DateTime, Utc};

struct CertificateCache {
    cache: Arc<RwLock<HashMap<String, (DateTime<Utc>, bool)>>>,
}

impl CertificateCache {
    fn new() -> Self {
        CertificateCache {
            cache: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    fn get(&self, url: &str) -> Option<bool> {
        let guard = self.cache.read().unwrap();
        guard.get(url).map(|(_, valid)| *valid)
    }

    fn set(&self, url: String, valid: bool, expiration: DateTime<Utc>) {
        let mut guard = self.cache.write().unwrap();
        guard.insert(url, (expiration, valid));
    }
}

fn create_request_builder(
    url: &str,
    disable_certificate_validation: bool,
    certificate_cache: Arc<CertificateCache>,
) -> Result<RequestBuilder> {
