function generateAndHashPassword($length, $charSet, $password, $salt = null, $hashType = 'sha256', $iterations = 1) {
    if (!in_array($hashType, ['bcrypt', 'sha256'])) {
        return [
            'error' => 'Unsupported hashing algorithm. Please choose from bcrypt or sha256.'
        ];
    }

    $generatedString = '';
    for ($i = 0; $i < $length; $i++) {
        $generatedString .= $charSet[rand(0, strlen($charSet) - 1)];
    }

    $hashedPassword = null;
    switch ($hashType) {
        case 'bcrypt':
            $hashedPassword = password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => $iterations]);
            break;
        case 'sha256':
            $hashedPassword = hash('sha256', $password . $salt);
            break;
    }

    return [
        'generatedString' => $generatedString,
        'hashedPassword' => $hashedPassword
    ];
}
