const https = require('https');
const { Readable } = require('stream');

function generatePEMCertificate(oauthRequest) {
  return new Promise((resolve, reject) => {
    const privateKeyUrl = oauthRequest.privateKeyUrl;
    const certificateUrl = oauthRequest.certificateUrl;

    const fetchStream = (url) => {
      return new Promise((resolve, reject) => {
        https.get(url, { timeout: 5000 }, (res) => {
          if (res.statusCode !== 200) {
            reject(new Error(`Failed to fetch data from ${url}: Status code ${res.statusCode}`));
          }

          const stream = new Readable();
          res.on('data', (chunk) => stream.push(chunk));
          res.on('end', () => stream.push(null));

          stream.on('error', (err) => reject(err));

          resolve(stream);
        }).on('error', (err) => {
          reject(err);
        });
      });
    };

    Promise.all([fetchStream(privateKeyUrl), fetchStream(certificateUrl)])
      .then(([privateKeyStream, certificateStream]) => {
        const pemCertificate = Readable.from([
          '-----BEGIN PRIVATE KEY-----\n',
          privateKeyStream.toString(),
          '-----END PRIVATE KEY-----\n',
          '-----BEGIN CERTIFICATE-----\n',
          certificateStream.toString(),
          '-----END CERTIFICATE-----\n'
        ]);

        resolve(pemCertificate);
      })
      .catch((error) => {
        reject(error);
      });
  });
}
