#include <time.h>

typedef struct {
    unsigned long last_id;
    time_t last_time;
} IdentifierGenerator;

unsigned long generate_unique_id(IdentifierGenerator *generator, int node_id) {
    unsigned long id;
    time_t now = time(NULL);

    while (1) {
        // Generate a pseudo-random number
        id = rand() % 0xFFFFFFFFUL; // Assuming 32-bit ID for simplicity

        // Append the current time and node ID to avoid collisions
        id = (id << 16) | ((unsigned long)(now - generator->last_time) << 8) | node_id;

        // Check if the generated ID is unique within the last five minutes
        if (id != generator->last_id && (time(NULL) - generator->last_time) >= 5 * 60) {
            break;
        }
    }

    // Update the state for the next call
    generator->last_id = id;
    generator->last_time = now;

    return id;
}

int main() {
    IdentifierGenerator generator;
    generator.last_id = 0;
    generator.last_time = 0;

    srand(time(NULL)); // Seed the PRNG

    int node_id = 1; // Example node ID
    for (int i = 0; i < 20; i++) {
        unsigned long id = generate_unique_id(&generator, node_id);
        printf("Generated ID: %lu\n", id);
        sleep(1); // Simulate time passing
    }

    return 0;
}
