    GameCharacter() : rng(std::random_device{}()), dist(0, 2) {
        // Initialize cooldowns and reset them
        for (int i = 0; i < 3; ++i) {
            attackCooldowns[i] = 0;
            cooldownsActive[i] = false;
        }
