            int selectedAttack = dist(rng);
            std::cout << "Selected Attack: " << selectedAttack + 1 << std::endl;
            attackCooldowns[selectedAttack] = getCooldownDuration(selectedAttack);
            cooldownsActive[selectedAttack] = true;
