using System;
using UnityEngine;

public class DynamicRandomGenerator
{
    private float _minFloatRange;
    private float _maxFloatRange;
    private int _minIntRange;
    private int _maxIntRange;

    public DynamicRandomGenerator(float minFloatRange, float maxFloatRange, int minIntRange, int maxIntRange)
    {
        if (minFloatRange >= maxFloatRange || minIntRange >= maxIntRange)
            throw new ArgumentException("Invalid range. Min value should be less than Max value.");

        _minFloatRange = minFloatRange;
        _maxFloatRange = maxFloatRange;
        _minIntRange = minIntRange;
        _maxIntRange = maxIntRange;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(_minFloatRange, _maxFloatRange);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range(_minIntRange, _maxIntRange + 1); // Adding 1 to make it inclusive
    }

    public Vector2[] GenerateRandomVectorArray(int length)
    {
        var vectors = new Vector2[length];
        for (int i = 0; i < length; i++)
            vectors[i] = new Vector2(GenerateRandomFloat(), GenerateRandomFloat());
        return vectors;
    }

    public Matrix4x4 GenerateRandomMatrix()
    {
        Matrix4x4 matrix = Matrix4x4.zero;
        for (int i = 0; i < 16; i++)
            matrix[i] = GenerateRandomFloat();
        return matrix;
    }

    public override string ToString()
    {
        return $"DynamicRandomGenerator with float range ({_minFloatRange}, {_maxFloatRange}) and int range ({_minIntRange}, {_maxIntRange})";
    }
}
