// Function to process financial transactions using reduce and a callback
function processTransactions(transactions, initialBalance, callback) {
  return new Promise((resolve, reject) => {
    let balance = initialBalance;
    const prng = new Prando(); // Pseudo-random number generator

    if (!Array.isArray(transactions)) {
      return reject(new Error('Invalid transaction list'));
    }

    transactions.reduce(async (acc, transaction) => {
      try {
        const transactionId = Math.floor(prng.next() * 10000); // Simulate a random ID
        console.log(`Processing transaction ${transactionId}:`, transaction);

        // Simulate asynchronous processing with callback
        await new Promise((res, rej) => {
          setTimeout(() => {
            if (!transaction.status) {
              return rej(new Error('Transaction status missing'));
            }
            if (transaction.status === 'success') {
              balance += transaction.amount;
            } else if (transaction.status === 'failure') {
              balance -= transaction.amount;
            }
            res();
          }, Math.floor(Math.random() * 100)); // Simulate network delay
        });

        console.log(`Transaction ${transactionId} processed, new balance:`, balance);
      } catch (error) {
        console.error(`Error processing transaction:`, error);
        reject(error);
      }
    }, Promise.resolve())
    .then(() => resolve(balance))
    .catch(reject);
  });
}

