#define MAX_EVENT_LENGTH 100
#define MAX_LINES_PER_FILE 1000

typedef struct {
    char **event_types;
    int count;
} EventList;

EventList* process_log_directory(const char *dir_path, int max_event_length, int max_lines_per_file) {
    EventList *list = (EventList *)malloc(sizeof(EventList));
    if (!list) {
        return NULL; // Handle memory allocation failure
    }
    list->event_types = NULL;
    list->count = 0;

    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir(dir_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (ent->d_type == DT_REG) { // Check if it's a regular file
                char path[1024];
                snprintf(path, sizeof(path), "%s/%s", dir_path, ent->d_name);
                FILE *file = fopen(path, "r");
                if (file) {
                    char **event_types = list->event_types;
                    int current_count = list->count;
                    while (1) {
                        char line[MAX_LINES_PER_FILE];
                        if (!fgets(line, sizeof(line), file)) {
                            break; // End of file or read error
                        }
                        char *token = strtok(line, "\n"); // Remove newline character
                        if (strlen(token) > max_event_length) {
                            continue; // Skip lines with event type too long
                        }
                        int found = 0;
                        for (int i = 0; i < current_count; i++) {
                            if (strcmp(event_types[i], token) == 0) {
                                found = 1;
                                break;
                            }
                        }
                        if (!found) {
                            char **new_event_types = realloc(event_types, (current_count + 2) * sizeof(char *));
                            if (!new_event_types) {
                                free(event_types);
                                fclose(file);
                                closedir(dir);
                                free(list);
                                return NULL; // Handle memory allocation failure
                            }
                            event_types = new_event_types;
                            char *event_type_copy = strdup(token);
                            if (!event_type_copy) {
                                free(new_event_types);
                                fclose(file);
                                closedir(dir);
                                free(list);
                                return NULL; // Handle memory allocation failure
                            }
                            event_types[current_count] = event_type_copy;
                            event_types[current_count + 1] = NULL;
                            current_count++;
                        }
                    }
                    list->event_types = event_types;
                    list->count = current_count;
                    fclose(file);
                } else {
                    // Handle file access failure
                }
            }
        }
        closedir(dir);
    } else {
        // Handle directory opening failure
    }

    return list;
}
