function traverseDOM(node, selector, testFn, collector = []) {
    if (!node) return;

    if (testFn(node)) {
        collector.push(node);
    }

    for (let child of node.childNodes) {
        traverseDOM(child, selector, testFn, collector);
    }

    return collector;
}

