// Function to calculate average of last two numeric fields in a line
double calculateAverage(const char* line) {
    char* token = strtok((char*)line, " ");
    double num1 = 0, num2 = 0;
    int count = 0;

    while (token != NULL) {
        if (sscanf(token, "%lf", &num1) == 1) {
            if (count == 0) {
                num2 = num1;
            }
        }
        token = strtok(NULL, " ");
        count++;
    }

    return (num1 + num2) / 2;
}

// Function to process each line in a file
void processFile(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        printf("%s,%f\n", line, calculateAverage(line));
    }

    free(line);
    fclose(file);
}

// Function to process all files in a directory
void processDirectory(const char* dirPath) {
    DIR* dir;
    struct dirent* ent;

    if ((dir = opendir(dirPath)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;

            char filePath[1024];
            snprintf(filePath, sizeof(filePath), "%s/%s", dirPath, ent->d_name);
            processFile(filePath);
        }
        closedir(dir);
    } else {
        perror("Error opening directory");
    }
}

int main() {
    const char* dirPath = "user-specified-directory";
    processDirectory(dirPath);
    return 0;
}
