// Assume this is a library function that generates random digits
char* generate_random_digits(int num_digits);

char* rename_file_with_random_extension(const char* original_filename, const char* file_type, int* new_filename_length) {
    if (strlen(original_filename) >= MAX_FILENAME_LENGTH || strlen(file_type) > 128) {
        return NULL; // Invalid input
    }

    *new_filename_length = strlen(original_filename) + strlen(file_type) + 5;
    if (*new_filename_length > MAX_NEW_FILENAME_LENGTH) {
        return NULL; // New filename too long
    }

    char* new_filename = (char*)malloc(*new_filename_length);
    if (!new_filename) {
        return NULL; // Memory allocation failed
    }

    int num_digits = strlen(original_filename) / 2;
    if (num_digits < 1) {
        num_digits = 1; // Minimum one digit for the extension
    }

    char* random_digits = generate_random_digits(num_digits);
    if (!random_digits) {
        free(new_filename);
        return NULL; // Random digits generation failed
    }

    snprintf(new_filename, *new_filename_length, "%s_%s.%s", original_filename, random_digits, file_type);
    free(random_digits);

    return new_filename;
}

// Example usage
int main() {
    const char* original_filename = "example_file.txt";
    const char* file_type = "log";
    int new_filename_length;

    char* new_filename = rename_file_with_random_extension(original_filename, file_type, &new_filename_length);
    if (new_filename) {
        printf("New filename: %s\n", new_filename);
        free(new_filename); // Don't forget to free the allocated memory
    } else {
        printf("Failed to generate new filename.\n");
    }

    return 0;
}
