public class ObjectDeserialiser {

    public static Object deserializeObjectFromByteArray(byte[] byteArray, ClassLoader trustedClassLoader) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteArray))) {
            return ois.readObject();
        } catch (IOException e) {
            logError("Failed to read byte array", e);
        } catch (ClassNotFoundException e) {
            if (!trustedClassLoader.equals(e.getClass().getClassLoader())) {
                logError("Untrusted class attempted deserialization");
            } else {
                logError("Class not found during deserialization", e);
            }
        } catch (CertificateException e) {
            logError("Certificate exception during deserialization", e);
        }

        return null;
    }

    private static void logError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
        // Additional logging logic can be added here
    }
}
