public class WebSiteManager
{
    public static Process AddAndStartSite(string rootDirectory, string siteName, int timeout)
    {
        // Validate the directory path to prevent navigation outside the intended root directory
        if (!Path.IsPathRooted(siteName) && !siteName.StartsWith(".."))
        {
            throw new ArgumentException("Invalid site name. It cannot navigate outside the root directory.");
        }

        // Construct the full path to the web.config file
        string webConfigPath = Path.Combine(rootDirectory, "web.config");

        // Check if the web.config file exists
        if (!File.Exists(webConfigPath))
        {
            return null;
        }

        // Resolve the full path of the site within the root directory
        string fullPath = Path.GetFullPath(Path.Combine(rootDirectory, siteName));

        // Create the command to start the website using a hypothetical external web server service
        ProcessStartInfo startInfo = new ProcessStartInfo("startWebServer.exe", fullPath);

        try
        {
            // Start the process
            Process process = Process.Start(startInfo);
            process.EnableRaisingEvents = true;

            // Set up a timer to monitor the process
            Stopwatch stopwatch = Stopwatch.StartNew();
            while (stopwatch.Elapsed.TotalSeconds < timeout && !process.HasExited)
            {
                System.Threading.Thread.Sleep(100);
            }

            if (process.HasExited && process.ExitCode != 0)
            {
                throw new InvalidOperationException("Website failed to start within the specified timeout period.");
            }

            return process;
        }
        catch (Exception ex)
        {
            // Log the exception
            Console.WriteLine($"An error occurred: {ex.Message}");
            return null;
        }
    }
}
