import java.util.logging.Logger;

public class DirectoryLister {
    private static final Logger LOGGER = Logger.getLogger(DirectoryLister.class.getName());

    public static void main(String[] args) {
        // Simulate retrieval of directory path from an external source
        String directoryPath = "/path/to/directory"; // Replace with actual logic to fetch this

        if (isValidDirectory(directoryPath)) {
            listFilesInDirectory(directoryPath);
            checkForSpecificFile(directoryPath, "specificFile.txt");
        } else {
            LOGGER.log(Level.SEVERE, "Invalid directory path provided.");
        }
    }

    private static boolean isValidDirectory(String path) {
        Path dir = Paths.get(path);
        try {
            return Files.exists(dir) && Files.isDirectory(dir);
        } catch (SecurityException e) {
            LOGGER.log(Level.WARNING, "Security exception while checking directory.", e);
            return false;
        }
    }

    private static void listFilesInDirectory(String path) {
        File dir = new File(path);
        if (dir.exists() && dir.isDirectory()) {
            File[] files = dir.listFiles();
            if (files != null) {
                for (File file : files) {
                    LOGGER.info("Found file: " + file.getName());
                }
            }
        } else {
            LOGGER.severe("Directory does not exist or is not a directory.");
        }
    }

    private static void checkForSpecificFile(String path, String fileName) {
        Path dir = Paths.get(path);
        Path specificFilePath = dir.resolve(fileName);
        try {
            if (Files.exists(specificFilePath)) {
                LOGGER.info("Found the specific file: " + fileName);
            } else {
                LOGGER.info("Specific file not found: " + fileName);
            }
        } catch (SecurityException e) {
            LOGGER.log(Level.WARNING, "Security exception while checking for specific file.", e);
        }
    }
}
