[StructLayout(LayoutKind.Sequential)]
public struct SecureDataPointer
{
    public IntPtr Password;
    public IntPtr Connection;
    public IntPtr Callback;
}

public class SecurityManager
{
    private static readonly Dictionary<string, (byte[], byte[])> keyCache = new Dictionary<string, (byte[], byte[])>();
    private static readonly object cacheLock = new object();

    [DllImport("myKeyManagementService.dll", CallingConvention = CallingConvention.Cdecl)]
    private static extern int GetSecureKeyAndIV(string keyName, out IntPtr keyData, out int keySize, out IntPtr ivData, out int ivSize);

    public static string ProcessSecureData(SecureDataPointer data)
    {
        if (data.Password == IntPtr.Zero || Marshal.PtrToStringAnsi(data.Password).Length == 0)
            return "Error: Password is empty or NULL";

        if (data.Connection == IntPtr.Zero)
            return "Error: Connection object is NULL";

