char* EnsureStringSuffix(char* buffer, size_t bufferSize, char suffix) {
    if (buffer == NULL || bufferSize <= 0)
        return NULL;

    size_t length = strlen(buffer);
    if (length < bufferSize - 1) {
        buffer[length] = suffix;
        buffer[length + 1] = '\0';
        return buffer;
    } else {
        printf("Buffer overflow detected.\n");
