    public static string DecryptMessage(string base64EncodedString, byte[] key, byte[] iv, CipherMode mode)
    {
        if (key.Length != 8 || iv.Length != 8)
        {
            throw new ArgumentException("Key and IV must be exactly 8 bytes long.");
        }

        try
        {
            byte[] encryptedBytes = Convert.FromBase64String(base64EncodedString);
            using (TripleDES tdes = TripleDES.Create())
            {
                tdes.Key = key;
                tdes.IV = iv;
                tdes.Mode = mode;

                ICryptoTransform decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV);
                using (MemoryStream ms = new MemoryStream(encryptedBytes))
                {
                    using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader sr = new StreamReader(cs))
                        {
                            return sr.ReadToEnd();
                        }
                    }
                }
            }
        }
        catch (FormatException)
        {
            throw new InvalidDataException("Invalid Base64-encoded string.");
        }
        catch (Exception ex)
        {
            // Log error without exposing sensitive information
            Console.WriteLine($"Decryption failed: {ex.Message}");
            return null;
        }
    }
}
