public class FileProcessor
{
    private readonly ILoggingSystem _loggingSystem;

    public FileProcessor(ILoggingSystem loggingSystem)
    {
        _loggingSystem = loggingSystem;
    }

    public void ProcessFile(string filePath, string outputFilePath)
    {
        using (var reader = new StreamReader(filePath))
        using (var writer = new StreamWriter(outputFilePath))
        {
            var sw = Stopwatch.StartNew();
            int lineCount = 0;

            while (!reader.EndOfStream)
            {
                string line = reader.ReadLine();
                lineCount++;

                if (line != null)
                {
                    byte[] hashBytes = ComputeSHA256Hash(line);
                    string hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

                    writer.WriteLine($"{line}:{hashString}");
                }
            }

            sw.Stop();
            _loggingSystem.Log($"Processed {lineCount} lines in {sw.ElapsedMilliseconds} ms");
        }
    }

    private byte[] ComputeSHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }
}

public interface ILoggingSystem
{
    void Log(string message);
}

// Example logging system implementation
public class ConsoleLoggingSystem : ILoggingSystem
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }
}
