using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    private readonly byte[] _fallbackKey;
    private readonly byte[] _fallbackIV;
    private readonly string _logFilePath;
    private readonly int _maxDecryptedDataSize;

    public AesCbcDecryptor(byte[] fallbackKey, byte[] fallbackIV, string logFilePath, int maxDecryptedDataSize)
    {
        _fallbackKey = fallbackKey;
        _fallbackIV = fallbackIV;
        _logFilePath = logFilePath;
        _maxDecryptedDataSize = maxDecryptedDataSize;
    }

    public byte[] Decrypt(byte[] key, byte[] iv, byte[] ciphertext)
    {
        ValidateParameters(key, iv, ciphertext);

        using (Aes aes = Aes.Create())
        {
            aes.Key = key ?? _fallbackKey;
            aes.IV = iv ?? _fallbackIV;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream ms = new MemoryStream(ciphertext))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    byte[] plaintext = new byte[_maxDecryptedDataSize];
                    int decryptedBytes = cs.Read(plaintext, 0, _maxDecryptedDataSize);

                    Array.Resize(ref plaintext, decryptedBytes);
                    return plaintext;
                }
            }
        }
    }

    private void ValidateParameters(byte[] key, byte[] iv, byte[] ciphertext)
    {
        if (key == null || iv == null || ciphertext == null)
            throw new ArgumentNullException("Input parameters cannot be null.");

        if (key.Length != Aes.KeySizes.MaxSize.Value / 8 ||
            iv.Length != Aes.BlockSize / 8 ||
            ciphertext.Length % aes.BlockSize != 0)
            throw new ArgumentException("Invalid key, IV, or ciphertext size.");
    }

    private void LogError(Exception ex, string message = "")
    {
        using (StreamWriter writer = File.AppendText(_logFilePath))
        {
            writer.WriteLine($"{DateTime.Now}: {message} - {ex}");
        }
    }
}
