using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class DataDeserializer<T>
{
    public async Task<T> DeserializeAsync(string filePath, Func<byte[], byte[], bool> validateMetadata)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("The file does not exist.");

        using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
        {
            // Read the metadata length
            int metadataLength = await fs.ReadIntAsync();
            if (metadataLength < 0)
                throw new InvalidDataException("Invalid metadata length.");

            // Validate metadata
            byte[] metadata = new byte[metadataLength];
            await fs.ReadAsync(metadata, 0, metadata.Length);
            if (!validateMetadata(metadata))
                throw new SecurityException("Metadata validation failed.");

            // Read the data length
            int dataLength = await fs.ReadIntAsync();
            if (dataLength < 0)
                throw new InvalidDataException("Invalid data length.");

            // Calculate the hash of the data
            using (SHA256 sha256 = SHA256.Create())
            {
                byte[] actualHash = new byte[dataLength];
                await fs.ReadAsync(actualHash, 0, actualHash.Length);

                byte[] expectedHash = await fs.ReadBytesAsync(sha256.HashSize / 8);
                if (!actualHash.SequenceEqual(expectedHash))
                    throw new IntegrityException("Data integrity check failed.");
            }

            // Deserialize the data
            using (MemoryStream ms = new MemoryStream(await fs.ReadBytesAsync(dataLength)))
            {
                return await Task.Run(() => BinaryFormatter.Deserialize(ms));
            }
        }
    }
}

public static class FileStreamExtensions
{
    public static async Task<int> ReadIntAsync(this FileStream fs)
    {
        byte[] buffer = await fs.ReadBytesAsync(4);
        if (buffer.Length != 4)
            throw new EndOfStreamException("End of stream encountered while reading an integer.");
        return BitConverter.ToInt32(buffer, 0);
    }

    public static async Task<byte[]> ReadBytesAsync(this FileStream fs, int count)
    {
        byte[] buffer = new byte[count];
        int bytesRead = await fs.ReadAsync(buffer, 0, count);
        if (bytesRead != count)
            throw new EndOfStreamException("End of stream encountered while reading bytes.");
        return buffer;
    }
}

public class IntegrityException : Exception
{
    public IntegrityException(string message) : base(message) { }
}
