import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInput;
import java.io.ObjectInputStream;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class CustomObjectDeserializer {

    private static final String HMAC_SHA256 = "HmacSHA256";
    private static final byte[] SECRET_KEY = "yourSecretKey".getBytes();

    public <T> T deserialize(byte[] serializedData, Class<T> clazz) {
        if (serializedData == null || clazz == null) {
            throw new IllegalArgumentException("Input data cannot be null");
        }

        // Validate data integrity
        if (!validateSignature(serializedData)) {
            throw new RuntimeException("Invalid signature for the provided data");
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(serializedData))) {
            return clazz.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Error during deserialization", e);
        }
    }

    private boolean validateSignature(byte[] data) {
        try {
            Mac mac = Mac.getInstance(HMAC_SHA256);
            SecretKeySpec secretKeySpec = new SecretKeySpec(SECRET_KEY, HMAC_SHA256);
            mac.init(secretKeySpec);

            byte[] expectedHmac = mac.doFinal(data);
            byte[] actualHmac = new byte[expectedHmac.length];

            // Assuming the last 32 bytes of data are the HMAC
            System.arraycopy(data, data.length - 32, actualHmac, 0, 32);

            return MessageDigest.isEqual(expectedHmac, actualHmac);
        } catch (Exception e) {
            throw new RuntimeException("Error during signature validation", e);
        }
    }
}
