    keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset(offsets, 0, MAX_KEYS * sizeof(long));
    memset(keys, 0, MAX_KEYS * sizeof(int));
    key_count = 0;
}

int generate_unique_key() {
    int new_key;
    while (1) {
        if (!RAND_bytes((unsigned char*)&new_key, sizeof(new_key))) {
            fprintf(stderr, "Failed to generate random number\n");
            exit(EXIT_FAILURE);
        }
        new_key = abs(new_key) % MAX_KEYS;
        if (keys[new_key] == 0) {
            keys[new_key] = 1;
            return new_key;
        }
    }
}

Record* create_record() {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    do {
        record->value = rand() % 1000 + 1;
    } while (find_record_by_value(record->value) != NULL);
    return record;
}

Record* find_record_by_value(int value) {
    for (int i = 0; i < key_count; i++) {
        if (keys[i] == 1 && records[i].value == value) {
            return &records[i];
        }
    }
    return NULL;
}

void cleanup() {
    free(offsets);
    free(keys);
    curl_multi_cleanup(multi_handle);
}

