// fileOperations.js

const fs = require('fs').promises;
const os = require('os');
const path = require('path');

class FileOperations {
  constructor(config) {
    this.config = config || {};
    this.logService = this.config.loggingService || console;
    this.cache = new Map();
  }

  async read(filePath) {
    try {
      if (this.config.useCache && this.cache.has(filePath)) {
        return this.cache.get(filePath);
      }
      const data = await fs.readFile(filePath, 'utf8');
      if (this.config.useCache) {
        this.cache.set(filePath, data);
      }
      return data;
    } catch (error) {
      this.logService.error(`Error reading file: ${filePath}`, error);
      throw new Error('Failed to read file');
    }
  }

  async write(filePath, data) {
    try {
      await fs.writeFile(filePath, data, 'utf8');
      if (this.config.useCache && this.cache.has(filePath)) {
        this.cache.set(filePath, data);
      }
    } catch (error) {
      this.logService.error(`Error writing file: ${filePath}`, error);
      throw new Error('Failed to write file');
    }
  }

  async append(filePath, data) {
    try {
      await fs.appendFile(filePath, data, 'utf8');
      if (this.config.useCache && this.cache.has(filePath)) {
        const existingData = this.cache.get(filePath);
        this.cache.set(filePath, existingData + data);
      }
    } catch (error) {
      this.logService.error(`Error appending to file: ${filePath}`, error);
      throw new Error('Failed to append to file');
    }
  }

  async delete(filePath) {
    try {
      await fs.unlink(filePath);
      if (this.config.useCache && this.cache.has(filePath)) {
        this.cache.delete(filePath);
      }
    } catch (error) {
      this.logService.error(`Error deleting file: ${filePath}`, error);
      throw new Error('Failed to delete file');
    }
  }

  configureLogging(service) {
    this.logService = service;
  }

  configureCache(useCache, maxCacheSize = 100) {
    this.config.useCache = useCache;
    if (useCache) {
      this.cache = new Map();
      this.maxCacheSize = maxCacheSize;
    }
  }

  async clearCache() {
    if (this.config.useCache) {
      this.cache.clear();
    }
  }
}

module.exports = FileOperations;
