#include <iostream>
#include <vector>
#include <string>
#include <boost/asio.hpp>
#include <boost/uuid/uuid.hpp>
#include <boost/uuid/uuid_generators.hpp>
#include <boost/uuid/uuid_io.hpp>

using boost::asio::ip::tcp;
using boost::system::error_code;

class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& io_context, const std::string& server_ip, int server_port)
        : socket_(io_context), resolver_(io_context), query_(server_ip, std::to_string(server_port)) {}

    void send_request(const std::string& request, boost::function<void(const std::string&)> callback) {
        auto resolve_result = resolver_.resolve(query_);
        boost::asio::async_connect(socket_, resolve_result,
            [this, &request, callback](const error_code& ec, const tcp::endpoint&) {
                if (!ec) {
                    boost::asio::write(socket_, boost::asio::buffer(request),
                        [this, callback](const error_code& ec, std::size_t /*bytes_transferred*/) {
                            if (!ec) {
                                boost::asio::streambuf response;
                                boost::asio::read_until(socket_, response, "\n",
                                    [this, callback, &response](const error_code& ec, std::size_t /*bytes_transferred*/) {
                                        if (!ec) {
                                            std::istream is(&response);
                                            std::string line;
                                            std::getline(is, line);
                                            callback(line);
                                        } else {
                                            handle_error(ec);
                                        }
                                    });
                            } else {
                                handle_error(ec);
                            }
                        });
                } else {
                    handle_error(ec);
                }
            });
    }

private:
    void handle_error(const error_code& ec) {
        // Custom logging mechanism for internal errors
        std::cerr << "Error: " << ec.message() << std::endl;
    }

    tcp::socket socket_;
    boost::asio::ip::tcp::resolver resolver_;
    tcp::resolver::query query_;
};

int main() {
    boost::asio::io_context io_context;

    SandeshClient client(io_context, "your_server_ip", 12345);

    std::string add_vertex_request = "POST /vertex HTTP/1.1\r\nHost: your_server_ip\r\nContent-Type: application/json\r\n\r\n{\"id\":\"" + boost::uuids::to_string(boost::uuids::random_generator()()) + "\"}";
    client.send_request(add_vertex_request, [](const std::string& response) {
        std::cout << "Vertex added response: " << response << std::endl;
    });

    std::string add_edge_request = "POST /edge HTTP/1.1\r\nHost: your_server_ip\r\nContent-Type: application/json\r\n\r\n{\"from\":\"vertex_id_1\",\"to\":\"vertex_id_2\", \"weight\":1}";
    client.send_request(add_edge_request, [](const std::string& response) {
        std::cout << "Edge added response: " << response << std::endl;
    });

    return 0;
}
