static DIRECTORY_PATH_ENV: &str = "DIRECTORY_PATH";
const ROOT_DIRECTORY: &str = "/safe_root_directory";

struct DirectoryManager {
    root_dir: PathBuf,
    env_var_lock: Arc<Mutex<String>>,
}

impl DirectoryManager {
    fn new() -> Self {
        DirectoryManager {
            root_dir: PathBuf::from(ROOT_DIRECTORY),
            env_var_lock: Arc::new(Mutex::new(String::new())),
        }
    }

    fn get_or_create_directory(&self) -> Result<PathBuf, String> {
        let mut env_var = self.env_var_lock.lock().unwrap();
        if env_var.is_empty() {
            *env_var = self.get_existing_directory_from_env()?;
        }

        if env_var.is_empty() {
            *env_var = self.create_new_directory()?.to_str().unwrap().to_string();
        }

        Ok(PathBuf::from(&*env_var))
    }

    fn get_existing_directory_from_env(&self) -> Result<String, String> {
        match env::var(DIRECTORY_PATH_ENV) {
            Ok(path) => {
                if !path.starts_with(self.root_dir.to_str().unwrap()) {
                    error!("Invalid directory path in environment variable");
                    Err("Invalid directory path".to_string())
                } else {
                    Ok(path)
                }
            },
            Err(_) => Ok(String::new()),
        }
    }

    fn create_new_directory(&self) -> Result<PathBuf, String> {
        let new_dir = self.root_dir.join(self.sanitize_and_generate_name());
        if !new_dir.exists() {
            fs::create_dir_all(&new_dir).map_err(|e| format!("Failed to create directory: {}", e))?;
        }
        Ok(new_dir)
    }

    fn sanitize_and_generate_name(&self) -> String {
        use rand::{Rng, thread_rng};
        let mut rng = thread_rng();
        loop {
            let name: String = (0..16).map(|_| rng.sample(rand::distributions::Alphanumeric)).collect();
            if !fs::metadata(&PathBuf::from(self.root_dir.join(name))).is_ok() {
                return name;
            }
        }
    }
}

fn main() {
    env_logger::init();

    let manager = DirectoryManager::new();
    match manager.get_or_create_directory() {
        Ok(path) => info!("Directory path: {:?}", path),
        Err(e) => error!("Error managing directory: {}", e),
    }
}
