import json
from abc import ABC, abstractmethod
from typing import Any, Dict, Callable, Type, List

class CustomDataType(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, data: str) -> 'CustomDataType':
        pass

class JSONManager:
    _registry: Dict[str, Callable[[Any], CustomDataType]] = {}

    @staticmethod
    def register_factory(type_id: str, factory_func: Callable[[Any], CustomDataType]):
        if type_id in JSONManager._registry:
            raise ValueError(f"Factory function for type '{type_id}' already registered.")
        JSONManager._registry[type_id] = factory_func

    @staticmethod
    def unregister_factory(type_id: str):
        if type_id not in JSONManager._registry:
            raise KeyError(f"No factory function found for type '{type_id}'.")
        del JSONManager._registry[type_id]

    @staticmethod
    def create_instance(data: Any) -> CustomDataType:
        type_id = data.get('type')
        if type_id is None or type_id not in JSONManager._registry:
            raise ValueError(f"Unknown type ID: {type_id}")
        factory_func = JSONManager._registry[type_id]
        return factory_func(data)

    @staticmethod
    def serialize(obj: CustomDataType) -> str:
        return json.dumps({'type': obj.__class__.__name__, 'data': obj.to_json()})

    @staticmethod
    def deserialize(json_str: str) -> CustomDataType:
        data = json.loads(json_str)
        type_id = data.get('type')
        if type_id is None or type_id not in JSONManager._registry:
            raise ValueError(f"Unknown type ID: {type_id}")
        factory_func = JSONManager._registry[type_id]
        return factory_func(CustomDataType.from_json(data['data']))

# Example usage
class MyCustomType(CustomDataType):
    def __init__(self, value):
        self.value = value

    def to_json(self) -> str:
        return json.dumps({'value': self.value})

    @classmethod
    def from_json(cls, data: str) -> 'MyCustomType':
        parsed_data = json.loads(data)
        return cls(parsed_data['value'])

JSONManager.register_factory('my_custom_type', MyCustomType.from_json)

# Adding a custom type to the registry
obj = JSONManager.create_instance({'type': 'my_custom_type', 'data': '{"value": 42}'})
serialized = JSONManager.serialize(obj)
deserialized = JSONManager.deserialize(serialized)

print(deserialized.value)  # Output: 42
