#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Define a simple data structure to hold encrypted data with unique keys
typedef struct {
    int key;
    unsigned char *data;
    size_t length;
} EncryptedEntry;

// Global variables for thread safety and error handling
static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
static EncryptedEntry *data_store = NULL;
static size_t data_size = 0;

// Function to add ciphers and digests to OpenSSL library
void setup_crypto_primitives() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_128_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest_alias("SHA", "sha1");
}

// Function to generate a cryptographically strong pseudo-random number
int generate_unique_key() {
    int key;
    do {
        if (!RAND_bytes((unsigned char *)&key, sizeof(key))) {
            // Handle error in generating random number
            return -1;
        }
    } while (key < 1 || key > 1000);
    return key;
}

// Function to add an entry to the data store with a unique key
int add_entry_to_store(const unsigned char *data, size_t length) {
    pthread_mutex_lock(&data_mutex);
    int key = generate_unique_key();
    if (key == -1) {
        pthread_mutex_unlock(&data_mutex);
        return -1;
    }

    // Check for duplicate keys or allocation failures
    for (size_t i = 0; i < data_size; i++) {
        if (data_store[i].key == key) {
            pthread_mutex_unlock(&data_mutex);
            return -1;
        }
    }

    EncryptedEntry new_entry = { key, NULL, length };
    new_entry.data = malloc(length);
    if (!new_entry.data) {
        pthread_mutex_unlock(&data_mutex);
        return -1;
    }
    memcpy(new_entry.data, data, length);

    // Resize and add the new entry to the data store
    EncryptedEntry *new_store = realloc(data_store, (data_size + 1) * sizeof(EncryptedEntry));
    if (!new_store) {
        free(new_entry.data);
        pthread_mutex_unlock(&data_mutex);
        return -1;
    }
    data_store = new_store;
    data_store[data_size++] = new_entry;

    pthread_mutex_unlock(&data_mutex);
    return key;
}

// Function to safely cleanup resources
void cleanup() {
    pthread_mutex_lock(&data_mutex);
    for (size_t i = 0; i < data_size; i++) {
        free(data_store[i].data);
    }
    free(data_store);
    data_store = NULL;
    data_size = 0;
    pthread_mutex_unlock(&data_mutex);
}

// Example usage
int main() {
    setup_crypto_primitives();
    int key = add_entry_to_store((const unsigned char *)"example_data", 12);
    if (key != -1) {
        printf("Entry added with key: %d\n", key);
    } else {
        printf("Failed to add entry.\n");
    }
    cleanup();
    return 0;
}
```

