class RandomRecordManager {
private:
    static std::mt19937 rng;
    static std::mutex mtx;
    std::map<int, long> recordPool;

public:
    RandomRecordManager() {}

    ~RandomRecordManager() {
        // Ensure proper cleanup of resources
    }

    int generateKey() {
        std::lock_guard<std::mutex> lock(mtx);
        static std::uniform_int_distribution<> dist(0, 1000000); // Adjust range as needed
        while (true) {
            int key = dist(rng);
            if (recordPool.find(key) == recordPool.end()) {
                return key;
            }
        }
    }

    bool insertKey(int key, long offset) {
        std::lock_guard<std::mutex> lock(mtx);
        if (recordPool.find(key) != recordPool.end()) {
            return false; // Key already exists
        }
        recordPool[key] = offset;
        return true;
    }

    long getOffset(int key) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = recordPool.find(key);
        if (it != recordPool.end()) {
            return it->second;
        }
        throw std::runtime_error("Key not found");
    }

    void cleanup() {
        // Perform any necessary cleanup operations
    }
};

std::mt19937 RandomRecordManager::rng(std::random_device{}());
std::mutex RandomRecordManager::mtx;

int main() {
    RandomRecordManager manager;
    int key = manager.generateKey();
    manager.insertKey(key, 42);
    long offset = manager.getOffset(key);
    std::cout << "Generated key: " << key << ", Offset: " << offset << std::endl;
    return 0;
}
