#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <random>
#include <chrono>

class RandomRecordManager {
private:
    static std::mt19937 prng;
    std::unordered_map<int, long> keyOffsetMap;
    std::mutex mtx;
    std::condition_variable cv;
    bool running;

public:
    RandomRecordManager() : running(true) {
        // Initialize PRNG seed
        std::random_device rd;
        prng.seed(rd());
        std::thread refreshThread(&RandomRecordManager::refreshSeed, this);
        refreshThread.detach();
    }

    ~RandomRecordManager() {
        running = false;
        cv.notify_all();
    }

    static int generateKey() {
        std::uniform_int_distribution<> dis(std::numeric_limits<int>::min(), std::numeric_limits<int>::max());
        return dis(prng);
    }

    bool insertKey(int key, long offset) {
        std::lock_guard<std::mutex> lock(mtx);
        if (keyOffsetMap.find(key) != keyOffsetMap.end()) {
            return false; // Key already exists
        }
        keyOffsetMap[key] = offset;
        return true;
    }

    bool retrieveKey(int key, long& offset) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = keyOffsetMap.find(key);
        if (it != keyOffsetMap.end()) {
            offset = it->second;
            return true;
        }
        return false;
    }

private:
    static void refreshSeed() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::minutes(1));
            std::random_device rd;
            prng.seed(rd());
        }
    }
};

std::mt19937 RandomRecordManager::prng;

int main() {
    RandomRecordManager manager;
    int key = RandomRecordManager::generateKey();
    long offset = 0;

    if (manager.insertKey(key, offset)) {
        std::cout << "Key inserted successfully." << std::endl;
    } else {
        std::cout << "Failed to insert key." << std::endl;
    }

    if (manager.retrieveKey(key, offset)) {
        std::cout << "Offset retrieved: " << offset << std::endl;
    } else {
        std::cout << "Failed to retrieve key." << std::endl;
    }

    return 0;
}
