typedef struct PacketInfo {
    void* payload;
    size_t length;
} PacketInfo;

typedef struct Node {
    PacketInfo packet;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t count;
} LinkedList;

Node* createNode(PacketInfo packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->packet = packet;
    newNode->next = NULL;
    return newNode;
}

LinkedList* createPacketLinkedList(int numPackets, size_t averagePayloadSize) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    size_t maxPayloadSize = averagePayloadSize * numPackets;
    for (int i = 0; i < numPackets; i++) {
        PacketInfo packet;
        packet.payload = malloc(maxPayloadSize);
        if (!packet.payload) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        packet.length = maxPayloadSize;

        Node* newNode = createNode(packet);
        if (list->head == NULL) {
            list->head = newNode;
        } else {
            list->tail->next = newNode;
        }
        list->tail = newNode;
        list->count++;
    }

    return list;
}

