#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

#define MAX_FILE_PATHS 100
#define MAX_PATH_LENGTH 256

typedef struct {
    int parent;
    int rank;
} UnionFind;

int find(UnionFind *uf, int u) {
    if (uf[u].parent != u)
        uf[u].parent = find(uf, uf[u].parent);
    return uf[u].parent;
}

void unionElements(UnionFind *uf, int u, int v) {
    int pu = find(uf, u);
    int pv = find(uf, v);

    if (pu != pv) {
        if (uf[pu].rank < uf[pv].rank)
            uf[pu].parent = pv;
        else if (uf[pu].rank > uf[pv].rank)
            uf[pv].parent = pu;
        else {
            uf[pv].parent = pu;
            uf[pu].rank++;
        }
    }
}

int countDisjointPairs(UnionFind *uf, int n) {
    int disjointCount = 0;
    for (int i = 1; i <= n; i++) {
        if (uf[i].parent == i)
            disjointCount++;
    }
    return disjointCount;
}

void readFileMetadata(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    // Simulate reading metadata
    printf("Reading metadata from %s\n", filePath);
    fclose(file);
}

int processFilePaths(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file_path>...\n", argv[0]);
        return -1;
    }

    UnionFind uf[MAX_FILE_PATHS + 1];
    for (int i = 1; i <= MAX_FILE_PATHS; i++) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }

    struct timeval start, end;
    gettimeofday(&start, NULL);

    int fileCount = argc - 1;
    for (int i = 1; i < argc; i++) {
        readFileMetadata(argv[i]);
        // Simulate union operation between two files
        if (i % 2 == 0 && i + 1 < argc) {
            unionElements(uf, i, i + 1);
        }
    }

    gettimeofday(&end, NULL);

    long seconds = end.tv_sec - start.tv_sec;
    long microseconds = end.tv_usec - start.tv_usec;
    double elapsed = seconds + microseconds * 1e-6;

    printf("File operations took %.2f milliseconds\n", elapsed * 1000);
    int disjointCount = countDisjointPairs(uf, fileCount);
    printf("Number of disjoint pairs: %d\n", disjointCount);

    return 0;
}
