data_store* create_data_store(size_t num_records) {
    data_store* ds = (data_store*)malloc(sizeof(data_store));
    if (!ds) return NULL;

    ds->offset_values = (long*)calloc(num_records, sizeof(long));
    ds->keys = (int*)calloc(num_records, sizeof(int));
    ds->records = (record*)calloc(num_records, sizeof(record));
    ds->key_used = (bool*)calloc(MAX_KEYS, sizeof(bool));
    ds->used_keys_count = 0;
    ds->max_records = num_records;

    if (!ds->offset_values || !ds->keys || !ds->records || !ds->key_used) {
        free(ds->offset_values);
        free(ds->keys);
        free(ds->records);
        free(ds->key_used);
        free(ds);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        ds->records[i].value = rand() % 2001;
        int key;
        do {
            key = rand() % MAX_KEYS;
        } while (ds->key_used[key]);
        ds->keys[i] = key;
        ds->key_used[key] = true;
        ds->used_keys_count++;
    }

    return ds;
}

void free_data_store(data_store* ds) {
    if (!ds) return;

    free(ds->offset_values);
    free(ds->keys);
    free(ds->records);
    free(ds->key_used);
