#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

long* offset_values;
int* keys;
record* records;
int num_records;
pthread_mutex_t key_lock;

void initialize_arrays(int size) {
    offset_values = (long*)malloc(size * sizeof(long));
    keys = (int*)malloc(size * sizeof(int));
    records = (record*)malloc(size * sizeof(record));

    pthread_mutex_init(&key_lock, NULL);

    srand(time(NULL));  // Seed for PRNG
}

void generate_records(int size) {
    for (int i = 0; i < size; i++) {
        do {
            keys[i] = rand() % MAX_KEYS;
        } while (keys[i] == -1);  // Assuming -1 is an invalid key

        records[i].value = rand();
    }
}

void* execute_background_command(void* arg) {
    const char* command = (const char*)arg;
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return NULL;
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(EXIT_FAILURE);
    } else {
        int status;
        wait(&status);
        if (WIFEXITED(status)) {
            printf("Command exited with status %d\n", WEXITSTATUS(status));
            return (void*)WEXITSTATUS(status);
        }
    }

    return NULL;
}

void clean_up() {
    free(offset_values);
    free(keys);
    free(records);
    pthread_mutex_destroy(&key_lock);
}

int main() {
    int size = 1000;  // Example size

    initialize_arrays(size);
    generate_records(size);

    const char* command = "ls -l";
    execute_background_command((void*)command);

    clean_up();

    return 0;
}
