public:
    void logSuccessfulRequest();
    void logFailedAttempt();
    void logError(const std::string& error);
};

class Client {
private:
    NetworkManager* networkManager;
    FileHandler fileHandler;
    HashCalculator hashCalculator;
    Logger logger;

public:
    Client(NetworkManager* nm) : networkManager(nm) {}

    bool downloadAndVerifyFile(const std::string& url, const std::string& knownHash) {
        try {
            std::string content = networkManager->fetchContentFromUrl(url);
            if (content.empty()) {
                logger.logFailedAttempt();
                return false;
            }

            std::string calculatedHash = hashCalculator.calculateMD5(content);
            if (calculatedHash == knownHash) {
                logger.logSuccessfulRequest();
                return true;
            } else {
                logger.logError("Hash verification failed");
                return false;
            }
        } catch (const boost::system::error_code& ec) {
            logger.logFailedAttempt();
            std::cerr << "Network error: " << ec.message() << std::endl;
            return false;
        } catch (...) {
            logger.logError("Internal error occurred");
            return false;
        }
    }
};

