    int *keys;
    long *offsets;
    Record *records;
    int used_keys[1024];
    pthread_mutex_t lock;
} DataStorage;

DataStorage *initialize_storage(int max_records) {
    DataStorage *storage = (DataStorage *)malloc(sizeof(DataStorage));
    storage->keys = (int *)calloc(max_records, sizeof(int));
    storage->offsets = (long *)calloc(max_records, sizeof(long));
    storage->records = (Record *)calloc(max_records, sizeof(Record));
    pthread_mutex_init(&storage->lock, NULL);
    return storage;
}

unsigned int custom_hash(int key) {
    // Simple hash function to minimize collisions
    return (key * 17 + 31) % MAX_RECORDS;
}

int generate_random_value() {
    static unsigned long seed = 0;
    if (seed == 0)
        seed = time(NULL);
    seed *= 1103515245 + 12345; // Fast PRNG
    return (seed >> 16) % 1001; // Scale to [1, 1000]
}

int add_record(DataStorage *storage, int key) {
    pthread_mutex_lock(&storage->lock);
    unsigned int index = custom_hash(key);
    while (storage->keys[index] != 0 && storage->keys[index] != key) {
        index = (index + 1) % MAX_RECORDS; // Linear probing
    }
    if (storage->keys[index] == 0) {
        storage->keys[index] = key;
        storage->records[index].value = generate_random_value();
        pthread_mutex_unlock(&storage->lock);
        return 1;
    } else {
        pthread_mutex_unlock(&storage->lock);
        return 0; // Key already exists
    }
}

void clean_up(DataStorage *storage) {
    free(storage->keys);
    free(storage->offsets);
    free(storage->records);
    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

int main() {
    DataStorage *storage = initialize_storage(MAX_RECORDS);
    add_record(storage, 123);
    clean_up(storage);
    return 0;
}
