#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_KEYS 2048

typedef struct {
    int value;
} record;

int* used_keys = NULL;
int used_keys_count = 0;

void initialize_record(record** records, int num_records) {
    srand(time(NULL)); // Seed the PRNG with the current time

    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        int key;
        do {
            key = rand() % MAX_KEYS + 1; // Generate a random key between 1 and 2047
        } while (is_key_used(key));

        records[i]->value = key;
        mark_key_as_used(key);
    }
}

int is_key_used(int key) {
    for (int i = 0; i < used_keys_count; i++) {
        if (used_keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

void mark_key_as_used(int key) {
    used_keys = realloc(used_keys, (used_keys_count + 1) * sizeof(int));
    if (!used_keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    used_keys[used_keys_count++] = key;
}

void cleanup_records(record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(used_keys);
}

// Example usage
int main() {
    record** records;
    initialize_record(&records, 10);

    // Use the records...

    cleanup_records(records, 10);
    return 0;
}
