// NetworkPacketProcessor.java

import java.security.Key;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;

public class NetworkPacketProcessor {
    private Cipher encryptCipher;
    private Cipher decryptCipher;
    private Key encryptionKey;
    private IvParameterSpec ivParameterSpec;

    public NetworkPacketProcessor(String algorithm, byte[] keyBytes) throws Exception {
        initializeCiphers(algorithm, keyBytes);
    }

    private void initializeCiphers(String algorithm, byte[] keyBytes) throws Exception {
        switch (algorithm) {
            case "AES-128-CBC":
                encryptionKey = javax.crypto.KeyGenerator.getInstance("AES").generateKey();
                ivParameterSpec = new IvParameterSpec(new byte[16]);
                encryptCipher = Cipher.getInstance(algorithm);
                decryptCipher = Cipher.getInstance(algorithm);
                break;
            case "AES-256-CBC":
                encryptionKey = javax.crypto.KeyGenerator.getInstance("AES").generateKey();
                ivParameterSpec = new IvParameterSpec(new byte[16]);
                encryptCipher = Cipher.getInstance(algorithm);
                decryptCipher = Cipher.getInstance(algorithm);
                break;
            case "null":
                // No initialization needed for null encryption
                encryptCipher = null;
                decryptCipher = null;
                break;
            default:
                throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
        }
    }

    public byte[] encrypt(byte[] data) throws Exception {
        if (encryptCipher == null) return data; // Null encryption
        encryptCipher.init(Cipher.ENCRYPT_MODE, encryptionKey, ivParameterSpec);
        return encryptCipher.doFinal(data);
    }

    public byte[] decrypt(byte[] data) throws Exception {
        if (decryptCipher == null) return data; // Null decryption
        decryptCipher.init(Cipher.DECRYPT_MODE, encryptionKey, ivParameterSpec);
        return decryptCipher.doFinal(data);
    }
}

// SignatureVerifier.java

import java.security.Signature;

public class SignatureVerifier {
    private Signature signature;

    public SignatureVerifier(String algorithm) throws Exception {
        this.signature = Signature.getInstance(algorithm);
    }

    public void initVerify(byte[] publicKey) throws Exception {
        signature.initVerify(publicKey);
    }

    public boolean verify(byte[] data, byte[] signatureBytes) throws Exception {
        return signature.verify(signatureBytes);
    }
}

// NetworkPacket.java

public class NetworkPacket {
    private byte[] payload;
    private byte[] signature;

    public NetworkPacket(byte[] payload, byte[] signature) {
        this.payload = payload;
        this.signature = signature;
    }

    public byte[] getPayload() {
        return payload;
    }

    public byte[] getSignature() {
        return signature;
    }
}

// Main.java

import java.security.MessageDigest;

public class Main {
    public static void main(String[] args) {
        try {
            NetworkPacketProcessor processor = new NetworkPacketProcessor("AES-256-CBC", "0123456789abcdef".getBytes());
            SignatureVerifier verifier = new SignatureVerifier("SHA256withRSA");

            byte[] originalData = "Hello, World!".getBytes();
            byte[] encryptedData = processor.encrypt(originalData);
            byte[] signature = generateSignature(encryptedData);

            NetworkPacket packet = new NetworkPacket(encryptedData, signature);
            if (verifyPacket(packet)) {
                byte[] decryptedData = processor.decrypt(packet.getPayload());
                System.out.println("Decrypted Data: " + new String(decryptedData));
            } else {
                System.err.println("Packet verification failed!");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static byte[] generateSignature(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA256");
        byte[] hash = md.digest(data);
        return hash;
    }

    private static boolean verifyPacket(NetworkPacket packet) throws Exception {
        SignatureVerifier verifier = new SignatureVerifier("SHA256withRSA");
        verifier.initVerify("publicKey".getBytes());
        return verifier.verify(packet.getPayload(), packet.getSignature());
    }
}
