const int MAX_FEATURE_SIZE = 100;
const int MAX_LEAF_NODES = 1000;

struct Octree {
    float* prefixLeafs;
    char** data;
    int featureSize;
    int leafNodes;
};

int initializeOctreeWithSemaphore(int featureSize, int numLeafNodes, int dataCapacity, size_t* systemLimit, int initialSemaphoreValue) {
    if (featureSize < 0 || featureSize > MAX_FEATURE_SIZE) {
        std::cerr << "Invalid feature size" << std::endl;
        return -1;
    }
    if (numLeafNodes <= 0 || numLeafNodes > MAX_LEAF_NODES) {
        std::cerr << "Invalid number of leaf nodes" << std::endl;
        return -2;
    }

    Octree* octree = new Octree();
    octree->featureSize = featureSize;
    octree->leafNodes = numLeafNodes;

    size_t requiredMemory = (numLeafNodes * sizeof(float)) + (dataCapacity * sizeof(char*));
    if (requiredMemory > *systemLimit) {
        std::cerr << "Insufficient system memory" << std::endl;
        delete octree;
        return -3;
    }

    octree->prefixLeafs = new float[numLeafNodes];
    for (int i = 0; i < numLeafNodes; ++i) {
        octree->prefixLeafs[i] = 0.0f;
    }

    octree->data = new char*[dataCapacity];
    for (int i = 0; i < dataCapacity; ++i) {
        octree->data[i] = nullptr;
    }

    sem_t* semaphore = new sem_t();
    if (sem_init(semaphore, 0, initialSemaphoreValue) != 0) {
        std::cerr << "Failed to initialize semaphore" << std::endl;
        delete[] octree->prefixLeafs;
        delete[] octree->data;
        delete octree;
        delete semaphore;
        return -4;
    }

    *systemLimit -= requiredMemory;
    sem_t* result = semaphore;

    // Perform operations on the octree...

    sem_destroy(semaphore);
    delete semaphore;
    delete[] octree->prefixLeafs;
    delete[] octree->data;
    delete octree;

    return 0;
}
