    static unsigned short node_id = 0;
    Identifier identifier;

    // Use a simple PRNG to ensure predictable yet unique IDs
    srand(time(NULL) + getpid()); // Seed based on time and process ID for uniqueness
    last_id = (last_id * 134775813L + 123456789L) % MAX_NODES;
    node_id = (node_id + 1) % MAX_NODES; // Cycle through nodes

    identifier.id = ((unsigned long)time(NULL) << 16) | last_id | ((unsigned long)node_id << 8);
    identifier.timestamp = time(NULL);

    return identifier;
}

void log_identifier(Identifier id) {
    printf("ID: %lu, Timestamp: %ld\n", id.id, id.timestamp);
}

int main() {
    Identifier id = generate_unique_id();
    log_identifier(id);
    return 0;
}
