public class CustomRandom
{
    private double _minIntValue;
    private double _maxIntValue;
    private double _minDoubleValue;
    private double _maxDoubleValue;
    private Random _random;
    private RNGCryptoServiceProvider _cryptoProvider;

    public CustomRandom(double minInt, double maxInt, double minDouble, double maxDouble)
    {
        if (minInt >= maxInt || minDouble >= maxDouble)
            throw new ArgumentException("Range values must be valid.");

        _minIntValue = minInt;
        _maxIntValue = maxInt;
        _minDoubleValue = minDouble;
        _maxDoubleValue = maxDouble;

        _random = new Random();
        _cryptoProvider = new RNGCryptoServiceProvider();
    }

    public int NextInt()
    {
        byte[] data = new byte[4];
        _cryptoProvider.GetBytes(data);
        return BitConverter.ToInt32(data, 0) % (int)(_maxIntValue - _minIntValue + 1) + (int)_minIntValue;
    }

    public double NextDouble()
    {
        byte[] data = new byte[8];
        _cryptoProvider.GetBytes(data);
        return BitConverter.ToDouble(data, 0) * (_maxDoubleValue - _minDoubleValue) + _minDoubleValue;
    }

    public Vector2 RandomVector2()
    {
        return new Vector2(NextDouble(), NextDouble());
    }

    public Matrix4x4 RandomMatrix4x4()
    {
        Matrix4x4 matrix = new Matrix4x4();
        for (int i = 0; i < 16; i++)
        {
            matrix.M[i] = NextDouble();
        }
        return matrix;
    }

    public override string ToString()
    {
        return $"Int Range: {_minIntValue} to {_maxIntValue}, Double Range: {_minDoubleValue} to {_maxDoubleValue}";
    }
}

public class Vector2
{
    public double X { get; set; }
    public double Y { get; set; }

    public Vector2(double x, double y)
    {
        X = x;
        Y = y;
    }
}

public class Matrix4x4
{
    public double[] M { get; set; } = new double[16];

    public Matrix4x4()
    {
        for (int i = 0; i < 16; i++)
            M[i] = 0;
    }
