#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* truncate_string(const char* input, int size_limit, int max_chars) {
    if (input == NULL || *input == '\0') {
        return NULL;
    }

    int len = strlen(input);
    if (len <= size_limit && len <= max_chars) {
        return strdup(input); // Duplicate the string safely
    }

    char* result = (char*)malloc(size_limit + 2);
    if (result == NULL) {
        return NULL; // Handle memory allocation failure
    }

    strncpy(result, input, size_limit - 1);
    result[size_limit - 1] = '/';
    result[size_limit] = '\0';

    return result;
}
