int64_t xorshift1024star(uint64_t *state) {
    static const uint64_t MUL = 1181783497276652981ULL;
    uint64_t s0 = state[0];
    uint64_t s1 = state[1], t = state[1] ^ (state[1] << 7);
    state[1] = state[2];
    state[2] = state[3];
    state[3] = state[4];
    state[4] = state[5];
    state[5] = state[6];
    state[6] = s0;
    s0 ^= s0 >> 9;
    s1 ^= s1 << 17;
    return (s0 + s1) * MUL;
}

LogEntry* init_arrays(uint64_t seed, size_t num_entries) {
    uint64_t state[16];
    for (size_t i = 0; i < 16; ++i) {
        state[i] = xorshift1024star((uint64_t[]){seed + i});
    }
    srand(seed);

    Event *timestamps = malloc(num_entries * sizeof(Event));
    int32_t *identifiers = malloc(num_entries * sizeof(int32_t));
    LogEntry *log_entries = malloc(num_entries * sizeof(LogEntry));
    ResourceUsage *resource_usages = malloc(num_entries * sizeof(ResourceUsage));

    for (size_t i = 0; i < num_entries; ++i) {
        timestamps[i].timestamp = xorshift1024star(state);
        identifiers[i] = rand();
        log_entries[i].identifier = identifiers[i];
        log_entries[i].event_type = xorshift1024star(state) % 256;
        resource_usages[i].memory_usage = xorshift1024star(state) % 1024;
    }

    return (LogEntry*)log_entries;
}
