typedef struct {
    uint32_t value;
    int* errorCode;
} Record;

uint64_t xorshift64star(uint64_t* state) {
    *state ^= *state >> 12;
    *state ^= *state << 25;
    *state ^= *state >> 27;
    return (*state * 268589130769825093ULL);
}

void initializeArrays(uint64_t seed, uint64_t* offsets, uint32_t* keys, Record** records, int** errorCodes, size_t numRecords) {
    srand(seed);

    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = xorshift64star(&seed);
        keys[i] = rand();

        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand();
        records[i]->errorCode = errorCodes[i];

        *errorCodes[i] = xorshift64star(&seed) % 2; // Simulating success or failure
    }
}

int main() {
    size_t numRecords = 100000;
    uint64_t* offsets = malloc(numRecords * sizeof(uint64_t));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    uint32_t* keys = malloc(numRecords * sizeof(uint32_t));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    Record** records = malloc(numRecords * sizeof(Record*));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    int* errorCodes = malloc(numRecords * sizeof(int));
    if (errorCodes == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    initializeArrays(time(NULL), offsets, keys, records, &errorCodes, numRecords);

    // Use the arrays as needed...

    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(errorCodes);

    return 0;
}
