#include <stdlib.h>
#include <string.h>

// AES encryption function
int aes_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key,
                const unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len, ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto end;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto end;
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto end;
    ciphertext_len += len;

end:
    EVP_CIPHER_CTX_free(ctx);
    return (ciphertext_len < 0) ? -1 : ciphertext_len;
}

// PRNG to assign unique 'int' keys between 1 and 1000
int prng(int *previous_key) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int new_key;

    pthread_mutex_lock(&lock);
    while (1) {
        new_key = arc4random_uniform(1000) + 1;
        if (new_key != *previous_key)
            break;
    }
    *previous_key = new_key;
    pthread_mutex_unlock(&lock);

    return new_key;
}

// Error recovery and retry logic for external data source interactions
int safe_exec(const char *command, int retries) {
    const char *delim = " \t\n";
    char **args = strsplit(command, delim);
    int status;

    while (retries--) {
        pid_t pid = fork();
        if (pid == -1)
            return -1;
        else if (pid == 0) {
            execvp(args[0], args);
            _exit(EXIT_FAILURE);
        } else {
            waitpid(pid, &status, 0);
            if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
                break;
        }
    }

    for (int i = 0; args[i]; ++i)
        free(args[i]);
    free(args);

    return status;
}

// Monitoring system
