#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} Record;

// Thread-safe data structure
struct KeyStore {
    long *offsets;
    int *keys;
    pthread_mutex_t mutex;
    bool used[MAX_KEYS];
};

void initialize_key_store(struct KeyStore *ks) {
    ks->offsets = (long *)malloc(MAX_KEYS * sizeof(long));
    ks->keys = (int *)malloc(MAX_KEYS * sizeof(int));
    pthread_mutex_init(&ks->mutex, NULL);
    for (int i = 0; i < MAX_KEYS; ++i) {
        ks->used[i] = false;
    }
}

void destroy_key_store(struct KeyStore *ks) {
    free(ks->offsets);
    free(ks->keys);
    pthread_mutex_destroy(&ks->mutex);
}

bool add_key(struct KeyStore *ks, int key, long offset) {
    if (key < 0 || key >= MAX_KEYS) return false;
    pthread_mutex_lock(&ks->mutex);
    if (ks->used[key]) {
        pthread_mutex_unlock(&ks->mutex);
        return false; // Collision detected
    }
    ks->keys[key] = key;
    ks->offsets[key] = offset;
    ks->used[key] = true;
    pthread_mutex_unlock(&ks->mutex);
    return true;
}

void initialize_records(Record *records, int num_records) {
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 1000 + 1;
    }
}
