import java.util.Random;

public class RemoteDataProcessor {

    private Selector selector;
    private ConcurrentHashMap<Integer, Boolean> usedKeys = new ConcurrentHashMap<>();
    private int[] offsets;
    private record[] records;
    private int maxRecords;

    public void initialize(int maxRecords) throws IOException {
        this.maxRecords = maxRecords;
        selector = Selector.open();
        offsets = new long[maxRecords];
        records = new record[maxRecords];

        // Initialize keys and records here
        initializeKeysAndRecords();

        // Register channels and start processing
        startProcessing();
    }

    private void initializeKeysAndRecords() {
        Random random = new SecureRandom();
        for (int i = 0; i < maxRecords; i++) {
            int key;
            do {
                key = random.nextInt(1024);
            } while (!usedKeys.putIfAbsent(key, true) == null);

            offsets[i] = System.currentTimeMillis(); // Example offset
            records[i] = new record(random.nextInt(1000)); // Random value between 1 and 1000
        }
    }

    private void startProcessing() throws IOException {
        for (int i = 0; i < maxRecords; i++) {
            SocketChannel channel = SocketChannel.open();
            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_CONNECT);
            channel.connect(new InetSocketAddress("remoteAddress", 12345)); // Replace with actual address
        }

        while (true) {
            selector.select();
            for (SelectionKey key : selector.selectedKeys()) {
                if (key.isConnectable()) {
                    SocketChannel channel = (SocketChannel) key.channel();
                    try {
                        channel.finishConnect();
                        processChannel(channel);
                    } catch (IOException e) {
                        System.err.println("Connection failed: " + e.getMessage());
                        channel.close();
                    }
                }
            }
        }
    }

    private void processChannel(SocketChannel channel) throws IOException {
        // Simulate data processing
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        while (channel.read(buffer) > 0) {
            // Process data
        }
        System.out.println("Data processed from channel: " + channel.getRemoteAddress());
    }

    public void cleanUp() throws IOException {
        selector.close();
        for (SocketChannel channel : selector.selectedKeys()) {
            channel.close();
        }
    }

    public static record record(int value) {}

    // Helper function to read integers from standard input and find the largest
    public static int readAndFindLargest() {
        Scanner scanner = new Scanner(System.in);
        List<Integer> numbers = new ArrayList<>();
        while (scanner.hasNextInt()) {
            numbers.add(scanner.nextInt());
        }
        return numbers.stream().max(Integer::compare).orElseThrow(NoSuchElementException::new);
    }

    public static void main(String[] args) {
        try {
            RemoteDataProcessor processor = new RemoteDataProcessor();
            processor.initialize(100); // Initialize with 100 records
            // Perform other tasks here
        } catch (IOException e) {
            System.err.println("Initialization failed: " + e.getMessage());
        }
    }
}
