public class RecordProcessor {

    private final ConcurrentHashMap<Integer, Integer> keyStore = new ConcurrentHashMap<>();
    private final AtomicInteger recordCount = new AtomicInteger();
    private int maxRecords;
    private double logLevel;
    private long latencyThreshold;
    private String remoteAddress;
    private List<ChannelHandler> channelHandlers;

    public void processRecords() {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        try {
            System.out.println("Enter a list of integers separated by spaces:");
            String input = reader.readLine();
            String[] inputs = input.split("\\s+");
            List<Integer> numbers = new ArrayList<>();
            for (String num : inputs) {
                try {
                    int value = Integer.parseInt(num);
                    if (value < 1 || value > 1000) throw new NumberFormatException();
                    numbers.add(value);
                } catch (NumberFormatException e) {
                    System.err.println("Invalid integer: " + num);
                }
            }

            int largestNumber = findLargest(numbers);
            System.out.println("The largest number is: " + largestNumber);

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            try {
                reader.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private int findLargest(List<Integer> numbers) {
        return numbers.stream().max(Integer::compare).orElse(0);
    }

