        RecordProcessor processor = new RecordProcessor();
        processor.maxRecords = 1000; // Example configuration
        processor.logLevel = 2.0;
        processor.latencyThreshold = 500;
        processor.remoteAddress = "example.com";
        processor.channelHandlers = new ArrayList<>();

