    if (!storage) return NULL;

    storage->offsets = (long *)calloc(initial_size, sizeof(long));
    storage->keys = (int *)calloc(initial_size, sizeof(int));
    storage->records = (record *)calloc(initial_size, sizeof(record));
    if (!storage->offsets || !storage->keys || !storage->records) {
        free(storage);
        return NULL;
    }

