        }
        storage->offsets[i] = offset;
        storage->keys[i] = key;
    }

    return storage;
}

void destroy_distributed_data_storage(distributed_data_storage *storage) {
    if (!storage) return;

    pthread_mutex_lock(&storage->lock);
    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    pthread_mutex_unlock(&storage->lock);

    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

int add_record(distributed_data_storage *storage, int value) {
    if (!storage || storage->num_records >= MAX_KEYS) return -1;

    pthread_mutex_lock(&storage->lock);
    record new_record = {value};
    storage->records[storage->num_records] = new_record;
    ++storage->num_records;
    pthread_mutex_unlock(&storage->lock);

    return 0;
}

int get_random_value(distributed_data_storage *storage) {
    if (!storage || storage->num_records == 0) return -1;

    int key = rand() % MAX_KEYS;
    for (size_t i = 0; i < storage->num_records; ++i) {
        if (storage->keys[i] == key) {
            pthread_mutex_lock(&storage->lock);
            int value = storage->records[i].value;
            pthread_mutex_unlock(&storage->lock);
            return value;
        }
    }

    return -1;
}
