import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class TokenGenerator {
    private static final SecureRandom secureRandom = new SecureRandom();
    private static final Set<String> tokenCache = ConcurrentHashMap.newKeySet();
    private static final char[] characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?".toCharArray();
    private static final int TOKEN_LENGTH = 32;
    private static long generationSuccessCount = 0;
    private static long generationFailureCount = 0;
    private static long totalGenerationTime = 0;

    public static String generateToken() {
        long startTime = System.nanoTime();
        while (true) {
            String token = generateRandomString();
            if (tokenCache.add(token)) {
                generationSuccessCount++;
                totalGenerationTime += System.nanoTime() - startTime;
                return token;
            }
            generationFailureCount++;
        }
    }

    private static String generateRandomString() {
        StringBuilder sb = new StringBuilder(TOKEN_LENGTH);
        for (int i = 0; i < TOKEN_LENGTH; i++) {
            int randomIndex = secureRandom.nextInt(characters.length);
            sb.append(characters[randomIndex]);
        }
        return sb.toString();
    }

    public static long getGenerationSuccessCount() {
        return generationSuccessCount;
    }

    public static long getGenerationFailureCount() {
        return generationFailureCount;
    }

    public static double getAverageGenerationTime() {
        if (generationSuccessCount == 0) return 0;
        return (double) totalGenerationTime / generationSuccessCount;
    }

    // Add methods for token expiration and invalidation, cleanup, and performance monitoring
}
