#define ARRAY_SIZE 100
#define SEED_INTERVAL 60

typedef struct {
    long offset;
    int key;
} Record;

void* allocate_and_seed_array(void* arg) {
    int size = *(int*)arg;
    Record* array = (Record*)malloc(size * sizeof(Record));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    static unsigned long seed = time(NULL);
    srand(seed);

    for (int i = 0; i < size; ++i) {
        array[i].offset = i;
        array[i].key = rand() % INT_MAX;
    }

    pthread_t reseed_thread;
    if (pthread_create(&reseed_thread, NULL, &reseed_prng, NULL) != 0) {
        perror("Failed to create reseed thread");
        free(array);
        return NULL;
    }

    // Perform operations with the array
    for (int i = 0; i < size; ++i) {
        printf("Offset: %ld, Key: %d\n", array[i].offset, array[i].key);
    }

    pthread_join(reseed_thread, NULL);
    free(array);
    return NULL;
}

void* reseed_prng(void* arg) {
    while (1) {
        sleep(SEED_INTERVAL);
        srand(time(NULL));
    }
    return NULL;
}

int main() {
    int size = ARRAY_SIZE;
    pthread_t allocate_thread;

    if (pthread_create(&allocate_thread, NULL, &allocate_and_seed_array, &size) != 0) {
        perror("Failed to create allocation thread");
        return EXIT_FAILURE;
    }

    pthread_join(allocate_thread, NULL);
    return EXIT_SUCCESS;
}
