    Record* head = NULL;
    Record** current = &head;

    for (size_t i = 0; i < num_records; ++i) {
        // Allocate memory for the new record
        Record* new_record = malloc(sizeof(Record));
        if (new_record == NULL) {
            // Free previously allocated records and return NULL on failure
            while (head != NULL) {
                Record* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        // Initialize record fields
