#define MAX_KEYS 1024

typedef struct {
    long offset;
    int key;
} Record;

struct PRNGState {
    unsigned int seed;
};

PRNGState prng_state;
Record *records[MAX_KEYS];
int record_count = 0;
pthread_mutex_t mutex;

void init_prng(PRNGState *state, unsigned int seed) {
    state->seed = seed;
}

unsigned int xorshift32(unsigned int *state) {
    unsigned int x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return (*state = x);
}

int generate_unique_key() {
    while (1) {
        unsigned int key = xorshift32(&prng_state.seed) % MAX_KEYS;
        if (records[key] == NULL) {
            return key;
        }
    }
}

void *add_record(void *arg) {
    pthread_mutex_lock(&mutex);
    if (record_count >= MAX_KEYS) {
        printf("Error: Maximum number of keys reached.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    int key = generate_unique_key();
    records[key] = malloc(sizeof(Record));
    records[key]->offset = rand(); // Simulate offset generation
    records[key]->key = key;
    record_count++;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    init_prng(&prng_state, time(NULL));

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        printf("Mutex initialization failed.\n");
        return 1;
    }

    for (int i = 0; i < 5; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, add_record, NULL) != 0) {
            printf("Thread creation failed.\n");
            return 1;
        }
        pthread_join(thread, NULL);
    }

    // Clean up
    for (int i = 0; i < MAX_KEYS; i++) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
    pthread_mutex_destroy(&mutex);

    return 0;
}
