#include <pthread.h>

// Define the struct record
typedef struct {
    long offset;
    int key;
} Record;

// Forward declaration of PRNG functions
int performancePRNG();
int qualityPRNG();

// Global variables for thread safety and PRNG re-seeding
Record* records = NULL;
long size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
time_t lastSeededTime = 0;
const time_t RESEED_INTERVAL = 60; // Re-seed every minute

// Function to dynamically allocate memory for an array of struct records
void* createRecords(long numRecords, int prngType) {
    pthread_mutex_lock(&mutex);

    // Check if the number of records has changed since last allocation
    if (numRecords != size) {
        if (records != NULL) {
            free(records);
        }
        records = malloc(numRecords * sizeof(Record));
        size = numRecords;
    }

    if (records == NULL) {
        pthread_mutex_unlock(&mutex);
        perror("Memory allocation failed");
        return NULL;
    }

    // Seed PRNG based on current time if re-seeding interval has passed
    if (time(NULL) - lastSeededTime > RESEED_INTERVAL) {
        srand(time(NULL));
        lastSeededTime = time(NULL);
    }

    // Initialize records using the chosen PRNG
    for (long i = 0; i < numRecords; i++) {
        records[i].offset = i;
        if (prngType == 1) {
            records[i].key = performancePRNG();
        } else {
            records[i].key = qualityPRNG();
        }
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

// Example PRNG functions
int performancePRNG() {
    return rand();
}

int qualityPRNG() {
    // Higher quality random number generation logic here
    return rand_r((unsigned int*)time(NULL));
}
