// Define a structure to hold encryption keys
typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *digest_ctx;
} EncryptionKey;

// Function to initialize an encryption key
EncryptionKey* init_encryption_key(EVP_CIPHER *cipher, EVP_MD *digest) {
    EncryptionKey *key = (EncryptionKey *)malloc(sizeof(EncryptionKey));
    key->cipher_ctx = EVP_CIPHER_CTX_new();
    key->digest_ctx = EVP_MD_CTX_new();

    if (!EVP_EncryptInit_ex(key->cipher_ctx, cipher, NULL, NULL, NULL) ||
        !EVP_DigestInit_ex(key->digest_ctx, digest, NULL)) {
        free(key);
        return NULL;
    }

    return key;
}

// Function to clean up an encryption key
void cleanup_encryption_key(EncryptionKey *key) {
    if (key->cipher_ctx) EVP_CIPHER_CTX_free(key->cipher_ctx);
    if (key->digest_ctx) EVP_MD_CTX_free(key->digest_ctx);
    free(key);
}

// Function to generate a random key between 1 and 1000
int generate_random_key() {
    int key;
    while ((RAND_bytes((unsigned char *)&key, sizeof(int)) != 1) ||
           (key < 1) || (key > 1000)) {
        // Retry on failure or invalid range
    }
    return key;
}

// Function to hash a string using SHA-256
void hash_string(const unsigned char *input, int length, unsigned char *output) {
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (!EVP_DigestInit_ex(ctx, EVP_sha256(), NULL) ||
        !EVP_DigestUpdate(ctx, input, length) ||
        !EVP_DigestFinal_ex(ctx, output, NULL)) {
        fprintf(stderr, "Hashing failed\n");
    }
    EVP_MD_CTX_free(ctx);
}

// Function to encrypt data using AES-256-CBC
int encrypt_data(const unsigned char *input, int input_len, unsigned char *output,
                 EncryptionKey *key) {
    if (!EVP_EncryptUpdate(key->cipher_ctx, output, &output_len, input, input_len)) {
        return 0;
    }
    if (!EVP_EncryptFinal_ex(key->cipher_ctx, output + output_len, &output_len)) {
        return 0;
    }
    return 1;
}

// Function to decrypt data using AES-256-CBC
int decrypt_data(const unsigned char *input, int input_len, unsigned char *output,
                 EncryptionKey *key) {
    if (!EVP_DecryptUpdate(key->cipher_ctx, output, &output_len, input, input_len)) {
        return 0;
    }
    if (!EVP_DecryptFinal_ex(key->cipher_ctx, output + output_len, &output_len)) {
        return 0;
    }
    return 1;
}

// Function to handle concurrent access with locking
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* thread_safe_store(void *arg) {
    pthread_mutex_lock(&lock);
    // Perform data storage operation here
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    EVP_CIPHER *cipher = EVP_aes_256_cbc();
    EVP_MD *digest = EVP_sha256();

    EncryptionKey *key = init_encryption_key(cipher, digest);
    if (!key) {
        fprintf(stderr, "Failed to initialize encryption key\n");
        return 1;
    }

    unsigned char input[] = "Hello, World!";
    unsigned char output[1024];

    int encrypted_len = encrypt_data(input, sizeof(input), output, key);
    if (encrypted_len > 0) {
        printf("Encrypted data: ");
        for (int i = 0; i < encrypted_len; i++) {
            printf("%02x", output[i]);
        }
        printf("\n");

        unsigned char decrypted[1024];
        int decrypted_len = decrypt_data(output, encrypted_len, decrypted, key);
        if (decrypted_len > 0) {
            printf("Decrypted data: %s\n", decrypted);
        } else {
            fprintf(stderr, "Decryption failed\n");
        }
    } else {
        fprintf(stderr, "Encryption failed\n");
    }

    cleanup_encryption_key(key);

    return 0;
}
