#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    int key;
    long offset;
} Record;

typedef struct Node {
    Record* data;
    struct Node* next;
} Node;

Node* create_node(Record* record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = record;
    new_node->next = NULL;
    return new_node;
}

Node* init_database(int key_count, int seed, long offset_range_start, long offset_range_end, int value_min, int value_max) {
    srand(seed);

    Node* head = NULL;
    for (int i = 0; i < key_count; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        record->value = rand() % (value_max - value_min + 1) + value_min;
        record->key = i;
        record->offset = rand() % (offset_range_end - offset_range_start + 1) + offset_range_start;

        Node* new_node = create_node(record);
        if (!head) {
            head = new_node;
        } else {
            Node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    return head;
}

void free_database(Node* head) {
    Node* current = head;
    Node* next;
    while (current) {
        Record* record = current->data;
        free(record);
        next = current->next;
        free(current);
        current = next;
    }
}
