#include <stdlib.h>
#include <time.h>

typedef struct {
    int duration;
} Task;

long* timestamps;
int* priorities;
Task* tasks;
size_t capacity;
size_t size;

void init_task_scheduler(size_t initial_capacity) {
    capacity = initial_capacity;
    size = 0;

    timestamps = (long*)malloc(capacity * sizeof(long));
    if (!timestamps) {
        perror("Failed to allocate memory for timestamps");
        exit(EXIT_FAILURE);
    }

    priorities = (int*)malloc(capacity * sizeof(int));
    if (!priorities) {
        free(timestamps);
        perror("Failed to allocate memory for priorities");
        exit(EXIT_FAILURE);
    }

    tasks = (Task*)malloc(capacity * sizeof(Task));
    if (!tasks) {
        free(timestamps);
        free(priorities);
        perror("Failed to allocate memory for tasks");
        exit(EXIT_FAILURE);
    }
}

void resize_task_scheduler(size_t new_capacity) {
    long* new_timestamps = (long*)realloc(timestamps, new_capacity * sizeof(long));
    if (!new_timestamps) {
        perror("Failed to reallocate memory for timestamps");
        return;
    }

    int* new_priorities = (int*)realloc(priorities, new_capacity * sizeof(int));
    if (!new_priorities) {
        free(new_timestamps);
        perror("Failed to reallocate memory for priorities");
        return;
    }

    Task* new_tasks = (Task*)realloc(tasks, new_capacity * sizeof(Task));
    if (!new_tasks) {
        free(new_timestamps);
        free(new_priorities);
        perror("Failed to reallocate memory for tasks");
        return;
    }

    timestamps = new_timestamps;
    priorities = new_priorities;
    tasks = new_tasks;
    capacity = new_capacity;
}

void add_task(int duration_range_min, int duration_range_max) {
    if (size == capacity) {
        resize_task_scheduler(capacity * 2);
    }

    tasks[size].duration = duration_range_min + rand() % (duration_range_max - duration_range_min + 1);
    timestamps[size] = time(NULL);
    priorities[size] = rand() % 10; // Simplified priority generation

    size++;
}

void validate_task_scheduler() {
    for (size_t i = 0; i < size; i++) {
        if (tasks[i].duration <= 0) {
            fprintf(stderr, "Task duration is invalid at index %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }
}
