#include <time.h>

typedef struct {
    uint64_t sessionID;
    time_t expiration;
    uint32_t activity;
} userSession;

userSession* allocateUserSessions(size_t numSessions, int minRandom, int maxRandom) {
    if (numSessions == 0 || minRandom > maxRandom) return NULL;

    // Allocate memory for the user sessions
    userSession *sessions = (userSession *)malloc(numSessions * sizeof(userSession));
    if (sessions == NULL) return NULL;

    // Seed the random number generator
    srand(time(NULL));

    // Initialize each session with a unique ID, expiration time, and random activity count
    for (size_t i = 0; i < numSessions; ++i) {
        sessions[i].sessionID = rand();
        sessions[i].expiration = time(NULL) + 3600; // Expires in one hour
        sessions[i].activity = minRandom + rand() % (maxRandom - minRandom + 1);
    }

    return sessions;
}

void invalidateExpiredSessions(userSession *sessions, size_t numSessions, uint32_t interactionsThreshold) {
    for (size_t i = 0; i < numSessions; ++i) {
        if ((time(NULL) - sessions[i].expiration) > interactionsThreshold) {
            // Invalidate the session
            sessions[i].sessionID = 0;
            sessions[i].activity = 0;
        }
    }
}

void freeUserSessions(userSession *sessions, size_t numSessions) {
    if (sessions != NULL) {
        free(sessions);
    }
}
```

