    for (int i = 0; i < size; ++i) {
        records[i].offset = i;
        records[i].key = rand() % 1000; // Example key generation
        records[i].counter = (uint32_t)(rand() % (range_end - range_start + 1)) + range_start;
    }
}

void reset_counters(record* records, int size) {
    for (int i = 0; i < size; ++i) {
        records[i].counter = 0;
    }
}

void simulate_latency(int delay_ms) {
    usleep(delay_ms * 1000); // Convert milliseconds to microseconds
}

void process_records(record* records, int size, int range_start, int range_end, int latency_ms, int use_efficient_rand) {
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < size; ++i) {
        if (use_efficient_rand) {
            // Use a more efficient random number generation algorithm
            records[i].counter = (uint32_t)(rand() % (range_end - range_start + 1)) + range_start;
        } else {
            // Use the standard rand() function
            records[i].counter++;
        }

        if ((i + 1) % CHECKPOINT_INTERVAL == 0) {
