long* allocateLongArray(size_t size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocateIntArray(size_t size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecordArray(size_t size) {
    return (record*)malloc(size * sizeof(record));
}

void initializeArrays(long** offsets, int** keys, record** records, size_t size, unsigned long seed) {
    srand(seed);

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % 1024;
        do {
            keys[i] = rand() % 1024;
        } while (keys[i] == *keys); // Ensure uniqueness
        records[i].value = rand() % 1000 + 1; // Range from 1 to 1000
    }
}

void cleanup(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int findLargestInteger(int arr[], size_t size) {
    if (size == 0) return -1; // Handle empty array
    int largest = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

int main() {
    size_t size = 1000;
    long* offsets = allocateLongArray(size);
    int* keys = allocateIntArray(size);
    record* records = allocateRecordArray(size, time(NULL)); // Seed with current time for randomness

    initializeArrays(&offsets, &keys, &records, size, time(NULL)); // Optionally use a custom seed

    // Use the arrays...

    cleanup(offsets, keys, records);

    int inputSize;
    printf("Enter number of integers: ");
    scanf("%zu", &inputSize);
    int* inputArray = (int*)malloc(inputSize * sizeof(int));

    for (size_t i = 0; i < inputSize; ++i) {
        printf("Enter integer %zu: ", i + 1);
        if (scanf("%d", &inputArray[i]) != 1) {
            // Handle invalid input
            fprintf(stderr, "Invalid input. Exiting.\n");
            free(inputArray);
            return 1;
        }
    }

    int largest = findLargestInteger(inputArray, inputSize);
    printf("Largest integer: %d\n", largest);

    free(inputArray);
    return 0;
}
