import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Random;
import java.util.Scanner;

public class TaskManager {
    private long[] timestamps;
    private int[] taskIDs;
    private float[] priorityLevels;
    private ConcurrentHashMap<Integer, Boolean> usedTaskIDs;
    private Random prng;
    private int maxTasks;
    private static final int MAX_PRIORITY = 10;
    private static final int MIN_ID = 1;
    private static final int MAX_ID = 1023;

    public TaskManager(int maxTasks) {
        this.maxTasks = maxTasks;
        timestamps = new long[maxTasks];
        taskIDs = new int[maxTasks];
        priorityLevels = new float[maxTasks];
        usedTaskIDs = new ConcurrentHashMap<>();
        prng = new Random();
    }

    public void distributeTasks(List<Integer> taskSet, int clusterSize) {
        if (taskSet.size() > maxTasks) {
            throw new IllegalArgumentException("Too many tasks for the system.");
        }

        for (int task : taskSet) {
            int taskId;
            do {
                taskId = prng.nextInt(MAX_ID - MIN_ID + 1) + MIN_ID;
            } while (!usedTaskIDs.putIfAbsent(taskId, true));

            timestamps[taskId] = System.currentTimeMillis();
            priorityLevels[taskId] = prng.nextFloat() * MAX_PRIORITY;
        }

        // Simulate task execution and cleanup
        for (int taskId : usedTaskIDs.keySet()) {
            try {
                // Simulate task execution time
                Thread.sleep((long) (priorityLevels[taskId] * 100));
                System.out.println("Task " + taskId + " completed.");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                usedTaskIDs.remove(taskId);
                prng.setSeed(System.currentTimeMillis()); // Reset PRNG seed for security
            }
        }
    }

    public float findMedian(int[] numbers) {
        Arrays.sort(numbers);
        int n = numbers.length;
        if (n % 2 == 0)
            return (numbers[n / 2 - 1] + numbers[n / 2]) / 2.0f;
        else
            return numbers[n / 2];
    }

    public static void main(String[] args) {
        TaskManager manager = new TaskManager(100);
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter task set (comma-separated integers):");
        String input = scanner.nextLine();
        List<Integer> tasks = Arrays.stream(input.split(","))
                                    .mapToInt(Integer::parseInt)
                                    .boxed()
                                    .collect(Collectors.toList());

        manager.distributeTasks(tasks, 5); // Assuming a cluster of 5 nodes for demonstration
        int[] numbers = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
        System.out.println("Median: " + manager.findMedian(numbers));
    }
}
```

This code provides a basic implementation of the task distribution and median calculation. It includes error handling for allocation failures and ensures partial operations are properly rolled back. The `distributeTasks` method dynamically adjusts its behavior based on the maximum number of tasks allowed, ensuring thread safety through concurrent collections, and handles concurrency by simulating task execution and cleanup. Memory management is optimized for a large number of tasks, and performance considerations guide implementation choices.']

