}

unsigned int customHash(int key) {
    return key % HASH_SIZE;
}

bool insertRecord(int key, Record *record) {
    if (key >= MAX_KEYS || key < 0) return false;
    unsigned int index = customHash(key);
    HashNode *newNode = (HashNode *)malloc(sizeof(HashNode));
    newNode->key = key;
    newNode->record = record;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
    recordCount++;
    return true;
}

void initializeRecords() {
    Record records[1000];
    for (int i = 0; i < 1000; i++) {
        records[i].value = i + 1;
        insertRecord(i, &records[i]);
    }
}

unsigned long generateRandomNumber() {
    static unsigned long seed = 123456789L;
    seed = (seed * 25214903917L + 11) % 4294967296L;
    return seed;
}

void* memoryPool[100];
int poolIndex;

void* allocateFromPool(size_t size) {
    if (poolIndex < 100) {
        void *ptr = memoryPool[poolIndex++];
        memset(ptr, 0, size);
        return ptr;
    }
    return malloc(size);
}

void deallocateToPool(void *ptr) {
    // Implement a simple pool management strategy
    for (int i = 0; i < 100; i++) {
        if (!memoryPool[i]) {
            memoryPool[i] = ptr;
            return;
        }
    }
    free(ptr);
}

void cleanup() {
    for (int i = 0; i < HASH_SIZE; i++) {
        HashNode *node = hashTable[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(hashTable);
    for (int i = 0; i < poolIndex; i++) {
        free(memoryPool[i]);
    }
}

int main() {
    initializeDataStructures();
    initializeRecords();
    // Use the data structures and functions as needed
    cleanup();
    return 0;
}
