// Function to generate random value and ensure uniqueness
int generate_unique_random() {
    static int numbers[1000];
    static int count = 0;
    if (count == 0) {
        srand(time(NULL));
        for (int i = 0; i < 1000; ++i) {
            numbers[i] = rand() % 1000 + 1;
        }
        count = 1000;
    }
    int index = rand() % count;
    int value = numbers[index];
    numbers[index] = numbers[--count];
    return value;
}

// Function to initialize array of records
Record* init_records(int num_records) {
    Record *records = (Record*)calloc(num_records, sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }
    int unique_keys[MAX_KEYS] = {0};
    int key_count = 0;
    while (key_count < num_records) {
        int key = rand() % MAX_KEYS;
        if (!used_keys[key] && !unique_keys[key]) {
