Ledger* create_ledger() {
    Ledger* ledger = (Ledger*)malloc(sizeof(Ledger));
    if (!ledger) return NULL;

    ledger->offsets = (long*)calloc(MAX_KEYS, sizeof(long));
    if (!ledger->offsets) goto cleanup_keys;

    ledger->keys = (KeyMapEntry*)calloc(MAX_KEYS, sizeof(KeyMapEntry));
    if (!ledger->keys) goto cleanup_offsets;

    srand(time(NULL));
    for (size_t i = 0; i < MAX_KEYS; ++i) {
        ledger->keys[i].key = -1;
        ledger->keys[i].used = 0;
    }

    return ledger;

cleanup_offsets:
    free(ledger->offsets);
cleanup_keys:
    free(ledger->keys);
    free(ledger);

    return NULL;
}

void destroy_ledger(Ledger* ledger) {
    if (!ledger) return;

    free(ledger->offsets);
    free(ledger->keys);
    free(ledger);
}

void process_transactions(Ledger* ledger, size_t num_transactions) {
    for (size_t i = 0; i < num_transactions; ++i) {
        double amount = 10.0 + ((double)rand() / RAND_MAX) * 990.0;
        Transaction transaction = {amount};

        // Simulate storing the transaction
