        // Simulate updating used keys
        int key = rand() % MAX_KEYS;
        while (ledger->keys[key].used) {
            key = rand() % MAX_KEYS;
        }
        ledger->keys[key].key = i;
        ledger->keys[key].used = 1;
    }
}

double calculate_total_volume(Ledger* ledger, size_t num_transactions) {
    double total_volume = 0.0;
    for (size_t i = 0; i < num_transactions; ++i) {
        total_volume += ledger->transactions[i].amount;
    }
    return total_volume;
}

