} DataStructures;

DataStructures* create_data_structures(size_t size) {
    DataStructures* ds = (DataStructures*)malloc(sizeof(DataStructures));
    if (!ds) return NULL;

    ds->offset = 0;
    ds->keys = (int*)malloc(size * sizeof(int));
    if (!ds->keys) {
        free(ds);
        return NULL;
    }

    ds->records = (Record**)malloc(size * sizeof(Record*));
    if (!ds->records) {
        free(ds->keys);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        ds->keys[i] = rand();
        ds->records[i] = (Record*)malloc(sizeof(Record));
        if (!ds->records[i]) {
            for (size_t j = 0; j < i; ++j) free(ds->records[j]);
            free(ds->keys);
            free(ds);
            return NULL;
        }
        ds->records[i]->value = rand();
    }

    ds->size = size;
    return ds;
}

void update_record(DataStructures* ds, int index, int new_value) {
    if (index < 0 || index >= ds->size) return;
    ds->records[index]->value = new_value;
}

void delete_record(DataStructures* ds, int index) {
    if (index < 0 || index >= ds->size) return;

    free(ds->records[index]);
    for (int i = index; i < ds->size - 1; ++i) {
        ds->keys[i] = ds->keys[i + 1];
        ds->records[i] = ds->records[i + 1];
    }
    ds->size--;
}

void destroy_data_structures(DataStructures* ds) {
    for (size_t i = 0; i < ds->size; ++i) free(ds->records[i]);
    free(ds->keys);
    free(ds->records);
    free(ds);
}
