typedef struct {
    int value;
} record;

#define MIN_SIZE 1024

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
    // Configuration for random number generation
    int min_range;
    int max_range;
} array_system;

array_system *create_array_system(int initial_size) {
    array_system *system = malloc(sizeof(array_system));
    if (system == NULL) return NULL;

    system->offsets = malloc(initial_size * sizeof(long));
    system->keys = malloc(initial_size * sizeof(int));
    system->records = malloc(initial_size * sizeof(record *));
    system->allocated_size = initial_size;
    system->used_size = 0;
    pthread_mutex_init(&system->lock, NULL);
    system->min_range = INT_MIN;
    system->max_range = INT_MAX;

    return system;
}

void free_array_system(array_system *system) {
    for (size_t i = 0; i < system->allocated_size; i++) {
        free(system->records[i]);
    }
    free(system->offsets);
    free(system->keys);
    free(system->records);
    pthread_mutex_destroy(&system->lock);
    free(system);
}

int resize_array_system(array_system *system, size_t new_size) {
    long *new_offsets = realloc(system->offsets, new_size * sizeof(long));
    int *new_keys = realloc(system->keys, new_size * sizeof(int));
    record **new_records = realloc(system->records, new_size * sizeof(record *));

    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        return -1; // Memory allocation failed
    }

    system->offsets = new_offsets;
    system->keys = new_keys;
    system->records = new_records;
    system->allocated_size = new_size;

    return 0;
}

int add_record(array_system *system, long offset, int key, int value) {
    pthread_mutex_lock(&system->lock);

    if (system->used_size >= system->allocated_size && resize_array_system(system, system->allocated_size * 2) != 0) {
        pthread_mutex_unlock(&system->lock);
        return -1; // Resize failed
    }

    system->offsets[system->used_size] = offset;
    system->keys[system->used_size] = key;
    record *new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        pthread_mutex_unlock(&system->lock);
        return -1; // Memory allocation failed
    }
    new_record->value = value;
    system->records[system->used_size] = new_record;

    system->used_size++;
    pthread_mutex_unlock(&system->lock);

    return 0;
}

int update_range(array_system *system, int min_range, int max_range) {
    pthread_mutex_lock(&system->lock);
    system->min_range = min_range;
    system->max_range = max_range;
    pthread_mutex_unlock(&system->lock);

    return 0;
}

// Function to generate a random number within the configured range
int generate_random(array_system *system) {
    pthread_mutex_lock(&system->lock);
    int random_number = rand() % (system->max_range - system->min_range + 1) + system->min_range;
    pthread_mutex_unlock(&system->lock);

    return random_number;
}

// Function to securely seed the random number generators
void secure_seed(array_system *system) {
    srand(time(NULL)); // Using time as a seed for simplicity; in real applications, use more secure sources
}

// Logging mechanism (example implementation)
void log_event(const char *event, const char *error_code) {
    // Log format: "Timestamp - Event - Error Code"
    printf("%s - %s - %s\n", timestamp(), event, error_code);
}

const char *timestamp() {
    static char buffer[100];
    time_t now = time(NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    return buffer;
}
