use std::sync::{Arc, Mutex};
use rand::prelude::*;
use std::env;
use std::fs;

fn distribute_tasks(max_tasks: usize) -> Result<(), Box<dyn std::error::Error>> {
    let used_ids = Arc::new(Mutex::new(Vec::new()));
    let long_timestamps: Vec<u64> = vec![0; max_tasks];
    let task_ids: Vec<i32> = vec![0; max_tasks];
    let priority_levels: Vec<f32> = vec![0.0; max_tasks];

    for i in 0..max_tasks {
        let mut rng = StdRng::from_entropy();
        loop {
            let id = rng.gen_range(1, 1024);
            if !used_ids.lock()?.contains(&id) {
                used_ids.lock()?.push(id);
                task_ids[i] = id;
                priority_levels[i] = (rng.gen_range(1, 11) as f32 / 10.0);
                break;
            }
        }
    }

    let input: String = std::io::stdin().lines().next().unwrap()?;
    let numbers: Vec<i32> = input
        .split_whitespace()
        .filter_map(|s| s.parse::<i32>().ok())
        .collect();

    if !numbers.is_empty() {
        let median = find_median(&numbers);
        println!("Median value: {}", median);
    } else {
        eprintln!("Error: Empty or invalid input");
    }

    Ok(())
}

fn find_median(numbers: &[i32]) -> f64 {
    let mut sorted_numbers = numbers.to_vec();
    sorted_numbers.sort_unstable();
    if sorted_numbers.len() % 2 == 0 {
        (sorted_numbers[sorted_numbers.len() / 2 - 1] as f64 + sorted_numbers[sorted_numbers.len() / 2] as f64) / 2.0
    } else {
        sorted_numbers[sorted_numbers.len() / 2] as f64
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let max_tasks: usize = match env::var("MAX_TASKS") {
        Ok(value) => value.parse::<usize>()?,
        Err(_) => 100,
    };

    distribute_tasks(max_tasks)?;

    let dir_name = "new_directory";
    fs::create_dir(dir_name)?;
    env::set_var("DIRECTORY_PATH", dir_name);

    if let Some(path) = env::var_os("DIRECTORY_PATH") {
        println!("Environment variable 'DIRECTORY_PATH' set to: {:?}", path);
    } else {
        eprintln!("Error: Environment variable 'DIRECTORY_PATH' not set");
    }

    Ok(())
}
