} AccountPool;

AccountPool *account_pool;

unsigned int generate_unique_id() {
    static unsigned int current_id = 0;
    return ++current_id % MAX_ACCOUNTS;
}

void init_account_pool() {
    account_pool = (AccountPool *)malloc(sizeof(AccountPool));
    pthread_mutex_init(&account_pool->lock, NULL);
    for (int i = 0; i < MAX_ACCOUNTS; i++) {
        account_pool->accounts[i].id = 0;
        memset(account_pool->accounts[i].session_token, 0, SESSION_TOKEN_LENGTH);
    }
}

unsigned int get_unique_id() {
    unsigned int id;
    pthread_mutex_lock(&account_pool->lock);
    do {
        id = generate_unique_id();
    } while (account_pool->accounts[id].id != 0);
    account_pool->accounts[id].id = id + 1;
    pthread_mutex_unlock(&account_pool->lock);
    return id;
}

void assign_session_token(unsigned int id) {
    pthread_mutex_lock(&account_pool->lock);
    sprintf(account_pool->accounts[id].session_token, "%u", id); // Simplified for demonstration
    pthread_mutex_unlock(&account_pool->lock);
}

void cleanup_account_pool() {
    pthread_mutex_destroy(&account_pool->lock);
    free(account_pool);
}

int main() {
    init_account_pool();

    unsigned int account_id = get_unique_id();
    assign_session_token(account_id);

    printf("Account ID: %u, Session Token: %s\n", account_id, account_pool->accounts[account_id].session_token);

    cleanup_account_pool();
    return 0;
}
