// Assuming a mock distributed database class for demonstration purposes
class DistributedDB {
public:
    bool storeAttackHistory(const std::string& attackKey, const std::string& userId) {
        // Simulate successful storage
        return true;
    }
};

// Mock logging service for demonstration purposes
class LoggingService {
public:
    void logAttackSelection(const std::string& attackKey, const std::string& userId) {
        std::cout << "Logging attack selection: " << attackKey << " by user " << userId << std::endl;
    }
};

class AttackManager {
private:
    static constexpr int MAX_KEY = 1023;
    std::vector<int> usedKeys;
    std::mutex keysMutex;
    DistributedDB db;
    LoggingService logger;
    std::atomic_int64_t lastAttackTime;

public:
    AttackManager() : lastAttackTime(0) {}

    void selectAttack(const std::string& userId) {
        auto now = std::chrono::system_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - std::chrono::time_point_cast<std::chrono::seconds>(lastAttackTime)).count() < 9) {
            // Cooldown period not yet expired
            return;
        }

        int attackKey = generateUniqueKey();

        // Log the attack selection
        logger.logAttackSelection(std::to_string(attackKey), userId);

        // Store in distributed database
        db.storeAttackHistory(std::to_string(attackKey), userId);

        lastAttackTime = std::chrono::system_clock::now();
    }

private:
    int generateUniqueKey() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, MAX_KEY);

        while (true) {
            int key = dis(gen);
            if (isKeyAvailable(key)) {
                markKeyAsUsed(key);
                return key;
            }
        }
    }

    bool isKeyAvailable(int key) {
        std::lock_guard<std::mutex> lock(keysMutex);
        return std::find(usedKeys.begin(), usedKeys.end(), key) == usedKeys.end();
    }

    void markKeyAsUsed(int key) {
        std::lock_guard<std::mutex> lock(keysMutex);
        usedKeys.push_back(key);
    }
};

int main() {
    AttackManager attackManager;
    // Simulate player attacks
    for (int i = 0; i < 15; ++i) {
        std::string userId = "user" + std::to_string(i % 10); // Simulated user IDs
        attackManager.selectAttack(userId);
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate time passing between attacks
    }
    return 0;
}
