public class PacketProcessor {
    private Cipher aes128Cbc;
    private Cipher aes256Ecb;
    private Cipher nullCipher;

    public PacketProcessor() throws Exception {
        aes128Cbc = Cipher.getInstance("AES/CBC/PKCS5Padding");
        aes256Ecb = Cipher.getInstance("AES/ECB/PKCS5Padding");
        nullCipher = Cipher.getInstance("NoPadding");
    }

    public byte[] processPacket(byte[] packet, String mode, String key, String iv) throws Exception {
        if ("aes128-cbc".equals(mode)) {
            aes128Cbc.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(key.getBytes(), "AES"), new IvParameterSpec(iv.getBytes()));
            return aes128Cbc.doFinal(packet);
        } else if ("aes256-ecb".equals(mode)) {
            aes256Ecb.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(key.getBytes(), "AES"));
            return aes256Ecb.doFinal(packet);
        } else if ("null".equals(mode)) {
            nullCipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(new byte[0], "Null"));
            return nullCipher.doFinal(packet);
        } else {
            throw new IllegalArgumentException("Unsupported encryption mode: " + mode);
        }
    }

    public byte[] decryptPacket(byte[] packet, String mode, String key, String iv) throws Exception {
        if ("aes128-cbc".equals(mode)) {
            aes128Cbc.init(Cipher.DECRYPT_MODE, new SecretKeySpec(key.getBytes(), "AES"), new IvParameterSpec(iv.getBytes()));
            return aes128Cbc.doFinal(packet);
        } else if ("aes256-ecb".equals(mode)) {
            aes256Ecb.init(Cipher.DECRYPT_MODE, new SecretKeySpec(key.getBytes(), "AES"));
            return aes256Ecb.doFinal(packet);
        } else if ("null".equals(mode)) {
            nullCipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(new byte[0], "Null"));
            return nullCipher.doFinal(packet);
        } else {
