    return array;
}

long find_largest(long *array, int count) {
    if (!array || count <= 0) {
        fprintf(stderr, "Invalid input\n");
        exit(EXIT_FAILURE);
    }

    long largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

EVP_CIPHER *get_cipher(const char *mode) {
    EVP_CIPHER *cipher = NULL;
    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb();
    }

    if (!cipher) {
        fprintf(stderr, "Invalid cipher mode\n");
        exit(EXIT_FAILURE);
    }

    return cipher;
}

int generate_session_token(unsigned long *token) {
    if (RAND_bytes((unsigned char *)token, sizeof(*token)) != 1) {
        fprintf(stderr, "Failed to generate session token\n");
        return -1;
    }

    return 0;
}

void *session_thread(void *arg) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        perror("Memory allocation failed");
        pthread_exit(NULL);
    }

    if (generate_session_token(&record->token) != 0) {
        free(record);
        pthread_exit(NULL);
    }

    // Simulate session management and data integrity checks
    printf("Session token: %lu\n", record->token);

    // Free allocated memory
    free(record);

    pthread_exit(NULL);
}

int main() {
    long *array = read_integers();
    int count = (int)(sizeof(array) / sizeof(array[0]));
    long largest = find_largest(array, count);
    printf("Largest integer: %ld\n", largest);

    // Example usage of cipher and session management
    const char *mode = "ECB";
    EVP_CIPHER *cipher = get_cipher(mode);

    pthread_t thread;
    if (pthread_create(&thread, NULL, session_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    // Free allocated memory for integers array
    free(array);

    return EXIT_SUCCESS;
}
