#define NUM_THREADS 10
#define MAX_IDENTIFIER_LENGTH 8
#define MAX_TRANSACTION_COUNT 100

typedef struct {
    float amount;
    char identifier[MAX_IDENTIFIER_LENGTH];
} Transaction;

unsigned long* serial_numbers;
char** identifiers;
float* values;
Transaction* transactions;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int transaction_count = 0;
int* used_identifiers;
int used_identifier_count = 0;

unsigned long generate_serial_number() {
    return rand();
}

void generate_unique_identifier(char* identifier) {
    do {
        sprintf(identifier, "%08lX", generate_serial_number());
    } while (used_identifier_exists(identifier));
    add_used_identifier(identifier);
}

int used_identifier_exists(const char* identifier) {
    for (int i = 0; i < used_identifier_count; i++) {
        if (strcmp(used_identifiers[i], identifier) == 0) {
            return 1;
        }
    }
    return 0;
}

void add_used_identifier(const char* identifier) {
    pthread_mutex_lock(&mutex);
    used_identifiers[used_identifier_count++] = strdup(identifier);
    pthread_mutex_unlock(&mutex);
}

float generate_random_amount() {
    return ((float)rand() / RAND_MAX) * 1000.0f;
}

void initialize_transactions() {
    transactions = (Transaction*)malloc(MAX_TRANSACTION_COUNT * sizeof(Transaction));
    for (int i = 0; i < MAX_TRANSACTION_COUNT; i++) {
        transactions[i].amount = generate_random_amount();
        generate_unique_identifier(transactions[i].identifier);
    }
}

void cleanup_memory() {
    free(serial_numbers);
    for (int i = 0; i < used_identifier_count; i++) {
        free(used_identifiers[i]);
    }
    free(used_identifiers);
    free(values);
    free(transactions);
}

void* thread_function(void* arg) {
    int thread_id = *(int*)arg;
    srand(time(NULL) + thread_id); // Seed PRNG differently for each thread
    initialize_transactions();
    cleanup_memory();
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS];

    serial_numbers = (unsigned long*)malloc(10 * sizeof(unsigned long));
    identifiers = (char**)malloc(10 * sizeof(char*));
    used_identifiers = (int*)malloc(10 * sizeof(int));

    for (int i = 0; i < 10; i++) {
        identifiers[i] = (char*)malloc(MAX_IDENTIFIER_LENGTH + 1);
        used_identifiers[i] = -1;
    }

    values = (float*)malloc(10 * sizeof(float));

    for (int i = 0; i < NUM_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_memory();

    return 0;
}
