#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ArrayManager;

ArrayManager* array_manager_create(size_t initial_capacity) {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    if (!manager->offsets || !manager->keys || !manager->records) {
        array_manager_free(manager);
        return NULL;
    }

    return manager;
}

void array_manager_free(ArrayManager* manager) {
    if (manager) {
        free(manager->offsets);
        free(manager->keys);
        for (size_t i = 0; i < manager->size; ++i) {
            free(manager->records[i]);
        }
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int array_manager_add_record(ArrayManager* manager, int* key_out) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        long* new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
        int* new_keys = realloc(manager->keys, new_capacity * sizeof(int));
        Record** new_records = realloc(manager->records, new_capacity * sizeof(Record*));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (manager->size > 0 && array_manager_contains_key(manager, key));

    manager->offsets[manager->size] = manager->size * sizeof(Record);
    manager->keys[manager->size] = key;
    manager->records[manager->size] = (Record*)malloc(sizeof(Record));
    if (!manager->records[manager->size]) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failed
    }

    *key_out = key;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int array_manager_contains_key(ArrayManager* manager, int key) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

// Example usage:
int main() {
    ArrayManager* manager = array_manager_create(10);
    if (!manager) {
        fprintf(stderr, "Failed to create array manager\n");
        return 1;
    }

    int key;
    for (size_t i = 0; i < 20; ++i) {
        if (array_manager_add_record(manager, &key) == -1) {
            fprintf(stderr, "Failed to add record\n");
            break;
        }
        printf("Added record with key: %d\n", key);
    }

    array_manager_free(manager);
    return 0;
}
```

