    if (num_used_keys >= MAX_KEYS) {
        fprintf(stderr, "Maximum number of records reached\n");
        exit(1);
    }
    array_records[key].value = rand();
    num_used_keys++;
    pthread_mutex_unlock(&lock);
}

void cleanup() {
