    unsigned long current_time = (unsigned long)now;

    while (1) {
        seed = xorshift128plus(seed, current_time);
        int id = seed % MAX_TRANSACTIONS;

        if (!timestamps[id] || timestamps[id] < current_time - TIME_WINDOW) {
            return id;
        }
    }
}

void create_transaction(int operation_id) {
    int transaction_id = generate_transaction_id();

    timestamps[transaction_id] = time(NULL);
    counters[transaction_id]++;
    transactions[transaction_id] = (Transaction*)malloc(sizeof(Transaction));
    transactions[transaction_id]->transaction_id = transaction_id;

    // Simulate some processing
    usleep(100); // 100 microseconds
}

