import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.codec.LengthFieldBasedFrameDecoder;
import io.netty.handler.codec.LengthFieldPrepender;
import io.netty.handler.timeout.IdleStateHandler;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class NettyClient {
    private static final Logger logger = LoggerFactory.getLogger(NettyClient.class);
    private EventLoopGroup workerGroup;
    private Channel channel;
    private ExecutorService executorService;
    private Map<Integer, Long> keyOffsetMap;

    public NettyClient() {
        workerGroup = new NioEventLoopGroup();
        executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        keyOffsetMap = new ConcurrentHashMap<>();
    }

    public void connect(String host, int port) throws Exception {
        Bootstrap b = new Bootstrap();
        b.group(workerGroup);
        b.channel(NioSocketChannel.class);
        b.option(ChannelOption.SO_KEEPALIVE, true);
        b.handler(new ChannelInitializer<SocketChannel>() {
            @Override
            public void initChannel(SocketChannel ch) throws Exception {
                ChannelPipeline p = ch.pipeline();
                p.addLast(new LengthFieldPrepender(4));
                p.addLast(new LengthFieldBasedFrameDecoder(Integer.MAX_VALUE, 0, 4, 0, 4));
                p.addLast(new IdleStateHandler(0, 0, 30, TimeUnit.SECONDS));
                p.addLast(new ClientHandler(keyOffsetMap, executorService));
            }
        });

        channel = b.connect(host, port).sync().channel();
    }

    public void allocateAndInitializeKeys(int numKeys) {
        Random random = new SecureRandom();
        Set<Integer> keys = new HashSet<>();

        while (keys.size() < numKeys) {
            int key = random.nextInt(1024);
            if (!keyOffsetMap.containsKey(key)) {
                keys.add(key);
            }
        }

        for (int key : keys) {
            long offset = generateRandomOffset();
            keyOffsetMap.put(key, offset);
        }
    }

    private long generateRandomOffset() {
        Random random = new SecureRandom();
        return (long) (random.nextDouble() * Long.MAX_VALUE);
    }

    public void sendMessage(int key, String message) throws InterruptedException {
        if (!keyOffsetMap.containsKey(key)) {
            throw new IllegalArgumentException("Invalid key");
        }
        channel.writeAndFlush(new Message(key, message)).sync();
    }

    public void shutdown() throws InterruptedException {
        channel.closeFuture().sync();
        workerGroup.shutdownGracefully(0, 5, TimeUnit.SECONDS);
        executorService.shutdown();
    }

    private static class ClientHandler extends ChannelInboundHandlerAdapter {
        private final Map<Integer, Long> keyOffsetMap;
        private final ExecutorService executorService;

        public ClientHandler(Map<Integer, Long> keyOffsetMap, ExecutorService executorService) {
            this.keyOffsetMap = keyOffsetMap;
            this.executorService = executorService;
        }

        @Override
        public void channelActive(ChannelHandlerContext ctx) throws Exception {
            logger.info("Channel active");
        }

        @Override
        public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
            Message message = (Message) msg;
            int key = message.getKey();
            String content = message.getContent();

            executorService.submit(() -> {
                try {
                    // Process the received message
                    logger.info("Received message for key {}: {}", key, content);
                } catch (Exception e) {
                    logger.error("Error processing message", e);
                }
            });
        }

        @Override
        public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
            if (evt instanceof IdleStateEvent) {
                // Handle idle state event
                logger.info("Channel is idle");
            }
        }

        @Override
        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
            logger.error("Exception caught", cause);
            ctx.close();
        }
    }

    private static class Message {
        private int key;
        private String content;

        public Message(int key, String content) {
            this.key = key;
            this.content = content;
        }

        public int getKey() {
            return key;
        }

        public String getContent() {
            return content;
        }
    }
}
