#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    int key;
    long offset;
    struct record* next;
} Record;

typedef struct database {
    Record** records;
    int* used_keys;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Database;

Database* create_database(size_t initial_capacity) {
    Database* db = malloc(sizeof(Database));
    if (db == NULL) return NULL;

    db->records = calloc(initial_capacity, sizeof(Record*));
    if (db->records == NULL) {
        free(db);
        return NULL;
    }

    db->used_keys = calloc(initial_capacity, sizeof(int));
    if (db->used_keys == NULL) {
        free(db->records);
        free(db);
        return NULL;
    }

    db->capacity = initial_capacity;
    db->count = 0;

    if (pthread_mutex_init(&db->lock, NULL) != 0) {
        free(db->used_keys);
        free(db->records);
        free(db);
        return NULL;
    }

    srand(time(NULL));
    return db;
}

void destroy_database(Database* db) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->count; ++i) {
        Record* record = db->records[i];
        while (record != NULL) {
            Record* next = record->next;
            free(record);
            record = next;
        }
    }
    pthread_mutex_unlock(&db->lock);

    free(db->used_keys);
    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

Record* create_record(int key, long offset) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) return NULL;

    record->value = rand() % 1000; // Pseudo-random number between 0 and 999
    record->key = key;
    record->offset = offset;
    record->next = NULL;

    return record;
}

int add_record(Database* db, int key, long offset) {
    pthread_mutex_lock(&db->lock);
    if (key >= 1024 || key < 0 || db->used_keys[key]) {
        pthread_mutex_unlock(&db->lock);
        return -1; // Key out of range or already used
    }

    if (db->count == db->capacity) {
        size_t new_capacity = db->capacity * 2;
        Record** new_records = realloc(db->records, new_capacity * sizeof(Record*));
        int* new_used_keys = realloc(db->used_keys, new_capacity * sizeof(int));

        if (new_records == NULL || new_used_keys == NULL) {
            pthread_mutex_unlock(&db->lock);
            return -2; // Memory allocation failed
        }

        db->records = new_records;
        db->used_keys = new_used_keys;
        db->capacity = new_capacity;

        // Initialize newly allocated memory to zero or free previous records as needed
    }

    Record* record = create_record(key, offset);
    if (record == NULL) {
        pthread_mutex_unlock(&db->lock);
        return -2; // Memory allocation failed
    }

    db->records[db->count] = record;
    db->used_keys[key] = 1;
    db->count++;
    pthread_mutex_unlock(&db->lock);

    return 0; // Success
}

Record* get_record(Database* db, int key) {
    if (key < 0 || key >= 1024 || !db->used_keys[key]) return NULL;

    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->count; ++i) {
        Record* record = db->records[i];
        while (record != NULL) {
            if (record->key == key) {
                pthread_mutex_unlock(&db->lock);
                return record;
            }
            record = record->next;
        }
    }

    pthread_mutex_unlock(&db->lock);
    return NULL; // Record not found
}

void print_database(Database* db) {
    pthread_mutex_lock(&db->lock);
    for (size_t i = 0; i < db->count; ++i) {
        Record* record = db->records[i];
        while (record != NULL) {
            printf("Key: %d, Value: %d, Offset: %ld\n", record->key, record->value, record->offset);
            record = record->next;
        }
    }
    pthread_mutex_unlock(&db->lock);
}
