#define MAX_KEYS 1024

int used_keys[MAX_KEYS] = {0};
pthread_mutex_t key_lock;

record* create_records(int *offsets, int num_offsets) {
    record *records = (record*)malloc(num_offsets * sizeof(record));
    if (!records) return NULL;

    pthread_mutex_init(&key_lock, NULL);

    srand(time(NULL));

    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % MAX_KEYS;
        while (used_keys[offsets[i]]) {
            offsets[i] = rand() % MAX_KEYS;
        }
        used_keys[offsets[i]] = 1;

        records[i].value = rand() % 1000 + 1;
    }

    return records;
}

void cleanup(record *records, int num_offsets) {
    free(records);
    pthread_mutex_destroy(&key_lock);

    for (int i = 0; i < MAX_KEYS; i++) {
        used_keys[i] = 0;
    }
}

int main() {
    int offsets[10];
    record *records = create_records(offsets, 10);

    if (!records) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Use records and offsets as needed

    cleanup(records, 10);
    return 0;
}
