import java.io.File;
import java.io.IOException;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class DirectoryManager {
    private final ConcurrentHashMap<String, Long> directorySizes = new ConcurrentHashMap<>();
    private final long totalSizeLimit;
    private final SecureRandom random;
    private final AtomicLong currentTotalSize;

    public DirectoryManager(long totalSizeLimit) {
        this.totalSizeLimit = totalSizeLimit;
        this.random = new SecureRandom();
        this.currentTotalSize = new AtomicLong(0);
    }

    public String createDirectory() throws IOException {
        while (true) {
            String directoryName = generateUniqueDirectoryName();
            if (directorySizes.putIfAbsent(directoryName, 0L) == null) {
                File dir = new File(directoryName);
                if (dir.mkdir()) {
                    return directoryName;
                }
            }
        }
    }

    public void deleteDirectory(String directoryName) throws IOException {
        long size = directorySizes.remove(directoryName);
        if (size != null) {
            currentTotalSize.getAndAdd(-size);
            File dir = new File(directoryName);
            if (!dir.delete()) {
                throw new IOException("Failed to delete directory: " + directoryName);
            }
        }
    }

    public void addData(String directoryName, long dataSize) throws IOException {
        Long size = directorySizes.get(directoryName);
        if (size == null) {
            throw new IOException("Directory not found: " + directoryName);
        }

        long newSize = size + dataSize;
        if (newSize > getTotalLimit()) {
            throw new IOException("Disk space exhausted");
        }

        if (!directorySizes.replace(directoryName, size, newSize)) {
            throw new IOException("Concurrent modification detected");
        }

        currentTotalSize.getAndAdd(dataSize);
    }

    public void removeData(String directoryName, long dataSize) throws IOException {
        Long size = directorySizes.get(directoryName);
        if (size == null) {
            throw new IOException("Directory not found: " + directoryName);
        }

        long newSize = size - dataSize;
        if (newSize < 0) {
            throw new IOException("Invalid data removal");
        }

        if (!directorySizes.replace(directoryName, size, newSize)) {
            throw new IOException("Concurrent modification detected");
        }

        currentTotalSize.getAndAdd(-dataSize);
    }

    public long getDirectoryUsage(String directoryName) throws IOException {
        Long size = directorySizes.get(directoryName);
        if (size == null) {
            throw new IOException("Directory not found: " + directoryName);
        }
        return size;
    }

    public long getTotalUsedSpace() {
        return currentTotalSize.get();
    }

    public long getTotalLimit() {
        return totalSizeLimit;
    }

    private String generateUniqueDirectoryName() {
        byte[] randomBytes = new byte[16];
        random.nextBytes(randomBytes);
        StringBuilder sb = new StringBuilder();
        for (byte b : randomBytes) {
            sb.append(String.format("%02x", b));
        }
        return "temp_dir_" + sb.toString();
    }
}
