#define MAX_KEYS 2048
#define RECORD_COUNT 1000

typedef struct {
    int value;
} Record;

// Function prototypes
int allocateMemory(int** keys, long** offsets);
void populateRecords(Record* records);
void initializeStorage();
void lockResource();
void unlockResource();
void cleanUp();

int main() {
    srand(time(NULL)); // Initialize random seed

    int* keys = NULL;
    long* offsets = NULL;

    if (allocateMemory(&keys, &offsets) != 0) {
        printf("Failed to allocate memory\n");
        return -1;
    }

    Record records[RECORD_COUNT];
    populateRecords(records);

    initializeStorage();
    lockResource();

    // Perform operations on storage
    // ...

    unlockResource();
    cleanUp();

    free(keys);
    free(offsets);

    return 0;
}

int allocateMemory(int** keys, long** offsets) {
    *keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (*keys == NULL) {
        return -1;
    }

    *offsets = (long*)malloc(RECORD_COUNT * sizeof(long));
    if (*offsets == NULL) {
        free(*keys);
        return -1;
    }

    // Initialize keys and offsets
