data_storage* create_data_storage() {
    data_storage* ds = (data_storage*)malloc(sizeof(data_storage));
    if (!ds) return NULL;

    ds->long_offsets = (int*)calloc(MAX_KEYS, sizeof(int));
    ds->keys = (int*)calloc(MAX_KEYS, sizeof(int));
    ds->records = (record**)calloc(MAX_KEYS, sizeof(record*));
    pthread_mutex_init(&ds->key_lock, NULL);
    return ds;
}

void free_data_storage(data_storage* ds) {
    if (!ds) return;

    for (int i = 0; i < MAX_KEYS; ++i) {
        if (ds->records[i]) {
            free(ds->records[i]);
        }
    }

    free(ds->long_offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->key_lock);
    free(ds);
}

int is_key_unique(data_storage* ds, int key) {
    pthread_mutex_lock(&ds->key_lock);
    for (int i = 0; i < MAX_KEYS; ++i) {
        if (ds->keys[i] == key) {
            pthread_mutex_unlock(&ds->key_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ds->key_lock);
    return 1;
}

void insert_key(data_storage* ds, int key, long offset) {
    pthread_mutex_lock(&ds->key_lock);
    for (int i = 0; i < MAX_KEYS; ++i) {
        if (!ds->keys[i]) {
            ds->keys[i] = key;
            ds->long_offsets[i] = offset;
            break;
        }
    }
    pthread_mutex_unlock(&ds->key_lock);
}

