import java.io.File;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class TemporaryDirectoryManager {
    private static final SecureRandom secureRandom = new SecureRandom();
    private ConcurrentHashMap<String, File> directoryMap;
    private long totalStorageThreshold;
    private double averageStorageUtilization;
    private double peakStorageUtilization;
    private int maxDirectories;
    private double cleanupThreshold;

    public TemporaryDirectoryManager(long totalStorageThreshold, int maxDirectories, double cleanupThreshold) {
        this.totalStorageThreshold = totalStorageThreshold;
        this.directoryMap = new ConcurrentHashMap<>();
        this.maxDirectories = maxDirectories;
        this.cleanupThreshold = cleanupThreshold;
    }

    public File createDirectory() throws Exception {
        if (directoryMap.size() >= maxDirectories) {
            throw new Exception("Maximum number of directories reached");
        }
        String directoryName = generateUniqueDirectoryName();
        File directory = new File(directoryName);
        if (!directory.mkdir()) {
            throw new Exception("Failed to create directory: " + directoryName);
        }
        directoryMap.put(directoryName, directory);
        updateStorageUtilization();
        return directory;
    }

    public void deleteDirectory(String directoryName) throws Exception {
        File directory = directoryMap.get(directoryName);
        if (directory == null || !directory.isDirectory()) {
            throw new Exception("Invalid directory: " + directoryName);
        }
        if (!deleteContents(directory)) {
            throw new Exception("Failed to delete directory contents: " + directoryName);
        }
        directory.delete();
        directoryMap.remove(directoryName);
        updateStorageUtilization();
    }

    private String generateUniqueDirectoryName() {
        while (true) {
            byte[] bytes = new byte[16];
            secureRandom.nextBytes(bytes);
            String directoryName = bytesToHex(bytes);
            if (!directoryMap.containsKey(directoryName)) {
                return directoryName;
            }
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private boolean deleteContents(File directory) {
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (!file.delete()) {
                    return false;
                }
            }
        }
        return true;
    }

    private void updateStorageUtilization() {
        long totalSize = 0;
        for (File directory : directoryMap.values()) {
            totalSize += getDirectorySize(directory);
        }
        double currentUsage = (double) totalSize / totalStorageThreshold;
        if (currentUsage > peakStorageUtilization) {
            peakStorageUtilization = currentUsage;
        }
        averageStorageUtilization = (averageStorageUtilization * directoryMap.size() + currentUsage) / (directoryMap.size() + 1);
    }

    private long getDirectorySize(File directory) {
        if (!directory.isDirectory()) {
            return directory.length();
        }
        File[] files = directory.listFiles();
        if (files == null) {
            return 0;
        }
        long size = 0;
        for (File file : files) {
            if (file.isDirectory()) {
                size += getDirectorySize(file);
            } else {
                size += file.length();
            }
        }
        return size;
    }

    public double getAverageStorageUtilization() {
        return averageStorageUtilization;
    }

    public double getPeakStorageUtilization() {
        return peakStorageUtilization;
    }
}
