    int key;
    do {
        pthread_mutex_lock(key_lock);
        key = rand() % max_key;
        while (used_keys[key]) {
            key = (key + 1) % max_key;
        }
        used_keys[key] = 1;
        pthread_mutex_unlock(key_lock);
    } while (!key); // Ensure we don't use zero
    return key;
}

