import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.HashSet;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class RecordManager {
    private static final int MAX_RECORDS = 1024;
    private static final String[] REMOTE_ADDRESSES = {"address1", "address2"};
    private static final Random RANDOM = new Random();
    private static final Set<Integer> usedKeys = ConcurrentHashMap.newKeySet();
    private static final ConcurrentHashMap<SocketChannel, Record[]> channelRecords = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        long startTime = System.currentTimeMillis();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = reader.readLine()) != null) {
            int[] inputArray = parseInput(line);
            if (inputArray == null) continue;

            Record[] records = initializeRecords(inputArray.length);
            for (SocketChannel channel : SocketChannel.open(REMOTE_ADDRESSES)) {
                channel.configureBlocking(false);
                channel.connect(new InetSocketAddress(REMOTE_ADDRESSES[0]));
                if (channel.finishConnect()) {
                    channelRecords.put(channel, records);
                    connectAndProcessRecords(channel, records);
                } else {
                    System.err.println("Failed to connect to remote address.");
                }
            }

            findAndPrintLargest(inputArray);
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Total execution time: " + (endTime - startTime) + " ms");
    }

    private static int[] parseInput(String line) {
        String[] parts = line.split(",");
        int[] inputArray = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            try {
                inputArray[i] = Integer.parseInt(parts[i]);
            } catch (NumberFormatException e) {
                System.err.println("Invalid integer in input: " + parts[i]);
                return null;
            }
        }
        return inputArray;
    }

    private static Record[] initializeRecords(int size) {
        if (size > MAX_RECORDS) {
            throw new IllegalArgumentException("Too many records requested.");
        }

        Record[] records = new Record[size];
        Set<Integer> keys = new HashSet<>();
        while (keys.size() < size) {
            int key;
            do {
                key = RANDOM.nextInt(1024);
            } while (!usedKeys.add(key));
            keys.add(key);
        }

        for (int i = 0; i < size; i++) {
            records[i] = new Record(keys.toArray(new Integer[0])[i], RANDOM.nextInt(1000) + 1);
        }
        return records;
    }

    private static void connectAndProcessRecords(SocketChannel channel, Record[] records) throws Exception {
        ByteBuffer buffer = ByteBuffer.allocate(records.length * 4);
        for (Record record : records) {
            buffer.putInt(record.getKey());
        }
        buffer.flip();
        channel.write(buffer);

        // Simulate processing time
        Thread.sleep(100);
    }

    private static void findAndPrintLargest(int[] inputArray) {
        int max = Integer.MIN_VALUE;
        for (int num : inputArray) {
            if (num > max) {
                max = num;
            }
        }
        System.out.println("Largest integer in array: " + max);
    }

    static class Record {
        private final int key;
        private final int value;

        public Record(int key, int value) {
            this.key = key;
            this.value = value;
        }

        public int getKey() {
            return key;
        }

        public int getValue() {
            return value;
        }
    }
}
