#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

long* offset_values;
int* keys;
record* records;
int num_records = 0;
pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

void init_arrays(int initial_size) {
    offset_values = (long*)malloc(initial_size * sizeof(long));
    keys = (int*)malloc(initial_size * sizeof(int));
    if (!offset_values || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

int is_key_valid(int key) {
    return key >= 0 && key < MAX_KEYS;
}

void ensure_uniqueness(int key) {
    pthread_mutex_lock(&key_lock);
    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            pthread_mutex_unlock(&key_lock);
            return;
        }
    }
    keys[num_records++] = key;
    pthread_mutex_unlock(&key_lock);
}

record* generate_record() {
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    while (!RAND_bytes((unsigned char*)&new_record->value, sizeof(int))) {}
    ensure_uniqueness(new_record->value);
    return new_record;
}

void* generate_records(void* arg) {
    int num_new_records = *(int*)arg;
    for (int i = 0; i < num_new_records; i++) {
        records[i] = *generate_record();
    }
    pthread_exit(NULL);
}

void clean_up() {
    free(offset_values);
    free(keys);
    for (int i = 0; i < num_records; i++) {
        free(&records[i]);
    }
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <num_records>\n", argv[0]);
        return 1;
    }

    int num_new_records = atoi(argv[1]);
    init_arrays(num_new_records);

    records = (record*)malloc(num_new_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        clean_up();
        return 1;
    }

    srand(time(NULL));
    RAND_seed((unsigned char*)&srand, sizeof(srand));

    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_records, &num_new_records) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        clean_up();
        return 1;
    }

    pthread_join(thread, NULL);

    for (int i = 0; i < num_new_records; i++) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }

    clean_up();

    return 0;
}
