#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define RECORD_COUNT 1000

typedef struct {
    int value;
} Record;

int hash(int key, int size) {
    return key % size;
}

void* generate_keys_and_records(void* arg) {
    int* offsets = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    int* keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    Record* records = (Record*)malloc(RECORD_COUNT * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize keys and offsets
    int used_keys[MAX_KEYS] = {0};
    for (int i = 0; i < MAX_KEYS; ++i) {
        int key;
        do {
            key = rand() % MAX_KEYS;
        } while (used_keys[key]);
        used_keys[key] = 1;

        keys[i] = key;
        offsets[i] = hash(key, RECORD_COUNT);
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < RECORD_COUNT; ++i) {
        records[i].value = rand() % 1000 + 1;
    }

    pthread_mutex_destroy(&lock);

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_keys_and_records, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
