#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define user profile structure
typedef struct {
    int id;
    char name[100];
    char email[100];
    char password[100];
} UserProfile;

// Thread-safe global variables
UserProfile *userProfiles = NULL;
int userProfileCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// PRNG function to generate unique keys and values
unsigned int prng() {
    static unsigned int state = 123456789; // Seed for the PRNG
    state = (state * 1103515245 + 12345) % 0xFFFFFFFF;
    return state;
}

// Helper function to find the largest integer in an array
int findLargest(int *array, int size) {
    if (size == 0) {
        fprintf(stderr, "Empty input\n");
        exit(1);
    }
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to manage user accounts
void manageUserAccount(int id, const char *name, const char *email, const char *password, const char *sub_action) {
    pthread_mutex_lock(&mutex);

    if (strcmp(sub_action, "delete") == 0) {
        // Delete user account logic
        for (int i = 0; i < userProfileCount; i++) {
            if (userProfiles[i].id == id) {
                free(userProfiles[i].name);
                free(userProfiles[i].email);
                free(userProfiles[i].password);
                memmove(&userProfiles[i], &userProfiles[i + 1], sizeof(UserProfile) * (userProfileCount - i - 1));
                userProfileCount--;
                break;
            }
        }
    } else {
        // Create or update user account logic
        for (int i = 0; i < userProfileCount; i++) {
            if (userProfiles[i].id == id) {
                free(userProfiles[i].name);
                free(userProfiles[i].email);
                free(userProfiles[i].password);
                break;
            }
        }
        userProfiles = realloc(userProfiles, sizeof(UserProfile) * (userProfileCount + 1));
        UserProfile newUser = {id, strdup(name), strdup(email), strdup(password)};
        userProfiles[userProfileCount++] = newUser;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to read integers from standard input and find the largest
void readInputAndFindLargest() {
    int size;
    printf("Enter number of elements: ");
    scanf("%d", &size);

    int *array = malloc(size * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        if (scanf("%d", &array[i]) != 1) {
            fprintf(stderr, "Invalid integer input\n");
            free(array);
            return;
        }
    }

    int largest = findLargest(array, size);
    printf("The largest number is: %d\n", largest);

    free(array);
}

int main() {
    // Example usage
    manageUserAccount(prng(), "John Doe", "john.doe@example.com", "password123", "create");
    manageUserAccount(1, "Jane Doe", "jane.doe@example.com", "newpassword456", "update");

    readInputAndFindLargest();

    return 0;
}
