import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class TemporaryDirectoryManager {

    private static final SecureRandom PRNG = new SecureRandom();
    private static final ConcurrentHashMap<String, Long> directoryUsage = new ConcurrentHashMap<>();
    private static long totalStorageLimit = 1024 * 1024 * 1024; // 1 GB
    private static int maxDirectories = 10;

    public static Path createTemporaryDirectory(String prefix) throws IOException {
        String uniqueName = generateUniqueName(prefix);
        Path directoryPath = Paths.get(uniqueName);
        Files.createDirectories(directoryPath);
        setUsage(uniqueName, 0L);
        return directoryPath;
    }

    private static String generateUniqueName(String prefix) {
        byte[] bytes = new byte[16];
        PRNG.nextBytes(bytes);
        return prefix + "_" + bytesToHex(bytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void setUsage(String directoryName, long size) {
        directoryUsage.put(directoryName, size);
        updateTotalStorageUsed();
    }

    private static void updateTotalStorageUsed() {
        totalStorageLimit -= directoryUsage.values().stream().mapToLong(Long::longValue).sum();
    }

    public static boolean deleteTemporaryDirectory(Path directoryPath) throws IOException {
        String directoryName = directoryPath.toString();
        if (directoryUsage.containsKey(directoryName)) {
            Files.walkFileTree(directoryPath, new DirectoryDeleter());
            directoryUsage.remove(directoryName);
            updateTotalStorageUsed();
            return true;
        }
        return false;
    }

    private static class DirectoryDeleter implements java.nio.file.FileVisitor<Path> {
        @Override
        public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
            return FileVisitResult.CONTINUE;
        }

        @Override
        public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
            Files.delete(file);
            return FileVisitResult.CONTINUE;
        }

        @Override
        public FileVisitResult visitFileFailed(Path file, IOException exc) throws IOException {
            return FileVisitResult.CONTINUE;
        }

        @Override
        public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
            Files.delete(dir);
            return FileVisitResult.CONTINUE;
        }
    }

    // Additional methods for monitoring storage usage, handling disk space exhaustion,
    // integrating with distributed framework, dynamic resizing, automatic cleanup,
    // logging, and edge case handling can be implemented here.
}
