int load_cipher_config(const char* config_file, CipherConfig** configs, int* count) {
    FILE* file = fopen(config_file, "r");
    if (!file) return -1;

    *count = 0;
    while (fgetc(file) != EOF) (*count)++;
    rewind(file);

    *configs = malloc(*count * sizeof(CipherConfig));
    if (!*configs) {
        fclose(file);
        return -2;
    }

    for (int i = 0; i < *count; i++) {
        fscanf(file, "%s %s %s %s", (*configs)[i].cipher->name, 
               (*configs)[i].key, (*configs)[i].iv, (*configs)[i].signature_key);
    }

    fclose(file);
    return 0;
}

int perform_cipher_operation(CipherConfig* config, const unsigned char* plaintext, unsigned char* ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, config->cipher, NULL, config->key, config->iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -2;
    }

    int len, ciphertext_len;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, strlen(plaintext)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -3;
    }
    ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -4;
    }

    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

