#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 2048

typedef struct {
    long offset;
    int key;
    char *userID;
} record;

int usedKeys[MAX_KEYS] = {0};
char **userIDs;
record *records;
int numRecords = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initArrays() {
    userIDs = (char **)malloc(MAX_KEYS * sizeof(char *));
    records = (record *)malloc(numRecords * sizeof(record));
}

long generateRandomOffset(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int findAvailableKey() {
    for (int i = 0; i < MAX_KEYS; i++) {
        if (!usedKeys[i]) {
            usedKeys[i] = 1;
            return i;
        }
    }
    return -1;
}

void *allocateMemoryAndInitArrays(void *arg) {
    pthread_mutex_lock(&mutex);

    if (numRecords >= MAX_KEYS) {
        printf("Maximum number of records reached.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    int key = findAvailableKey();
    if (key == -1) {
        printf("No available keys.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    records[numRecords].offset = generateRandomOffset(1, 2000);
    records[numRecords].key = key;
    records[numRecords].userID = (char *)malloc(5 * sizeof(char)); // Assuming max 4 digits + null terminator
    sprintf(records[numRecords].userID, "%d", key);

    usedKeys[key] = 1;

    numRecords++;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void cleanup() {
    for (int i = 0; i < numRecords; i++) {
        free(records[i].userID);
    }
    free(userIDs);
    free(records);
    pthread_mutex_destroy(&mutex);
}

int main() {
    srand(time(NULL));
    initArrays();

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, allocateMemoryAndInitArrays, NULL);
    pthread_create(&thread2, NULL, allocateMemoryAndInitArrays, NULL);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    cleanup();
    return 0;
}
