import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ConcurrentConnectionManager {

    private static final int MAX_KEYS = 1024;
    private static final int RANDOM_RANGE = 1000;
    private final Set<Integer> usedKeys = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private AsynchronousChannelGroup group;
    private ExecutorService executor;
    private Logger logger;

    public ConcurrentConnectionManager(int poolSize, String level) {
        this.logger = Logger.getLogger(ConcurrentConnectionManager.class.getName());
        this.logger.setLevel(Level.parse(level));
        try {
            group = AsynchronousChannelGroup.withFixedThreadPool(poolSize);
            executor = Executors.newScheduledThreadPool(poolSize);
        } catch (IOException e) {
            throw new RuntimeException("Failed to initialize connection manager", e);
        }
    }

    public void manageConnections(List<String> addresses, int maxRecords) throws IOException {
        try (AsynchronousSocketChannel[] channels = new AsynchronousSocketChannel[addresses.size()]) {
            for (int i = 0; i < addresses.size(); i++) {
                channels[i] = AsynchronousSocketChannel.open(group);
                connect(channels[i], addresses.get(i), maxRecords);
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error managing connections", e);
        }
    }

    private void connect(AsynchronousSocketChannel channel, String address, int maxRecords) {
        channel.connect(new InetSocketAddress(address, 8080)).thenAccept(future -> {
            try {
                handleConnection(channel, maxRecords);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error handling connection", e);
            }
        }).exceptionally(ex -> {
            logger.log(Level.WARNING, "Failed to connect to " + address, ex);
            return null;
        });
    }

    private void handleConnection(AsynchronousSocketChannel channel, int maxRecords) throws IOException, InterruptedException {
        ByteBuffer buffer = ByteBuffer.allocate(maxRecords * 4);
        channel.read(buffer).thenAccept(result -> {
            if (result == -1) {
                logger.info("Connection closed");
                return;
            }
            processRecords(buffer, maxRecords);
        }).exceptionally(ex -> {
            logger.log(Level.SEVERE, "Error reading from channel", ex);
            return null;
        });
    }

    private void processRecords(ByteBuffer buffer, int maxRecords) {
        buffer.flip();
        int[] keys = new int[maxRecords];
        long[] offsets = new long[maxRecords];
        for (int i = 0; i < maxRecords; i++) {
            if (!usedKeys.add(nextUniqueKey())) {
                throw new RuntimeException("Duplicate key detected");
            }
            keys[i] = usedKeys.size() - 1;
            offsets[i] = buffer.getLong();
        }
        storeRecords(keys, offsets);
    }

    private int nextUniqueKey() {
        Random random = new SecureRandom();
        while (true) {
            int key = random.nextInt(MAX_KEYS);
            if (!usedKeys.contains(key)) {
                return key;
            }
        }
    }

    private void storeRecords(int[] keys, long[] offsets) {
        // Placeholder for actual storage logic
        logger.info("Storing records with keys: " + Arrays.toString(keys));
    }

    public int findMaxValue(List<Integer> numbers) {
        if (numbers.isEmpty()) {
            throw new IllegalArgumentException("Input list cannot be empty");
        }
        return numbers.stream().max(Integer::compare).get();
    }

    public void close() throws IOException, InterruptedException {
        if (group != null) {
            group.shutdownNow();
            group.awaitTermination(5, TimeUnit.SECONDS);
        }
        if (executor != null) {
            executor.shutdownNow();
            executor.awaitTermination(5, TimeUnit.SECONDS);
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        List<String> addresses = Arrays.asList("192.168.1.1", "192.168.1.2");
        ConcurrentConnectionManager manager = new ConcurrentConnectionManager(4, "FINE");
        manager.manageConnections(addresses, 100);
        // Simulate reading input and finding max value
        List<Integer> numbers = Arrays.asList(3, 5, 1, 4, 8, 9, 7, 6, 2);
        int maxValue = manager.findMaxValue(numbers);
        System.out.println("Largest number: " + maxValue);
        manager.close();
    }
}
