#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    pthread_mutex_t lock;
    int *used_keys;
    Record records[MAX_KEYS];
} HashTable;

HashTable table = {PTHREAD_MUTEX_INITIALIZER, NULL};

void initialize_hash_table() {
    table.used_keys = (int *)calloc(MAX_KEYS, sizeof(int));
}

void insert_record(int key, long offset) {
    pthread_mutex_lock(&table.lock);
    if (!table.used_keys[key]) {
        table.records[key].key = key;
        table.records[key].offset = offset;
        table.used_keys[key] = 1;
    }
    pthread_mutex_unlock(&table.lock);
}

int generate_random_key() {
    static int initialized = 0;
    static unsigned seed;

    if (!initialized) {
        srand(time(NULL));
        seed = rand();
        initialized = 1;
    }

    while (1) {
        int key = rand_r(&seed) % MAX_KEYS;
        pthread_mutex_lock(&table.lock);
        if (!table.used_keys[key]) {
            table.used_keys[key] = 2; // Mark as temporarily used
            pthread_mutex_unlock(&table.lock);
            return key;
        }
        pthread_mutex_unlock(&table.lock);
    }
}

void cleanup() {
    free(table.used_keys);
}

int main() {
    initialize_hash_table();

    int random_key = generate_random_key();
    insert_record(random_key, 12345);

    cleanup();

    return 0;
}
```

