import java.io.IOException;
import java.nio.file.*;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class TempDirectoryManager {
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final ConcurrentHashMap<String, Long> directoryUsage = new ConcurrentHashMap<>();
    private static long totalUsedSpace = 0;
    private static long maxTotalSpace;
    private static int maxDirectories;
    private static final ReentrantLock lock = new ReentrantLock();

    public TempDirectoryManager(long maxTotalSpace, int maxDirectories) {
        this.maxTotalSpace = maxTotalSpace;
        this.maxDirectories = maxDirectories;
    }

    public Path createDirectory() throws IOException {
        lock.lock();
        try {
            if (directoryUsage.size() >= maxDirectories) {
                throw new IllegalStateException("Maximum number of directories reached");
            }
            long usedSpace;
            do {
                String dirName = generateUniqueDirName();
                Path directory = Paths.get(dirName);
                Files.createDirectory(directory);
                usedSpace = getTotalUsedSpace() + directory.toFile().length();
            } while (usedSpace > maxTotalSpace);

            updateDirectoryUsage(Paths.get(generateUniqueDirName()), 0L);
            totalUsedSpace += usedSpace;
            return Paths.get(generateUniqueDirName());
        } finally {
            lock.unlock();
        }
    }

    public void deleteDirectory(Path directory) throws IOException {
        lock.lock();
        try {
            if (Files.exists(directory)) {
                Files.deleteIfExists(directory);
                updateDirectoryUsage(directory, -directory.toFile().length());
                totalUsedSpace -= directory.toFile().length();
            }
        } finally {
            lock.unlock();
        }
    }

    private String generateUniqueDirName() {
        byte[] bytes = new byte[16];
        RANDOM.nextBytes(bytes);
        return "temp-" + bytesToHex(bytes);
    }

    private void updateDirectoryUsage(Path directory, long sizeChange) {
        lock.lock();
        try {
            Long currentSize = directoryUsage.getOrDefault(directory.toString(), 0L);
            directoryUsage.put(directory.toString(), currentSize + sizeChange);
        } finally {
            lock.unlock();
        }
    }

    public long getTotalUsedSpace() {
        return totalUsedSpace;
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

