import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.security.SecureRandom;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class MultiChannelServer {

    private static final SecureRandom random = new SecureRandom();
    private static final Set<Double> usedAmounts = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private static int maxTransactionsPerChannel;

    public static void main(String[] args) {
        try (Selector selector = Selector.open()) {
            ServerSocketChannel serverChannel = ServerSocketChannel.open();
            serverChannel.socket().bind(new InetSocketAddress("localhost", 8080));
            serverChannel.configureBlocking(false);
            serverChannel.register(selector, SelectionKey.OP_ACCEPT);

            maxTransactionsPerChannel = Integer.parseInt(args[0]);

            while (true) {
                selector.select();
                Set<SelectionKey> selectedKeys = selector.selectedKeys();
                Iterator<SelectionKey> iter = selectedKeys.iterator();

                while (iter.hasNext()) {
                    SelectionKey key = iter.next();
                    if (key.isAcceptable()) {
                        handleAccept(serverChannel, selector);
                    } else if (key.isReadable()) {
                        handleRead(key);
                    }
                    iter.remove();
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void handleAccept(ServerSocketChannel serverChannel, Selector selector) throws IOException {
        SocketChannel clientChannel = serverChannel.accept();
        clientChannel.configureBlocking(false);
        clientChannel.register(selector, SelectionKey.OP_READ);

        System.out.println("Accepted connection from " + clientChannel.getRemoteAddress());
    }

    private static void handleRead(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(8);
        int bytesRead = channel.read(buffer);

        if (bytesRead == -1) {
            channel.close();
            System.out.println("Connection closed by client");
            return;
        }

        buffer.flip();
        double transactionAmount = buffer.getDouble();

        if (!validateTransactionAmount(transactionAmount)) {
            channel.write(ByteBuffer.wrap(new byte[0]));
        } else {
            channel.write(ByteBuffer.wrap(new byte[]{1}));
        }
    }

    private static boolean validateTransactionAmount(double amount) {
        synchronized (usedAmounts) {
            if (amount < 0 || usedAmounts.contains(amount)) {
                return false;
            }
            usedAmounts.add(amount);
            prefetchData(amount);
            return true;
        }
    }

    private static void prefetchData(double amount) {
        // Implement caching logic here
    }

    public static double[] readTransactionAmounts(List<String> input) {
        List<Double> amounts = new ArrayList<>();
        for (String line : input) {
            try {
                double amount = Double.parseDouble(line.trim());
                if (amount >= 0 && !usedAmounts.contains(amount)) {
                    amounts.add(amount);
                }
            } catch (NumberFormatException e) {
                System.out.println("Invalid transaction amount: " + line);
            }
        }
        return amounts.stream().mapToDouble(Double::doubleValue).toArray();
    }

    public static double calculateAverageTransaction(double[] transactions) {
        if (transactions.length == 0) {
            return 0.0;
        }
        return Arrays.stream(transactions).average().orElse(0.0);
    }

    private static void cleanup() {
        usedAmounts.clear();
        // Add other cleanup logic here
    }
}
