    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < size; ++i) {
        prngFunc(&array[i].value);
        if (array[i].value < minVal || array[i].value > maxVal) {
            fprintf(stderr, "PRNG generated an out-of-range value\n");
            free(array); // Free partially allocated memory
            return NULL;
        }
    }

    return array;
}

void simplePrng(int* result) {
    *result = rand() % 100; // Generate a random number between 0 and 99
