#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1024

typedef struct record {
    int key;
    int value;
} Record;

typedef struct hash_table {
    Record *table[TABLE_SIZE];
    pthread_mutex_t lock;
} HashTable;

HashTable *create_hash_table() {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    for (int i = 0; i < TABLE_SIZE; i++) {
        ht->table[i] = NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

int hash_function(int key) {
    return key % TABLE_SIZE;
}

void insert_record(HashTable *ht, int key, int value) {
    pthread_mutex_lock(&ht->lock);
    int index = hash_function(key);
    while (ht->table[index] != NULL && ht->table[index]->key != -1) {
        index = (index + 1) % TABLE_SIZE;
    }
    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    ht->table[index] = new_record;
    pthread_mutex_unlock(&ht->lock);
}

int find_value(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    int index = hash_function(key);
    while (ht->table[index] != NULL && ht->table[index]->key != key) {
        index = (index + 1) % TABLE_SIZE;
    }
    if (ht->table[index] == NULL || ht->table[index]->key == -1) {
        pthread_mutex_unlock(&ht->lock);
        return -1; // Key not found
    }
    int value = ht->table[index]->value;
    pthread_mutex_unlock(&ht->lock);
    return value;
}

void free_hash_table(HashTable *ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (ht->table[i] != NULL) {
            free(ht->table[i]);
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int main() {
    HashTable *ht = create_hash_table();
    srand(time(NULL));
    for (int i = 0; i < TABLE_SIZE; i++) {
        int key = rand() % 1024;
        int value = rand() % 1000 + 1;
        insert_record(ht, key, value);
    }
    int key_to_find = 512;
    int value = find_value(ht, key_to_find);
    if (value != -1) {
        printf("Value for key %d is %d\n", key_to_find, value);
    } else {
        printf("Key %d not found\n", key_to_find);
    }
    free_hash_table(ht);
    return 0;
}
