typedef struct {
    Session sessions[MAX_SESSIONS];
    int count;
    time_t lastSeed;
} SessionManager;

void seedPRNG() {
    time_t current = time(NULL);
    if (current != sessionManager.lastSeed) {
        srand(current);
        sessionManager.lastSeed = current;
    }
}

char* generateSessionToken(int userId) {
