    snprintf(token, sizeof(token), "%d-%ld", userId, rand());
    return strdup(token);
}

int initializeSession(Session *session, int userId) {
    session->timestamp = time(NULL);
    session->userId = userId;
    session->sessionToken = generateSessionToken(userId);
    if (session->sessionToken == NULL) {
        return -1; // Memory allocation failed
    }
    return 0;
}

int addSession(SessionManager *manager, int userId) {
    if (manager->count >= MAX_SESSIONS) {
        return -2; // Maximum sessions reached
    }
    seedPRNG();
    Session *session = &manager->sessions[manager->count];
    if (initializeSession(session, userId) != 0) {
        return -3; // Failed to initialize session
    }
    manager->count++;
    return 0;
}

void cleanupSessions(SessionManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->sessions[i].sessionToken);
    }
    manager->count = 0;
}
