record* create_records(size_t max_size) {
    if (max_size > 1024 * 1024) {
        // Maximum size exceeds reasonable limits
        return NULL;
    }

    record* records = malloc(max_size * sizeof(record));
    if (!records) {
        // Memory allocation failed
        return NULL;
    }

    long* offsets = malloc(max_size * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < max_size; ++i) {
        offsets[i] = rand() % (max_size * 2); // Random offset
        records[i].offsets = &offsets[i];
        records[i].keys[0] = i + 1; // Sequential keys from 1 to 1024
        records[i].length = rand() % 1024; // Random length between 0 and 1023
    }

    free(offsets); // Clean up temporary offset array

    return records;
}

void free_records(record* records, size_t max_size) {
    if (records) {
        for (size_t i = 0; i < max_size; ++i) {
            if (records[i].offsets) {
                // Free any dynamically allocated offsets
                free(records[i].offsets);
            }
        }
        free(records);
    }
}
