#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_KEYS 65536
#define TABLE_SIZE 256

typedef struct {
    int key;
    long value;
} Record;

typedef struct {
    Record records[MAX_KEYS];
    pthread_mutex_t mutex;
    int used_keys[TABLE_SIZE];
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    for (int i = 0; i < TABLE_SIZE; i++) {
        array->used_keys[i] = -1;
    }

    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int insert_record(DynamicArray* array, int key, long value) {
    if (key < 0 || key >= MAX_KEYS) return -1;

    int index = key % TABLE_SIZE;
    pthread_mutex_lock(&array->mutex);

    while (array->used_keys[index] != -1 && array->records[array->used_keys[index]].key != key) {
        index = (index + 1) % TABLE_SIZE;
    }

    if (array->used_keys[index] != -1) {
        pthread_mutex_unlock(&array->mutex);
        return -2; // Collision detected
    }

    int record_index = array->used_keys[index];
    if (record_index == -1) {
        for (int i = 0; i < TABLE_SIZE; i++) {
            if (array->used_keys[i] == -1) {
                record_index = i;
                break;
            }
        }
    }

    array->records[record_index].key = key;
    array->records[record_index].value = value;
    array->used_keys[index] = record_index;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void find_min_max(DynamicArray* array, int* min_key, int* max_key) {
    *min_key = -1;
    *max_key = -1;

    for (int i = 0; i < TABLE_SIZE; i++) {
        if (array->used_keys[i] != -1) {
            int key = array->records[array->used_keys[i]].key;
            long value = array->records[array->used_keys[i]].value;

            if (*min_key == -1 || value < *min_key) {
                *min_key = key;
            }
            if (*max_key == -1 || value > *max_key) {
                *max_key = key;
            }
        }
    }
}

int main() {
    DynamicArray* array = create_dynamic_array();

    // Example usage
    insert_record(array, 10, 12345);
    insert_record(array, 20, 67890);

    int min_key, max_key;
    find_min_max(array, &min_key, &max_key);
    printf("Min Key: %d, Max Key: %d\n", min_key, max_key);

    destroy_dynamic_array(array);
    return 0;
}
