#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} Record;

typedef struct {
    Record records[MAX_KEYS];
    pthread_mutex_t lock;
} HashTable;

HashTable table;

void init_table() {
    pthread_mutex_init(&table.lock, NULL);
    for (int i = 0; i < MAX_KEYS; i++) {
        table.records[i].value = -1; // Initialize to invalid value
    }
}

int hash_function(int key) {
    return key % MAX_KEYS;
}

int insert_key(int key, int value) {
    pthread_mutex_lock(&table.lock);
    int index = hash_function(key);
    while (table.records[index].value != -1 && table.records[index].value != key) {
        index = (index + 1) % MAX_KEYS; // Linear probing
    }
    if (table.records[index].value == -1) {
        table.records[index].value = value;
        pthread_mutex_unlock(&table.lock);
        return 0; // Success
    } else {
        pthread_mutex_unlock(&table.lock);
        return -1; // Key already exists or collision occurred
    }
}

int find_key(int key) {
    pthread_mutex_lock(&table.lock);
    int index = hash_function(key);
    while (table.records[index].value != -1 && table.records[index].value != key) {
        index = (index + 1) % MAX_KEYS; // Linear probing
    }
    pthread_mutex_unlock(&table.lock);
    return table.records[index].value;
}

void cleanup_table() {
    pthread_mutex_destroy(&table.lock);
}

int main() {
    init_table();

    int key, value;
    printf("Enter a key and value to insert: ");
    scanf("%d %d", &key, &value);

    if (insert_key(key, value) == 0) {
        printf("Key inserted successfully.\n");
    } else {
        printf("Failed to insert key.\n");
    }

    int search_key;
    printf("Enter a key to find: ");
    scanf("%d", &search_key);

    int result = find_key(search_key);
    if (result != -1) {
        printf("Key found with value: %d\n", result);
    } else {
        printf("Key not found.\n");
    }

    cleanup_table();
    return 0;
}
