import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class TempDirectoryManager {
    private static final SecureRandom PRNG = new SecureRandom();
    private static final ConcurrentHashMap<String, AtomicInteger> directoryUsage = new ConcurrentHashMap<>();
    private static final int MAX_DIRECTORY_SIZE_LIMIT = Integer.parseInt(System.getenv("MAX_DIR_SIZE_LIMIT", "1048576"));
    private static final double GLOBAL_STORAGE_THRESHOLD = Double.parseDouble(System.getenv("GLOBAL_STORAGE_THRESHOLD", "0.9"));

    public synchronized Path createTempDirectory() throws IOException {
        String uniqueId;
        do {
            uniqueId = generateUniqueId();
        } while (directoryExists(uniqueId));

        Path directory = Files.createDirectories(Path.of("/temp", uniqueId));
        directoryUsage.put(uniqueId, new AtomicInteger(0));
        return directory;
    }

    private synchronized boolean directoryExists(String id) {
        // Check if the directory already exists
        return directoryUsage.containsKey(id);
    }

    public void updateDirectoryUsage(String id, int size) {
        directoryUsage.get(id).addAndGet(size);
        checkGlobalStorageThreshold();
    }

    private String generateUniqueId() {
        byte[] bytes = new byte[16];
        PRNG.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    private void checkGlobalStorageThreshold() {
        double totalUsage = directoryUsage.values().stream()
                .mapToInt(AtomicInteger::get)
                .sum();
        if (totalUsage / MAX_DIRECTORY_SIZE_LIMIT >= GLOBAL_STORAGE_THRESHOLD) {
            throw new IllegalStateException("Global storage threshold exceeded");
        }
    }

    public synchronized void deleteDirectory(String id) throws IOException {
        Path directory = Path.of("/temp", id);
        Files.walkFileTree(directory, FileVisitResult::delete);
        directoryUsage.remove(id);
    }

    // Additional methods for dynamic resizing, cleanup, and integration with distributed frameworks
}
