#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>
#include <pthread.h>

#define MAX_KEYS 2048
#define BUCKET_SIZE 10

typedef struct {
    int key;
    long offset;
} Record;

typedef struct HashNode {
    int key;
    long offset;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    pthread_mutex_t lock;
} HashTable;

HashTable *createHashTable() {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->buckets = (HashNode **)calloc(MAX_KEYS / BUCKET_SIZE, sizeof(HashNode *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insertIntoHashTable(HashTable *table, int key, long offset) {
    int index = key % (MAX_KEYS / BUCKET_SIZE);
    HashNode *newNode = (HashNode *)malloc(sizeof(HashNode));
    newNode->key = key;
    newNode->offset = offset;
    newNode->next = table->buckets[index];
    pthread_mutex_lock(&table->lock);
    table->buckets[index] = newNode;
    pthread_mutex_unlock(&table->lock);
}

int lookupInHashTable(HashTable *table, int key) {
    int index = key % (MAX_KEYS / BUCKET_SIZE);
    HashNode *node = table->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            return node->offset;
        }
        node = node->next;
    }
    return -1; // Key not found
}

void freeHashTable(HashTable *table) {
    for (int i = 0; i < MAX_KEYS / BUCKET_SIZE; i++) {
        HashNode *node = table->buckets[i];
        while (node != NULL) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

void generateRandomRecords(Record **records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        records[i]->value = rand() % 2001;
    }
}

void resizeDynamicArray(Record **array, int *size, int newSize) {
    Record *newArray = (Record *)realloc(*array, newSize * sizeof(Record));
    if (newArray != NULL) {
        *array = newArray;
        *size = newSize;
    } else {
        fprintf(stderr, "Failed to resize array\n");
    }
}

void addToDynamicArray(Record **array, int *size, Record newRecord) {
    if (*size == 0) {
        *size = 10; // Initial size
        *array = (Record *)malloc(*size * sizeof(Record));
    } else if (*size > 0 && *size % 10 == 0) {
        resizeDynamicArray(array, size, *size + 10);
    }
    (*array)[*size - 1] = newRecord;
}

void cleanupMemory() {
    // Add code to clean up allocated memory
}
