import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

public class ConnectionManager {

    private static final int MAX_RECORDS = 1024;
    private static final int RECORD_SIZE = 256;
    private Selector selector;
    private Map<Integer, SocketChannel> connections;
    private Random random;

    public ConnectionManager() throws IOException {
        this.selector = Selector.open();
        this.connections = new HashMap<>();
        this.random = new SecureRandom();
    }

    public void initializeConnections(List<InetSocketAddress> addresses) throws IOException {
        for (InetSocketAddress address : addresses) {
            SocketChannel channel = SocketChannel.open(address);
            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_READ);
            connections.put(address.getPort(), channel);
        }
    }

    public void manageConnections() throws IOException {
        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            for (SelectionKey key : selectedKeys) {
                if (key.isConnectable()) {
                    handleConnection(key);
                } else if (key.isReadable()) {
                    handleRead(key);
                }
            }
        }
    }

    private void handleConnection(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        if (channel.finishConnect()) {
            channel.register(selector, SelectionKey.OP_READ);
            // Log successful connection
        } else {
            // Handle connection failure
        }
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(RECORD_SIZE);
        int bytesRead = channel.read(buffer);

        if (bytesRead == -1) {
            // Handle end of stream
            connections.remove(key.attachment());
        } else if (bytesRead > 0) {
            // Process the read data
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            String record = new String(data).trim();
            int key = Integer.parseInt(record.split(",")[0]);
            // Log successful read and process the record
        }
    }

    public void closeConnections() throws IOException {
        selector.close();
        for (SocketChannel channel : connections.values()) {
            channel.close();
        }
    }

    public static void main(String[] args) {
        try {
            ConnectionManager manager = new ConnectionManager();
            List<InetSocketAddress> addresses = new ArrayList<>();
            // Add remote addresses
            manager.initializeConnections(addresses);
            manager.manageConnections();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
