public class NetworkPacketProcessor {

    public void processPacket(Socket socket) {
        try (
            InputStream inputStream = socket.getInputStream();
            DataInputStream dataInputStream = new DataInputStream(inputStream)
        ) {
            byte[] packetData = readPacket(dataInputStream);
            String protocol = (String) readObject(packetData, 0);
            CipherMode mode = (CipherMode) readObject(packetData, 1);
            String signature = (String) readObject(packetData, 2);

            if (!isValidSignature(packetData, signature)) {
                throw new SecurityException("Invalid packet signature");
            }

            byte[] decryptedData;
            switch (mode) {
                case AES_128_CBC:
                    decryptedData = decryptAES128CBC(packetData);
                    break;
                case AES_256_ECB:
                    decryptedData = decryptAES256ECB(packetData);
                    break;
                default:
                    decryptedData = packetData; // Null encryption fallback
            }

            handleDecryptedPacket(decryptedData, protocol);
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error processing packet: " + e.getMessage());
        }
    }

    private byte[] readPacket(DataInputStream dataInputStream) throws IOException {
        // Implement logic to read the entire packet from the input stream
        return new byte[1024]; // Placeholder
    }

    @SuppressWarnings("unchecked")
    private <T> T readObject(byte[] data, int offset) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(data, offset, data.length - offset);
        ObjectInputStream ois = new ObjectInputStream(bis);
        return (T) ois.readObject();
    }

    private boolean isValidSignature(byte[] data, String signature) {
        // Implement logic to verify the cryptographic signature
        try {
            Signature sig = Signature.getInstance("SHA256withRSA");
            PublicKey publicKey = KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(signature.split(",")[1])));
            sig.initVerify(publicKey);
            sig.update(data, 0, data.length - signature.length());
            return sig.verify(Base64.getDecoder().decode(signature.split(",")[2]));
        } catch (Exception e) {
            System.err.println("Error verifying signature: " + e.getMessage());
            return false;
        }
    }

    private byte[] decryptAES128CBC(byte[] data) {
        // Implement AES-128-CBC decryption logic
        try {
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            SecretKeySpec secretKeySpec = new SecretKeySpec("0123456789abcdef".getBytes(), "AES");
            IvParameterSpec ivParameterSpec = new IvParameterSpec(new byte[16]);
            cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, ivParameterSpec);
            return cipher.doFinal(data);
        } catch (Exception e) {
            System.err.println("Error decrypting AES-128-CBC: " + e.getMessage());
            return null;
        }
    }

    private byte[] decryptAES256ECB(byte[] data) {
        // Implement AES-256-ECB decryption logic
        try {
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            SecretKeySpec secretKeySpec = new SecretKeySpec("0123456789abcdef0123456789abcdef".getBytes(), "AES");
            cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);
            return cipher.doFinal(data);
        } catch (Exception e) {
            System.err.println("Error decrypting AES-256-ECB: " + e.getMessage());
            return null;
        }
