#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

#define INITIAL_CAPACITY 1024

long *offsets = NULL;
int *keys = NULL;
Record **records = NULL;

int capacity = 0;
int size = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays() {
    capacity = INITIAL_CAPACITY;
    offsets = (long *)malloc(capacity * sizeof(long));
    keys = (int *)malloc(capacity * sizeof(int));
    records = (Record **)malloc(capacity * sizeof(Record *));
}

void resize_arrays() {
    capacity *= 2;
    offsets = realloc(offsets, capacity * sizeof(long));
    keys = realloc(keys, capacity * sizeof(int));
    records = realloc(records, capacity * sizeof(Record *));
}

long allocate_offset() {
    pthread_mutex_lock(&lock);
    if (size == capacity) {
        resize_arrays();
    }
    long offset = offsets[size];
    size++;
    pthread_mutex_unlock(&lock);
    return offset;
}

int allocate_key(int min, int max) {
    pthread_mutex_lock(&lock);
    if (size == capacity) {
        resize_arrays();
    }
    int key = keys[size] = rand() % (max - min + 1) + min;
    size++;
    pthread_mutex_unlock(&lock);
    return key;
}

Record *allocate_record(int value) {
    pthread_mutex_lock(&lock);
    if (size == capacity) {
        resize_arrays();
    }
    Record *record = records[size] = (Record *)malloc(sizeof(Record));
    record->value = value;
    size++;
    pthread_mutex_unlock(&lock);
    return record;
}

void free_record(Record *record) {
    free(record);
}

long find_largest_integer(int *array, int length) {
    if (length == 0) {
        return -1; // Handle edge case for zero-length array
    }
    long largest = array[0];
    for (int i = 1; i < length; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void cleanup() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    size = capacity = 0;
    pthread_mutex_unlock(&lock);
}
