        if (!used_values[random_value]) {
            records[i].value = random_value;
            used_values[random_value] = 1;
            i++;
        }
    }

    return records;
}

void *initialize_distributed_store(void *args) {
    int batch_size = BATCH_SIZE;
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    record *records = initialize_records(batch_size, &mutex);
    if (!records) {
        pthread_exit(NULL);
    }

    // Simulate concurrent access
    for (int i = 0; i < batch_size; i++) {
        pthread_mutex_lock(&mutex);
        // Perform operations with records[i]
        pthread_mutex_unlock(&mutex);
    }

    free(records);
    pthread_mutex_destroy(&mutex);
    pthread_exit(NULL);
}

