#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define RANDOM_RANGE 1000

typedef struct {
    long offset;
    int key;
    int random;
} Record;

typedef struct {
    Record records[MAX_KEYS];
    pthread_mutex_t lock;
    int next_key;
    int collision_count;
} RecordManager;

RecordManager *record_manager_init() {
    RecordManager *manager = (RecordManager *)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->next_key = 0;
    manager->collision_count = 0;
    return manager;
}

int record_manager_add(RecordManager *manager, long offset) {
    pthread_mutex_lock(&manager->lock);

    if (manager->next_key >= MAX_KEYS) {
        fprintf(stderr, "Error: Maximum keys reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    int key = manager->next_key++;
    Record *record = &manager->records[key];
    record->offset = offset;
    record->key = key;
    record->random = rand() % RANDOM_RANGE + 1;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void record_manager_cleanup(RecordManager *manager) {
    free(manager);
}

int main() {
    RecordManager *manager = record_manager_init();
    if (!manager) {
        fprintf(stderr, "Error: Failed to initialize manager.\n");
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_KEYS + 5; i++) { // Attempting to add more than max keys to test collision handling
        if (record_manager_add(manager, i) != 0) {
            fprintf(stderr, "Error: Failed to add record.\n");
        }
    }

    printf("Collision count: %d\n", manager->collision_count);
    record_manager_cleanup(manager);
    return 0;
}
