        time_t timestamp = time(NULL);
        for (int j = 0; j < i; j++) {
            if (store[j].value == value && store[j].timestamp == timestamp) {
                continue; // Collision detected, try again
            }
        }
        store[i].value = value;
        store[i].node_id = rand() % MAX_NODES + 1;
        store[i].timestamp = timestamp;
        i++;
    }

    *error = 0; // Initialization successful
    return store;
}

void free_record_store(record *store) {
    if (store) {
        free(store);
    }
}
