#include <iostream>
#include <forward_list>
#include <string>
#include <random>
#include <mutex>

struct record {
    int value;
};

std::mutex used_keys_mutex;

void insertAfterString(std::forward_list<std::string>& lst, const std::string& searchStr, const std::string& insertStr) {
    auto it = lst.begin();
    bool found = false;

    while (it != lst.end()) {
        if (*it == searchStr) {
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        lst.push_back(insertStr);
    } else {
        lst.insert_after(it, insertStr);
    }
}

void threadSafeFunction(std::forward_list<std::string>& lst, const std::string& key1, const std::string& key2) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 1000);

    record* records = new (std::nothrow) record[1024];
    if (!records) {
        throw std::bad_alloc();
    }

    for (int i = 0; i < 1024; ++i) {
        records[i].value = dis(gen);
    }

    int* offsets = new (std::nothrow) long[1024];
    int* keys = new (std::nothrow) int[1024];

    if (!offsets || !keys) {
        delete[] records;
        throw std::bad_alloc();
    }

    for (int i = 0; i < 1024; ++i) {
        offsets[i] = rand() % 10000; // Simulate offset
        keys[i] = i;

        std::lock_guard<std::mutex> lock(used_keys_mutex);
        while (std::find(keys, keys + i, i) != keys + i) {
            keys[i] = rand() % 1024;
        }
    }

    try {
        insertAfterString(lst, key1, key2);
    } catch (...) {
        delete[] records;
        delete[] offsets;
        delete[] keys;
        throw;
    }

    delete[] records;
    delete[] offsets;
    delete[] keys;
}
