#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

int hashFunction(int key, int size) {
    return key % size;
}

int* createKeySet() {
    return (int*)calloc(MAX_KEYS, sizeof(int));
}

void insertKey(int* keySet, int key) {
    int index = hashFunction(key, MAX_KEYS);
    while (keySet[index] != 0 && keySet[index] != -1) {
        if (++index == MAX_KEYS)
            index = 0;
    }
    keySet[index] = key;
}

int isValidKey(int* keySet, int key) {
    return key > 0 && key < MAX_KEYS && keySet[key] == 0;
}

record** createRecordArray(int size) {
    record** records = (record**)malloc(size * sizeof(record*));
    for (int i = 0; i < size; ++i)
        records[i] = (record*)malloc(sizeof(record));
    return records;
}

void populateRecords(record** records, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        do {
            records[i]->value = rand() % 1001;
        } while (searchRecord(records, size, records[i]->value));
    }
}

int searchRecord(record** records, int size, int value) {
    for (int i = 0; i < size; ++i)
        if (records[i]->value == value)
            return 1;
    return 0;
}

void cleanupRecords(record** records, int size) {
    for (int i = 0; i < size; ++i)
        free(records[i]);
    free(records);
}

int main() {
    int* keySet = createKeySet();
    record** records = createRecordArray(10);

    populateRecords(records, 10);

    cleanupRecords(records, 10);
    free(keySet);

    return 0;
}
