use std::fs::{self, DirBuilder};
use std::env;
use std::io::{BufRead, BufReader};
use std::sync::{Arc, Mutex};
use rand::Rng;

// Function to initialize task data structures and allocate memory
fn init_task_data(max_tasks: usize) -> (Vec<u64>, Vec<i32>, Vec<f32>, Arc<Mutex<Vec<i32>>>) {
    let timestamps = vec![0u64; max_tasks];
    let task_ids = vec![0i32; max_tasks];
    let priorities = vec![0f32; max_tasks];
    let used_ids = Arc::new(Mutex::new(vec![]));
    (timestamps, task_ids, priorities, used_ids)
}

// Function to read and find the median of a list of integers
fn find_median(numbers: &[i32]) -> f64 {
    let mut sorted_numbers = numbers.to_vec();
    sorted_numbers.sort();
    let mid = sorted_numbers.len() / 2;
    if sorted_numbers.len() % 2 == 0 {
        (sorted_numbers[mid - 1] as f64 + sorted_numbers[mid] as f64) / 2.0
    } else {
        sorted_numbers[mid] as f64
    }
}

// Function to create a new directory and set an environment variable
fn create_directory_and_set_env(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = format!("/path/to/{}", dir_name);
    DirBuilder::new().create(&dir_path)?;
    env::set_var("TASK_DIR", &dir_path);
    Ok(())
}

// Main function to demonstrate the implementation
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let max_tasks = 1024; // Configuration option for maximum number of tasks
    let (timestamps, task_ids, priorities, used_ids) = init_task_data(max_tasks);
    println!("Memory allocated successfully.");

    let file = File::open("input.txt")?;
    let reader = BufReader::new(file);

    for line in reader.lines() {
        if let Ok(num_str) = line {
            if let Ok(num) = num_str.trim().parse::<i32>() {
                // Add task to the system
                let mut used_ids_lock = used_ids.lock().unwrap();
                if used_ids_lock.len() < max_tasks && !used_ids_lock.contains(&num) {
                    used_ids_lock.push(num);
                    println!("Task ID {} added successfully.", num);
                } else {
                    println!("Cannot add task ID {}. Max tasks reached or duplicate found.", num);
                }
            } else {
                println!("Invalid integer in input: {}", line?);
            }
        }
    }

    let median = find_median(&task_ids.iter().filter(|id| used_ids.lock().unwrap().contains(id)).cloned().collect::<Vec<i32>>());
    println!("Median task ID: {:.2}", median);

    create_directory_and_set_env("tasks")?;
    println!("Directory created and environment variable set successfully.");

    Ok(())
}
