import java.util.Random;
import java.util.Set;

public class DataProcessor {

    private static final int MAX_KEYS = 1024;
    private static final double MIN_FLOAT = 0.0;
    private static final double MAX_FLOAT = 1.0;

    public void processRecords() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            long[] offsets = new long[MAX_KEYS];
            int[] keys = new int[MAX_KEYS];
            double[] payloads = new double[MAX_KEYS];

            Random random = new Random();
            Set<Integer> usedKeys = new HashSet<>();

            for (int i = 0; i < MAX_KEYS; i++) {
                while (true) {
                    int key = random.nextInt(MAX_KEYS);
                    if (!usedKeys.contains(key)) {
                        keys[i] = key;
                        usedKeys.add(key);
                        break;
                    }
                }
                payloads[i] = MIN_FLOAT + (MAX_FLOAT - MIN_FLOAT) * random.nextDouble();
            }

            record[] records = new record[MAX_KEYS];
            for (int i = 0; i < MAX_KEYS; i++) {
                int randomInt = random.nextInt(1, 1001);
                while (usedKeys.contains(randomInt)) {
                    randomInt = random.nextInt(1, 1001);
                }
                usedKeys.add(randomInt);
                records[i] = new record(randomInt, MIN_FLOAT + (MAX_FLOAT - MIN_FLOAT) * random.nextDouble());
            }

            int largestInteger = findLargestInteger(keys);
            double smallestFloat = findSmallestFloat(payloads);

            System.out.println("Largest Integer: " + largestInteger);
            System.out.println("Smallest Float: " + smallestFloat);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private int findLargestInteger(int[] integers) {
        int largest = Integer.MIN_VALUE;
        for (int i : integers) {
            if (i > largest) {
                largest = i;
            }
        }
        return largest;
    }

    private double findSmallestFloat(double[] floats) {
        double smallest = Double.MAX_VALUE;
        for (double f : floats) {
            if (f < smallest) {
                smallest = f;
            }
        }
        return smallest;
    }

    static class record {
        int value;
        double payload;

        record(int value, double payload) {
            this.value = value;
            this.payload = payload;
        }
    }

    public static void main(String[] args) {
        DataProcessor processor = new DataProcessor();
        processor.processRecords();
    }
}
