public class RemoteServerConnector {

    private static final int MAX_KEYS = 1024;
    private static final double MIN_FLOAT_VALUE = 0.0;
    private static final double MAX_FLOAT_VALUE = 1.0;

    public void connectToServer(String host, int port) throws IOException {
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.connect(new InetSocketAddress(host, port));

        Selector selector = Selector.open();
        channel.register(selector, SelectionKey.OP_CONNECT);

        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isConnectable()) {
                    channel.finishConnect();
                    initializeDataArrays();
                    performBatchedWrites(channel);
                    keyIterator.remove();
                }
            }
        }
    }

    private void initializeDataArrays() {
        long[] offsetValues = new long[MAX_KEYS];
        int[] keys = new int[MAX_KEYS];
        double[] floatValues = new double[MAX_KEYS];

        Random random = new Random();

        for (int i = 0; i < MAX_KEYS; i++) {
            do {
                keys[i] = random.nextInt(MAX_KEYS);
            } while (!isKeyUnique(keys, i));

            offsetValues[i] = random.nextLong();
            floatValues[i] = generateRandomFloatValue(random);
        }

        // Use the arrays for further operations
