    private boolean isKeyUnique(int[] keys, int index) {
        for (int i = 0; i < index; i++) {
            if (keys[index] == keys[i]) {
                return false;
            }
        }
        return true;
    }

    private double generateRandomFloatValue(Random random) {
        while (true) {
            double value = random.nextDouble();
            int scale = (int)(Math.log10(value));
            if (scale <= 0) {
                return value;
            }
        }
    }

