#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_KEYS 1024

typedef struct {
    long timestamp;
    float activity_level;
} record;

long* offsets;
int* keys;
record* records;
int offset_size, key_size, record_size;
int used_keys[MAX_KEYS];
pthread_mutex_t lock;

unsigned int xorshift32(unsigned int *x) {
    unsigned int z = (*x += 0x9e3779b9);
    z = (z ^ (z >> 15)) * 0x85ebca6b;
    z = (z ^ (z >> 13)) * 0xca0dc3;
    return z ^ (z >> 16);
}

long generate_key() {
    pthread_mutex_lock(&lock);
    unsigned int seed = time(NULL);
    while (1) {
        unsigned int key = xorshift32(&seed) % MAX_KEYS;
        if (!used_keys[key]) {
            used_keys[key] = 1;
            pthread_mutex_unlock(&lock);
            return key;
        }
    }
}

void init() {
    offsets = malloc(10 * sizeof(long));
    keys = malloc(10 * sizeof(int));
    records = malloc(10 * sizeof(record));
    offset_size = key_size = record_size = 10;
    memset(used_keys, 0, MAX_KEYS * sizeof(int));
    pthread_mutex_init(&lock, NULL);
}

void insert_record(long timestamp, float activity_level) {
    pthread_mutex_lock(&lock);
    if (record_size == key_size) {
        record_size *= 2;
        records = realloc(records, record_size * sizeof(record));
    }
    records[key_size - 1].timestamp = timestamp;
    records[key_size - 1].activity_level = activity_level;
    key_size++;
    pthread_mutex_unlock(&lock);
}

void cleanup() {
    pthread_mutex_lock(&lock);
    free(offsets);
    free(keys);
    free(records);
    memset(used_keys, 0, MAX_KEYS * sizeof(int));
    pthread_mutex_unlock(&lock);
}

int main() {
    init();
    long key = generate_key();
    insert_record(time(NULL), 1.23f);
    cleanup();
    return 0;
}
