static int used_keys[MAX_KEYS] = {0};
static pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays(record *records, long *offsets) {
    pthread_mutex_lock(&key_lock);
    for (int i = 0; i < MAX_KEYS; i++) {
        if (!used_keys[i]) {
            used_keys[i] = 1;
            offsets[i] = rand();
            break;
        }
    }
