import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.HashSet;
import java.util.Set;

public class RemoteServerConnection {

    private SocketChannel channel;
    private ByteBuffer longBuffer = ByteBuffer.allocateDirect(16);
    private ByteBuffer intBuffer = ByteBuffer.allocateDirect(4);
    private Set<Integer> usedKeys = new HashSet<>();

    public void connectToServer(String host, int port) throws IOException {
        channel = SocketChannel.open();
        channel.connect(new InetSocketAddress(host, port));
        channel.configureBlocking(false);
    }

    public long[] generateLongOffsets(int count) {
        long[] offsets = new long[count];
        for (int i = 0; i < count; i++) {
            offsets[i] = System.nanoTime(); // Using high-resolution timestamp as a pseudo-random value
        }
        return offsets;
    }

    public int[] generateUniqueKeys(int count, Set<Integer> usedKeys) {
        int[] keys = new int[count];
        for (int i = 0; i < count; i++) {
            int key;
            do {
                key = ThreadLocalRandom.current().nextInt(1, 1024);
            } while (!usedKeys.add(key));
            keys[i] = key;
        }
        return keys;
    }

    public void writeToServer(long[] offsets, int[] keys) throws IOException {
        for (int i = 0; i < offsets.length; i++) {
            longBuffer.clear();
            longBuffer.putLong(offsets[i]);
            channel.write(longBuffer);

            intBuffer.clear();
            intBuffer.putInt(keys[i]);
            channel.write(intBuffer);
        }
    }

    public void closeConnection() throws IOException {
        if (channel != null) {
            channel.close();
        }
    }

    public static void main(String[] args) {
        try {
            RemoteServerConnection client = new RemoteServerConnection();
            client.connectToServer("example.com", 12345);

            int count = 100;
            long[] offsets = client.generateLongOffsets(count);
            int[] keys = client.generateUniqueKeys(count, client.usedKeys);

            client.writeToServer(offsets, keys);

            client.closeConnection();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

This code provides a basic structure for connecting to a remote server using Java NIO Channels and managing the connection lifecycle. It includes methods for generating long offsets and unique keys, writing data to the server, and closing the connection. Error handling is minimal, focusing on basic I/O exceptions. For a more comprehensive solution, additional features such as logging, memory management, and concurrency control would need to be implemented.']

