    pthread_mutex_init(&lock, NULL);
    srand(seed);

    capacity = INITIAL_CAPACITY;
    size = 0;

    offsets = (uint64_t*)malloc(capacity * sizeof(uint64_t));
    keys = (uint32_t*)malloc(capacity * sizeof(uint32_t));
    records = (Record*)malloc(capacity * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
