    pthread_mutex_lock(&lock);

    if (size == capacity) {
        capacity *= 2;
        offsets = (uint64_t*)realloc(offsets, capacity * sizeof(uint64_t));
        keys = (uint32_t*)realloc(keys, capacity * sizeof(uint32_t));
        records = (Record*)realloc(records, capacity * sizeof(Record));

        if (!offsets || !keys || !records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    offsets[size] = rand();
