#define BUNDLE_MAX_ITEMS 1000

typedef struct {
    char** keys;
    int* values;
    int size;
    pthread_mutex_t lock;
} ResourceBundle;

ResourceBundle* load_resource_bundle(const char* file_path) {
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) return NULL;

    // Initialize mutex
    pthread_mutex_init(&bundle->lock, NULL);

    // Simulate loading from file
    FILE* file = fopen(file_path, "r");
    if (!file) {
        free(bundle);
        return NULL;
    }

    bundle->keys = (char**)malloc(BUNDLE_MAX_ITEMS * sizeof(char*));
    bundle->values = (int*)malloc(BUNDLE_MAX_ITEMS * sizeof(int));
    if (!bundle->keys || !bundle->values) {
        pthread_mutex_destroy(&bundle->lock);
        free(bundle->keys);
        free(bundle->values);
        fclose(file);
        return NULL;
    }

    int i = 0;
    char key[256];
    int value;

    while (fscanf(file, "%s %d", key, &value) == 2 && i < BUNDLE_MAX_ITEMS) {
        bundle->keys[i] = strdup(key);
        if (!bundle->keys[i]) {
            pthread_mutex_destroy(&bundle->lock);
            for (int j = 0; j < i; j++) free(bundle->keys[j]);
            free(bundle->keys);
            free(bundle->values);
            fclose(file);
            return NULL;
        }
        bundle->values[i] = value;
        i++;
    }

    fclose(file);
    bundle->size = i;

    return bundle;
}

void free_resource_bundle(ResourceBundle* bundle) {
    if (!bundle) return;

    pthread_mutex_lock(&bundle->lock);

    for (int i = 0; i < bundle->size; i++) free(bundle->keys[i]);

    pthread_mutex_unlock(&bundle->lock);

    free(bundle->keys);
    free(bundle->values);
    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

int main() {
    srand(time(NULL));

    ResourceBundle* bundle = load_resource_bundle("resources.txt");
    if (bundle) {
        printf("Loaded %d items from resource bundle.\n", bundle->size);

        // Example usage
        int key_to_find = rand();
        pthread_mutex_lock(&bundle->lock);
        for (int i = 0; i < bundle->size; i++) {
            if (atoi(bundle->keys[i]) == key_to_find) {
                printf("Found key %d with value %d\n", key_to_find, bundle->values[i]);
                break;
            }
        }
        pthread_mutex_unlock(&bundle->lock);

        free_resource_bundle(bundle);
    } else {
        printf("Failed to load resource bundle.\n");
    }

    return 0;
}
