void initialize_session_management(const char *config_path) {
    // Load configuration file and initialize resources
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }

    used_ids = malloc(sizeof(unsigned long) * MAX_SESSIONS);
    if (!used_ids) {
        perror("Memory allocation failed for used_ids");
        fclose(file);
        exit(EXIT_FAILURE);
    }
    memset(used_ids, 0, sizeof(unsigned long) * MAX_SESSIONS);

    sessions = malloc(sizeof(UserSession) * MAX_SESSIONS);
    if (!sessions) {
        perror("Memory allocation failed for sessions");
        free(used_ids);
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Process configuration file and generate session identifiers
    while (fscanf(file, "%lu", &session_count) == 1 && session_count > 0) {
        if (session_count >= MAX_SESSIONS) {
            fprintf(stderr, "Too many sessions specified in config file\n");
            exit(EXIT_FAILURE);
