        for (int i = 0; i < session_count; ++i) {
            pthread_mutex_lock(&lock);
            unsigned long id;
            do {
                id = generate_unique_id();
            } while (used_ids[id % MAX_SESSIONS]);
            used_ids[id % MAX_SESSIONS] = 1;
            sessions[i].id = id;
            // Initialize user-specific information fields here
            pthread_mutex_unlock(&lock);
        }
    }

    fclose(file);
}

void cleanup_session_management() {
