    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        return -1;
    }

    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = create_records(size);

    if (!*offsets || !*keys || !*records) {
        perror("Memory allocation failed");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    srand(seed);
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % range_max + range_min;
        (*records)[i].value = rand() % range_max + range_min;
    }

    return 0;
}

void free_arrays(long* offsets, int* keys, record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
