typedef struct {
    long offset;
    int sequenceNumber;
    char status;
} Record;

// Custom PRNG for performance-critical applications
static unsigned long customPRNG(unsigned long *seed) {
    *seed = (*seed * 1664525UL + 1013904223UL);
    return *seed;
}

int initializeRecords(Record **records, int count, int minSeq, int maxSeq, time_t seedTime) {
    if (count <= 0 || minSeq >= maxSeq) return -1; // Invalid input
    unsigned long seed = ((unsigned long)seedTime << 32) | (seedTime & 0xFFFFFFFF);

    *records = malloc(count * sizeof(Record));
    if (*records == NULL) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for records");
        return -1;
    }

    int *allocatedSeqs = malloc((maxSeq - minSeq + 1) * sizeof(int));
    if (allocatedSeqs == NULL) {
        free(*records);
        perror("Failed to allocate memory for allocated sequence numbers");
        return -1;
    }

    for (int i = 0; i < maxSeq - minSeq + 1; ++i) allocatedSeqs[i] = 0;

    for (int i = 0; i < count; ) {
        unsigned long randVal = customPRNG(&seed);
        int seqNum = minSeq + randVal % (maxSeq - minSeq + 1);

        if (!allocatedSeqs[seqNum - minSeq]) {
            (*records)[i].offset = rand();
            (*records)[i].sequenceNumber = seqNum;
            (*records)[i].status = 'A'; // Assuming 'A' is the initial status
            allocatedSeqs[seqNum - minSeq] = 1;
            ++i;
        }
    }

    free(allocatedSeqs);
    return count;
}

// Example usage and testing (Not part of the function)
int main() {
    Record *records;
    int count = 1000;
    int minSeq = 100, maxSeq = 999;

    time_t seedTime = time(NULL);
    if (initializeRecords(&records, count, minSeq, maxSeq, seedTime) == -1) {
        fprintf(stderr, "Initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Free allocated memory when done
    free(records);

    return EXIT_SUCCESS;
}
