ErrorCode loadResourceBundle(const char* filePath, OffsetRecord** offsets, IntKeyRecord** keys) {
    FILE* file = fopen(filePath, "rb");
    if (!file) return FILE_ERROR;

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    *offsets = (OffsetRecord*)malloc(fileSize);
    *keys = (IntKeyRecord*)malloc((fileSize / sizeof(long)) * sizeof(IntKeyRecord));

    if (!*offsets || !*keys) {
        free(*offsets);
        fclose(file);
        return MEMORY_ERROR;
    }

    fread(*offsets, 1, fileSize, file);
    int numItems = fileSize / sizeof(long);

    for (int i = 0; i < numItems; i++) {
        (*keys)[i].key = rand(); // Using rand() as a placeholder for CSPRNG
    }

    fclose(file);
    return SUCCESS;
}

void freeResourceBundle(OffsetRecord* offsets, IntKeyRecord* keys) {
    free(offsets);
    free(keys);
}

