} memory_manager;

memory_manager* create_memory_manager(size_t initial_capacity) {
    memory_manager *mm = malloc(sizeof(memory_manager));
    if (!mm) return NULL;

    mm->offsets = malloc(initial_capacity * sizeof(long));
    mm->keys = malloc(initial_capacity * sizeof(int));
    mm->records = malloc(initial_capacity * sizeof(record*));
    if (!mm->offsets || !mm->keys || !mm->records) {
        free(mm);
        return NULL;
    }

    mm->size = 0;
    mm->capacity = initial_capacity;

    srand(time(NULL)); // Initialize PRNG with system time for uniqueness

    return mm;
}

int add_record(memory_manager *mm, int key, record value) {
    if (key >= MAX_KEYS || key < 0) return -1; // Key out of bounds
    if (mm->size == mm->capacity) {
        size_t new_capacity = mm->capacity ? mm->capacity * 2 : 16;
        long *new_offsets = realloc(mm->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(mm->keys, new_capacity * sizeof(int));
        record **new_records = realloc(mm->records, new_capacity * sizeof(record*));
        if (!new_offsets || !new_keys || !new_records) return -1;

        mm->offsets = new_offsets;
        mm->keys = new_keys;
        mm->records = new_records;
        mm->capacity = new_capacity;
    }

    for (size_t i = 0; i < mm->size; ++i) {
        if (mm->keys[i] == key) return -1; // Duplicate key
    }

    mm->offsets[mm->size] = 0; // Placeholder for offset
    mm->keys[mm->size] = key;
    mm->records[mm->size] = malloc(sizeof(record));
    if (!mm->records[mm->size]) return -1;

    *mm->records[mm->size] = value;
    ++mm->size;

    return 0;
}

void free_memory_manager(memory_manager *mm) {
    for (size_t i = 0; i < mm->size; ++i) {
        free(mm->records[i]);
    }
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    free(mm);
}
