import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class DatabaseManager {
    private ConcurrentHashMap<String, Database> databases = new ConcurrentHashMap<>();
    private ReentrantLock lock = new ReentrantLock();
    private int maxDatabases;
    private double memoryThreshold;
    private long retentionPolicy;

    public DatabaseManager(int maxDatabases, double memoryThreshold, long retentionPolicy) {
        this.maxDatabases = maxDatabases;
        this.memoryThreshold = memoryThreshold;
        this.retentionPolicy = retentionPolicy;
    }

    public String createDatabase() {
        lock.lock();
        try {
            if (databases.size() >= maxDatabases) {
                throw new IllegalStateException("Maximum number of databases reached");
            }
            long id = generateUniqueId();
            Database db = new Database(id, memoryThreshold);
            databases.put(String.valueOf(id), db);
            return String.valueOf(id);
        } finally {
            lock.unlock();
        }
    }

    public void deleteDatabase(String id) {
        lock.lock();
        try {
            databases.remove(id);
        } finally {
            lock.unlock();
        }
    }

