#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct record {
    int value;
} Record;

typedef struct memory_manager {
    long* offset_values;
    int* keys;
    Record** records;
    int num_records;
    int max_records;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} MemoryManager;

MemoryManager* create_memory_manager(int initial_size) {
    MemoryManager* mm = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!mm) {
        perror("Failed to allocate memory for MemoryManager");
        return NULL;
    }
    mm->offset_values = (long*)calloc(initial_size, sizeof(long));
    mm->keys = (int*)calloc(initial_size, sizeof(int));
    mm->records = (Record**)calloc(initial_size, sizeof(Record*));
    if (!mm->offset_values || !mm->keys || !mm->records) {
        perror("Failed to allocate memory for data structures");
        free(mm->offset_values);
        free(mm->keys);
        free(mm->records);
        free(mm);
        return NULL;
    }
    mm->num_records = 0;
    mm->max_records = initial_size;
    pthread_mutex_init(&mm->lock, NULL);
    pthread_cond_init(&mm->cond, NULL);
    return mm;
}

void destroy_memory_manager(MemoryManager* mm) {
    if (mm) {
        for (int i = 0; i < mm->num_records; ++i) {
            free(mm->records[i]);
        }
        free(mm->offset_values);
        free(mm->keys);
        free(mm->records);
        pthread_mutex_destroy(&mm->lock);
        pthread_cond_destroy(&mm->cond);
        free(mm);
    }
}

int add_record(MemoryManager* mm, int value) {
    if (!mm || !value) return -1;

    pthread_mutex_lock(&mm->lock);

    while (mm->num_records >= mm->max_records) {
        pthread_cond_wait(&mm->cond, &mm->lock);
    }

    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) {
        perror("Failed to allocate memory for new record");
        pthread_mutex_unlock(&mm->lock);
        return -1;
    }
    rec->value = value;

    int key;
    while (1) {
        key = rand_r((unsigned int*)&time(NULL)) % MAX_KEYS;
        int found = 0;
        for (int i = 0; i < mm->num_records; ++i) {
            if (mm->keys[i] == key) {
                found = 1;
                break;
            }
        }
        if (!found) break;
    }

    mm->offset_values[mm->num_records] = (long)(rec - mm->records);
    mm->keys[mm->num_records] = key;
    mm->records[mm->num_records++] = rec;

    pthread_cond_signal(&mm->cond);
    pthread_mutex_unlock(&mm->lock);

    return 0;
}

void* record_generator(void* arg) {
    MemoryManager* mm = (MemoryManager*)arg;
    if (!mm) return NULL;

    while (1) {
        int value = rand_r((unsigned int*)&time(NULL)) % 100; // Adjust range as needed
        add_record(mm, value);
        sleep(1); // Simulate real-time data generation
    }

    return NULL;
}

int main() {
    MemoryManager* mm = create_memory_manager(10);

    if (mm) {
        pthread_t thread;
        pthread_create(&thread, NULL, record_generator, mm);

        pthread_join(thread, NULL);
        destroy_memory_manager(mm);
    }

    return 0;
}
```

