#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

long *offsets = NULL;
int *keys = NULL;
record *records = NULL;
uint8_t used_keys[MAX_KEYS] = {0};
pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

void seed_prng(uint64_t seed) {
    srand(seed);
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* generate_records(int count, int min_value, int max_value) {
    records = allocate_memory(count * sizeof(record));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

void* generate_keys(int count, int max_key) {
    keys = allocate_memory(count * sizeof(int));
    for (int i = 0; i < count; i++) {
        int key;
        do {
            key = rand() % max_key;
        } while (used_keys[key]);
        used_keys[key] = 1;
        keys[i] = key;
    }
    return keys;
}

void* generate_offsets(int count, int min_offset, int max_offset) {
    offsets = allocate_memory(count * sizeof(long));
    for (int i = 0; i < count; i++) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
    }
    return offsets;
}

void free_resources() {
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&key_lock);
}

int read_integers_and_find_max() {
    int count;
    printf("Enter the number of integers: ");
    if (scanf("%d", &count) != 1 || count <= 0) {
        fprintf(stderr, "Invalid input\n");
        return -1;
    }

    int* numbers = allocate_memory(count * sizeof(int));
    for (int i = 0; i < count; i++) {
        printf("Enter integer %d: ", i + 1);
        if (scanf("%d", &numbers[i]) != 1) {
            fprintf(stderr, "Invalid input\n");
            free(numbers);
            return -1;
        }
    }

    int max = numbers[0];
    for (int i = 1; i < count; i++) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }

    printf("The largest integer is: %d\n", max);
    free(numbers);
    return max;
}

void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = thread_id; i < 1000; i += pthread_num_threads()) {
        pthread_mutex_lock(&key_lock);
        if (!used_keys[i]) {
            used_keys[i] = 1;
            keys[thread_id] = i;
            pthread_mutex_unlock(&key_lock);
            break;
        }
        pthread_mutex_unlock(&key_lock);
    }
    return NULL;
}

int main() {
    seed_prng(time(NULL));
    generate_records(10, 0, 1000);
    generate_keys(10, MAX_KEYS - 1);
    generate_offsets(10, 0, 1000);

    int num_threads = 4;
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &i);
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    read_integers_and_find_max();
    free_resources();

    return 0;
}
