import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.security.SecureRandom;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class RemoteServiceConnector {

    private static final int MAX_KEYS = 1024;
    private static final int MIN_VALUE = 1;
    private static final int MAX_VALUE = 1000;

    private Selector selector;
    private SocketChannel socketChannel;
    private ByteBuffer longBuffer = ByteBuffer.allocate(8);
    private ByteBuffer intBuffer = ByteBuffer.allocate(4);
    private SecureRandom secureRandom = new SecureRandom();
    private Map<Integer, Integer> usedKeys = new ConcurrentHashMap<>();

    public void connect(String host, int port) throws IOException {
        selector = Selector.open();
        socketChannel = SocketChannel.open(new InetSocketAddress(host, port));
        socketChannel.configureBlocking(false);
        socketChannel.register(selector, SelectionKey.OP_CONNECT);
    }

    public void manageConnection() throws IOException {
        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> iter = selectedKeys.iterator();

            while (iter.hasNext()) {
                SelectionKey key = iter.next();
                if (!key.isValid()) {
                    continue;
                }

                if (key.isConnectable()) {
                    connect(key);
                } else if (key.isWritable()) {
                    writeData(key);
                }
                iter.remove();
            }
        }
    }

    private void connect(SelectionKey key) throws IOException {
        socketChannel.finishConnect();
        key.interestOps(SelectionKey.OP_WRITE);
    }

    private void writeData(SelectionKey key) throws IOException {
        if (usedKeys.size() >= MAX_KEYS) {
            throw new IllegalStateException("Maximum keys reached");
        }

        int randomInt;
        do {
            randomInt = secureRandom.nextInt(MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        } while (usedKeys.containsKey(randomInt));

        usedKeys.put(randomInt, randomInt);
        longBuffer.clear();
        intBuffer.clear();

        // Populate buffers with data
        longBuffer.putLong(0); // Placeholder for offset
        intBuffer.putInt(randomInt);

        socketChannel.write(longBuffer);
        socketChannel.write(intBuffer);
    }

    public void readFromInput() {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextInt()) {
            int input = scanner.nextInt();
            if (input < MIN_VALUE || input > MAX_VALUE) {
                System.out.println("Invalid input. Please enter a number between 1 and 1000.");
                continue;
            }
            // Store or process the input
        }
    }

    public int findLargestInteger(int[] array) {
        return Arrays.stream(array).max().orElseThrow(NoSuchElementException::new);
    }

    public void cleanup() throws IOException {
        if (socketChannel != null && socketChannel.isOpen()) {
            socketChannel.close();
        }
        if (selector != null && selector.isOpen()) {
            selector.close();
        }
        usedKeys.clear();
    }

    // Unit tests
    public static void main(String[] args) {
        RemoteServiceConnector connector = new RemoteServiceConnector();
        try {
            connector.connect("remote.host", 1234);
            connector.manageConnection();
            int[] inputArray = {10, 20, 30, 40};
            System.out.println("Largest integer: " + connector.findLargestInteger(inputArray));
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                connector.cleanup();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
