#define MAX_SESSIONS 1024
#define BUFFER_SIZE 256

typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    short id;
    int is_used;
} UniqueID;

typedef struct {
    double value;
} Transaction;

typedef struct {
    char data[BUFFER_SIZE];
} Metadata;

OffsetStruct* offsets[MAX_SESSIONS];
UniqueID* unique_ids[MAX_SESSIONS];
Transaction* transactions[MAX_SESSIONS];
Metadata* metadata[MAX_SESSIONS];

int init_structs(int max_sessions) {
    for (int i = 0; i < max_sessions; ++i) {
        offsets[i] = malloc(sizeof(OffsetStruct));
        unique_ids[i] = malloc(sizeof(UniqueID));
        transactions[i] = malloc(sizeof(Transaction));
        metadata[i] = malloc(BUFFER_SIZE * sizeof(char));

        if (!offsets[i] || !unique_ids[i] || !transactions[i] || !metadata[i]) {
            printf("Memory allocation failed for session %d\n", i);
            return -1;
        }
    }
    return 0;
}

void cleanup_structs(int max_sessions) {
    for (int i = 0; i < max_sessions; ++i) {
        free(offsets[i]);
        free(unique_ids[i]);
        free(transactions[i]);
        free(metadata[i]);
    }
}

int generate_unique_id(UniqueID* ids, int size) {
    while (1) {
        short id = arc4random_uniform(65536);
        for (int i = 0; i < size; ++i) {
            if (!ids[i].is_used && ids[i].id == id) {
                ids[i].is_used = 1;
                return id;
            }
        }
    }
}

void initialize_transactions(Transaction* transactions, int count, double min_value, double max_value) {
    for (int i = 0; i < count; ++i) {
        transactions[i].value = arc4random_uniform(max_value * 1000000) / 1000000.0 + min_value;
    }
}

void generate_session_token(Metadata* metadata, int index) {
    snprintf(metadata[index].data, BUFFER_SIZE, "%llx", (unsigned long long)index);
}

int main() {
    srand(time(NULL));

    if (init_structs(MAX_SESSIONS) == -1) {
        printf("Failed to initialize structures\n");
        return 1;
    }

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        offsets[i]->offset = rand();
        unique_ids[i]->id = generate_unique_id(unique_ids, MAX_SESSIONS);
        transactions[i]->value = 0.0;
        generate_session_token(metadata, i);
    }

    cleanup_structs(MAX_SESSIONS);

    return 0;
