    for (int i = 0; i < array_size; i++) {
        long_array[i] = i + 1;
        int_array[i] = i * 2 + 3;
    }

    // Linear Congruential Generator (LCG) parameters
    unsigned long lcg_a = 1664525;
    unsigned long lcg_c = 1013904223;
    unsigned long lcg_m = 4294967296;

    // Seed for LCG (using time as a simple seed generator)
    unsigned long lcg_seed = (unsigned long)time(NULL);
    lcg_seed = (lcg_seed * lcg_a + lcg_c) % lcg_m;

    // Fill record array with random numbers
    for (int i = 0; i < array_size; i++) {
        if ((long)(range_end - range_start + 1) > UINT_MAX / lcg_m) {
            // Handle potential overflow
            free(long_array);
            free(int_array);
            free(record_array);
            return NULL;
        }
        record_array[i].value = (int)((lcg_seed * lcg_a + lcg_c) % lcg_m % (unsigned)(range_end - range_start + 1)) + range_start;
        lcg_seed = (lcg_seed * lcg_a + lcg_c) % lcg_m; // Update seed
    }

    return record_array;
}
