#define MAX_RECORDS 1024

typedef struct {
    int value;
} record;

void* memory_pool[MAX_RECORDS];
int pool_index = -1;

record* allocate_record() {
    if (pool_index >= MAX_RECORDS) {
        return NULL; // Pool exhausted
    }
    if (memory_pool[pool_index] == NULL) {
        memory_pool[pool_index] = malloc(sizeof(record));
        if (memory_pool[pool_index] == NULL) {
            return NULL; // Memory allocation failed
        }
    }
    record* rec = (record*)memory_pool[pool_index];
    pool_index++;
    return rec;
}

void free_record(record* rec) {
    int index = -1;
    for (int i = 0; i <= pool_index; i++) {
        if (memory_pool[i] == (void*)rec) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        memory_pool[index] = NULL;
    }
}

void initialize_arrays(long** offsets, int** keys, int size) {
    *offsets = malloc(size * sizeof(long));
    *keys = malloc(size * sizeof(int));
