        (*timestamp_array)[i] = i * 1000; // Sequential timestamp initialization
        (*id_array)[i] = i + 1; // Sequential ID initialization

        transactions[i].amount = rand() % (range_max - range_min) + range_min; // LCG for transaction IDs
        transactions[i].description = malloc(256 * sizeof(char));
        if (transactions[i].description == NULL) {
            free(*timestamp_array);
            free(*id_array);
            free(transactions);
            for (int j = 0; j < i; j++) {
                free(transactions[j].description);
            }
            return NULL;
        }

        // Generate a random ID within the specified range
        sprintf(transactions[i].description, "TX%d", rand() % (range_max - range_min) + range_min);
    }

    srand(time(0)); // Seed PRNG for better randomness

