['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ConnectionPool {

    private static final Logger LOGGER = Logger.getLogger(ConnectionPool.class.getName());
    private static final int MAX_RECORDS = 1024;
    private static final int RECORD_SIZE = 4; // Assuming each record is an integer
    private static final int MAX_CONNECTION_ATTEMPTS = 5;
    private static final long EVICTION_THRESHOLD = 1000L;

    private final List<InetSocketAddress> addresses;
    private final Selector selector;
    private final AtomicInteger keyPool;
    private final Map<Integer, byte[]> recordsCache;
    private final Map<Integer, SocketChannel> channels;
    private final Random random;

    public ConnectionPool(List<String> addressStrings) throws IOException {
        this.addresses = new ArrayList<>();
        for (String address : addressStrings) {
            String[] parts = address.split(":");
            addresses.add(new InetSocketAddress(parts[0], Integer.parseInt(parts[1])));
        }
        this.selector = Selector.open();
        this.keyPool = new AtomicInteger(1); // Start from 1 to avoid zero
        this.recordsCache = new ConcurrentHashMap<>();
        this.channels = new ConcurrentHashMap<>();
        this.random = new SecureRandom();

        for (int i = 0; i < MAX_RECORDS; i++) {
            recordsCache.put(i, ByteBuffer.allocate(RECORD_SIZE).putInt(random.nextInt(1000)).array());
        }
    }

    public void run() throws IOException {
        while (!Thread.currentThread().isInterrupted()) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            for (SelectionKey key : selectedKeys) {
                if (!key.isValid()) continue;

                SocketChannel channel = (SocketChannel) key.channel();
                try {
                    if (key.isConnectable()) {
                        connect(channel);
                    } else if (key.isReadable()) {
                        readData(channel);
                    }
                } catch (IOException e) {
                    handleException(channel, e);
                }
            }
            selectedKeys.clear();
        }
    }

    private void connect(SocketChannel channel) throws IOException {
        if (channel.finishConnect()) {
            LOGGER.info("Connection successful: " + channel.getRemoteAddress());
            channel.register(selector, SelectionKey.OP_READ);
            processRecordsForChannel(channel);
        } else {
            LOGGER.warning("Failed to connect to: " + channel.getRemoteAddress());
        }
    }

    private void readData(SocketChannel channel) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(RECORD_SIZE);
        int bytesRead = channel.read(buffer);
        if (bytesRead == -1) {
            channel.close();
            channels.remove(channel.socket().getPort());
            LOGGER.info("Connection closed: " + channel.getRemoteAddress());
        } else {
            buffer.flip();
            while (buffer.hasRemaining()) {
                int key = buffer.getInt() & 0x3FF; // Mask to ensure key is less than 1024
                byte[] record = recordsCache.get(key);
                if (record != null) {
                    processRecord(record, channel);
                }
            }
        }
    }

    private void processRecordsForChannel(SocketChannel channel) throws IOException {
        for (int i = 0; i < MAX_RECORDS; i++) {
            int key = keyPool.getAndIncrement() & 0x3FF;
            byte[] record = recordsCache.get(key);
            if (record != null) {
                channel.write(ByteBuffer.wrap(record));
            }
        }
    }

    private void processRecord(byte[] record, SocketChannel channel) throws IOException {
        // Process the record
        LOGGER.fine("Processing record: " + ByteBuffer.wrap(record).getInt());
    }

    private void handleException(SocketChannel channel, IOException e) throws IOException {
        channel.close();
        channels.remove(channel.socket().getPort());
        LOGGER.log(Level.SEVERE, "Error processing connection: " + channel.getRemoteAddress(), e);
    }

    public void shutdown() throws IOException {
        selector.wakeup();
        selector.close();
        for (SocketChannel channel : channels.values()) {
            channel.close();
        }
    }
}
