typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    unsigned short id;
} IdentifierStruct;

typedef struct {
    double value;
} TransactionStruct;

typedef struct {
    char metadata[257];
} MetadataStruct;

typedef struct {
    OffsetStruct *offsets;
    IdentifierStruct *identifiers;
    TransactionStruct *transactions;
    MetadataStruct *metadatas;
    int max_sessions;
    int used_identifiers_count;
    unsigned short *used_identifiers;
} SessionManager;

SessionManager* create_session_manager(int max_sessions) {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->max_sessions = max_sessions;
    manager->offsets = (OffsetStruct*)calloc(max_sessions, sizeof(OffsetStruct));
    manager->identifiers = (IdentifierStruct*)calloc(max_sessions, sizeof(IdentifierStruct));
    manager->transactions = (TransactionStruct*)calloc(max_sessions, sizeof(TransactionStruct));
    manager->metadatas = (MetadataStruct*)calloc(max_sessions, sizeof(MetadataStruct));
    manager->used_identifiers_count = 0;
    manager->used_identifiers = (unsigned short*)malloc(sizeof(unsigned short) * max_sessions);
    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    free(manager->offsets);
    free(manager->identifiers);
    free(manager->transactions);
    free(manager->metadatas);
    free(manager->used_identifiers);
    free(manager);
}

int allocate_session_id(SessionManager *manager, unsigned short new_id) {
    for (int i = 0; i < manager->used_identifiers_count; i++) {
        if (manager->used_identifiers[i] == new_id) {
            return -1;
        }
    }
    manager->used_identifiers[manager->used_identifiers_count++] = new_id;
    return 0;
}

void deallocate_session_id(SessionManager *manager, unsigned short id_to_deallocate) {
    for (int i = 0; i < manager->used_identifiers_count; i++) {
        if (manager->used_identifiers[i] == id_to_deallocate) {
            manager->used_identifiers[i] = manager->used_identifiers[--manager->used_identifiers_count];
            return;
        }
    }
}

