        fprintf(stderr, "Invalid session index\n");
        return;
    }

    unsigned long seed = time(NULL);
    DRBG_st *drbg = DRBG_new(NID_sha256, NULL, NULL, &seed);

    if (!DRBG_instantiate(drbg, (unsigned char*)&min_value, sizeof(min_value), (unsigned char*)&max_value, sizeof(max_value))) {
        fprintf(stderr, "Failed to instantiate DRBG\n");
        return;
    }

    unsigned char buf[sizeof(double)];
    if (!DRBG_generate(drbg, buf, sizeof(buf), 0)) {
        fprintf(stderr, "Failed to generate random number\n");
        return;
    }

    manager->transactions[session_index].value = *((double*)buf);

    DRBG_uninstantiate(drbg);
    DRBG_free(drbg);
}

void log_performance(const char *message) {
    // Implement logging mechanism here
}

