#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t record_count;
    pthread_mutex_t lock;
} data_struct;

data_struct* create_data_struct(size_t initial_capacity) {
    data_struct* ds = malloc(sizeof(data_struct));
    if (!ds) return NULL;

    ds->offsets = calloc(initial_capacity, sizeof(long));
    ds->keys = calloc(initial_capacity, sizeof(int));
    ds->records = calloc(initial_capacity, sizeof(record*));
    ds->record_count = 0;
    pthread_mutex_init(&ds->lock, NULL);

    if (!ds->offsets || !ds->keys || !ds->records) {
        destroy_data_struct(ds);
        return NULL;
    }

    return ds;
}

void destroy_data_struct(data_struct* ds) {
    for (size_t i = 0; i < ds->record_count; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int add_record(data_struct* ds, int key, long offset) {
    pthread_mutex_lock(&ds->lock);

    if (ds->record_count >= MAX_KEYS || key >= MAX_KEYS || ds->keys[key] != 0) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    record* rec = malloc(sizeof(record));
    if (!rec) {
        pthread_mutex_unlock(&ds->lock);
        return -2;
    }

    rec->value = rand() % 1001; // Random value between 1 and 1000
    ds->records[ds->record_count] = rec;
    ds->keys[key] = offset;
    ds->offsets[ds->record_count++] = offset;

    pthread_mutex_unlock(&ds->lock);
    return 0;
}

void resize_data_struct(data_struct* ds, size_t new_capacity) {
    pthread_mutex_lock(&ds->lock);

    long* new_offsets = realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = realloc(ds->keys, new_capacity * sizeof(int));
    record** new_records = realloc(ds->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_records) {
        // Handle reallocation failure (cleanup)
        pthread_mutex_unlock(&ds->lock);
        return;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;

    pthread_mutex_unlock(&ds->lock);
}

int main() {
    srand(time(NULL));
    data_struct* ds = create_data_struct(10);

    if (!ds) return -1;

    for (int i = 0; i < 5; ++i) {
        int key = rand() % MAX_KEYS;
        long offset = rand();
        add_record(ds, key, offset);
    }

    resize_data_struct(ds, 20); // Example of resizing

    destroy_data_struct(ds);

    return 0;
}
