#include <openssl/rand.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t num_records;
    size_t capacity;
    pthread_mutex_t lock;
} KeyRecordManager;

KeyRecordManager* create_key_record_manager(size_t initial_capacity) {
    KeyRecordManager *manager = malloc(sizeof(KeyRecordManager));
    if (!manager) return NULL;

    manager->offsets = malloc(initial_capacity * sizeof(long));
    manager->keys = malloc(initial_capacity * sizeof(int));
    manager->records = malloc(initial_capacity * sizeof(Record));
    manager->num_records = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_key_record_manager(KeyRecordManager *manager) {
    if (manager) {
        free(manager->offsets);
        free(manager->keys);
        for (size_t i = 0; i < manager->num_records; ++i) {
            // Assuming records contain pointers or dynamically allocated memory
            // Free any such resources here.
        }
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int generate_unique_key(KeyRecordManager *manager, int min_value, int max_value) {
    pthread_mutex_lock(&manager->lock);
    int key;
    do {
        if (!RAND_bytes((unsigned char *)&key, sizeof(key))) {
            // Handle error: PRNG failed
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        key = (int)((uint64_t)key * (max_value - min_value + 1)) / UINT64_MAX + min_value;
    } while (is_key_used(manager, key));
    manager->keys[manager->num_records] = key;
    pthread_mutex_unlock(&manager->lock);
    return key;
}

int is_key_used(KeyRecordManager *manager, int key) {
    for (size_t i = 0; i < manager->num_records; ++i) {
        if (manager->keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

void add_record(KeyRecordManager *manager, Record record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->num_records >= manager->capacity) {
        // Resize the arrays if needed
        manager->offsets = realloc(manager->offsets, manager->capacity * 2 * sizeof(long));
        manager->keys = realloc(manager->keys, manager->capacity * 2 * sizeof(int));
        manager->records = realloc(manager->records, manager->capacity * 2 * sizeof(Record));
        if (!manager->offsets || !manager->keys || !manager->records) {
            // Handle error: Memory reallocation failed
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->capacity *= 2;
    }
    manager->records[manager->num_records] = record;
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    srand(time(NULL));
    KeyRecordManager *manager = create_key_record_manager(100);

    Record new_record;
    for (int i = 0; i < 100; ++i) {
        new_record.value = rand() % 1000 + 1;
        add_record(manager, new_record);
    }

    destroy_key_record_manager(manager);
    return 0;
}
```

