#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    uint64_t session_id;
    char user_handle[256];
} SessionRecord;

typedef struct {
    SessionRecord *sessions;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} SessionPool;

void init_session_pool(SessionPool *pool, size_t initial_capacity) {
    pool->sessions = malloc(initial_capacity * sizeof(SessionRecord));
    if (pool->sessions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pool->capacity = initial_capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_session_pool(SessionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->sessions);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

uint64_t generate_session_id() {
    static uint64_t last_id = 0;
    uint64_t new_id;
    do {
        new_id = rand();
    } while (new_id == last_id); // Avoid collisions
    last_id = new_id;
    return new_id;
}

void add_session(SessionPool *pool, const char *user_handle) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used >= pool->capacity) {
        pool->sessions = realloc(pool->sessions, pool->capacity * 2 * sizeof(SessionRecord));
        if (pool->sessions == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        pool->capacity *= 2;
    }
    SessionRecord *new_session = &pool->sessions[pool->used];
    time(&new_session->timestamp);
    new_session->session_id = generate_session_id();
    strncpy(new_session->user_handle, user_handle, sizeof(new_session->user_handle) - 1);
    pool->used++;
    pthread_mutex_unlock(&pool->lock);
}

void remove_session(SessionPool *pool, uint64_t session_id) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used; i++) {
        if (pool->sessions[i].session_id == session_id) {
            memmove(&pool->sessions[i], &pool->sessions[i + 1], (pool->used - i - 1) * sizeof(SessionRecord));
            pool->used--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void expire_sessions(SessionPool *pool, time_t expiration_time) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used; i++) {
        if (difftime(pool->sessions[i].timestamp, expiration_time) > 0) {
            memmove(&pool->sessions[i], &pool->sessions[i + 1], (pool->used - i - 1) * sizeof(SessionRecord));
            pool->used--;
            i--; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void cleanup_session_pool(SessionPool *pool) {
    destroy_session_pool(pool);
}
```

