#include <pthread.h>

#define MAX_KEYS 2048
#define RECORD_SIZE 100

typedef struct {
    int value;
} Record;

int* long_offsets = NULL;
int* keys = NULL;
Record** records = NULL;
int key_count = 0;
pthread_mutex_t mutex;

void init_memory() {
    long_offsets = (int*)malloc(MAX_KEYS * sizeof(int));
    keys = (int*)malloc(MAX_KEYS * sizeof(int));
    records = (Record**)malloc(RECORD_SIZE * sizeof(Record*));
    pthread_mutex_init(&mutex, NULL);
}

void free_memory() {
    for (int i = 0; i < key_count; i++) {
        free(records[i]);
    }
    free(long_offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&mutex);
}

int find_unused_key() {
    for (int i = 0; i < MAX_KEYS; i++) {
        if (keys[i] == -1) return i;
    }
    return -1;
}

void add_record(int value) {
    pthread_mutex_lock(&mutex);
    int key = find_unused_key();
    if (key != -1) {
        keys[key] = value;
        records[key_count++] = malloc(sizeof(Record));
        records[key_count - 1]->value = value;
        long_offsets[key] = 0; // Initialize offset
    }
    pthread_mutex_unlock(&mutex);
}

void* concurrent_add_record(void* arg) {
    int value = rand() % 2000 + 1;
    add_record(value);
    return NULL;
}

int main() {
    srand(time(NULL));
    init_memory();

    pthread_t threads[RECORD_SIZE];
    for (int i = 0; i < RECORD_SIZE; i++) {
        pthread_create(&threads[i], NULL, concurrent_add_record, NULL);
    }

    for (int i = 0; i < RECORD_SIZE; i++) {
        pthread_join(threads[i], NULL);
    }

    free_memory();
    return 0;
}
