#define MAX_RECORDS 1000
#define MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int value;
} record;

long offsets[MAX_RECORDS];
int keys[MAX_RECORDS];
record records[MAX_RECORDS];

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int error_flag = 0;
char error_message[256];
size_t memory_used = 0;

void generate_random_value(int *value, int min, int max) {
    *value = rand() % (max - min + 1) + min;
}

void track_record_value(int value) {
    // Implement tracking mechanism
}

void* allocate_memory(void* arg) {
    pthread_mutex_lock(&mutex);

    if (memory_used >= MEMORY_LIMIT) {
        int reduction = memory_used - MEMORY_LIMIT;

        for (int i = MAX_RECORDS - 1; i >= 0; i--) {
            if (memory_used > MEMORY_LIMIT && offsets[i] != 0) {
                memory_used -= offsets[i];
                offsets[i] = 0;
                keys[i] = 0;
                records[i].value = 0;

                if (memory_used <= MEMORY_LIMIT)
                    break;
            }
        }

        if (memory_used > MEMORY_LIMIT) {
            sprintf(error_message, "Memory allocation failed: Memory limit exceeded.");
            error_flag = 1;
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    int offset_index = -1;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (offsets[i] == 0) {
            offset_index = i;
            break;
        }
    }

    if (offset_index == -1) {
        sprintf(error_message, "Memory allocation failed: No available slots.");
        error_flag = 1;
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    offsets[offset_index] = sizeof(long) + sizeof(int) + sizeof(record);
    memory_used += offsets[offset_index];

    keys[offset_index] = rand();
    generate_random_value(&records[offset_index].value, -100, 100);
    track_record_value(records[offset_index].value);

    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (pthread_create(&threads[i], NULL, allocate_memory, NULL) != 0) {
            perror("Thread creation failed");
            break;
        }
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    if (error_flag) {
        printf("Error: %s\n", error_message);
    } else {
        printf("Memory allocation successful.\n");
    }

    return 0;
}
