import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class TemporaryDirectoryManager {
    private static final Logger logger = Logger.getLogger(TemporaryDirectoryManager.class.getName());
    private static final SecureRandom PRNG = new SecureRandom();
    private static final ConcurrentHashMap<String, Long> directoryUsage = new ConcurrentHashMap<>();
    private long totalDataLimit;
    private int maxDirectories;

    public TemporaryDirectoryManager(long dataLimit, int maxDirs) {
        this.totalDataLimit = dataLimit;
        this.maxDirectories = maxDirs;
    }

    public String createTemporaryDirectory() throws IOException {
        if (directoryUsage.size() >= maxDirectories || getTotalUsedSpace() + getMaxAllowedSize() > totalDataLimit) {
            throw new IOException("Cannot create more directories or space limit exceeded.");
        }
        String uniqueName = generateUniqueName();
        File directory = Files.createTempDirectory(uniqueName);
        directoryUsage.put(directory.getAbsolutePath(), 0L);
        return directory.getAbsolutePath();
    }

    private String generateUniqueName() {
        byte[] bytes = new byte[16];
        PRNG.nextBytes(bytes);
        return Base64.getEncoder().encodeToString(bytes);
    }

    public void deleteTemporaryDirectory(String directoryPath) throws IOException {
        File directory = new File(directoryPath);
        if (directory.exists()) {
            Files.walkFileTree(directory.toPath(), new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    Files.delete(file);
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
                    Files.delete(dir);
                    directoryUsage.remove(dir.toString());
                    return FileVisitResult.CONTINUE;
                }
            });
        } else {
            logger.log(Level.WARNING, "Attempted to delete non-existent directory: {0}", directoryPath);
        }
    }

    public void updateDirectoryUsage(String directoryPath, long dataSize) {
        directoryUsage.merge(directoryPath, dataSize, Long::sum);
    }

    private long getTotalUsedSpace() {
        return directoryUsage.values().stream().mapToLong(Long::longValue).sum();
    }

    private long getMaxAllowedSize() {
        return totalDataLimit - getTotalUsedSpace();
    }

    // Additional methods for monitoring, error handling, and cleanup can be added here
}

// C function implementation (not directly related to the Java class)
extern "C" const char* appendSlashIfNotExceedingSize(const char* input, size_t size, char* buffer) {
    if (strlen(input) < size - 1) {
        strcpy(buffer, input);
        strcat(buffer, "/");
        return buffer;
    } else {
        return NULL; // Buffer overflow would occur
    }
}
