record* initialize_records(size_t size) {
    if (size < 512 || size > 1024) {
        fprintf(stderr, "Invalid size for records array\n");
        return NULL;
    }

    record* records = malloc(size * sizeof(record));
    if (records == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
    }

    return records;
}

void initialize_offsets_and_keys(long* offsets, int* keys, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = (long)i;
        keys[i] = (int)i;
    }
}

record** allocate_memory(size_t* records_size, long** offsets, int** keys) {
    *records_size = 512 + rand() % 513; // Random size between 512 and 1024

    record* records = initialize_records(*records_size);
    if (records == NULL) {
        return NULL;
    }

    *offsets = malloc(1024 * sizeof(long));
    if (*offsets == NULL) {
        free(records);
        perror("Memory allocation failed");
        return NULL;
    }

    *keys = malloc(1024 * sizeof(int));
    if (*keys == NULL) {
        free(records);
        free(*offsets);
        perror("Memory allocation failed");
        return NULL;
    }

    initialize_offsets_and_keys(*offsets, *keys, 1024);

    record** result = malloc(3 * sizeof(record*));
    if (result == NULL) {
        free(records);
        free(*offsets);
        free(*keys);
        perror("Memory allocation failed");
        return NULL;
    }

    result[0] = records;
    result[1] = (record*)*offsets;
    result[2] = (record*)*keys;

    return result;
}

void free_memory(record** memory) {
    if (memory != NULL && memory[0] != NULL) {
        free(memory[0]);
    }
    if (memory != NULL && memory[1] != NULL) {
        free((long*)memory[1]);
    }
    if (memory != NULL && memory[2] != NULL) {
        free((int*)memory[2]);
    }
    if (memory != NULL) {
        free(memory);
    }
}

int main() {
    size_t records_size;
    long* offsets;
    int* keys;

    record** memory = allocate_memory(&records_size, &offsets, &keys);
    if (memory == NULL) {
        return 1;
    }

    // Use the allocated memory here

    free_memory(memory);

    return 0;
}
