    int *keys = malloc(key_size * sizeof(int));
    record *records = malloc(record_size * sizeof(record));
    struct audit_log_entry *logs = malloc(log_size * sizeof(struct audit_log_entry));

    if (!offsets || !keys || !records || !logs) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = i * 10; // Sequential numbers as an example
    }
    for (int i = 0; i < key_size; ++i) {
        keys[i] = i + range_start; // Sequential numbers within the range
    }

    int lcg_state = time(NULL);
    for (int i = 0; i < record_size; ++i) {
        long random_value = ((lcg_state * 214013L + 2531011L) >> 16) % (range_end - range_start + 1) + range_start;
        records[i].value = random_value;
        records[i].log = &logs[log_interval * i / record_size];
        logs[log_interval * i / record_size].timestamp = time(NULL);
        logs[log_interval * i / record_size].sequence_number = i;
    }

    return records;
}

void free_records(record* records, int size) {
    free(records); // No need to individually free the log entries as they are part of the records array
