#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int key;
    long offset;
} record;

record* records = NULL;
int* used_keys = NULL;
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize() {
    records = (record*)malloc(MAX_KEYS * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    used_keys = (int*)calloc(MAX_KEYS, sizeof(int));
    if (!used_keys) {
        free(records);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void cleanup() {
    pthread_mutex_lock(&lock);
    free(records);
    free(used_keys);
    pthread_mutex_unlock(&lock);
}

int generate_unique_key() {
    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (used_keys[key]);
    return key;
}

record* create_record(int value) {
    if (record_count >= MAX_KEYS) {
        fprintf(stderr, "Maximum number of records reached\n");
        return NULL;
    }
    pthread_mutex_lock(&lock);
    record* rec = &records[record_count++];
    rec->key = generate_unique_key();
    used_keys[rec->key] = 1;
    rec->offset = (long)value;
    pthread_mutex_unlock(&lock);
    return rec;
}

int find_largest() {
    int max_val = -1;
    for (int i = 0; i < record_count; i++) {
        if (records[i].offset > max_val) {
            max_val = records[i].offset;
        }
    }
    return max_val;
}

void* read_input(void* arg) {
    int value;
    while (1) {
        printf("Enter an integer (or -1 to exit): ");
        scanf("%d", &value);
        if (value == -1) break;
        record* rec = create_record(value);
        if (!rec) continue;
        if (value > find_largest()) {
            printf("Largest value: %d\n", find_largest());
        }
    }
    pthread_exit(NULL);
}

int main() {
    srand(time(0));
    initialize();

    pthread_t reader_thread;
    pthread_create(&reader_thread, NULL, read_input, NULL);

    pthread_join(reader_thread, NULL);

    cleanup();
    return 0;
}
