#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

long* offsetArray;
int* keyArray;
record** recordArray;
pthread_mutex_t keyMutex;

void initArrays() {
    offsetArray = (long*)malloc(sizeof(long) * MAX_KEYS);
    keyArray = (int*)malloc(sizeof(int) * MAX_KEYS);
    recordArray = (record**)malloc(sizeof(record*) * MAX_KEYS);

    pthread_mutex_init(&keyMutex, NULL);

    for (int i = 0; i < MAX_KEYS; i++) {
        offsetArray[i] = -1;
        keyArray[i] = -1;
        recordArray[i] = NULL;
    }
}

void* generateRandomRecords(void* arg) {
    int threadID = *(int*)arg;
    unsigned long seed = time(NULL) + threadID;

    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_mutex_lock(&keyMutex);
        while (1) {
            int key = rand_r(&seed) % MAX_KEYS;
            if (keyArray[key] == -1) {
                keyArray[key] = key;
                recordArray[key] = (record*)malloc(sizeof(record));
                recordArray[key]->value = rand_r(&seed) % 1000 + 1;
                pthread_mutex_unlock(&keyMutex);
                break;
            }
        }
    }

    return NULL;
}

void cleanUp() {
    for (int i = 0; i < MAX_KEYS; i++) {
        if (recordArray[i] != NULL) {
            free(recordArray[i]);
        }
    }

    pthread_mutex_destroy(&keyMutex);
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}

int main() {
    initArrays();

    pthread_t threads[MAX_KEYS];
    int threadIDs[MAX_KEYS];

    for (int i = 0; i < MAX_KEYS; i++) {
        threadIDs[i] = i;
        if (pthread_create(&threads[i], NULL, generateRandomRecords, &threadIDs[i]) != 0) {
            fprintf(stderr, "Error creating thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanUp();

    return 0;
}
