#define MAX_OFFSETS 10000
#define RECORD_COUNT 500

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t used_keys_count;
    pthread_mutex_t lock;
} data_structure;

void initialize_data_structure(data_structure* ds, size_t num_offsets) {
    if (num_offsets > MAX_OFFSETS) {
        fprintf(stderr, "Error: Requested number of offsets exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }

    ds->offsets = malloc(num_offsets * sizeof(long));
    if (!ds->offsets) {
        perror("Memory allocation failed for offsets array.");
        exit(EXIT_FAILURE);
    }
    memset(ds->offsets, 0, num_offsets * sizeof(long));

    ds->keys = malloc(num_offsets * sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        perror("Memory allocation failed for keys array.");
        exit(EXIT_FAILURE);
    }
    memset(ds->keys, 0, num_offsets * sizeof(int));

    ds->records = malloc(RECORD_COUNT * sizeof(record));
    if (!ds->records) {
        free(ds->offsets);
        free(ds->keys);
        perror("Memory allocation failed for records array.");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&ds->lock, NULL);

    // Initialize keys and records
    ds->used_keys_count = 0;
}

void cleanup_data_structure(data_structure* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
}

data_structure* create_data_structure(size_t num_offsets) {
    data_structure* ds = malloc(sizeof(data_structure));
    if (!ds) {
        perror("Memory allocation failed for data structure.");
        exit(EXIT_FAILURE);
    }
    initialize_data_structure(ds, num_offsets);
    return ds;
}

// Function to generate a random integer between 1 and 1000
int generate_random_value() {
    static unsigned int seed = 12345; // Seed can be initialized with a better value in practice
    seed = (seed * 1103515245 + 12345) % 32768;
    return (int)(seed * (1000.0 / 32768));
}

// Function to find a unique key and record, ensuring no duplicates
void add_record(data_structure* ds) {
    pthread_mutex_lock(&ds->lock);
    int next_key = ds->used_keys_count + 1;
    if (next_key >= 1024) {
        fprintf(stderr, "Error: No available keys left.\n");
        pthread_mutex_unlock(&ds->lock);
        return;
    }
    ds->keys[ds->used_keys_count++] = next_key;

    record* rec = &ds->records[ds->used_keys_count - 1];
    rec->value = generate_random_value();
    while (rec->value == 0) { // Ensure non-zero value
        rec->value = generate_random_value();
    }
    pthread_mutex_unlock(&ds->lock);
}

// Example usage
int main() {
    data_structure* ds = create_data_structure(500);

    for (size_t i = 0; i < RECORD_COUNT; ++i) {
        add_record(ds);
    }

    cleanup_data_structure(ds);
    free(ds);
    return 0;
}
