void initialize_data_structures(long* offsets, int* keys, record** records, size_t threshold, int range_start, int range_end) {
    srand(time(NULL)); // Seed the random number generator
    size_t total_memory = 0;
    for (size_t i = 0; i < threshold / sizeof(record); ++i) {
        offsets[i] = rand() % threshold;
        keys[i] = rand() % (range_end - range_start + 1) + range_start;

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % (range_end - range_start + 1) + range_start;

        size_t str_len = 10; // Fixed length of the string
        records[i]->str = malloc(str_len * sizeof(char));
        if (!records[i]->str) {
            perror("Failed to allocate memory for string");
            free(records[i]);
            exit(EXIT_FAILURE);
        }
        for (size_t j = 0; j < str_len - 1; ++j) {
            records[i]->str[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        records[i]->str[str_len - 1] = '\0';

        total_memory += sizeof(record) + str_len * sizeof(char);
        if (total_memory > threshold) {
            fprintf(stderr, "Memory allocation exceeds the specified threshold\n");
            break;
        }
    }
}

