// Global key database with concurrent access support
struct KeyDatabase {
    pthread_mutex_t lock;
    int keys[MAX_KEYS];
    int count;
};

struct KeyDatabase global_key_db = { .lock = PTHREAD_MUTEX_INITIALIZER, .count = 0 };

int is_key_available(int key) {
    for (int i = 0; i < global_key_db.count; i++) {
        if (global_key_db.keys[i] == key) {
            return 0;
        }
    }
    return 1;
}

void add_key_to_database(int key) {
    pthread_mutex_lock(&global_key_db.lock);
    global_key_db.keys[global_key_db.count++] = key;
    pthread_mutex_unlock(&global_key_db.lock);
}

int generate_random_record_value() {
    int value;
    while (1) {
        if (RAND_bytes((unsigned char*)&value, sizeof(value)) != 1) {
            // Fallback to slower PRNG if OpenSSL fails
            srand(time(NULL));
            value = rand() % 1000 + 1;
            break;
        } else {
            value = ((int)value) % 1000 + 1;
            break;
        }
    }
    return value;
}

