    if (!records) {
        return NULL; // Handle allocation failure
    }

    for (int i = 0; i < num_records; i++) {
        int key;
        do {
            key = rand() % MAX_KEYS + 1; // Generate a unique key less than 1024
        } while (!is_key_available(key));

        add_key_to_database(key);
        records[i].value = generate_random_record_value();
    }

    return records;
}

void free_records(Record* records, int num_records) {
    free(records); // Clean up allocated memory
}

int main() {
    Record* records = allocate_and_initialize_records(NUM_RECORDS);
    if (!records) {
        fprintf(stderr, "Failed to allocate records\n");
        return 1;
    }

    // Use the records...

    free_records(records, NUM_RECORDS);

    return 0;
}
