int *offsets = NULL;
int offsets_size = 0;
int offsets_capacity = 0;

int *used_keys = NULL;
int used_keys_size = 0;
int used_keys_capacity = 0;

pthread_mutex_t lock;

void init_arrays() {
    offsets_capacity = 1024;
    offsets = malloc(offsets_capacity * sizeof(int));
    if (!offsets) return;

    used_keys_capacity = 512;
    used_keys = malloc(used_keys_capacity * sizeof(int));
    if (!used_keys) {
        free(offsets);
        offsets = NULL;
        return;
    }

    pthread_mutex_init(&lock, NULL);
}

int add_key(int key) {
    if (key >= MAX_KEYS) return -1;

    pthread_mutex_lock(&lock);
    for (int i = 0; i < used_keys_size; ++i) {
        if (used_keys[i] == key) {
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }
    if (used_keys_size >= used_keys_capacity) {
        int new_capacity = used_keys_capacity * 2;
        int *new_used_keys = realloc(used_keys, new_capacity * sizeof(int));
        if (!new_used_keys) {
            pthread_mutex_unlock(&lock);
            return -1;
        }
        used_keys = new_used_keys;
        used_keys_capacity = new_capacity;
    }
    used_keys[used_keys_size++] = key;
    pthread_mutex_unlock(&lock);

    return 0;
}

Transaction *create_transactions(int num_transactions) {
    if (num_transactions <= 0) return NULL;

    Transaction *transactions = malloc(num_transactions * sizeof(Transaction));
    if (!transactions) return NULL;

    srand(time(NULL));
    double min_amount = 0.01;
    double max_amount = 1000.00;
    for (int i = 0; i < num_transactions; ++i) {
        while (1) {
            double amount = (max_amount - min_amount) * ((double)rand() / RAND_MAX) + min_amount;
            if (find_transaction(transactions, num_transactions, amount) == -1) {
                transactions[i].amount = amount;
                break;
            }
        }

        // Generate a unique key for each transaction
        int key;
        do {
            key = rand() % MAX_KEYS;
        } while (add_key(key) != 0);

        snprintf(transactions[i].description, 128, "Transaction %d", i + 1);
    }

    return transactions;
}

int find_transaction(Transaction *transactions, int num_transactions, double amount) {
    for (int i = 0; i < num_transactions; ++i) {
        if (transactions[i].amount == amount) return i;
    }
    return -1;
}

void free_resources() {
    free(offsets);
    offsets = NULL;
    offsets_size = 0;
    offsets_capacity = 0;

    for (int i = 0; i < used_keys_size; ++i) {
        // Assuming key cleanup is needed
