    }
    free(used_keys);
    used_keys = NULL;
    used_keys_size = 0;
    used_keys_capacity = 0;

    pthread_mutex_destroy(&lock);
}

// Example usage
int main() {
    init_arrays();
    Transaction *transactions = create_transactions(10);

    if (transactions) {
        for (int i = 0; i < 10; ++i) {
            printf("Transaction %d: Amount %.2f, Description %s\n", i + 1, transactions[i].amount, transactions[i].description);
        }
        free(transactions);
    }

    free_resources();
    return 0;
}
