#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct Record {
    int value;
} Record;

typedef struct HashTable {
    Record *records[MAX_KEYS];
    int occupied[MAX_KEYS];
} HashTable;

HashTable *createHashTable() {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    for (int i = 0; i < MAX_KEYS; i++) {
        table->records[i] = NULL;
        table->occupied[i] = 0;
    }
    return table;
}

void insertRecord(HashTable *table, int key, Record *record) {
    if (key >= MAX_KEYS || key < 0) {
        fprintf(stderr, "Invalid key: %d\n", key);
        return;
    }
    if (table->occupied[key]) {
        fprintf(stderr, "Key already occupied: %d\n", key);
        return;
    }
    table->records[key] = record;
    table->occupied[key] = 1;
}

Record *findRecord(HashTable *table, int key) {
    if (key >= MAX_KEYS || key < 0) {
        fprintf(stderr, "Invalid key: %d\n", key);
        return NULL;
    }
    if (!table->occupied[key]) {
        fprintf(stderr, "Key not found: %d\n", key);
        return NULL;
    }
    return table->records[key];
}

void freeHashTable(HashTable *table) {
    for (int i = 0; i < MAX_KEYS; i++) {
        if (table->occupied[i]) {
            free(table->records[i]);
        }
    }
    free(table);
}

Record *generateRandomRecord() {
    Record *record = (Record *)malloc(sizeof(Record));
    record->value = rand() % 1001;
    return record;
}

int main() {
    srand(time(NULL));
    HashTable *table = createHashTable();

    for (int i = 0; i < MAX_KEYS - 1; i++) {
        Record *record = generateRandomRecord();
        insertRecord(table, i, record);
    }

    Record *foundRecord = findRecord(table, 500);
    if (foundRecord) {
        printf("Found record with value: %d\n", foundRecord->value);
    }

    freeHashTable(table);
    return 0;
}
