import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

public class AdvancedConnectionHandler {

    private static final int MAX_RECORDS = 1024;
    private static final int RECORD_SIZE = Integer.BYTES;
    private static final long TIMEOUT = 5000; // milliseconds
    private static final int BACKOFF_FACTOR = 2;
    private static final int BACKOFF_LIMIT = 30; // seconds

    private SocketChannel socketChannel;
    private ByteBuffer buffer;
    private Random random;
    private ReentrantLock lock;
    private Set<Integer> usedKeys;

    public AdvancedConnectionHandler() {
        this.lock = new ReentrantLock();
        this.usedKeys = new HashSet<>();
        this.random = new Random();
        this.buffer = ByteBuffer.allocate(MAX_RECORDS * RECORD_SIZE);
    }

    public void connect(String host, int port) throws IOException {
        socketChannel = SocketChannel.open(new InetSocketAddress(host, port));
        socketChannel.configureBlocking(true);
    }

    public void initializeRecords() {
        for (int i = 0; i < MAX_RECORDS; ) {
            int key;
            do {
                key = random.nextInt(1024);
            } while (!usedKeys.add(key));
            buffer.putInt(i * RECORD_SIZE, key);
            buffer.putInt((i * RECORD_SIZE) + Integer.BYTES, random.nextInt(1000) + 1);
            i++;
        }
    }

    public void findAndPrintLargest() {
        int max = 0;
        for (int i = 0; i < MAX_RECORDS; i++) {
            buffer.position(i * RECORD_SIZE + Integer.BYTES);
            int value = buffer.getInt();
            if (value > max) {
                max = value;
            }
        }
        System.out.println("Largest integer: " + max);
    }

    public void handleInput(List<Integer> input) throws IOException {
        for (int num : input) {
            if (num >= 0 && num < MAX_RECORDS) {
                lock.lock();
                try {
                    buffer.position(num * RECORD_SIZE);
                    int value = buffer.getInt((num * RECORD_SIZE) + Integer.BYTES);
                    System.out.println("Input: " + num + ", Value: " + value);
                } finally {
                    lock.unlock();
                }
            }
        }
    }

    public void disconnect() throws IOException {
        if (socketChannel != null && socketChannel.isOpen()) {
            socketChannel.close();
        }
    }

    public static void main(String[] args) {
        AdvancedConnectionHandler handler = new AdvancedConnectionHandler();
        try {
            handler.connect("example.com", 12345);
            handler.initializeRecords();
            List<Integer> input = Arrays.asList(0, 256, 512, 768);
            handler.handleInput(input);
            handler.findAndPrintLargest();
            handler.disconnect();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
