#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

record* allocate_records(size_t size) {
    if (size == 0) {
        fprintf(stderr, "Error: Size must be greater than zero.\n");
        return NULL;
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    // Custom PRNG function
    unsigned int seed = 12345; // Example seed
    for (size_t i = 0; i < size; ++i) {
        records[i].value = (seed * 1103515245 + 12345) % size;
        seed = records[i].value; // Update seed
    }

    return records;
}

void free_records(record* records, size_t size) {
    if (records != NULL) {
        free(records);
    }
}

// Example usage with pthreads
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* worker_thread(void* arg) {
    size_t thread_id = *(size_t*)arg;
    record* records = allocate_records(1000); // Allocate 1000 records per thread

    if (records == NULL) {
        pthread_exit(NULL);
    }

    // Process records
    for (size_t i = 0; i < 1000; ++i) {
        pthread_mutex_lock(&mutex);
        printf("Thread %zu: Value = %d\n", thread_id, records[i].value);
        pthread_mutex_unlock(&mutex);
    }

    free_records(records, 1000); // Free allocated memory
    pthread_exit(NULL);
}

int main() {
    size_t num_threads = 4;
    pthread_t threads[num_threads];
    size_t thread_ids[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]) != 0) {
            perror("Failed to create thread.");
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread.");
            return EXIT_FAILURE;
        }
    }

    pthread_mutex_destroy(&mutex);
    return EXIT_SUCCESS;
}
