import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;

public class Server {

    private static final int MAX_KEYS = 1024;
    private static final int RECORD_SIZE = 4;
    private static final long COOLDOWN_PERIOD = 9000; // 9 seconds
    private static Set<Integer> usedKeys = new HashSet<>();
    private static Random prng = new Random();

    public static void main(String[] args) throws IOException {
        AsynchronousChannelGroup group = AsynchronousChannelGroup.withFixedThreadPool(10);
        AsynchronousServerSocketChannel serverChannel = AsynchronousServerSocketChannel.open(group);
        serverChannel.bind(new InetSocketAddress("localhost", 8080));

        System.out.println("Server started on port 8080");

        while (true) {
            serverChannel.accept(null, new AcceptHandler(serverChannel));
        }
    }

    private static int[] generateRecords(int count) {
        if (count > MAX_KEYS * RECORD_SIZE / Integer.BYTES) {
            throw new IllegalArgumentException("Too many records requested");
        }

        Set<Integer> keys = new HashSet<>();
        int[] records = new int[count];

        while (keys.size() < count) {
            int key = prng.nextInt(MAX_KEYS);
            if (!usedKeys.contains(key)) {
                keys.add(key);
            }
        }

        for (int i = 0; i < count; i++) {
            records[i] = prng.nextInt(1000) + 1;
        }

        usedKeys.addAll(keys);

        return records;
    }

    private static void findAndPrintLargest(int[] numbers) {
        if (numbers == null || numbers.length == 0) {
            System.out.println("No numbers provided");
            return;
        }

        int largest = Integer.MIN_VALUE;

        for (int num : numbers) {
            if (num > largest) {
                largest = num;
            }
        }

        System.out.println("Largest number: " + largest);
    }

    private static void selectAttack() {
        Random attackSelector = new Random();
        int selectedAttack = attackSelector.nextInt(2) + 1;

        System.out.println("Selected attack: " + selectedAttack);
    }

    private static class AcceptHandler implements AsynchronousChannelGroupCompletionHandler<AsynchronousSocketChannel, Void> {

        private final AsynchronousServerSocketChannel serverChannel;

        public AcceptHandler(AsynchronousServerSocketChannel serverChannel) {
            this.serverChannel = serverChannel;
        }

        @Override
        public void completed(AsynchronousSocketChannel result, Void attachment) {
            try {
                result.read(ByteBuffer.allocate(1024), null, new ReadHandler(result));
                serverChannel.accept(null, this);
            } catch (IOException e) {
                System.err.println("Error accepting connection: " + e.getMessage());
            }
        }

        @Override
        public void failed(Throwable exc, Void attachment) {
            System.err.println("Accept failed: " + exc.getMessage());
        }
    }

    private static class ReadHandler implements CompletionHandler<Integer, ByteBuffer> {

        private final AsynchronousSocketChannel channel;

        public ReadHandler(AsynchronousSocketChannel channel) {
            this.channel = channel;
        }

        @Override
        public void completed(Integer result, ByteBuffer buffer) {
            if (result == -1) {
                try {
                    channel.close();
                } catch (IOException e) {
                    System.err.println("Error closing channel: " + e.getMessage());
                }
                return;
            }

            byte[] data = new byte[buffer.position()];
            buffer.flip();
            buffer.get(data);

            int count = data.length / Integer.BYTES;
            int[] numbers = new int[count];

            for (int i = 0; i < count; i++) {
                int index = i * Integer.BYTES;
                numbers[i] = ((data[index + 3] & 0xFF) << 24)
                        | ((data[index + 2] & 0xFF) << 16)
                        | ((data[index + 1] & 0xFF) << 8)
                        | (data[index] & 0xFF);
            }

            findAndPrintLargest(numbers);
            selectAttack();

            try {
                channel.close();
            } catch (IOException e) {
                System.err.println("Error closing channel: " + e.getMessage());
            }
        }

        @Override
        public void failed(Throwable exc, ByteBuffer attachment) {
            System.err.println("Read failed: " + exc.getMessage());
        }
    }
}
