#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/rand.h>

#define MAX_KEYS 1024

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct KeySet {
    pthread_mutex_t lock;
    int used[MAX_KEYS];
} KeySet;

KeySet* key_set_init() {
    KeySet* set = malloc(sizeof(KeySet));
    if (!set) return NULL;
    pthread_mutex_init(&set->lock, NULL);
    memset(set->used, 0, sizeof(set->used));
    return set;
}

void key_set_destroy(KeySet* set) {
    pthread_mutex_destroy(&set->lock);
    free(set);
}

int key_set_add(KeySet* set, int key) {
    pthread_mutex_lock(&set->lock);
    if (key < 0 || key >= MAX_KEYS || set->used[key]) {
        pthread_mutex_unlock(&set->lock);
        return -1;
    }
    set->used[key] = 1;
    pthread_mutex_unlock(&set->lock);
    return 0;
