typedef struct {
    int key;
    long offset;
    void* data; // Pointer to record data
} Record;

typedef struct {
    int size;
    int capacity;
    Record** records;
    pthread_mutex_t lock;
} DynamicSet;

DynamicSet* create_dynamic_set(int initial_capacity) {
    DynamicSet* set = (DynamicSet*)malloc(sizeof(DynamicSet));
    if (!set) return NULL;
    set->size = 0;
    set->capacity = initial_capacity;
    set->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!set->records) {
        free(set);
        return NULL;
    }
    pthread_mutex_init(&set->lock, NULL);
    return set;
}

void destroy_dynamic_set(DynamicSet* set) {
    for (int i = 0; i < set->size; i++) {
        free(set->records[i]->data);
        free(set->records[i]);
    }
    free(set->records);
    pthread_mutex_destroy(&set->lock);
    free(set);
}

void resize_dynamic_set(DynamicSet* set) {
    int new_capacity = set->capacity * 2;
    Record** new_records = (Record**)realloc(set->records, new_capacity * sizeof(Record*));
    if (!new_records) return;
    set->records = new_records;
    set->capacity = new_capacity;
}

int insert_record(DynamicSet* set, int key, long offset, size_t data_size) {
    pthread_mutex_lock(&set->lock);
    for (int i = 0; i < set->size; i++) {
        if (set->records[i]->key == key) {
            pthread_mutex_unlock(&set->lock);
            return -1;
        }
    }
    if (set->size == set->capacity) resize_dynamic_set(set);
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&set->lock);
        return -2;
    }
    record->key = key;
    record->offset = offset;
    record->data = malloc(data_size);
    if (!record->data) {
        free(record);
        pthread_mutex_unlock(&set->lock);
        return -2;
    }
    // Initialize random data for the record
    srand(time(NULL));
    for (size_t i = 0; i < data_size; i++) {
        ((char*)record->data)[i] = rand() % 1000 + 1;
    }
    set->records[set->size++] = record;
    pthread_mutex_unlock(&set->lock);
    return 0;
}

void apply_transform(DynamicSet* set, void (*transform)(Record*)) {
    pthread_mutex_lock(&set->lock);
    for (int i = 0; i < set->size; i++) {
        transform(set->records[i]);
    }
    pthread_mutex_unlock(&set->lock);
}

