    Record *records;
    unsigned char used[MAX_KEYS];
    size_t count;
} DynamicSet;

DynamicSet* dynamic_set_create() {
    DynamicSet *set = (DynamicSet*)malloc(sizeof(DynamicSet));
    if (!set) return NULL;

    set->lock = PTHREAD_MUTEX_INITIALIZER;
    set->records = (Record*)calloc(MAX_KEYS, sizeof(Record));
    if (!set->records) {
        free(set);
        return NULL;
    }

    memset(set->used, 0, MAX_KEYS);
    set->count = 0;

    return set;
}

void dynamic_set_destroy(DynamicSet *set) {
    pthread_mutex_lock(&set->lock);
    for (size_t i = 0; i < set->count; i++) {
        // Free any allocated resources for each record
    }
    free(set->records);
    pthread_mutex_unlock(&set->lock);
    pthread_mutex_destroy(&set->lock);
    free(set);
}

int dynamic_set_add(DynamicSet *set, int key, long offset) {
    pthread_mutex_lock(&set->lock);

    if (key < 0 || key >= MAX_KEYS || set->used[key]) {
        pthread_mutex_unlock(&set->lock);
        return -1; // Key out of range or already used
    }

    set->records[set->count].key = key;
    set->records[set->count].offset = offset;
    set->used[key] = 1;
    set->count++;

    pthread_mutex_unlock(&set->lock);
    return 0;
}

void dynamic_set_iterate(DynamicSet *set, void (*transform)(Record*)) {
    pthread_mutex_lock(&set->lock);
    for (size_t i = 0; i < set->count; i++) {
        transform(&set->records[i]);
    }
    pthread_mutex_unlock(&set->lock);
}
