import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.SecureRandom;

public class TemporaryDirectoryManager {
    private static final SecureRandom RANDOM = new SecureRandom();
    private long storageThreshold;
    private Path rootDir;
    private double peakUsageRate;
    private double averageUsageRate;

    public TemporaryDirectoryManager(long initialStorageThreshold) {
        this.storageThreshold = initialStorageThreshold;
        try {
            this.rootDir = Files.createTempDirectory("temp_data");
        } catch (IOException e) {
            throw new RuntimeException("Failed to create root directory", e);
        }
    }

    public synchronized Path createTemporaryDirectory(long maxSize) throws IOException {
        if (Files.size(rootDir) + maxSize > storageThreshold) {
            throw new IllegalStateException("Storage threshold exceeded");
        }
        String uniqueName = generateUniqueName();
        Path dir = Files.createTempDirectory(rootDir, uniqueName);
        Files.setAttribute(dir, "user.attribute.maxSize", maxSize);
        return dir;
    }

    private String generateUniqueName() {
        byte[] randomBytes = new byte[16];
        RANDOM.nextBytes(randomBytes);
        return bytesToHex(randomBytes);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void updateStorageThreshold(long newThreshold) {
        this.storageThreshold = newThreshold;
    }

    public double getPeakUsageRate() {
        return peakUsageRate;
    }

    public double getAverageUsageRate() {
        return averageUsageRate;
    }

    // Additional methods for handling concurrency, error handling, logging, prefetching,
    // dynamic resizing, cleanup, model library preloading, resilience to node failures,
    // and auditing logs would be implemented here.
}
