import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Executors;

public class RecordProcessor {

    private AsynchronousChannelGroup channelGroup;
    private Set<Integer> usedKeys;
    private int maxRecords;
    private SecureRandom random;

    public RecordProcessor(int maxRecords) {
        this.maxRecords = maxRecords;
        this.usedKeys = new HashSet<>();
        this.random = new SecureRandom();
        this.channelGroup = AsynchronousChannelGroup.withFixedThreadPool(Runtime.getRuntime().availableProcessors(), Executors.defaultThreadFactory());
    }

    public void processRecords() throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = reader.readLine()) != null) {
            int record = Integer.parseInt(line);
            if (record > 0 && record <= maxRecords) {
                addRecord(record, random.nextInt(1000));
            } else {
                System.out.println("Invalid record: " + record);
            }
        }
    }

    private void addRecord(int key, int value) throws Exception {
        while (!usedKeys.add(key)) {
            key = random.nextInt(maxRecords);
        }
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(channelGroup);
        InetSocketAddress address = new InetSocketAddress("example.com", 12345); // Replace with actual address
        channel.connect(address).get();
        ByteBuffer buffer = ByteBuffer.allocate(8 + 4 + 4); // Long offset, int key, int value
        buffer.putLong(0L);
        buffer.putInt(key);
        buffer.putInt(value);
        buffer.flip();
        channel.write(buffer).get();
        System.out.println("Record added with key: " + key + ", value: " + value);
    }

    public static void main(String[] args) {
        RecordProcessor processor = new RecordProcessor(1024);
        try {
            processor.processRecords();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

