typedef struct {
    double value;
} TransactionStruct;

typedef struct {
    char data[257];
} MetadataStruct;

IDList *id_list = NULL;
int max_ids = 0;

void init_id_list(int capacity) {
    max_ids = capacity;
    id_list = (IDList *)malloc(max_ids * sizeof(IDList));
    for (int i = 0; i < max_ids; i++) {
        id_list[i].id = i;
        id_list[i].used = 0;
    }
}

short get_unique_id() {
    if (id_list == NULL) return -1;
    while (1) {
        int index = rand() % max_ids;
        if (!id_list[index].used) {
            id_list[index].used = 1;
            return id_list[index].id;
        }
    }
}

void free_id(short id) {
    if (id < max_ids) {
        id_list[id].used = 0;
    }
}

TransactionStruct *generate_transaction(double min, double max) {
    TransactionStruct *tx = (TransactionStruct *)malloc(sizeof(TransactionStruct));
    if (tx == NULL) return NULL;
    tx->value = min + ((double)rand() / RAND_MAX) * (max - min);
    return tx;
}

MetadataStruct *generate_metadata(int length) {
    MetadataStruct *meta = (MetadataStruct *)malloc(sizeof(MetadataStruct));
    if (meta == NULL) return NULL;
    for (int i = 0; i < length; i++) {
        meta->data[i] = 'a' + rand() % 26;
    }
    meta->data[length] = '\0';
    return meta;
}

void free_metadata(MetadataStruct *meta) {
    free(meta);
}

void log_event(const char *message) {
    printf("Event: %s\n", message);
}

int main() {
    if (!RAND_load_file("/dev/urandom", 1024)) {
        fprintf(stderr, "Error loading random data for PRNG.\n");
        return 1;
    }

    init_id_list(65536);

    // Example usage
    OffsetStruct *offset = (OffsetStruct *)malloc(sizeof(OffsetStruct));
    offset->offset = 12345;

    TransactionStruct *tx = generate_transaction(0.0, 100.0);
    if (tx == NULL) {
        fprintf(stderr, "Memory allocation failed for transaction.\n");
        return 1;
    }
    log_event("Transaction generated.");

    MetadataStruct *meta = generate_metadata(256);
    if (meta == NULL) {
        fprintf(stderr, "Memory allocation failed for metadata.\n");
        free(offset);
        free(tx);
        return 1;
    }
    log_event("Metadata generated.");

    // Free resources
    free(offset);
    free_transaction(tx);
    free_metadata(meta);

    return 0;
