#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

int *offsets;
int *keys;
record *records;
int used_keys[MAX_KEYS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_memory() {
    offsets = (int *)malloc(MAX_KEYS * sizeof(int));
    keys = (int *)malloc(MAX_KEYS * sizeof(int));
    records = (record *)malloc(MAX_KEYS * sizeof(record));
}

int generate_unique_key() {
    int key;
    do {
        key = rand_r((unsigned int *)time(NULL)) % MAX_KEYS;
    } while (used_keys[key]);
    return key;
}

void initialize_records() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_KEYS; ++i) {
        used_keys[i] = 0;
    }
    record_count = 0;
    srand(time(NULL));
    while (record_count < MAX_KEYS && record_count < rand_r((unsigned int *)time(NULL)) % (MAX_KEYS / 2)) {
        int key = generate_unique_key();
        records[record_count].value = rand_r((unsigned int *)time(NULL)) % 1000 + 1;
        offsets[key] = record_count * sizeof(record);
        keys[key] = key;
        used_keys[key] = 1;
        ++record_count;
    }
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    init_memory();
    initialize_records();
    // Use the records, offsets, and keys as needed
    cleanup();
    return 0;
}
