void init_prng(unsigned seed) {
    srand(seed);
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void populate_data(int min_value, int max_value) {
    for (int i = 0; i < record_count; ++i) {
        records[i] = safe_malloc(sizeof(Record));
        keys[i] = rand() % 1000; // Simplified key generation
        offsets[i] = rand() % MAX_RECORDS;
        records[i]->value = min_value + rand() % (max_value - min_value + 1);
    }
}

void update_record(int index, int new_value) {
    if (index >= 0 && index < record_count) {
        records[index]->value = new_value;
    } else {
        printf("Index out of bounds\n");
    }
}

void free_data() {
    for (int i = 0; i < record_count; ++i) {
        free(records[i]);
    }
}

