typedef struct {
    uint64_t identifier;
} Message;

Message* message_pool[MAX_MESSAGES];
int pool_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_message_pool() {
    srand(time(NULL));
    for (int i = 0; i < MAX_MESSAGES; i++) {
        message_pool[i] = malloc(sizeof(Message));
        (*message_pool[i]).identifier = rand();
    }
}

uint64_t generate_unique_identifier() {
    uint64_t id;
    do {
        id = rand();
    } while (id == 0); // Ensure the identifier is not zero
    return id;
}

void* allocate_message(void* arg) {
    pthread_mutex_lock(&mutex);
    if (pool_index < MAX_MESSAGES) {
        Message* msg = message_pool[pool_index++];
        *msg = (Message){.identifier = generate_unique_identifier()};
        pthread_mutex_unlock(&mutex);
        return msg;
    }
    pthread_mutex_unlock(&mutex);
    return NULL; // No more messages available
}

void free_message(Message* msg) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_MESSAGES; i++) {
        if (message_pool[i] == msg) {
            message_pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void read_and_find_largest() {
    int count, num;
    printf("Enter the number of integers: ");
    scanf("%d", &count);

    if (count <= 0) {
        fprintf(stderr, "Invalid input. Please enter a positive integer.\n");
        return;
    }

    uint64_t* numbers = malloc(count * sizeof(uint64_t));
    for (int i = 0; i < count; i++) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &num);
        numbers[i] = num;
    }

    uint64_t largest = numbers[0];
    for (int i = 1; i < count; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("The largest integer is: %llu\n", largest);

    free(numbers);
}

int main() {
    initialize_message_pool();

    pthread_t reader_thread;
    pthread_create(&reader_thread, NULL, read_and_find_largest, NULL);

    // Simulate message allocation
    for (int i = 0; i < 10; i++) {
        Message* msg = allocate_message(NULL);
        if (msg != NULL) {
            printf("Allocated message with ID: %llu\n", (*msg).identifier);
        } else {
            printf("No more messages available.\n");
            break;
        }
    }

    pthread_join(reader_thread, NULL);

    // Clean up allocated memory
    for (int i = 0; i < MAX_MESSAGES; i++) {
        if (message_pool[i] != NULL) {
            free(message_pool[i]);
        }
    }

    return 0;
}
