DataStorage* create_data_storage(size_t initial_capacity) {
    DataStorage* storage = (DataStorage*)malloc(sizeof(DataStorage));
    if (!storage) return NULL;

    storage->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!storage->records) {
        free(storage);
        return NULL;
    }

    storage->capacity = initial_capacity;
    storage->size = 0;
    pthread_mutex_init(&storage->mutex, NULL);

    storage->used_labels = (unsigned char*)calloc(MAX_LABEL_LENGTH, sizeof(unsigned char));
    if (!storage->used_labels) {
        free(storage->records);
        free(storage);
        return NULL;
    }

    storage->max_used_label = 0;
    return storage;
}

void destroy_data_storage(DataStorage* storage) {
    for (size_t i = 0; i < storage->size; ++i) {
        // Custom cleanup if needed
    }
    pthread_mutex_destroy(&storage->mutex);
    free(storage->records);
    free(storage->used_labels);
    free(storage);
}

int add_record(DataStorage* storage, unsigned long id, const char* label) {
    pthread_mutex_lock(&storage->mutex);

    if (id == 0 || strlen(label) >= MAX_LABEL_LENGTH || storage->size >= storage->capacity) {
        pthread_mutex_unlock(&storage->mutex);
        return -1; // Invalid input or no space
    }

    if (storage->used_labels[label[0]]) {
        pthread_mutex_unlock(&storage->mutex);
        return -2; // Label already used
    }

    storage->records[storage->size].id = id;
    strncpy(storage->records[storage->size].label, label, MAX_LABEL_LENGTH - 1);
    storage->records[storage->size].value = rand(); // Placeholder for PRNG

    storage->used_labels[label[0]] = 1;
    if (label[0] > storage->max_used_label) {
        storage->max_used_label = label[0];
    }

    ++storage->size;

    pthread_mutex_unlock(&storage->mutex);
    return 0; // Success
}

// Additional functions for resizing, updating records, and cleanup can be implemented here

