typedef struct {
    unsigned long *seed_values;
    int *keys;
    record *records;
    int num_keys;
    pthread_mutex_t lock;
} key_record_pool;

key_record_pool* create_key_record_pool() {
    key_record_pool *pool = (key_record_pool*)malloc(sizeof(key_record_pool));
    if (!pool) return NULL;

    pool->seed_values = (unsigned long*)calloc(MAX_KEYS, sizeof(unsigned long));
    pool->keys = (int*)calloc(MAX_KEYS, sizeof(int));
    pool->records = (record*)calloc(MAX_KEYS, sizeof(record));
    if (!pool->seed_values || !pool->keys || !pool->records) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->num_keys = 0;

    return pool;
}

int add_key(key_record_pool *pool, unsigned long seed) {
    if (pool->num_keys >= MAX_KEYS) return -1;

    pthread_mutex_lock(&pool->lock);

    int key = rand_r(&seed);
    while (pool->keys[key]) {
        key = rand_r(&seed);
    }

    pool->keys[key] = 1;
    pool->seed_values[key] = seed;
    pool->records[key].value = ((double)rand_r(&seed)) / RAND_MAX;

    pthread_mutex_unlock(&pool->lock);

    pool->num_keys++;
    return key;
}

void free_key_record_pool(key_record_pool *pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->lock);
    free(pool->seed_values);
    free(pool->keys);
    free(pool->records);
    free(pool);
}
