Record** create_record_array(size_t size, time_t seed, int* error_code) {
    if (size == 0 || error_code == NULL) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    Record** records = (Record**)malloc(size * sizeof(Record*));
    if (records == NULL) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    srand(seed);
    for (size_t i = 0; i < size; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (records[i] == NULL) {
            *error_code = -3; // Failed to allocate memory for a record
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }
        records[i]->key = i;
        records[i]->offset = rand();
    }

    *error_code = 0; // Success
    return records;
}

void free_record_array(Record** records, size_t size) {
    if (records == NULL) return;

    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(records);
}
