#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long id;
    double amount;
} transaction;

// Non-cryptographic PRNG for transaction IDs
long non_cryptographic_prng(long seed) {
    return (seed * 1103515245 + 12345) % 0xFFFFFFFF;
}

// Cryptographic PRNG for transaction amounts
double cryptographic_prng(double seed, double min_amount, double max_amount) {
    seed = fmod(seed * 6364136223809661L + 1442695040888963407L, 0xFFFFFFFFFFFFFFFFL);
    return (seed / 0xFFFFFFFFFFFFFFFFL) * (max_amount - min_amount) + min_amount;
}

// Function to allocate memory for transactions and populate them
transaction* allocate_transactions(long seed, long num_transactions, double min_amount, double max_amount) {
    transaction* txs = malloc(num_transactions * sizeof(transaction));
    if (!txs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (long i = 0; i < num_transactions; i++) {
        txs[i].id = non_cryptographic_prng(seed + i);
        txs[i].amount = cryptographic_prng(seed + i * 100, min_amount, max_amount);
    }

    return txs;
}

// Function to print transaction details
void print_transactions(transaction* txs, long num_transactions) {
    for (long i = 0; i < num_transactions; i++) {
        printf("Transaction ID: %ld, Amount: %.2f\n", txs[i].id, txs[i].amount);
    }
}

// Function to deallocate memory
void free_transactions(transaction* txs) {
    free(txs);
}

int main() {
    srand(time(NULL)); // Seed for non-cryptographic PRNG
    long num_transactions = 1000;
    double min_amount = 10.0, max_amount = 500.0;

    transaction* txs = allocate_transactions(12345L, num_transactions, min_amount, max_amount);
    print_transactions(txs, num_transactions);
    free_transactions(txs);

    return 0;
}
```

