    int num_types = sizeof(transaction_types) / sizeof(transaction_types[0]);

    // Allocate memory for an array of Transaction pointers
    Transaction** transactions = malloc(500 * sizeof(Transaction*));
    if (!transactions) {
        *error_code = 1; // Memory allocation failed
        return NULL;
    }

    // Populate the array with unique transaction structures
    for (int i = 0; i < 500; ++i) {
        transactions[i] = malloc(sizeof(Transaction));
        if (!transactions[i]) {
            *error_code = 1; // Memory allocation failed
            // Free previously allocated memory before returning NULL
            for (int j = 0; j < i; ++j) {
                free(transactions[j]);
            }
            free(transactions);
            return NULL;
        }

        transactions[i]->id = i + 1; // Assign unique ID from 1 to 500
        transactions[i]->amount = ((double)(rand() % 1000)) / 10.0; // Pseudo-random amount

        // Select a random transaction type and allocate memory for its description
        int type_index = rand() % num_types;
        transactions[i]->description = malloc((strlen(transaction_types[type_index]) + 1) * sizeof(char));
        if (!transactions[i]->description) {
