        offsets[i] = rand_func();
        keys[i] = rand_func() % 1001;
        snprintf(records[i].string, RECORD_SIZE, "%d", records[i].value);
    }

    return records;
}

void free_pipeline(long *offsets, int *keys, Record *records, size_t size) {
    free(offsets);
    free(keys);
    free(records);
}

