    unsigned long range_min = offset_range[0];
    unsigned long range_max = offset_range[1];

    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            *error_code = 2; // Error: Memory allocation failed
            goto cleanup;
        }

        records[i]->key = i;

        srand(seed + i); // Seed PRNG differently for each thread
        unsigned long offset = range_min + (rand() % (range_max - range_min + 1));
        records[i]->offset = offset;
    }

cleanup:
