#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_RECORDS 1000000
#define RECORD_SIZE sizeof(int)

typedef struct {
    int* data;
    pthread_mutex_t mutex;
} RecordManager;

void initializeRecordManager(RecordManager* manager, size_t size) {
    manager->data = (int*)calloc(size, RECORD_SIZE);
    if (!manager->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->mutex, NULL);
}

void cleanupRecordManager(RecordManager* manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->mutex);
}

int generateUniqueID() {
    return (int)((double)rand() / RAND_MAX * INT_MAX);
}

void* initializeRecords(void* arg) {
    RecordManager* manager = (RecordManager*)arg;
    for (size_t i = 0; i < NUM_RECORDS; ++i) {
        pthread_mutex_lock(&manager->mutex);
        int id;
        do {
            id = generateUniqueID();
        } while (manager->data[id] != 0); // Ensure uniqueness
        manager->data[id] = 1;
        pthread_mutex_unlock(&manager->mutex);
    }
    return NULL;
}

int checkUniqueness(RecordManager* manager) {
    for (size_t i = 0; i < NUM_RECORDS; ++i) {
        if (manager->data[i] != 1) {
            return 0; // Not all IDs are unique
        }
    }
    return 1;
}

int main() {
    RecordManager manager;
    initializeRecordManager(&manager, NUM_RECORDS);

    pthread_t threads[4]; // Example with 4 threads
    for (size_t i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, initializeRecords, &manager) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (checkUniqueness(&manager)) {
        printf("All IDs are unique.\n");
    } else {
        printf("ID uniqueness check failed.\n");
    }

    cleanupRecordManager(&manager);

    return 0;
}
```

