#define MAX_TRANSACTIONS 1000

typedef struct {
    int* transaction_ids;
    time_t* timestamps;
    double* amounts;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TransactionManager;

void init_transaction_manager(TransactionManager* manager) {
    manager->transaction_ids = (int*)malloc(MAX_TRANSACTIONS * sizeof(int));
    manager->timestamps = (time_t*)malloc(MAX_TRANSACTIONS * sizeof(time_t));
    manager->amounts = (double*)malloc(MAX_TRANSACTIONS * sizeof(double));
    if (!manager->transaction_ids || !manager->timestamps || !manager->amounts) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    manager->count = 0;
    manager->capacity = MAX_TRANSACTIONS;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_transaction(TransactionManager* manager, int id, time_t timestamp, double amount) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        int* new_ids = (int*)realloc(manager->transaction_ids, new_capacity * sizeof(int));
        time_t* new_timestamps = (time_t*)realloc(manager->timestamps, new_capacity * sizeof(time_t));
        double* new_amounts = (double*)realloc(manager->amounts, new_capacity * sizeof(double));
        if (!new_ids || !new_timestamps || !new_amounts) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
        manager->transaction_ids = new_ids;
        manager->timestamps = new_timestamps;
        manager->amounts = new_amounts;
        manager->capacity = new_capacity;
    }
    manager->transaction_ids[manager->count] = id;
    manager->timestamps[manager->count] = timestamp;
    manager->amounts[manager->count] = amount;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void destroy_transaction_manager(TransactionManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->transaction_ids);
    free(manager->timestamps);
    free(manager->amounts);
}
