#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

record* records[MAX_KEYS];
int key_pool[MAX_KEYS];
int pool_index = 0;
pthread_mutex_t lock;

void init_memory() {
    for (int i = 0; i < MAX_KEYS; i++) {
        key_pool[i] = i;
    }
    pthread_mutex_init(&lock, NULL);
}

record* allocate_record(int value) {
    record* new_record = malloc(sizeof(record));
    if (!new_record) return NULL;
    new_record->value = value;
    return new_record;
}

int get_unique_key() {
    int key;
    pthread_mutex_lock(&lock);
    if (pool_index >= MAX_KEYS) {
        pthread_mutex_unlock(&lock);
        return -1; // No more keys available
    }
    key = key_pool[pool_index++];
    pthread_mutex_unlock(&lock);
    return key;
}

void free_key(int key) {
    pthread_mutex_lock(&lock);
    key_pool[--pool_index] = key;
    pthread_mutex_unlock(&lock);
}

int generate_random_value() {
    static int seed_set = 0;
    if (!seed_set) {
        srand(time(NULL));
        seed_set = 1;
    }
    return rand() % 1001; // Random between 0 and 1000
}

void* record_thread(void* arg) {
    int key = get_unique_key();
    if (key == -1) {
        printf("No more keys available\n");
        pthread_exit(NULL);
    }

    record* rec = allocate_record(generate_random_value());
    if (!rec) {
        free_key(key);
        printf("Memory allocation failed for new record\n");
        pthread_exit(NULL);
    }

    records[key] = rec;
    printf("Record allocated with key %d and value %d\n", key, rec->value);

    // Simulate work
    sleep(1);

    free_key(key);
    free(rec);
    printf("Record freed with key %d\n", key);

    pthread_exit(NULL);
}

int main() {
    init_memory();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, record_thread, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&lock);

    return 0;
}
