#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct HashTableEntry {
    int key;
    Record *record;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct HashTable {
    HashTableEntry **buckets;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

HashTable *hash_table_create(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->buckets = calloc(capacity, sizeof(HashTableEntry *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->capacity = capacity;
    table->size = 0;
    return table;
}

void hash_table_destroy(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableEntry *entry = table->buckets[i];
        while (entry) {
            HashTableEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    free(table);
}

int hash_table_insert(HashTable *table, int key, Record *record) {
    size_t index = hash(key, table->capacity);
    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    if (!entry) return -1;
    entry->key = key;
    entry->record = record;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    ++table->size;
    return 0;
}

Record *hash_table_get(HashTable *table, int key) {
    size_t index = hash(key, table->capacity);
    HashTableEntry *entry = table->buckets[index];
    while (entry) {
        if (entry->key == key) return entry->record;
        entry = entry->next;
    }
    return NULL;
}

int initialize_structures(size_t max_records, int min_value, int max_value) {
    srand(time(NULL));
    HashTable *table = hash_table_create(max_records);
    if (!table) return -1;

    for (size_t i = 0; i < max_records; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            hash_table_destroy(table);
            return -1;
        }
        record->value = min_value + rand() % (max_value - min_value + 1);

        int key = i;
        if (hash_table_get(table, key)) {
            // Handle collision
            free(record);
            --i; // Retry with a new index
        } else {
            if (hash_table_insert(table, key, record) != 0) {
                free(record);
                hash_table_destroy(table);
                return -1;
            }
        }
    }

    // Cleanup and return success
    hash_table_destroy(table);
    return 0;
}
