#include <limits.h>

#define MAX_RECORDS 1024

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
    record rec;
} data_struct;

typedef struct {
    data_struct *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} memory_manager;

memory_manager* mm_init(size_t initial_capacity) {
    memory_manager *mm = (memory_manager*)malloc(sizeof(memory_manager));
    if (!mm) return NULL;
    mm->data = (data_struct*)calloc(initial_capacity, sizeof(data_struct));
    if (!mm->data) {
        free(mm);
        return NULL;
    }
    mm->capacity = initial_capacity;
    mm->size = 0;
    pthread_mutex_init(&mm->lock, NULL);
    return mm;
}

void mm_destroy(memory_manager *mm) {
    free(mm->data);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}

int mm_add_record(memory_manager *mm) {
    pthread_mutex_lock(&mm->lock);
    if (mm->size == mm->capacity) {
        data_struct *new_data = realloc(mm->data, mm->capacity * 2 * sizeof(data_struct));
        if (!new_data) {
            pthread_mutex_unlock(&mm->lock);
            return -1;
        }
        mm->data = new_data;
        mm->capacity *= 2;
    }
    mm->data[mm->size].offset = rand();
    mm->data[mm->size].key = rand();
    mm->data[mm->size].rec.value = rand();
    mm->size++;
    pthread_mutex_unlock(&mm->lock);
    return 0;
}

void* thread_function(void *arg) {
    memory_manager *mm = (memory_manager*)arg;
    for (int i = 0; i < 100; i++) {
        if (mm_add_record(mm) != 0) break;
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    memory_manager *mm = mm_init(256);
    if (!mm) {
        fprintf(stderr, "Failed to initialize memory manager\n");
        return 1;
    }

    pthread_t threads[8];
    for (int i = 0; i < 8; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, mm) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 8; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Total records added: %zu\n", mm->size);

    mm_destroy(mm);
    return 0;
}
