#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record *record;
    struct Node *next;
} Node;

typedef struct {
    Node **buckets;
    int size;
    int capacity;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(int initial_capacity) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (Node**)calloc(initial_capacity, sizeof(Node*));
    ht->size = 0;
    ht->capacity = initial_capacity;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void free_record(Record *rec) {
    if (rec) {
        free(rec);
    }
}

void free_node(Node *node) {
    if (node) {
        free_record(node->record);
        free(node);
    }
}

void free_hash_table(HashTable *ht) {
    if (ht) {
        for (int i = 0; i < ht->capacity; ++i) {
            Node *current = ht->buckets[i];
            while (current) {
                Node *temp = current;
                current = current->next;
                free_node(temp);
            }
        }
        free(ht->buckets);
        pthread_mutex_destroy(&ht->lock);
        free(ht);
    }
}

void* insert(HashTable *ht, long offset, int key, int value_range) {
    pthread_mutex_lock(&ht->lock);
    int index = hash_function(offset) % ht->capacity;
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->offset = offset;
    new_node->key = key;
    new_node->record = create_record(value_range);
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
    ht->size++;
    pthread_mutex_unlock(&ht->lock);
    return new_node;
}

void* create_record(int value_range) {
    Record *rec = (Record*)malloc(sizeof(Record));
    rec->value = rand() % value_range;
    return rec;
}

int hash_function(long offset) {
    // Simple hash function for demonstration
    return offset ^ (offset >> 16);
}
```

