// Define structures
typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    int key;
} KeyStruct;

typedef struct {
    int value;
    char *str_ptr;
} RecordStruct;

typedef struct {
    time_t timestamp;
    int sequence_number;
} AuditLogEntry;

typedef struct {
    char token[64];
} SessionTokenStruct;

// Function to initialize structures
void initialize_structs(long offset_size, int key_size, int record_range, double timestamp_interval, int max_sessions) {
    OffsetStruct *offsets = (OffsetStruct *)malloc(offset_size * sizeof(OffsetStruct));
    KeyStruct *keys = (KeyStruct *)malloc(key_size * sizeof(KeyStruct));
    RecordStruct *records = (RecordStruct *)malloc(record_size * sizeof(RecordStruct));
    AuditLogEntry *audit_log = (AuditLogEntry *)malloc(max_sessions * sizeof(AuditLogEntry));
    SessionTokenStruct *sessions = (SessionTokenStruct *)malloc(max_sessions * sizeof(SessionTokenStruct));

    if (!offsets || !keys || !records || !audit_log || !sessions) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize structures with sequential numbers or user-defined sequences
    for (long i = 0; i < offset_size; i++) {
        offsets[i].offset = i;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i].key = i + 1; // Sequential keys starting from 1
    }

    // Use a linear congruential generator and CSPRNG to fill records with random numbers within the specified range
    srand(time(0));
    for (int i = 0; i < record_size; i++) {
        records[i].value = rand() % (record_range + 1); // Random number in range [0, record_range]
        records[i].str_ptr = (char *)malloc(256 * sizeof(char)); // Allocate memory for string pointer
    }

    // Initialize audit log with timestamps and sequence numbers
    time_t current_time;
    for (int i = 0; i < max_sessions; i++) {
        time(&current_time);
        audit_log[i].timestamp = current_time + (i * timestamp_interval); // Timestamps spaced by interval
        audit_log[i].sequence_number = i + 1; // Sequential sequence numbers starting from 1
    }

    // Initialize session tokens with unique identifiers
    for (int i = 0; i < max_sessions; i++) {
        snprintf(sessions[i].token, sizeof(sessions[i].token), "session_%d", i);
    }

    // Perform cleanup
    free(offsets);
    free(keys);
    for (int i = 0; i < record_size; i++) {
        free(records[i].str_ptr); // Free allocated memory for string pointers
    }
    free(records);
    free(audit_log);
    free(sessions);
}

// Example usage
int main() {
    initialize_structs(5, 5, 100, 60.0, 10);
    return 0;
}
