#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_KEYS 1024

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordPool;

RecordPool record_pool;

void init_record_pool(size_t initial_capacity) {
    record_pool.capacity = initial_capacity;
    record_pool.count = 0;
    record_pool.records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (record_pool.records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&record_pool.lock, NULL);
}

bool insert_record(int key, long offset) {
    pthread_mutex_lock(&record_pool.lock);
    if (record_pool.count >= record_pool.capacity) {
        Record *new_records = (Record *)realloc(record_pool.records, record_pool.capacity * 2 * sizeof(Record));
        if (new_records == NULL) {
            pthread_mutex_unlock(&record_pool.lock);
            return false;
        }
        record_pool.records = new_records;
        record_pool.capacity *= 2;
    }

    for (size_t i = 0; i < record_pool.count; ++i) {
        if (record_pool.records[i].key == key) {
            pthread_mutex_unlock(&record_pool.lock);
            return false;
        }
    }

    record_pool.records[record_pool.count].key = key;
    record_pool.records[record_pool.count].offset = offset;
    ++record_pool.count;
    pthread_mutex_unlock(&record_pool.lock);
    return true;
}

void destroy_record_pool() {
    pthread_mutex_lock(&record_pool.lock);
    free(record_pool.records);
    pthread_mutex_destroy(&record_pool.lock);
}

int main() {
    init_record_pool(1024);

    // Example usage
    if (insert_record(1, 100)) {
        printf("Record inserted successfully\n");
    } else {
        printf("Failed to insert record\n");
    }

    destroy_record_pool();
    return 0;
}
```

