use std::sync::{Arc, Mutex};
use std::collections::HashSet;
use std::cmp::Ordering;
use rand::{thread_rng, Rng};

// Define the Task structure
struct Task {
    timestamp: u64,
    task_id: i32,
    priority_level: f32,
}

// Function to allocate and initialize memory for tasks
fn allocate_tasks(max_tasks: usize) -> Result<(Vec<u64>, Vec<i32>, Vec<f32>), &'static str> {
    if max_tasks == 0 {
        return Err("Maximum number of tasks cannot be zero.");
    }

    let mut timestamps = vec![0; max_tasks];
    let mut task_ids = vec![0; max_tasks];
    let mut priority_levels = vec![0.0; max_tasks];

    let used_ids = Arc::new(Mutex::new(HashSet::new()));

    for i in 0..max_tasks {
        loop {
            let new_id = thread_rng().gen_range(1, 1024);
            if !used_ids.lock().unwrap().contains(&new_id) {
                used_ids.lock().unwrap().insert(new_id);
                task_ids[i] = new_id;
                break;
            }
        }

        timestamps[i] = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or_else(|_| 0, |d| d.as_secs());
        priority_levels[i] = thread_rng().gen_range(1.0..=10.0);
    }

    Ok((timestamps, task_ids, priority_levels))
}

// Helper function to find and print the median value in an array
fn print_median(arr: &[i32]) {
    let mut arr = arr.to_vec();
    arr.sort_unstable();

    match arr.len() % 2 {
        0 => println!("Median: {}", (arr[arr.len() / 2 - 1] + arr[arr.len() / 2]) as f64 / 2.0),
        _ => println!("Median: {}", arr[arr.len() / 2]),
    }
}

fn main() {
    // Example usage
    match allocate_tasks(5) {
        Ok((timestamps, task_ids, priority_levels)) => {
            for i in 0..task_ids.len() {
                println!("Task {}: ID={}, Priority={}", i + 1, task_ids[i], priority_levels[i]);
            }

            let input: Vec<i32> = vec![5, 3, 9, 1, 7];
            print_median(&input);
        },
        Err(e) => eprintln!("Error allocating tasks: {}", e),
    }
}
