import java.util.*;
import java.security.SecureRandom;
import java.sql.*;

public class OrderProcessor {

    private static final SecureRandom RANDOM = new SecureRandom();
    private static final Set<Integer> usedIdentifiers = Collections.synchronizedSet(new HashSet<>());
    private static final String DB_URL = "jdbc:mysql://localhost:3306/orders";
    private static final String USER = "user";
    private static final String PASS = "password";

    public void processOrders(int maxOrders) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter transaction amounts (separated by spaces):");
        List<Integer> transactions = Arrays.asList(scanner.nextLine().split("\\s+"))
                                           .stream()
                                           .map(Integer::parseInt)
                                           .collect(Collectors.toList());

        int batchSize = Math.min(transactions.size(), maxOrders);
        for (int i = 0; i < batchSize; i++) {
            try {
                int uniqueId = generateUniqueId();
                double transactionAmount = transactions.get(i);
                processOrder(uniqueId, transactionAmount);
                System.out.println("Order processed successfully: ID=" + uniqueId + ", Amount=" + transactionAmount);
            } catch (Exception e) {
                System.err.println("Failed to process order: " + e.getMessage());
            }
        }
    }

    private int generateUniqueId() throws SQLException {
        while (true) {
            int id = RANDOM.nextInt(10000);
            synchronized (usedIdentifiers) {
                if (!usedIdentifiers.contains(id)) {
                    usedIdentifiers.add(id);
                    return id;
                }
            }
        }
    }

    private void processOrder(int uniqueId, double amount) throws SQLException {
        // Simulate database operation
        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS)) {
            String sql = "INSERT INTO orders (id, amount) VALUES (?, ?)";
            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
                pstmt.setInt(1, uniqueId);
                pstmt.setDouble(2, amount);
                pstmt.executeUpdate();
            }
        } catch (SQLException e) {
            if (e.getSQLState().equals("08000")) { // Connection failure
                System.err.println("Transient database connection failure. Retrying...");
                Thread.sleep(100); // Wait before retrying
                processOrder(uniqueId, amount);
            } else {
                throw e;
            }
        }
    }

    public static void main(String[] args) {
