#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_CHANNELS 10

typedef struct {
    int id;
    int age;
    double weighted_sum;
} Transaction;

typedef struct {
    Transaction transactions[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} TransactionPool;

TransactionPool pool = {0};
int channel_records[MAX_CHANNELS][MAX_RECORDS] = {0};
pthread_mutex_t channel_locks[MAX_CHANNELS] = {[0 ... MAX_CHANNELS - 1] = PTHREAD_MUTEX_INITIALIZER};

void init_pool() {
    pthread_mutex_init(&pool.lock, NULL);
}

void add_transaction(Transaction t) {
    pthread_mutex_lock(&pool.lock);
    if (pool.count < MAX_RECORDS) {
        pool.transactions[pool.count++] = t;
    }
    pthread_mutex_unlock(&pool.lock);
}

int find_largest_integer() {
    int max = INT_MIN;
    for (int i = 0; i < pool.count; ++i) {
        if (pool.transactions[i].weighted_sum > max) {
            max = pool.transactions[i].weighted_sum;
        }
    }
    return max;
}

void* process_transactions(void* arg) {
    int channel_id = *(int*)arg;
    pthread_mutex_lock(&channel_locks[channel_id]);
    for (int i = 0; i < channel_records[channel_id][i]; ++i) {
        add_transaction(channel_records[channel_id][i]);
    }
    pthread_mutex_unlock(&channel_locks[channel_id]);
    return NULL;
}

void main() {
    init_pool();
    int input[MAX_RECORDS];
    int count = 0;

    while (scanf("%d", &input[count]) == 1) {
        ++count;
    }

    if (count > MAX_RECORDS) {
        printf("Too many records.\n");
        return;
    }

    for (int i = 0; i < count; ++i) {
        Transaction t = {i, 0, input[i]};
        add_transaction(t);
    }

    int largest = find_largest_integer();
    printf("Largest integer: %d\n", largest);

    pthread_t threads[MAX_CHANNELS];
    for (int i = 0; i < MAX_CHANNELS; ++i) {
        pthread_create(&threads[i], NULL, process_transactions, &i);
    }

    for (int i = 0; i < MAX_CHANNELS; ++i) {
        pthread_join(threads[i], NULL);
    }
}
