import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.Random;

public class ConcurrentConnectionHandler {

    private static final int MAX_CONNECTIONS = 100_000;
    private static final Set<Integer> usedKeys = new HashSet<>();
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final ByteBuffer buffer = ByteBuffer.allocate(4);

    public static void main(String[] args) throws IOException {
        AsynchronousServerSocketChannel serverSocketChannel = AsynchronousServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress("localhost", 8080));
        System.out.println("Server started on port 8080");

        while (true) {
            serverSocketChannel.accept(null, new AcceptHandler());
        }
    }

    private static class AcceptHandler implements AsynchronousAcceptHandler<AsynchronousSocketChannel> {
        @Override
        public void accept(AsynchronousSocketChannel socketChannel, Object attachment, CompletionHandler<Void, Void> handler) throws IOException {
            if (usedKeys.size() < MAX_CONNECTIONS) {
                usedKeys.add(generateUniqueKey());
                executorService.submit(() -> handleConnection(socketChannel));
            } else {
                socketChannel.close();
            }
        }

        private void handleConnection(AsynchronousSocketChannel socketChannel) {
            CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
                try {
                    while (true) {
                        ByteBuffer buffer = ByteBuffer.allocate(4);
                        int bytesRead = socketChannel.read(buffer).get();
                        if (bytesRead == -1) break;
                        buffer.flip();
                        int data = buffer.getInt();
                        processData(data);
                    }
                    socketChannel.close();
                } catch (IOException | InterruptedException e) {
                    e.printStackTrace();
                }
            }, executorService);
        }

        private void processData(int data) {
            // Process data here
        }

        private int generateUniqueKey() {
            while (true) {
                int key = new Random().nextInt(1024);
                if (usedKeys.add(key)) return key;
            }
        }
    }

    public static void findLargestInteger(int[] numbers) {
        int largest = Integer.MIN_VALUE;
        for (int number : numbers) {
            if (number > largest) {
                largest = number;
            }
        }
        System.out.println("Largest integer: " + largest);
    }

    // Other methods and classes can be added here
}
```

