    private static final ConcurrentHashMap<String, Long> sessionMap = new ConcurrentHashMap<>();

    public static String generateSessionId() {
        return UUID.randomUUID().toString();
    }

    public static boolean isValidSession(String sessionId) {
        return sessionMap.containsKey(sessionId);
    }

    public static void addSession(String sessionId) {
        if (sessionMap.size() > 10000) { // Example threshold
            removeExpiredSessions();
        }
        sessionMap.putIfAbsent(sessionId, System.currentTimeMillis());
    }

    public static void removeSession(String sessionId) {
        sessionMap.remove(sessionId);
    }

    private static void removeExpiredSessions() {
        long currentTime = System.currentTimeMillis();
        sessionMap.entrySet().removeIf(entry -> (currentTime - entry.getValue()) > 3600000); // Example expiration time of 1 hour
    }
}
