import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Random;

public class TaskDistributor {

    private static final int MAX_TASK_ID = 1024;
    private static final float MIN_PRIORITY = 0.0f;
    private static final float MAX_PRIORITY = 1.0f;
    private static final int BATCH_SIZE = 1000;
    private static final String LOG_FILE = "task_distributor.log";
    private static final int MAX_RECORDS = Integer.parseInt(System.getProperty("maxRecords", "10000"));

    private SocketChannel channel;
    private ByteBuffer buffer;
    private ConcurrentHashMap<Integer, Boolean> usedKeys;
    private AtomicInteger nextTaskId;
    private Random random;

    public TaskDistributor(String remoteAddress) throws IOException {
        this.channel = SocketChannel.open();
        this.buffer = ByteBuffer.allocate(BUFFER_SIZE);
        this.usedKeys = new ConcurrentHashMap<>();
        this.nextTaskId = new AtomicInteger(0);
        this.random = new Random(System.nanoTime());
        channel.connect(InetSocketAddress.getByName(remoteAddress));
    }

    public void distributeTasks(List<Integer> taskIds, List<Float> priorities) {
        if (taskIds.size() != priorities.size()) {
            throw new IllegalArgumentException("Task IDs and priorities must have the same size");
        }
        if (taskIds.isEmpty()) {
            return;
        }

        int batchSize = Math.min(taskIds.size(), BATCH_SIZE);
        for (int i = 0; i < taskIds.size(); i += batchSize) {
            List<Integer> batchTaskIds = taskIds.subList(i, Math.min(i + batchSize, taskIds.size()));
            List<Float> batchPriorities = priorities.subList(i, Math.min(i + batchSize, priorities.size()));

            ByteBuffer batchBuffer = allocateBatchBuffer(batchTaskIds, batchPriorities);
            writeToStorageSystem(batchBuffer);
        }
    }

    private ByteBuffer allocateBatchBuffer(List<Integer> taskIds, List<Float> priorities) {
        ByteBuffer buffer = ByteBuffer.allocate(estimateBufferSize(taskIds, priorities));
        for (int taskId : taskIds) {
            putLong(buffer, System.currentTimeMillis());
            putInt(buffer, taskId);
            putFloat(buffer, priorities.get(taskIds.indexOf(taskId)));
        }
        return buffer.flip();
    }

    private void writeToStorageSystem(ByteBuffer buffer) {
        try {
            channel.write(buffer);
        } catch (IOException e) {
            handleWriteFailure(e);
        }
    }

    private void handleWriteFailure(IOException e) {
        // Log error and rollback partial operation
        System.err.println("Failed to write data to storage system: " + e.getMessage());
        // Implement rollback logic here if needed
    }

    private long getLong(ByteBuffer buffer, int index) {
        buffer.position(index * Long.BYTES);
        return buffer.getLong();
    }

    private void putLong(ByteBuffer buffer, long value) {
        buffer.putLong(value);
    }

    private int getInt(ByteBuffer buffer, int index) {
        buffer.position(index * Integer.BYTES);
        return buffer.getInt();
    }

    private void putInt(ByteBuffer buffer, int value) {
        buffer.putInt(value);
    }

    private float getFloat(ByteBuffer buffer, int index) {
        buffer.position(index * Float.BYTES);
        return buffer.getFloat();
    }

    private void putFloat(ByteBuffer buffer, float value) {
        buffer.putFloat(value);
    }

    private static int estimateBufferSize(List<Integer> taskIds, List<Float> priorities) {
        // Calculate the total size of the batch buffer
        return taskIds.size() * (Long.BYTES + Integer.BYTES + Float.BYTES);
    }

    public void cleanUp() throws IOException {
        channel.close();
    }

    public static void main(String[] args) {
        try {
            TaskDistributor distributor = new TaskDistributor("remote_address");
            List<Integer> taskIds = readInputIntegers();
            List<Float> priorities = readInputFloats();
            distributor.distributeTasks(taskIds, priorities);
            distributor.cleanUp();
        } catch (IOException e) {
            System.err.println("Error occurred: " + e.getMessage());
        }
    }

    private static List<Integer> readInputIntegers() {
        List<Integer> integers = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            while ((line = reader.readLine()) != null) {
                try {
                    integers.add(Integer.parseInt(line.trim()));
                } catch (NumberFormatException e) {
                    System.err.println("Invalid integer input: " + line);
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
        return integers;
    }

    private static List<Float> readInputFloats() {
        List<Float> floats = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            while ((line = reader.readLine()) != null) {
                try {
                    floats.add(Float.parseFloat(line.trim()));
                } catch (NumberFormatException e) {
                    System.err.println("Invalid float input: " + line);
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
        return floats;
    }

    public static void main(String[] args) {
        try {
            TaskDistributor distributor = new TaskDistributor("remote_address");
            List<Integer> taskIds = readInputIntegers();
            List<Float> priorities = readInputFloats();
            float maxPriority = findMaxPriority(priorities);
            int minInteger = findMinInteger(taskIds);
            System.out.println("Largest integer: " + minInteger);
            System.out.println("Smallest floating-point number: " + maxPriority);
            distributor.distributeTasks(taskIds, priorities);
            distributor.cleanUp();
        } catch (IOException e) {
            System.err.println("Error occurred: " + e.getMessage());
        }
    }

    private static float findMaxPriority(List<Float> priorities) {
        return priorities.stream().max(Float::compare).orElse(MIN_PRIORITY);
    }

    private static int findMinInteger(List<Integer> integers) {
        return integers.stream().min(Integer::compare).orElse(Integer.MAX_VALUE);
    }
}
