#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_KEYS 1024
#define RECORD_POOL_SIZE 1000

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    bool *used_keys;
    pthread_mutex_t used_keys_lock;
    record *record_pool;
    size_t record_count;
} data_struct;

data_struct *create_data_struct() {
    data_struct *ds = (data_struct *)malloc(sizeof(data_struct));
    ds->offsets = (long *)malloc(MAX_KEYS * sizeof(long));
    ds->keys = (int *)malloc(MAX_KEYS * sizeof(int));
    ds->used_keys = (bool *)calloc(MAX_KEYS, sizeof(bool));
    pthread_mutex_init(&ds->used_keys_lock, NULL);
    ds->record_pool = (record *)malloc(RECORD_POOL_SIZE * sizeof(record));
    ds->record_count = 0;
    return ds;
}

void destroy_data_struct(data_struct *ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->used_keys);
    pthread_mutex_destroy(&ds->used_keys_lock);
    free(ds->record_pool);
    free(ds);
}

bool is_key_unique(int key, bool *used_keys) {
    pthread_mutex_lock(&used_keys_lock);
    bool unique = !used_keys[key];
    if (unique) used_keys[key] = true;
    pthread_mutex_unlock(&used_keys_lock);
    return unique;
}

record *get_record(data_struct *ds) {
    if (ds->record_count >= RECORD_POOL_SIZE) return NULL;
    return &ds->record_pool[ds->record_count++];
}

void insert_key(long offset, int key, data_struct *ds) {
    pthread_mutex_lock(&ds->used_keys_lock);
    if (key >= 0 && key < MAX_KEYS && !ds->used_keys[key % 32]) {
        ds->offsets[key] = offset;
        ds->keys[key] = key;
        ds->used_keys[key] = true;
        pthread_mutex_unlock(&ds->used_keys_lock);
    } else {
        pthread_mutex_unlock(&ds->used_keys_lock);
        fprintf(stderr, "Error: Key %d is already used or out of range.\n", key);
    }
}

void populate_records(data_struct *ds) {
    srand(time(NULL));
    for (size_t i = 0; i < RECORD_POOL_SIZE; ++i) {
        record *r = get_record(ds);
        if (!r) break;
        r->value = rand() % 1000 + 1;
    }
}

int main() {
    data_struct *ds = create_data_struct();

    // Example usage
    insert_key(12345, 789, ds);
    populate_records(ds);

    destroy_data_struct(ds);
    return 0;
}
