#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

int* used_keys = NULL;
record** records = NULL;
pthread_mutex_t mutex;

void init_memory() {
    used_keys = (int*)malloc(sizeof(int) * MAX_KEYS);
    memset(used_keys, 0, sizeof(int) * MAX_KEYS);
    pthread_mutex_init(&mutex, NULL);
}

int generate_unique_key() {
    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (used_keys[key]);
    used_keys[key] = 1;
    return key;
}

record* create_record(int value) {
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) return NULL;
    new_record->value = value;
    return new_record;
}

void free_memory() {
    for (int i = 0; i < MAX_KEYS; i++) {
        if (used_keys[i]) {
            record* rec = records[i];
            if (rec) {
                free(rec);
                records[i] = NULL;
            }
        }
    }
    free(used_keys);
    pthread_mutex_destroy(&mutex);
}

void* allocate_records(void* arg) {
    int num_records = *(int*)arg;
    records = (record**)malloc(sizeof(record*) * num_records);
    if (!records) return NULL;

    for (int i = 0; i < num_records; i++) {
        record* rec = create_record(rand() % 1001);
        if (!rec) {
            free_memory();
            pthread_exit(NULL);
        }
        records[i] = rec;
    }

    pthread_exit(NULL);
}

void find_largest_integer(int* arr, int size) {
    int max_value = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max_value) {
            max_value = arr[i];
        }
    }
    printf("Largest integer: %d\n", max_value);
}

int main() {
    srand(time(NULL));

    init_memory();

    int num_records = 100;
    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_records, &num_records) != 0) {
        perror("Failed to create thread");
        free_memory();
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    // Simulate concurrent access
    pthread_mutex_lock(&mutex);
    record* rec = records[rand() % num_records];
    printf("Record value: %d\n", rec->value);
    pthread_mutex_unlock(&mutex);

    int arr[] = {5, 3, 9, 1, 7};
    int size = sizeof(arr) / sizeof(arr[0]);
    find_largest_integer(arr, size);

    free_memory();
    return EXIT_SUCCESS;
}
