#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int key;
    long offset;
} Record;

typedef struct Node {
    int key;
    struct Node* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t capacity;
    size_t size;
} HashTable;

// Function to initialize the hash table
HashTable* init_hash_table(size_t capacity) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->table = (HashNode**)calloc(capacity, sizeof(HashNode*));
    ht->capacity = capacity;
    ht->size = 0;
    return ht;
}

// Function to hash a key
size_t hash_function(int key, size_t capacity) {
    return (size_t)(key * 2166136261ul) % capacity;
}

// Function to insert a key into the hash table
void hash_table_insert(HashTable* ht, int key, long offset) {
    size_t index = hash_function(key, ht->capacity);
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    node->key = key;
    node->next = ht->table[index];
    ht->table[index] = node;
    ht->size++;
}

// Function to check if a key is in the hash table
int hash_table_contains(HashTable* ht, int key) {
    size_t index = hash_function(key, ht->capacity);
    HashNode* current = ht->table[index];
    while (current != NULL) {
        if (current->key == key) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Function to free the memory allocated for a hash table
void free_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->capacity; i++) {
        HashNode* node = ht->table[i];
        while (node != NULL) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->table);
    free(ht);
}

// Function to generate a pseudo-random number using the xorshift algorithm
unsigned long xorshift128plus(unsigned long *x, unsigned long *y) {
    unsigned long s0 = *x;
    unsigned long s1 = *y;
    unsigned long result = s0 + s1;

    *x = s1 ^ (s1 << 23);
    *y = ((s0 ^ (s0 << 17)) >> 9) | (result << 24);

    return result;
}

// Function to initialize records with pseudo-random numbers
Record* init_records(int count, int seed, long range_start, long range_end) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    unsigned long x = seed, y = seed;
    for (int i = 0; i < count; i++) {
        records[i].key = xorshift128plus(&x, &y) % 1024;
        while (hash_table_contains(ht, records[i].key)) {
            records[i].key = xorshift128plus(&x, &y) % 1024;
        }
        hash_table_insert(ht, records[i].key, range_start + xorshift128plus(&x, &y) % (range_end - range_start));
        records[i].offset = records[i].key * sizeof(Record);
    }
    return records;
}

// Function to free the memory allocated for records
void free_records(Record* records, int count) {
    free(records);
}

// Main function to demonstrate the usage of the code
int main() {
    srand(time(NULL));
    HashTable* ht = init_hash_table(1024);
    Record* records = init_records(1000, time(NULL), 100, 1000);

    // Process records in parallel
    // ...

    free_records(records, 1000);
    free_hash_table(ht);

    return 0;
}
