    for (int i = 0; i < count; ++i) {
        // Validate and set name
        printf("Enter name for record %d: ", i + 1);
        fgets(records[i].name, MAX_NAME_LENGTH, stdin);
        records[i].name[strcspn(records[i].name, "\n")] = '\0'; // Remove newline

        if (strlen(records[i].name) > MAX_NAME_LENGTH - 1) {
            free(records);
            return NULL;
        }

        // Validate and set age
        printf("Enter age for record %d: ", i + 1);
        scanf("%d", &records[i].age);

        if (records[i].age < MIN_AGE || records[i].age > MAX_AGE) {
            free(records);
            return NULL;
        }

        // Set unique identifier with random number
        records[i].id = (unsigned long)rand() % (max_age - min_age + 1) + min_age;
    }

    return records;
