typedef struct {
    int value;
    time_t last_updated;
} record;

int allocate_memory(long** offsets, int** keys, record** records, int size, int range_min, int range_max, int* status) {
    *offsets = malloc(size * sizeof(long));
    if (*offsets == NULL) {
        *status = -1; // Memory allocation failed
        return 0;
    }

    *keys = malloc(size * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        *status = -1; // Memory allocation failed
        return 0;
    }

    *records = malloc(size * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        *status = -1; // Memory allocation failed
        return 0;
    }

    srand(time(0)); // Seed the random number generator
    for (int i = 0; i < size; i++) {
        (*records)[i].value = rand() % (range_max - range_min + 1) + range_min;
        time(&(*records)[i].last_updated);
    }

    *status = 0; // Success
    return 1;
}

void free_memory(long** offsets, int** keys, record** records) {
    if (*offsets != NULL) {
        free(*offsets);
        *offsets = NULL;
    }
    if (*keys != NULL) {
        free(*keys);
        *keys = NULL;
    }
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}

void log_operation(int status, const char* message) {
    FILE* log_file = fopen("memory_management.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: %d\n", message, status);
        fclose(log_file);
    }
}
