import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

public class JobManager {
    private static final SecureRandom secureRandom = new SecureRandom();
    private final ConcurrentHashMap<Integer, Job> jobMap;
    private final List<Long> timestamps;
    private final List<Integer> jobIds;
    private final List<Double> priorityLevels;
    private final int maxJobs;

    public JobManager(int maxJobs) {
        this.maxJobs = maxJobs;
        this.jobMap = new ConcurrentHashMap<>();
        this.timestamps = new ArrayList<>();
        this.jobIds = new ArrayList<>();
        this.priorityLevels = new ArrayList<>();
    }

    public void allocateJob() throws InterruptedException {
        if (jobMap.size() >= maxJobs) {
            System.out.println("Job allocation failed: Maximum jobs reached.");
            return;
        }

        int jobId;
        while ((jobId = generateRandomJobId()) != -1 && jobMap.containsKey(jobId)) {}

        if (jobId == -1) {
            System.out.println("Job allocation failed: Unable to generate a unique job ID.");
            return;
        }

        long timestamp = System.currentTimeMillis();
        double priorityLevel = secureRandom.nextDouble() * 10 + 1;

        Job newJob = new Job(jobId, timestamp, priorityLevel);
        jobMap.put(jobId, newJob);

        timestamps.add(timestamp);
        jobIds.add(jobId);
        priorityLevels.add(priorityLevel);

        System.out.println("Job allocated: ID=" + jobId + ", Priority=" + priorityLevel);
    }

    private int generateRandomJobId() {
        while (true) {
            int id = secureRandom.nextInt(10000) + 1;
            if (!jobMap.containsKey(id)) return id;
        }
    }

    public void cleanup() {
        jobMap.clear();
        timestamps.clear();
        jobIds.clear();
        priorityLevels.clear();
        System.out.println("All jobs and resources cleaned up.");
    }

    private static class Job {
        int jobId;
        long timestamp;
        double priorityLevel;

        Job(int jobId, long timestamp, double priorityLevel) {
            this.jobId = jobId;
            this.timestamp = timestamp;
            this.priorityLevel = priorityLevel;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        JobManager manager = new JobManager(10);
        for (int i = 0; i < 15; i++) {
            manager.allocateJob();
            Thread.sleep(500);
        }
        manager.cleanup();
    }
}
