#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1000

typedef struct {
    long* offset_values;
    int* keys;
    size_t used_count;
    pthread_mutex_t mutex;
} KeyManager;

void init_key_manager(KeyManager *km) {
    km->offset_values = (long*)malloc(MAX_KEYS * sizeof(long));
    km->keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!km->offset_values || !km->keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    km->used_count = 0;
    pthread_mutex_init(&km->mutex, NULL);
}

void destroy_key_manager(KeyManager *km) {
    free(km->offset_values);
    free(km->keys);
    pthread_mutex_destroy(&km->mutex);
}

int allocate_key(KeyManager *km, long offset_value) {
    int key;
    srand(time(NULL));
    do {
        key = rand() % MAX_KEYS + 1; // Random number between 1 and 1000
    } while (is_key_used(km, key));

    pthread_mutex_lock(&km->mutex);
    if (km->used_count >= MAX_KEYS) {
        pthread_mutex_unlock(&km->mutex);
        return -1; // Key manager is full
    }
    km->keys[km->used_count] = key;
    km->offset_values[km->used_count] = offset_value;
    km->used_count++;
    pthread_mutex_unlock(&km->mutex);

    return key;
}

int deallocate_key(KeyManager *km, int key) {
    pthread_mutex_lock(&km->mutex);
    for (size_t i = 0; i < km->used_count; i++) {
        if (km->keys[i] == key) {
            for (size_t j = i; j < km->used_count - 1; j++) {
                km->keys[j] = km->keys[j + 1];
                km->offset_values[j] = km->offset_values[j + 1];
            }
            km->used_count--;
            pthread_mutex_unlock(&km->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&km->mutex);
    return -1; // Key not found
}

int is_key_used(KeyManager *km, int key) {
    for (size_t i = 0; i < km->used_count; i++) {
        if (km->keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

void* read_and_print_largest() {
    int num;
    long largest = LONG_MIN;

    while ((num = getchar()) != EOF && num != '\n') {
        if (num >= '0' && num <= '9') {
            ungetc(num, stdin);
            scanf("%d", &num);
            if (num > largest) {
                largest = num;
            }
        } else {
            printf("Invalid input.\n");
        }
    }

    printf("Largest integer: %ld\n", largest);

    return NULL;
}

int main() {
    KeyManager km;
    init_key_manager(&km);

    // Example usage
    allocate_key(&km, 100);
    allocate_key(&km, 200);
    deallocate_key(&km, 100);

    destroy_key_manager(&km);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, read_and_print_largest, NULL);
    pthread_join(thread_id, NULL);

    return 0;
}
```

