DataStorage *init_data_storage() {
    DataStorage *storage = (DataStorage *)malloc(sizeof(DataStorage));
    storage->offsets = (long *)malloc(1024 * sizeof(long));
    storage->keys = (int *)malloc(1024 * sizeof(int));
    storage->weights = (double *)malloc(1024 * sizeof(double));
    storage->key_count = 0;
    pthread_mutex_init(&storage->used_keys_lock, NULL);
    for (int i = 0; i < MAX_KEYS; i++) {
        storage->used_keys[i] = 0;
    }
    return storage;
}

void free_data_storage(DataStorage *storage) {
    free(storage->offsets);
    free(storage->keys);
    free(storage->weights);
    pthread_mutex_destroy(&storage->used_keys_lock);
    free(storage);
}

int add_key(DataStorage *storage, int key, long offset, double weight) {
    pthread_mutex_lock(&storage->used_keys_lock);
    if (key >= 0 && key < MAX_KEYS && storage->used_keys[key] == 0) {
        storage->keys[storage->key_count] = key;
        storage->offsets[storage->key_count] = offset;
        storage->weights[storage->key_count] = weight;
        storage->used_keys[key] = 1;
        storage->key_count++;
        pthread_mutex_unlock(&storage->used_keys_lock);
        return 0; // Success
    }
    pthread_mutex_unlock(&storage->used_keys_lock);
    return -1; // Key already in use or out of range
}

void remove_key(DataStorage *storage, int key) {
    pthread_mutex_lock(&storage->used_keys_lock);
    if (key >= 0 && key < MAX_KEYS && storage->used_keys[key] == 1) {
        for (int i = 0; i < storage->key_count; i++) {
            if (storage->keys[i] == key) {
                for (int j = i; j < storage->key_count - 1; j++) {
                    storage->keys[j] = storage->keys[j + 1];
                    storage->offsets[j] = storage->offsets[j + 1];
                    storage->weights[j] = storage->weights[j + 1];
                }
                break;
            }
        }
        storage->key_count--;
        storage->used_keys[key] = 0;
