import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class CacheManager {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private int maxCacheSize = 1000;
    private double cleanupThreshold = 0.75;

    public CacheManager(int maxCacheSize, double cleanupThreshold) {
        this.maxCacheSize = maxCacheSize;
        this.cleanupThreshold = cleanupThreshold;
        scheduler.scheduleAtFixedRate(this::cleanUp, 1, 1, TimeUnit.HOURS);
    }

    public void put(String key, Object value, long ttl) {
        cache.put(key, new CacheEntry(value, ttl));
    }

    public Object get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && !entry.isExpired()) {
            return entry.getValue();
        } else {
            cache.remove(key);
            return null;
        }
    }

    private void cleanUp() {
        int size = cache.size();
        if (size > maxCacheSize * cleanupThreshold) {
            cache.entrySet().removeIf(entry -> entry.getValue().isExpired());
        }
    }

    static class CacheEntry {
        private final Object value;
        private final long ttl;
        private final long createdTime;

        public CacheEntry(Object value, long ttl) {
            this.value = value;
            this.ttl = ttl;
            this.createdTime = System.currentTimeMillis();
        }

        public Object getValue() {
            return value;
        }

        public boolean isExpired() {
            return (System.currentTimeMillis() - createdTime) > ttl;
        }
    }

    public void shutdown() {
        scheduler.shutdown();
    }
}
