#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct Record {
    int key;
    long offset;
    pthread_mutex_t lock; // For thread safety
} Record;

Record* create_record(int key) {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (rec == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    rec->key = key;
    rec->offset = rand();
    pthread_mutex_init(&rec->lock, NULL);
    return rec;
}

void destroy_record(Record* rec) {
    pthread_mutex_destroy(&rec->lock);
    free(rec);
}

int hash_function(int key) {
    // Simple hash function for demonstration
    return abs(key % MAX_KEYS);
}

void manage_memory_and_initialize_arrays() {
    Record* records[MAX_KEYS] = {NULL};
    int keys[] = {1, 2048, 4096}; // Example keys to demonstrate

    for (int i = 0; i < sizeof(keys) / sizeof(keys[0]); i++) {
        if (keys[i] >= MAX_KEYS) {
            fprintf(stderr, "Key exceeds maximum allowed\n");
            continue;
        }
        int hash = hash_function(keys[i]);
        Record* rec = records[hash];
        if (rec != NULL && rec->key == keys[i]) {
            fprintf(stderr, "Duplicate key detected\n");
            continue;
        }
        records[hash] = create_record(keys[i]);
    }

    // Simulate cleanup
    for (int i = 0; i < MAX_KEYS; i++) {
        if (records[i] != NULL) {
            destroy_record(records[i]);
        }
    }
}

int main() {
    srand(time(NULL));
    manage_memory_and_initialize_arrays();
    return 0;
}
```

