#define MAX_SESSIONS 1024

typedef struct {
    uint32_t config;
} session;

unsigned long *id_array;
uint32_t *session_id_array;
session *session_struct_array;
int used_ids[MAX_SESSIONS];
pthread_mutex_t id_mutex;

void init_session_arrays() {
    id_array = malloc(MAX_SESSIONS * sizeof(unsigned long));
    session_id_array = malloc(MAX_SESSIONS * sizeof(uint32_t));
    session_struct_array = calloc(MAX_SESSIONS, sizeof(session));

    if (id_array == NULL || session_id_array == NULL || session_struct_array == NULL) {
        // Handle allocation failure
        return;
    }

    pthread_mutex_init(&id_mutex, NULL);

    srand(time(NULL)); // Seed for PRNG
}

void generate_unique_session_ids() {
    uint32_t id;
    int i = 0;

    while (i < MAX_SESSIONS) {
        id = rand();
        if (!used_ids[id]) {
            used_ids[id] = 1;
            session_id_array[i] = id;
            i++;
        }
    }
}

void initialize_session_configs() {
    pthread_mutex_lock(&id_mutex);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        uint32_t config;
        do {
            config = rand();
        } while (config == session_struct_array[i].config);
        session_struct_array[i].config = config;
    }
    pthread_mutex_unlock(&id_mutex);
}

void cleanup() {
    free(id_array);
    free(session_id_array);
    free(session_struct_array);
    pthread_mutex_destroy(&id_mutex);
}

void *session_creation_thread(void *arg) {
    uint32_t thread_id = *(uint32_t *)arg;

    generate_unique_session_ids();
    initialize_session_configs();

    return NULL;
}

int main() {
    init_session_arrays();

    pthread_t threads[MAX_SESSIONS];
    uint32_t thread_args[MAX_SESSIONS];

    for (int i = 0; i < MAX_SESSIONS; i++) {
        thread_args[i] = i;
        pthread_create(&threads[i], NULL, session_creation_thread, &thread_args[i]);
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup();

    return 0;
}
