#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    long offset;
    int key;
    uint32_t counter;
} Record;

typedef struct {
    Record* records;
    bool used_keys[MAX_KEYS];
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(MAX_KEYS, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        collection->used_keys[i] = false;
    }

    if (pthread_mutex_init(&collection->lock, NULL) != 0) {
        free(collection->records);
        free(collection);
        return NULL;
    }

    collection->count = 0;
    return collection;
}

bool add_record(RecordCollection* collection, long offset, int key) {
    pthread_mutex_lock(&collection->lock);
    if (key < 0 || key >= MAX_KEYS || collection->used_keys[key]) {
        pthread_mutex_unlock(&collection->lock);
        return false;
    }

    Record* record = &collection->records[key];
    record->offset = offset;
    record->key = key;
    record->counter = 0;
    collection->used_keys[key] = true;
    collection->count++;
    pthread_mutex_unlock(&collection->lock);
    return true;
}

void reset_counters(RecordCollection* collection, size_t interval) {
    if (interval == 0 || collection->count < interval) return;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; i++) {
        collection->records[i].counter = 0;
    }
    pthread_mutex_unlock(&collection->lock);
}

void destroy_record_collection(RecordCollection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}
