pthread_mutex_t used_keys_lock;
unsigned long used_keys[MAX_KEYS];

void initialize() {
    srand(time(0));
    offset_values = (long*)malloc(MAX_KEYS * sizeof(long));
    unique_keys = (int*)malloc(MAX_KEYS * sizeof(int));
    records = (record*)malloc(RECORD_SIZE * sizeof(record));
    pthread_mutex_init(&used_keys_lock, NULL);
    for (int i = 0; i < MAX_KEYS; i++) {
        used_keys[i] = 0;
    }
}

void cleanup() {
    free(offset_values);
    free(unique_keys);
    free(records);
    pthread_mutex_destroy(&used_keys_lock);
}

int generate_unique_key() {
    int key;
    while (1) {
        key = rand() % MAX_KEYS;
        if (pthread_mutex_trylock(&used_keys_lock) == 0) {
            if (used_keys[key] == 0) {
                used_keys[key] = 1;
                pthread_mutex_unlock(&used_keys_lock);
                return key;
            }
            pthread_mutex_unlock(&used_keys_lock);
        }
    }
}

int generate_random_record_value() {
    int value;
    do {
        value = rand() % RECORD_SIZE + 1;
    } while (value == records[value].value);
    records[value].value = value;
    return value;
}

void create_record() {
    int key = generate_unique_key();
    offset_values[key] = key * sizeof(record);
    records[key].value = generate_random_record_value();
}

int main() {
    initialize();
    for (int i = 0; i < 1000; i++) {
        create_record();
    }
    cleanup();
    return 0;
}
