#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define KEY_RANGE 1024

typedef struct {
    long offset;
    int key;
    uint32_t counter;
} record;

typedef struct {
    pthread_mutex_t lock;
    int* used_keys;
    record* records;
} data_store;

data_store* create_data_store() {
    data_store* ds = malloc(sizeof(data_store));
    if (!ds) return NULL;

    ds->used_keys = calloc(KEY_RANGE, sizeof(int));
    if (!ds->used_keys) {
        free(ds);
        return NULL;
    }

    ds->records = malloc(MAX_RECORDS * sizeof(record));
    if (!ds->records) {
        free(ds->used_keys);
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void destroy_data_store(data_store* ds) {
    free(ds->used_keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int add_record(data_store* ds, long offset, int key, uint32_t min_counter, uint32_t max_counter) {
    pthread_mutex_lock(&ds->lock);

    if (key >= KEY_RANGE || ds->used_keys[key]) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (!ds->records[i].key) {
            ds->records[i].offset = offset;
            ds->records[i].key = key;
            ds->records[i].counter = min_counter + rand() % (max_counter - min_counter + 1);
            ds->used_keys[key] = 1;
            pthread_mutex_unlock(&ds->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&ds->lock);
    return -1;
}

void reset_counters(data_store* ds) {
    pthread_mutex_lock(&ds->lock);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        ds->records[i].counter = 0;
    }

    pthread_mutex_unlock(&ds->lock);
}

#ifdef USE_STD_RAND
#include <stdlib.h>
#endif

void simulate_network_latency() {
    struct timespec delay = { .tv_sec = 0, .tv_nsec = 1000 * 1000 }; // 1 millisecond
    nanosleep(&delay, NULL);
}

int main() {
    srand(time(NULL));
    data_store* ds = create_data_store();
    if (!ds) {
        fprintf(stderr, "Failed to create data store\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 15000; ++i) {
        long offset = rand() % 1024 * 1024;
        int key = rand() % KEY_RANGE;

#ifdef USE_STD_RAND
        if ((i % 100 == 0)) simulate_network_latency();
#endif

        if (add_record(ds, offset, key, 100, 500) != 0) {
            fprintf(stderr, "Failed to add record\n");
        }

        if ((i + 1) % 10000 == 0) reset_counters(ds);
    }

    destroy_data_store(ds);
    return EXIT_SUCCESS;
}
```

This code snippet defines a `data_store` structure that contains an array of used keys and records, along with a mutex for thread safety. The `create_data_store` function initializes the data store, `destroy_data_store` cleans up allocated memory, and `add_record` adds a new record to the data store while ensuring uniqueness. The `reset_counters` function resets all counters to zero every 10,000 iterations. The `simulate_network_latency` function introduces simulated network latency to mimic real-world conditions.

The `main` function demonstrates how to use these functions, including adding records with a random offset and key, simulating network latency, and resetting counters periodically. It uses the standard `rand()` function for generating random numbers, but this can be replaced with a more efficient PRNG if needed.']

