#define MAX_SESSIONS 65536

typedef struct {
    long timestamp;
    int session_id;
    uint32_t nonce;
} Session;

Session *session_list[MAX_SESSIONS];
uint16_t used_ids[MAX_SESSIONS] = {0};
int next_session_id = 1;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void regenerate_nonces() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_list[i]) {
            session_list[i]->nonce = random();
        }
    }
}

Session* create_session() {
    Session *new_session;
    pthread_mutex_lock(&session_lock);
    while (used_ids[next_session_id % MAX_SESSIONS] == 1) {
        next_session_id++;
        if (next_session_id >= MAX_SESSIONS) {
            next_session_id = 0;
        }
    }
    used_ids[next_session_id % MAX_SESSIONS] = 1;
    pthread_mutex_unlock(&session_lock);

    new_session = malloc(sizeof(Session));
    if (!new_session) {
        return NULL; // Handle memory allocation failure
    }

    new_session->timestamp = time(NULL);
    new_session->session_id = next_session_id++;
    new_session->nonce = random();

    if (next_session_id % 1000000 == 0) {
        regenerate_nonces();
    }

    pthread_mutex_lock(&session_lock);
    session_list[new_session->session_id] = new_session;
    pthread_mutex_unlock(&session_lock);

    return new_session;
}

void destroy_session(int session_id) {
    pthread_mutex_lock(&session_lock);
    if (session_list[session_id]) {
        free(session_list[session_id]);
        session_list[session_id] = NULL;
        used_ids[session_id % MAX_SESSIONS] = 0;
    }
    pthread_mutex_unlock(&session_lock);
}

void cleanup_sessions() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_list[i]) {
            free(session_list[i]);
        }
    }
}
