#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

#define MAX_KEYS 1024

long *offsets;
int *keys;
record *records;
int num_records = 0;
int used_keys[MAX_KEYS] = {0};
pthread_mutex_t key_lock;

void initialize() {
    offsets = (long *)malloc(MAX_KEYS * sizeof(long));
    keys = (int *)malloc(MAX_KEYS * sizeof(int));
    records = (record *)malloc(MAX_KEYS * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&key_lock, NULL);

    srand(time(NULL));
}

void generate_random_records() {
    for (int i = 0; i < MAX_KEYS; i++) {
        int key;
        do {
            key = rand() % MAX_KEYS;
        } while (used_keys[key]);

        used_keys[key] = 1;

        offsets[i] = (long)key * sizeof(record);
        keys[i] = key;

        records[i].value = rand() % 1001;
    }
}

void* thread_function(void* arg) {
    pthread_mutex_lock(&key_lock);

    if (num_records >= MAX_KEYS) {
        fprintf(stderr, "Maximum number of records reached\n");
        pthread_mutex_unlock(&key_lock);
        return NULL;
    }

    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (used_keys[key]);

    used_keys[key] = 1;

    offsets[num_records] = (long)key * sizeof(record);
    keys[num_records] = key;
    records[num_records].value = rand() % 1001;

    num_records++;

    pthread_mutex_unlock(&key_lock);

    return NULL;
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&key_lock);
}

int main() {
    initialize();
    generate_random_records();

    pthread_t threads[MAX_KEYS];
    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup();

    return 0;
}
