#define MAX_KEYS 1024

typedef struct {
    long offset;
    int key;
} record;

typedef struct hash_entry {
    int key;
    long offset;
    struct hash_entry *next;
} hash_entry;

hash_entry **create_hash_table() {
    return (hash_entry **)calloc(MAX_KEYS, sizeof(hash_entry *));
}

void free_hash_table(hash_entry **table) {
    for (int i = 0; i < MAX_KEYS; i++) {
        hash_entry *entry = table[i];
        while (entry != NULL) {
            hash_entry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(table);
}

unsigned long hash(int key) {
    return ((unsigned long)key * 2654435769) % MAX_KEYS;
}

void insert_into_hash_table(hash_entry **table, int key, long offset) {
    unsigned long index = hash(key);
    hash_entry *entry = table[index];
    if (entry == NULL) {
        entry = (hash_entry *)malloc(sizeof(hash_entry));
        entry->key = key;
        entry->offset = offset;
        entry->next = NULL;
        table[index] = entry;
    } else {
        while (entry->next != NULL) {
            entry = entry->next;
        }
        hash_entry *new_entry = (hash_entry *)malloc(sizeof(hash_entry));
        new_entry->key = key;
        new_entry->offset = offset;
        new_entry->next = NULL;
        entry->next = new_entry;
    }
}

int search_in_hash_table(hash_entry **table, int key) {
    unsigned long index = hash(key);
    hash_entry *entry = table[index];
    while (entry != NULL) {
        if (entry->key == key) {
            return 1;
        }
        entry = entry->next;
    }
    return 0;
}

void generate_random_records(record *records, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        int random_key;
        do {
            random_key = rand() % MAX_KEYS + 1;
        } while (search_in_hash_table(table, random_key));
        records[i].key = random_key;
        records[i].offset = rand();
    }
}

int main() {
    hash_entry **table = create_hash_table();
    record *records = (record *)malloc(100 * sizeof(record)); // Example allocation
    generate_random_records(records, 100);

    for (int i = 0; i < 100; i++) {
        insert_into_hash_table(table, records[i].key, records[i].offset);
    }

    free_hash_table(table);
    free(records);

    return 0;
}
