#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define CONFIG_FILE "config.txt"
#define MAX_KEYS 1024

typedef struct {
    char key[256];
    char value[1024];
    int present;
} ConfigEntry;

ConfigEntry config_table[MAX_KEYS];
int current_keys = 0;

pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void add_config(const char *key, const char *value) {
    pthread_mutex_lock(&config_lock);
    if (current_keys < MAX_KEYS) {
        strcpy(config_table[current_keys].key, key);
        strcpy(config_table[current_keys].value, value);
        config_table[current_keys++].present = 1;
    }
    pthread_mutex_unlock(&config_lock);
}

void set_config(const char *key, const char *value) {
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < current_keys; ++i) {
        if (strcmp(config_table[i].key, key) == 0) {
            strcpy(config_table[i].value, value);
            config_table[i].present = 1;
            break;
        }
    }
    pthread_mutex_unlock(&config_lock);
}

void delete_config(const char *key) {
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < current_keys; ++i) {
        if (strcmp(config_table[i].key, key) == 0) {
            config_table[i].present = 0;
            break;
        }
    }
    pthread_mutex_unlock(&config_lock);
}

const char* get_config(const char *key) {
    for (int i = 0; i < current_keys; ++i) {
        if (strcmp(config_table[i].key, key) == 0 && config_table[i].present) {
            return config_table[i].value;
        }
    }
    return NULL;
}

void save_config_to_file() {
    FILE *file = fopen(CONFIG_FILE, "w");
    for (int i = 0; i < current_keys; ++i) {
        if (config_table[i].present) {
            fprintf(file, "%s=%s\n", config_table[i].key, config_table[i].value);
        }
    }
    fclose(file);
}

void load_config_from_file() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) return;
    char line[2048];
    while (fgets(line, sizeof(line), file)) {
        char key[256], value[1024];
        if (sscanf(line, "%[^=]=%s", key, value) == 2) {
            add_config(key, value);
        }
    }
    fclose(file);
}

int main() {
    load_config_from_file();
    add_config("example_key", "example_value");
    printf("%s\n", get_config("example_key"));
    delete_config("example_key");
    save_config_to_file();
    return 0;
}
