    TransactionSystem* ts = (TransactionSystem*)allocate_memory(sizeof(TransactionSystem), "Transaction System");
    pthread_mutex_init(&ts->lock, NULL);

    ts->ids = (IDLabelPair*)allocate_memory(INITIAL_CAPACITY * sizeof(IDLabelPair), "ID Array");
    ts->transactions = (Transaction*)allocate_memory(INITIAL_CAPACITY * sizeof(Transaction), "Transaction Array");

    ts->capacity = INITIAL_CAPACITY;
    ts->size = 0;

    prng_func = default_prng; // Default PRNG function

    return ts;
}

void expand_transaction_system(TransactionSystem* ts) {
    size_t new_capacity = ts->capacity * 2;
    IDLabelPair* new_ids = (IDLabelPair*)allocate_memory(new_capacity * sizeof(IDLabelPair), "New ID Array");
    Transaction* new_transactions = (Transaction*)allocate_memory(new_capacity * sizeof(Transaction), "New Transaction Array");

    memcpy(new_ids, ts->ids, ts->size * sizeof(IDLabelPair));
    memcpy(new_transactions, ts->transactions, ts->size * sizeof(Transaction));

    free(ts->ids);
    free(ts->transactions);

    ts->ids = new_ids;
    ts->transactions = new_transactions;
    ts->capacity = new_capacity;
}

void add_transaction(TransactionSystem* ts, double amount) {
    pthread_mutex_lock(&ts->lock);

    if (ts->size == ts->capacity) {
        expand_transaction_system(ts);
    }

    Transaction* transaction = &ts->transactions[ts->size];
    transaction->amount = amount;

    prng_func(&transaction->amount); // Generate random amount

    // Ensure unique ID and label
    unsigned long id;
    char label[MAX_LABEL_LENGTH];
    do {
        id = (unsigned long)rand();
        snprintf(label, MAX_LABEL_LENGTH, "TXN-%lu", id);
    } while (id_exists(ts, id)); // Check if ID already exists

    transaction->label[0] = '\0';
    strncpy(transaction->label, label, MAX_LABEL_LENGTH - 1);

    ts->size++;
    pthread_mutex_unlock(&ts->lock);
}

int id_exists(TransactionSystem* ts, unsigned long id) {
    for (size_t i = 0; i < ts->size; ++i) {
        if (ts->ids[i].id == id) {
            return 1;
        }
    }
    return 0;
}

void free_transaction_system(TransactionSystem* ts) {
    pthread_mutex_destroy(&ts->lock);
    free(ts->ids);
    free(ts->transactions);
    free(ts);
}
