    long* offsets;
    int* keys;
    Record* records;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} DataStructure;

DataStructure* create_data_structure(int initial_capacity) {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    ds->offsets = (long*)calloc(initial_capacity, sizeof(long));
    ds->keys = (int*)calloc(initial_capacity, sizeof(int));
    ds->records = (Record*)malloc(initial_capacity * sizeof(Record));
    ds->size = 0;
    ds->capacity = initial_capacity;
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void destroy_data_structure(DataStructure* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

int hash_function(int key) {
    return (key * 31) % MAX_KEYS;
}

int insert_record(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->mutex);
    int index = hash_function(key);
    while (index < ds->capacity && ds->keys[index] != -1) {
        if (ds->keys[index] == key) {
            pthread_mutex_unlock(&ds->mutex);
            return 0; // Key already exists
        }
        index = (index + 1) % ds->capacity;
    }

    if (index >= ds->size) {
        ds->records[ds->size].value = rand() % 1001;
        ds->offsets[index] = sizeof(Record) * ds->size;
        ds->keys[index] = key;
        ds->size++;
        pthread_mutex_unlock(&ds->mutex);
        return 1; // Key inserted successfully
    }

    pthread_mutex_unlock(&ds->mutex);
    return -1; // Failed to insert due to capacity limits
}

// Additional functions for dynamic resizing, configuration changes, and error handling would be implemented here

int main() {
    srand(time(NULL));
    DataStructure* ds = create_data_structure(MAX_RECORDS);

    for (int i = 0; i < MAX_KEYS; i++) {
        insert_record(ds, i);
    }

    destroy_data_structure(ds);
    return 0;
}
