    dm->keys = (int *)calloc(MAX_KEYS, sizeof(int));
    dm->records = (record *)malloc(INITIAL_CAPACITY * sizeof(record));
    if (!dm->offsets || !dm->keys || !dm->records) {
        free(dm->offsets);
        free(dm->keys);
        free(dm->records);
        free(dm);
        return NULL;
    }

    dm->capacity = INITIAL_CAPACITY;
    dm->size = 0;
    pthread_mutex_init(&dm->mutex, NULL);
    for (int i = 0; i < MAX_KEYS; ++i) {
        dm->used_keys[i] = 0;
    }
    dm->seed = seed;

    return dm;
}

