            return;
        }
        dm->records = new_records;
        dm->capacity *= 2;
    }

    int key = generate_unique_key(dm);
    dm->keys[dm->size] = key;
    dm->offsets[key] = dm->size * sizeof(record);
    dm->records[dm->size] = generate_random_record();
    dm->size++;
    pthread_mutex_unlock(&dm->mutex);
