#include <string.h>
#include <time.h>

#define MAX_KEYS 1024
#define TABLE_SIZE 1024

typedef struct record {
    int value;
} Record;

int hash(int key) {
    return key % TABLE_SIZE;
}

int probe(int table[], int key, int &probe_count) {
    int index = hash(key);
    while (table[index] != -1 && table[index] != key) {
        index = (index + 1) % TABLE_SIZE;
        ++probe_count;
    }
    return index;
}

void insert_key(int keys[], int table[], int key, int &used_keys) {
    if (used_keys >= MAX_KEYS) {
        fprintf(stderr, "Error: Maximum number of keys reached.\n");
        exit(EXIT_FAILURE);
    }

    int probe_count = 0;
    int index = probe(table, key, probe_count);

    if (table[index] == -1) {
        table[index] = key;
        keys[used_keys++] = key;
        printf("Inserted %d at index %d with probes: %d\n", key, index, probe_count);
    } else {
        fprintf(stderr, "Error: Key collision detected.\n");
        exit(EXIT_FAILURE);
    }
}

void populate_records(Record records[], int size) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        int value;
        do {
            value = rand() % 1001;
        } while (value == records[i].value);
        records[i].value = value;
    }
}

void allocate_and_initialize(int keys[], Record records[], int &used_keys, int record_size) {
    int table[TABLE_SIZE] = {-1};
    used_keys = 0;

    // Insert unique keys into the hash table
    for (int i = 0; i < MAX_KEYS; ++i) {
        insert_key(keys, table, rand() % 1024, used_keys);
    }

    // Populate records with random integers
    populate_records(records, record_size);

    printf("Allocation and initialization completed successfully.\n");
}

void cleanup(int keys[], Record records[]) {
    free(keys);
    free(records);
    printf("Memory cleaned up.\n");
}

int main() {
    int *keys = (int *)malloc(MAX_KEYS * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        return EXIT_FAILURE;
    }

    Record *records = (Record *)malloc(record_size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(keys);
        return EXIT_FAILURE;
    }

    int used_keys;
    allocate_and_initialize(keys, records, used_keys, record_size);

    // Use the allocated resources here

    cleanup(keys, records);

    return 0;
}
