    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_KEYS; i++) {
        if (records[i] != NULL) {
            free(records[i]);
            records[i] = NULL;
        }
    }
    pthread_mutex_unlock(&mutex);
}

