int* generate_keys(int size, int min_key, int max_key) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL)); // Seed the PRNG
    while (size > 0) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        int found = 0;
        for (int i = 0; i < size - 1; ++i) {
            if (keys[i] == key) {
                found = 1;
                break;
            }
        }
        if (!found) {
            keys[--size] = key;
        }
    }
    return keys;
}

record* generate_records(int size, int min_value, int max_value) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
