void initializeRandomGenerator(unsigned int seed) {
    srand(seed);
}

long generateUniformRandomNumber(long min, long max) {
    return min + rand() % (max - min + 1);
}

float generateNonUniformRandomNumber(float* weights, size_t size) {
    float totalWeight = 0.0f;
    for (size_t i = 0; i < size; ++i) {
        totalWeight += weights[i];
    }

    float randomValue = ((float)rand() / RAND_MAX) * totalWeight;
    float cumulativeWeight = 0.0f;

    for (size_t i = 0; i < size; ++i) {
        cumulativeWeight += weights[i];
        if (randomValue <= cumulativeWeight) {
            return (float)i + (randomValue - cumulativeWeight) / weights[i];
        }
    }

    return (float)size - 1.0f;
}

void updateRandomNumberRange(long newMin, long newMax) {
    // Update the range for the random number generator
}

bool initializeDataStructures(size_t size, long minOffset, long maxOffset,
                              int minValue, int maxValue, float* nonUniformWeights,
                              record** records, long** offsets, int** keys) {
    *records = allocateRecordArray(size);
    *offsets = allocateLongArray(size);
    *keys = allocateIntArray(size);

    if (*records == NULL || *offsets == NULL || *keys == NULL) {
        return false;
    }

    initializeRandomGenerator(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        (*records)[i].value = generateUniformRandomNumber(minValue, maxValue);
        (*records)[i].identifier = (char)(minValue + rand() % (maxValue - minValue + 1));
        (*offsets)[i] = generateUniformRandomNumber(minOffset, maxOffset);

        if (nonUniformWeights != NULL) {
            (*keys)[i] = (int)generateNonUniformRandomNumber(nonUniformWeights, size);
        } else {
            (*keys)[i] = (int)(minValue + rand() % (maxValue - minValue + 1));
        }
    }

    return true;
}

void freeDataStructures(record* records, long* offsets, int* keys) {
    if (records != NULL) {
        free(records);
    }
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
