        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < max_sessions; i++) {
        if ((transactions[i] = (transaction*)malloc(sizeof(transaction))) == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; j++)
                free(transactions[j]);
            free(transactions);
            free(offsets);
            free(ids);
            exit(EXIT_FAILURE);
