        for (int i = 0; i < max_sessions; i++)
            free(transactions[i]);
        free(transactions);
        free(offsets);
        free(ids);
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < max_sessions; i++) {
        if ((metadatas[i] = (metadata*)malloc(sizeof(metadata))) == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j <= i; j++) {
                free(metadatas[j]);
                free(transactions[j]);
            }
            free(transactions);
            free(offsets);
            free(ids);
            exit(EXIT_FAILURE);
        }
        if (!RAND_bytes((unsigned char*)metadatas[i]->metadata, METADATA_LEN)) {
            fprintf(stderr, "Failed to generate random metadata\n");
            for (int j = 0; j <= i; j++) {
                free(metadatas[j]);
                free(transactions[j]);
            }
            free(transactions);
            free(offsets);
            free(ids);
            exit(EXIT_FAILURE);
        }
    }

    // Seed the PRNG with a unique value each time
    srand(time(NULL) ^ getpid());

    // Log initialization completion
    printf("Memory management initialized for %d sessions\n", max_sessions);

    // Function can now be used to populate and manage the structures

    // Free allocated memory when done
    for (int i = 0; i < max_sessions; i++) {
        free(transactions[i]);
        free(metadatas[i]);
    }
    free(transactions);
    free(offsets);
    free(ids);
}

int main() {
    int max_sessions = MAX_SESSIONS;
    long *offsets;
    short *ids;
    transaction **transactions;
    metadata **metadatas;

    manage_memory(max_sessions, offsets, ids, transactions, metadatas);

    return 0;
}
