void initialize_structures(size_t offset_size, size_t key_size, size_t record_size, long range_min, long range_max, time_t timestamp_interval) {
    OffsetStruct *offset_array = malloc(offset_size * sizeof(OffsetStruct));
    KeyStruct *key_array = malloc(key_size * sizeof(KeyStruct));
    RecordStruct *record_array = malloc(record_size * sizeof(RecordStruct));

    // Initialize offset and key arrays
    for (size_t i = 0; i < offset_size; ++i) {
        offset_array[i].offset = range_min + i;
        key_array[i].key = range_min + i;
    }

    // Initialize record array with random integers using LCG
    srand(time(NULL));
    for (size_t i = 0; i < record_size; ++i) {
        long random_value = (rand() % (range_max - range_min + 1)) + range_min;
        record_array[i].value = random_value;
        // Initialize audit log entry with timestamp and sequence number
        record_array[i].audit_log = malloc(sizeof(audit_log_entry));
        record_array[i].audit_log->timestamp = time(NULL);
        record_array[i].audit_log->sequence_number = i + 1;
    }

    // Conflict resolution strategy for keys (pseudo-code)
    int *used_keys = malloc(key_size * sizeof(int));
    memset(used_keys, 0, key_size * sizeof(int));

    for (size_t i = 0; i < record_size; ++i) {
        while (used_keys[key_array[i].key]) {
            // Resolve collision
            key_array[i].key += 1;
        }
        used_keys[key_array[i].key] = 1;
    }

    // Cleanup
    free(offset_array);
    free(key_array);
    for (size_t i = 0; i < record_size; ++i) {
        free(record_array[i].audit_log);
    }
    free(record_array);
    free(used_keys);
}
