import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Random;

public class ResourceAllocator {

    private ConcurrentHashMap<Integer, Long> timestampMap = new ConcurrentHashMap<>();
    private ConcurrentHashMap<Integer, Integer> resourceIDMap = new ConcurrentHashMap<>();
    private ConcurrentHashMap<Integer, Double> priorityMap = new ConcurrentHashMap<>();
    private ConcurrentHashMap<Integer, String> tagMap = new ConcurrentHashMap<>();
    private ConcurrentHashMap<Integer, Boolean> activeFlagMap = new ConcurrentHashMap<>();

    private Random random = new Random();
    private AtomicInteger nextResourceID = new AtomicInteger(0);

    public void allocateResources(int maxResources) {
        for (int i = 0; i < maxResources; i++) {
            int resourceID;
            do {
                resourceID = nextResourceID.incrementAndGet() % 65536;
            } while (!resourceIDMap.tryLock(resourceID));

            long timestamp = System.currentTimeMillis();
            double priority = random.nextDouble() * 9 + 1;

            try {
                timestampMap.putIfAbsent(resourceID, timestamp);
                resourceIDMap.putIfAbsent(resourceID, resourceID);
                priorityMap.putIfAbsent(resourceID, priority);
                tagMap.putIfAbsent(resourceID, "tag" + i);
                activeFlagMap.putIfAbsent(resourceID, true);

                // Log allocation details
                logAllocationDetails(resourceID, timestamp, priority, "Success");

            } catch (Exception e) {
                // Handle allocation failure
                logAllocationDetails(resourceID, timestamp, priority, "Failure");
                resourceIDMap.remove(resourceID);
            } finally {
                resourceIDMap.unlock(resourceID);
            }
        }
    }

    private void logAllocationDetails(int resourceID, long timestamp, double priority, String status) {
        System.out.println("Resource ID: " + resourceID + ", Timestamp: " + timestamp + ", Priority: " + priority + ", Status: " + status);
    }
}
```

