#define MAX_KEYS 1024

typedef struct record {
    int value;
    // Add more fields as needed
} record;

typedef struct {
    long* offset_values;
    int* keys;
    record** records;
    int size;
    pthread_mutex_t lock;
} data_structures;

data_structures* ds = NULL;

void init_data_structures() {
    ds = (data_structures*)malloc(sizeof(data_structures));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    ds->offset_values = (long*)calloc(MAX_KEYS, sizeof(long));
    ds->keys = (int*)calloc(MAX_KEYS, sizeof(int));
    ds->records = (record**)calloc(MAX_KEYS, sizeof(record*));
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);
}

void destroy_data_structures() {
    for (int i = 0; i < ds->size; i++) {
        free(ds->records[i]);
    }
    free(ds->offset_values);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int is_key_used(int key) {
    for (int i = 0; i < ds->size; i++) {
        if (ds->keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

void add_record(int key, int value) {
    pthread_mutex_lock(&ds->lock);
    if (is_key_used(key) || key >= MAX_KEYS) {
        fprintf(stderr, "Invalid or duplicate key\n");
