public class TemporaryDirectoryManager {
    private static final String TEMP_DIR_BASE = "temp_dataset_dir";
    private static final int MAX_DIRS = 100;
    private static final long SIZE_THRESHOLD = 10L * 1024 * 1024 * 1024; // 10GB
    private static final int RETENTION_POLICY = 30; // days

    private Map<String, Long> directoryUsage = new ConcurrentHashMap<>();
    private SecureRandom secureRandom = new SecureRandom();
    private long totalUsedSpace = 0;

    public String createDirectory(long sizeLimit) throws IOException {
        if (directoryUsage.size() >= MAX_DIRS || totalUsedSpace + sizeLimit > SIZE_THRESHOLD) {
            throw new IOException("Max directory limit or storage threshold reached");
        }

        while (true) {
            String dirName = generateUniqueDirName();
            File dir = new File(TEMP_DIR_BASE, dirName);
            if (dir.mkdir()) {
                synchronized (this) {
                    directoryUsage.put(dirName, sizeLimit);
                    totalUsedSpace += sizeLimit;
                }
                return dir.getAbsolutePath();
            }
        }
    }

    private String generateUniqueDirName() {
        byte[] bytes = new byte[16];
        secureRandom.nextBytes(bytes);
        return bytesToHex(bytes);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void deleteDirectory(String dirPath) throws IOException {
        File dir = new File(dirPath);
        if (!dir.isDirectory() || !dir.exists()) {
            throw new IllegalArgumentException("Invalid directory path");
        }

        long size = directoryUsage.remove(dir.getName());
        if (size != null) {
            synchronized (this) {
                totalUsedSpace -= size;
            }
        }

        if (!dir.delete()) {
            throw new IOException("Failed to delete directory");
        }
    }

