#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    time_t lastUpdated;
} record;

long* offsets = NULL;
int* keys = NULL;
record* records = NULL;
int size = 0;
int status = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile = fopen("log.txt", "a");

void init_arrays(int initialSize) {
    offsets = (long*)malloc(initialSize * sizeof(long));
    keys = (int*)malloc(initialSize * sizeof(int));
    records = (record*)malloc(initialSize * sizeof(record));
    if (offsets == NULL || keys == NULL || records == NULL) {
        status = -1;
        fprintf(logFile, "Memory allocation failed\n");
        return;
    }
    size = initialSize;
    for (int i = 0; i < size; i++) {
        offsets[i] = i * sizeof(long);
        keys[i] = rand() % 100;
        records[i].value = rand() % 1000;
        records[i].lastUpdated = time(NULL);
    }
    status = 0;
    fprintf(logFile, "Arrays initialized successfully\n");
}

void update_record(int index, int newValue) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= size) {
        status = -1;
        fprintf(logFile, "Invalid index for record update\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    records[index].value = newValue;
    records[index].lastUpdated = time(NULL);
    status = 0;
    fprintf(logFile, "Record updated successfully at index %d\n", index);
    pthread_mutex_unlock(&mutex);
}

void* thread_function(void* arg) {
    int index = *(int*)arg;
    update_record(index, rand() % 1000);
    free(arg);
    return NULL;
}

void test_performance(int numThreads, int updatesPerThread) {
    pthread_t threads[numThreads];
    for (int i = 0; i < numThreads; i++) {
        int* index = (int*)malloc(sizeof(int));
        *index = rand() % size;
        pthread_create(&threads[i], NULL, thread_function, index);
    }
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void cleanup() {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
    fclose(logFile);
}

int main() {
    srand(time(NULL));
    init_arrays(1000);
    test_performance(10, 100);
    cleanup();
    return 0;
}
