import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.security.SecureRandom;
import java.util.*;
import java.util.concurrent.*;

public class ConcurrentChannelManager {

    private static final SecureRandom RANDOM = new SecureRandom();
    private static final int MAX_KEYS = 1024;
    private static final long TIMEOUT_MILLIS = 5000;

    public void manageChannels(int maxRecords, String[] remoteAddresses) {
        Set<Integer> usedKeys = Collections.newSetFromMap(new ConcurrentHashMap<>());
        Map<Integer, Record> records = new ConcurrentHashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(maxRecords);
        List<Future<?>> futures = new ArrayList<>();

        for (String address : remoteAddresses) {
            futures.add(executor.submit(() -> connectToAddress(address, maxRecords, usedKeys, records)));
        }

        try {
            for (Future<?> future : futures) {
                future.get();
            }
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            System.err.println("Error managing channels: " + e.getMessage());
        } finally {
            executor.shutdownNow();
        }
    }

    private void connectToAddress(String address, int maxRecords, Set<Integer> usedKeys, Map<Integer, Record> records) {
        try (SocketChannel channel = SocketChannel.open()) {
            channel.configureBlocking(true);
            channel.socket().connect(new InetSocketAddress(address, 80), (int) TIMEOUT_MILLIS);

            ByteBuffer buffer = ByteBuffer.allocate(4 * maxRecords);
            for (int i = 0; i < maxRecords; i++) {
                int key;
                do {
                    key = RANDOM.nextInt(MAX_KEYS);
                } while (!usedKeys.add(key));

                Record record = records.computeIfAbsent(i, k -> new Record(RANDOM.nextInt(1000) + 1));
                buffer.putInt(key).putInt(record.value);
            }

            channel.write(buffer);

            // Simulate processing time
            Thread.sleep(100);

        } catch (IOException | InterruptedException e) {
            System.err.println("Error connecting to " + address + ": " + e.getMessage());
        }
    }

    private static class Record {
        final int value;

        Record(int value) {
            this.value = value;
        }
    }

    public static void main(String[] args) {
        ConcurrentChannelManager manager = new ConcurrentChannelManager();
        String[] remoteAddresses = {"192.168.1.1", "192.168.1.2"};
        manager.manageChannels(10, remoteAddresses);
    }
}
```

This code provides a basic structure for managing concurrent connections to remote addresses using Java NIO Channels. It includes error handling, connection attempts with timeouts, and logging of outcomes. The records are stored in a `ConcurrentHashMap` to ensure thread safety during read and write operations. The method dynamically adjusts based on the number of records allowed per channel and uses a secure random generator for unique keys. A fixed thread pool is used to manage multiple connections concurrently.

To fully implement all requirements, additional features such as handling network latency spikes, automatic reconnection upon address changes, integration with distributed caching systems, and detailed logging would need to be added.']

