import java.io.File;
import java.security.SecureRandom;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class TemporaryDirectoryManager {
    private final SecureRandom prng = new SecureRandom();
    private final Map<String, Long> directoryUsage = new ConcurrentHashMap<>();
    private long totalStorageLimit;
    private int maxDirectories;

    public TemporaryDirectoryManager(long totalStorageLimit, int maxDirectories) {
        this.totalStorageLimit = totalStorageLimit;
        this.maxDirectories = maxDirectories;
    }

    public String createDirectory() throws IOException {
        if (directoryUsage.size() >= maxDirectories || getTotalUsedStorage() + 1024 * 1024 > totalStorageLimit) {
            throw new IOException("Cannot create more directories. Storage limit reached.");
        }
        String uniqueName = generateUniqueDirectoryName();
        File directory = new File(uniqueName);
        if (!directory.mkdir()) {
            throw new IOException("Failed to create directory: " + uniqueName);
        }
        directoryUsage.put(uniqueName, 0L);
        return uniqueName;
    }

    public void deleteDirectory(String directoryName) throws IOException {
        long usedStorage = directoryUsage.get(directoryName);
        if (usedStorage != null) {
            directoryUsage.remove(directoryName);
            File directory = new File(directoryName);
            if (!directory.delete()) {
                throw new IOException("Failed to delete directory: " + directoryName);
            }
        } else {
            throw new IOException("Directory not found or already deleted: " + directoryName);
        }
    }

    public void writeToFile(String directoryName, String fileName, byte[] data) throws IOException {
        File file = new File(directoryName, fileName);
        if (!file.getParentFile().exists()) {
            throw new IOException("Parent directory does not exist.");
        }
        try (OutputStream outputStream = new FileOutputStream(file)) {
            outputStream.write(data);
        } catch (IOException e) {
            deleteDirectory(directoryName); // Rollback if write fails
            throw e;
        }
        long usedStorage = directoryUsage.get(directoryName) + data.length;
        directoryUsage.put(directoryName, usedStorage);
    }

    public byte[] readFromFile(String directoryName, String fileName) throws IOException {
        File file = new File(directoryName, fileName);
        if (!file.getParentFile().exists()) {
            throw new IOException("Parent directory does not exist.");
        }
        try (InputStream inputStream = new FileInputStream(file)) {
            return inputStream.readAllBytes();
        } catch (IOException e) {
            deleteDirectory(directoryName); // Rollback if read fails
            throw e;
        }
    }

    public long getTotalUsedStorage() {
        return directoryUsage.values().stream().mapToLong(Long::longValue).sum();
    }

    private String generateUniqueDirectoryName() {
        while (true) {
            String uniqueName = Long.toHexString(prng.nextLong());
            if (!directoryUsage.containsKey(uniqueName)) {
                return uniqueName;
            }
        }
    }
}
```

This code provides a basic implementation of the `TemporaryDirectoryManager` class, which manages temporary directories for storing large datasets in a distributed data processing framework. It includes methods to create and delete directories, write to and read from files within these directories, track storage usage, and generate unique directory names using a cryptographically strong pseudo-random number generator (PRNG). The implementation ensures thread safety and efficient file I/O operations while preventing naming conflicts and managing storage limits.']

