['```java
import java.util.*;

public class TaskManager {
    private final int maxTasks;
    private final List<Integer> usedTaskIds = new ArrayList<>();
    private final long[] timestamps;
    private final int[] taskIds;
    private final float[] priorityLevels;

    public TaskManager(int maxTasks) {
        this.maxTasks = maxTasks;
        timestamps = new long[maxTasks];
        taskIds = new int[maxTasks];
        priorityLevels = new float[maxTasks];
    }

    public synchronized void allocateTask() throws InterruptedException {
        if (usedTaskIds.size() >= maxTasks) {
            throw new IllegalStateException("Maximum number of tasks reached");
        }
        Random random = new Random();
        int taskId;
        while ((taskId = random.nextInt(1024)) <= 0 || usedTaskIds.contains(taskId));
        usedTaskIds.add(taskId);
        timestamps[usedTaskIds.size() - 1] = System.currentTimeMillis();
        priorityLevels[usedTaskIds.size() - 1] = random.nextFloat() * 9 + 1;
    }

    public synchronized void cleanUp() {
        usedTaskIds.clear();
    }

    public static float findMedian(int[] array) {
        Arrays.sort(array);
        int size = array.length;
        if (size % 2 == 0) {
            return (array[size / 2 - 1] + array[size / 2]) / 2.0f;
        } else {
            return array[size / 2];
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        Scanner scanner = new Scanner(System.in);
        int[] inputArray = Arrays.stream(scanner.nextLine().split(" "))
                .mapToInt(Integer::parseInt)
                .toArray();
        float median = findMedian(inputArray);
        System.out.println("Median: " + median);

        TaskManager taskManager = new TaskManager(100);
        for (int i = 0; i < 50; i++) {
            taskManager.allocateTask();
        }
        taskManager.cleanUp();
    }
}
