    pair->offsets = (long*)malloc(size * sizeof(long));
    pair->keys = (int*)malloc(size * sizeof(int));
    pair->size = size;

    if (!pair->offsets || !pair->keys) {
        free(pair);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        pair->offsets[i] = rand();
        pair->keys[i] = rand() % 1024;
    }

    return pair;
}

void freeArrays(ArrayPair* pair) {
    if (pair) {
        free(pair->offsets);
        free(pair->keys);
        free(pair);
    }
}
