import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class SessionTokenManager {

    private static final SecureRandom secureRandom = new SecureRandom();
    private static final ConcurrentHashMap<String, SessionToken> sessionTokens = new ConcurrentHashMap<>();

    public static String generateSessionToken(String userId, long expirationTimeMillis) {
        byte[] tokenBytes = new byte[16];
        secureRandom.nextBytes(tokenBytes);
        String sessionId = bytesToHex(tokenBytes);
        long expiry = System.currentTimeMillis() + expirationTimeMillis;
        sessionTokens.put(sessionId, new SessionToken(userId, expiry));
        return sessionId;
    }

    public static boolean validateSessionToken(String sessionId) {
        SessionToken token = sessionTokens.get(sessionId);
        if (token != null && token.isExpired()) {
            sessionTokens.remove(sessionId);
            return false;
        }
        return true;
    }

    public static void invalidateSessionToken(String sessionId) {
        sessionTokens.remove(sessionId);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    static class SessionToken {
        private final String userId;
        private final long expiry;

        public SessionToken(String userId, long expiry) {
            this.userId = userId;
            this.expiry = expiry;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expiry;
        }
    }

    // Configuration options
    public static int getMaxActiveSessions() {
        // Retrieve from configuration or default value
        return 10000;
    }

