    bool timestamps_initialized = true;
    for (int i = 0; i < num_events; ++i) {
        events[i].timestamp = time(NULL) + i; // Ensure unique timestamps
        int random_offset = rand() % (MAX_OFFSET - MIN_OFFSET + 1) + MIN_OFFSET;
        for (int j = 0; j < MAX_RECORDS; ++j) {
            events[i].data[j].offset = random_offset;
            events[i].data[j].key = rand();
        }
    }

    *all_timestamps_initialized = timestamps_initialized;
    return events;
}

void free_network_events(network_event *events, int num_events) {
    if (events) {
        free(events);
    }
