use std::collections::{HashSet, VecDeque};
use std::sync::{Arc, Mutex};
use rand::RngCore;
use std::time::{Instant, Duration};
use log::{info, error};

// Define a struct to represent a task
struct Task {
    id: u32,
    priority: u8,
}

impl Task {
    fn new(id: u32, priority: u8) -> Self {
        Task { id, priority }
    }
}

// Function to generate a unique task ID
fn get_unique_task_id(used_ids: &Arc<Mutex<HashSet<u32>>>) -> Option<u32> {
    let mut rng = rand::thread_rng();
    loop {
        let new_id = rng.next_u32() % 1024;
        if used_ids.lock().unwrap().insert(new_id) {
            return Some(new_id);
        }
    }
}

// Function to distribute tasks across worker nodes
fn distribute_tasks(worker_nodes: u32, max_tasks: u32) -> Result<(), String> {
    let task_ids = Arc::new(Mutex::new(HashSet::new()));
    let used_ids = Arc::clone(&task_ids);

    for _ in 0..max_tasks {
        if let Some(id) = get_unique_task_id(&used_ids) {
            let priority = rand::thread_rng().gen_range(1..=10);
            let task = Task::new(id, priority);
            // Simulate task distribution logic here
            info!("Distributed task with ID: {}, Priority: {}", id, priority);
        } else {
            error!("Failed to generate a unique task ID");
            return Err("Failed to distribute tasks".to_string());
        }
    }

    Ok(())
}

fn main() {
    // Initialize logging
    env_logger::init();

    let worker_nodes = 4;
    let max_tasks = 1000;

    match distribute_tasks(worker_nodes, max_tasks) {
        Ok(_) => info!("Task distribution completed successfully"),
        Err(e) => error!("Error during task distribution: {}", e),
    }

    // Example of finding the median in an array
    let numbers = vec![34, 78, 12, 56, 90];
    let median = find_median(&numbers);
    info!("Median value: {}", median);
}

// Helper function to find the median value in a slice
fn find_median(numbers: &[i32]) -> f64 {
    let mut sorted_numbers = numbers.to_vec();
    sorted_numbers.sort_unstable();
    let mid = sorted_numbers.len() / 2;
    if sorted_numbers.len() % 2 == 0 {
        (sorted_numbers[mid - 1] as f64 + sorted_numbers[mid] as f64) / 2.0
    } else {
        sorted_numbers[mid] as f64
    }
}
