#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    long* offset_values;
    int* keys;
    int size;
    pthread_mutex_t lock;
} key_manager;

typedef struct {
    record** records;
    int num_records;
    pthread_mutex_t lock;
} record_manager;

key_manager* km_create() {
    key_manager* km = (key_manager*)malloc(sizeof(key_manager));
    if (km == NULL) return NULL;

    km->offset_values = (long*)malloc(MAX_KEYS * sizeof(long));
    km->keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (km->offset_values == NULL || km->keys == NULL) {
        free(km->offset_values);
        free(km->keys);
        free(km);
        return NULL;
    }

    pthread_mutex_init(&km->lock, NULL);
    km->size = 0;

    return km;
}

int km_insert_key(key_manager* km, int key) {
    pthread_mutex_lock(&km->lock);
    for (int i = 0; i < km->size; ++i) {
        if (km->keys[i] == key) {
            pthread_mutex_unlock(&km->lock);
            return -1; // Key already exists
        }
    }
    km->keys[km->size++] = key;
    pthread_mutex_unlock(&km->lock);
    return 0;
}

record_manager* rm_create(int num_records) {
    record_manager* rm = (record_manager*)malloc(sizeof(record_manager));
    if (rm == NULL) return NULL;

    rm->records = (record**)malloc(num_records * sizeof(record*));
    if (rm->records == NULL) {
        free(rm);
        return NULL;
    }

    pthread_mutex_init(&rm->lock, NULL);
    rm->num_records = num_records;

    for (int i = 0; i < num_records; ++i) {
        record* r = (record*)malloc(sizeof(record));
        if (r == NULL) {
