            free(rm->records);
            free(rm);
            return NULL;
        }
        rm->records[i] = r;
    }

    return rm;
}

void rm_generate_records(record_manager* rm, key_manager* km) {
    pthread_mutex_lock(&rm->lock);
    for (int i = 0; i < rm->num_records; ++i) {
        while (1) {
            int key = rand() % MAX_KEYS;
            if (km_insert_key(km, key) == 0) break;
        }
        record* r = rm->records[i];
        r->value = rand() % 1001 + 1; // Random value between 1 and 1000
    }
    pthread_mutex_unlock(&rm->lock);
}

void km_free(key_manager* km) {
    free(km->offset_values);
    free(km->keys);
    pthread_mutex_destroy(&km->lock);
    free(km);
}

void rm_free(record_manager* rm) {
    for (int i = 0; i < rm->num_records; ++i) free(rm->records[i]);
    free(rm->records);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}
