#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    pthread_mutex_t key_mutex;
    int used_keys[MAX_KEYS];
    int next_unused_key_index;
} key_manager;

typedef struct {
    record** records;
    pthread_mutex_t record_mutex;
    int allocated_records;
    int used_records;
} data_storage;

// Function to initialize key manager
void init_key_manager(key_manager* km) {
    km->offsets = malloc(sizeof(long) * MAX_KEYS);
    km->keys = malloc(sizeof(int) * MAX_KEYS);
    pthread_mutex_init(&km->key_mutex, NULL);
    for (int i = 0; i < MAX_KEYS; ++i) {
        km->used_keys[i] = -1;
    }
    km->next_unused_key_index = 0;
}

// Function to initialize data storage
void init_data_storage(data_storage* ds) {
    ds->records = malloc(sizeof(record*) * 1024);
    pthread_mutex_init(&ds->record_mutex, NULL);
    ds->allocated_records = 1024;
    ds->used_records = 0;
}

// Custom PRNG function
int secure_rand() {
    static int initialized = 0;
    if (!initialized) {
        srand(time(NULL));
        initialized = 1;
    }
    return rand();
}

// Function to get a unique key from the manager
int get_key(key_manager* km) {
    pthread_mutex_lock(&km->key_mutex);
    int key;
    do {
        key = secure_rand() % MAX_KEYS;
    } while (km->used_keys[key] != -1);
    km->used_keys[key] = 0; // Mark as used
    pthread_mutex_unlock(&km->key_mutex);
    return key;
}

// Function to allocate a record and initialize it with a random value
void add_record(data_storage* ds, key_manager* km) {
    pthread_mutex_lock(&ds->record_mutex);
    if (ds->used_records == ds->allocated_records) {
        // Resize records array if needed
        ds->records = realloc(ds->records, sizeof(record*) * ds->allocated_records * 2);
        ds->allocated_records *= 2;
    }
    int key = get_key(km);
    ds->records[key] = malloc(sizeof(record));
    ds->records[key]->value = secure_rand();
    ++ds->used_records;
    pthread_mutex_unlock(&ds->record_mutex);
}

// Cleanup function
void cleanup(key_manager* km, data_storage* ds) {
    for (int i = 0; i < MAX_KEYS; ++i) {
        if (km->used_keys[i] != -1) {
            free(km->records[i]);
        }
    }
    free(km->offsets);
    free(km->keys);
    free(ds->records);
}

// Main function to demonstrate the usage
int main() {
    key_manager km;
    data_storage ds;
    init_key_manager(&km);
    init_data_storage(&ds);

    for (int i = 0; i < 100; ++i) {
        add_record(&ds, &km);
    }

    cleanup(&km, &ds);
    return 0;
}
