record records[MAX_KEYS];
int next_key = 0;
pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_key(long *offset) {
    pthread_mutex_lock(&key_lock);
    if (next_key >= MAX_KEYS) {
        pthread_mutex_unlock(&key_lock);
        return -1; // No available keys
    }
    records[next_key].key = next_key + 1;
    records[next_key].offset = *offset;
    *offset = next_key++;
    pthread_mutex_unlock(&key_lock);
    return records[next_key - 1].key;
}

void update_record(int key, long offset) {
    pthread_mutex_lock(&key_lock);
    for (int i = 0; i < next_key; i++) {
        if (records[i].key == key) {
            records[i].offset = offset;
            break;
        }
    }
    pthread_mutex_unlock(&key_lock);
}

int check_key_collision(int key) {
    pthread_mutex_lock(&key_lock);
    for (int i = 0; i < next_key; i++) {
        if (records[i].key == key) {
            pthread_mutex_unlock(&key_lock);
            return 1; // Key collision
        }
    }
    pthread_mutex_unlock(&key_lock);
    return 0;
}

void *initialize_records(void *arg) {
    for (int i = 0; i < MAX_KEYS; i++) {
        records[i].key = 0;
        records[i].offset = rand() % 1024L;
    }
    next_key = 0;
    return NULL;
}

