int initialize_records(OffsetRecord **offsets, KeyRecord **keys, Record **records, int count, int range) {
    if (!RAND_status()) {
        fprintf(stderr, "Error: CSPRNG not initialized.\n");
        return -1;
    }

    *offsets = malloc(count * sizeof(OffsetRecord));
    *keys = malloc(count * sizeof(KeyRecord));
    *records = malloc(count * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (int i = 0; i < count; i++) {
        if (!RAND_bytes((unsigned char *)&(*offsets)[i].offset, sizeof(long))) {
            fprintf(stderr, "Error: Failed to generate random offset.\n");
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
        (*keys)[i].key = i;
        if (!RAND_bytes((unsigned char *)&(*records)[i].value, sizeof(int))) {
            fprintf(stderr, "Error: Failed to generate random record value.\n");
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
        (*records)[i].value %= range; // Ensure the value is within the specified range
    }

    srand(time(NULL)); // Seed for deterministic behavior in non-CSPRNG context

