int customPRNG(int seed) {
    static int state = 0;
    if (seed != -1) state = seed;
    state = (state * 1664525 + 1013904223) & 0xFFFFFFFF;
    return state >> 1; // Return high bits for a reasonable range
}

int initializeRecords(Record **records, int keyRangeStart, int keyRangeEnd, long initialValue) {
    *records = malloc(MAX_RECORDS * sizeof(Record));
    if (*records == NULL) return -1; // Memory allocation failed

    srand(time(NULL)); // Seed the PRNG with current time for better randomness
    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*records)[i].key = customPRNG(keyRangeStart + keyRangeEnd);
        if ((*records)[i].key > keyRangeEnd) (*records)[i].key -= (keyRangeEnd - keyRangeStart + 1);
        (*records)[i].offset = malloc(sizeof(long));
        if ((*records)[i].offset == NULL) {
            free(*records); // Free previously allocated memory on error
            return -2; // Memory allocation failed for offset
        }
        **((*records)[i].offset) = initialValue;
    }

    return 0; // Success
}

void freeRecords(Record *records) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        free(records[i].offset);
    }
    free(records);
}
