int generateRandomNumber(int range, bool performanceSensitive, bool resourceConstrained) {
    if (performanceSensitive && !resourceConstrained) {
        // Fast PRNG for performance-sensitive mode
        return rand() % range;
    } else {
        // Cryptographically strong PRNG for reliability
#ifdef _WIN32
        return CryptoGenRandom(range);
#else
        // Use a cryptographically secure source like /dev/urandom
