#include <openssl/rand.h> // Ensure OpenSSL is installed

#define UNIQUE_ID_SIZE 16
#define MAX_CONCURRENT_REQUESTS 100

typedef struct {
    uint8_t unique_ids[MAX_CONCURRENT_REQUESTS][UNIQUE_ID_SIZE];
    uint32_t next_id_index;
} UniqueIdPool;

void initializeUniqueIdPool(UniqueIdPool *pool) {
    pool->next_id_index = 0;
}

uint8_t* generateUniqueId(UniqueIdPool *pool, time_t timestamp) {
    static uint8_t localComponent[UNIQUE_ID_SIZE];
    if (!RAND_bytes(localComponent, UNIQUE_ID_SIZE)) {
        fprintf(stderr, "Failed to generate random bytes\n");
        return NULL;
    }

    uint8_t *uniqueId = pool->unique_ids[pool->next_id_index];
    memcpy(uniqueId, &timestamp, sizeof(time_t));
    memcpy(uniqueId + sizeof(time_t), localComponent, UNIQUE_ID_SIZE - sizeof(time_t));

    if (pool->next_id_index < MAX_CONCURRENT_REQUESTS) {
        pool->next_id_index++;
    } else {
        fprintf(stderr, "Identifier pool is full\n");
        return NULL;
    }

    return uniqueId;
}

int main() {
    UniqueIdPool pool;
    initializeUniqueIdPool(&pool);

    time_t current_time = time(NULL);
    uint8_t *uniqueId = generateUniqueId(&pool, current_time);

    if (uniqueId != NULL) {
        printf("Generated Unique ID: ");
        for (int i = 0; i < UNIQUE_ID_SIZE; i++) {
            printf("%02x", uniqueId[i]);
        }
        printf("\n");
    }

    return 0;
}
