import java.io.File;
import java.io.IOException;
import java.math.BigInteger;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class TemporaryDirectoryManager {
    private static final SecureRandom PRNG = new SecureRandom();
    private static final ConcurrentHashMap<String, Integer> directoryUsage = new ConcurrentHashMap<>();
    private static final AtomicInteger totalStorageUsed = new AtomicInteger(0);
    private static int maxDirectories;
    private static long threshold;

    public TemporaryDirectoryManager(int maxDirectories, long threshold) {
        this.maxDirectories = maxDirectories;
        this.threshold = threshold;
    }

    public String createDirectory(long maxSize) throws IOException {
        while (true) {
            String directoryName = generateUniqueDirectoryName();
            if (directoryUsage.size() < maxDirectories && totalStorageUsed.get() + maxSize <= threshold) {
                File dir = new File(directoryName);
                if (dir.mkdir()) {
                    directoryUsage.put(directoryName, 0);
                    totalStorageUsed.addAndGet((int) maxSize);
                    return directoryName;
                }
            } else {
                try {
                    Thread.sleep(100); // Wait and retry
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new IOException("Directory creation interrupted", e);
                }
            }
        }
    }

    public void deleteDirectory(String directoryName) throws IOException {
        File dir = new File(directoryName);
        if (dir.isDirectory() && dir.delete()) {
            int usedStorage = directoryUsage.remove(directoryName);
            totalStorageUsed.addAndGet(-usedStorage);
        } else {
            throw new IOException("Failed to delete directory: " + directoryName);
        }
    }

    public void updateDirectorySize(String directoryName, long newSize) throws IOException {
        Integer currentUsage = directoryUsage.get(directoryName);
        if (currentUsage != null && totalStorageUsed.addAndGet((int) newSize - currentUsage) > threshold) {
            throw new IOException("Exceeded storage threshold");
        }
        directoryUsage.put(directoryName, (int) newSize);
    }

    private String generateUniqueDirectoryName() {
        byte[] bytes = new byte[16];
        PRNG.nextBytes(bytes);
        return "dir-" + new BigInteger(1, bytes).toString(32);
    }

    // Additional methods for monitoring, logging, and error handling can be implemented here
}
