import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;
import java.util.concurrent.*;
import java.nio.channels.*;
import java.security.SecureRandom;

public class RecordProcessor {

    private static final int MAX_KEYS = 1024;
    private static final SecureRandom random = new SecureRandom();
    private static final Set<Integer> usedKeys = Collections.synchronizedSet(new HashSet<>());
    private static final Map<String, String> cache = new ConcurrentHashMap<>();
    private static int maxRecords;

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Please provide the maximum number of records.");
            return;
        }
        maxRecords = Integer.parseInt(args[0]);

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            while ((line = reader.readLine()) != null && usedKeys.size() < maxRecords) {
                int recordValue = Integer.parseInt(line);
                if (!usedKeys.contains(recordValue)) {
                    usedKeys.add(recordValue);
                    // Process the record
                    System.out.println("Processed record: " + recordValue);
                } else {
                    System.out.println("Duplicate key encountered.");
                }
            }

            if (usedKeys.isEmpty()) {
                System.out.println("No records processed. Exiting.");
                return;
            }

            int largestRecord = findLargestRecord(usedKeys);
            System.out.println("The largest record is: " + largestRecord);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static int findLargestRecord(Set<Integer> records) {
        if (records.isEmpty()) return Integer.MIN_VALUE;
        return Collections.max(records);
    }
}
