#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_INDEXES 10000

typedef struct {
    double value;
} Measurement;

long *seed_values;
int *indices;
double *random_numbers;
Measurement *measurements;

unsigned int hash_function(int key) {
    return (unsigned int)(key * 2654435769U);
}

void insert_hash_table(int index, pthread_mutex_t *mutex) {
    unsigned int hash = hash_function(index);
    pthread_mutex_lock(mutex);
    // Assuming a simple linear probing for simplicity
    while (indices[hash] != -1 && indices[hash] != index) {
        hash = (hash + 1) % MAX_INDEXES;
    }
    indices[hash] = index;
    pthread_mutex_unlock(mutex);
}

int get_unique_index(pthread_mutex_t *mutex) {
    int index;
    do {
        srand(time(NULL));
        index = rand() % MAX_INDEXES;
    } while (indices[index] != -1);
    return index;
}

void initialize_arrays(int count, pthread_mutex_t *mutex) {
    seed_values = malloc(sizeof(long) * count);
    indices = malloc(sizeof(int) * count);
    random_numbers = malloc(sizeof(double) * count);
    measurements = malloc(sizeof(Measurement) * count);

    for (int i = 0; i < count; ++i) {
        seed_values[i] = rand();
        indices[i] = -1;
        random_numbers[i] = ((double)rand() / RAND_MAX);
        Measurement m = {random_numbers[i]};
        measurements[i] = m;

        insert_hash_table(indices[i], mutex);
    }
}

void clean_up(int count, pthread_mutex_t *mutex) {
    free(seed_values);
    free(indices);
    free(random_numbers);
    free(measurements);
    // Clean up hash table
    for (int i = 0; i < MAX_INDEXES; ++i) {
        if (indices[i] != -1) {
            pthread_mutex_lock(mutex);
            indices[i] = -1;
            pthread_mutex_unlock(mutex);
        }
    }
}

void find_min_max(double *array, int size, double *min, double *max) {
    if (size <= 0) return;

    *min = array[0];
    *max = array[0];

    for (int i = 1; i < size; ++i) {
        if (array[i] < *min) *min = array[i];
        if (array[i] > *max) *max = array[i];
    }
}

void read_input_and_find_min_max() {
    double input[MAX_INDEXES];
    int count;

    printf("Enter a list of doubles separated by spaces: ");
    for (count = 0; scanf("%lf", &input[count]) != EOF && count < MAX_INDEXES; ++count);

    double min, max;
    find_min_max(input, count, &min, &max);

