#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

int* offsets;
int* keys;
record* records;
int num_keys = 0;
pthread_mutex_t key_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays() {
    offsets = (int*)malloc(MAX_KEYS * sizeof(int));
    keys = (int*)calloc(MAX_KEYS, sizeof(int));
    records = (record*)malloc(MAX_KEYS * sizeof(record));
}

void add_key(int new_key) {
    pthread_mutex_lock(&key_mutex);
    for (int i = 0; i < num_keys; i++) {
        if (keys[i] == new_key) return;
    }
    keys[num_keys++] = new_key;
    pthread_mutex_unlock(&key_mutex);
}

void remove_key(int key_to_remove) {
    pthread_mutex_lock(&key_mutex);
    for (int i = 0; i < num_keys; i++) {
        if (keys[i] == key_to_remove) {
            keys[i] = keys[--num_keys];
            break;
        }
    }
    pthread_mutex_unlock(&key_mutex);
}

record* create_record() {
    record* new_record = &records[num_keys++];
    new_record->value = rand() % 1001;
    return new_record;
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
}

void* worker_thread(void* arg) {
    int key = *(int*)arg;
    remove_key(key);
    pthread_exit(NULL);
}

void test_functionality() {
    initialize_arrays();
    srand(time(NULL));

    for (int i = 0; i < MAX_KEYS; i++) {
        add_key(rand() % MAX_KEYS);
    }

    record* new_record = create_record();

    pthread_t thread;
    int key_to_remove = keys[rand() % num_keys];
    pthread_create(&thread, NULL, worker_thread, &key_to_remove);
    pthread_join(thread, NULL);

    cleanup();
}
