#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define TABLE_SIZE 1024

typedef struct Record {
    int value;
    int key;
    long offset;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    int size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    table->size = size;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; ++i) {
        Node* current = table->buckets[i];
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

void insert_record(HashTable* table, Record record) {
    int hash = abs(record.key) % table->size;
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    pthread_mutex_lock(&table->lock);
    new_node->data = record;
    new_node->next = table->buckets[hash];
    table->buckets[hash] = new_node;
    pthread_mutex_unlock(&table->lock);
}

Record* find_record(HashTable* table, int key) {
    int hash = abs(key) % table->size;
    Node* current = table->buckets[hash];

    while (current) {
        if (current->data.key == key) return &current->data;
        current = current->next;
    }
    return NULL;
}

void delete_record(HashTable* table, int key) {
    int hash = abs(key) % table->size;
    Node** current = &table->buckets[hash];

    pthread_mutex_lock(&table->lock);
    while (*current) {
        if ((*current)->data.key == key) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&table->lock);
}

// Pseudo-random number generator function
int fast_rand(int seed, int range) {
    return (seed * 1103515245 + 12345) % range;
}

