#define MAX_TRANSACTION_IDS 1024

typedef struct {
    int value;
} record;

int transaction_ids[MAX_TRANSACTION_IDS];
record* records;
long* timestamps;
int num_transactions;
pthread_mutex_t used_ids_mutex;
pthread_mutex_t id_pool_mutex;

void init() {
    srand(time(NULL));
    for (int i = 0; i < MAX_TRANSACTION_IDS; i++) {
        transaction_ids[i] = 0;
    }
    records = (record*)malloc(sizeof(record) * MAX_TRANSACTION_IDS);
    timestamps = (long*)malloc(sizeof(long) * MAX_TRANSACTION_IDS);
    num_transactions = 0;

    pthread_mutex_init(&used_ids_mutex, NULL);
    pthread_mutex_init(&id_pool_mutex, NULL);

    for (int i = 0; i < MAX_TRANSACTION_IDS; i++) {
        records[i].value = rand() % 1000 + 1;
    }
}

int generate_id() {
    int id;
    do {
        id = rand() % MAX_TRANSACTION_IDS;
    } while (transaction_ids[id] != 0);
    return id;
}

void add_transaction(int value) {
    pthread_mutex_lock(&id_pool_mutex);
    int id = generate_id();
    pthread_mutex_unlock(&id_pool_mutex);

    pthread_mutex_lock(&used_ids_mutex);
    transaction_ids[id] = 1;
    pthread_mutex_unlock(&used_ids_mutex);

    records[id].value = value;
    timestamps[num_transactions++] = time(NULL);
}

void* add_transaction_thread(void* arg) {
    int value = *(int*)arg;
    add_transaction(value);
    free(arg);
    return NULL;
}

double calculate_average() {
    double sum = 0;
    for (int i = 0; i < num_transactions; i++) {
        sum += records[i].value;
    }
    return sum / num_transactions;
}

void cleanup() {
    pthread_mutex_destroy(&used_ids_mutex);
    pthread_mutex_destroy(&id_pool_mutex);
    free(records);
    free(timestamps);
}

int main() {
    int input[100];
    for (int i = 0; i < 100; i++) {
        input[i] = rand() % 1000 + 1;
        pthread_t thread;
        pthread_create(&thread, NULL, add_transaction_thread, &input[i]);
        pthread_join(thread, NULL);
    }

    printf("Average transaction amount: %.2f\n", calculate_average());

    cleanup();
    return 0;
}
