unsigned long fast_prng(unsigned long seed) {
    return (seed * 214013 + 2531011) % ((unsigned long)1 << 31);
}

void* cryptographic_prng(void* arg) {
    unsigned long* seed = (unsigned long*)arg;
    while (1) {
        // Simulate a cryptographic PRNG operation
        *seed = (*seed * 0x5DEECE66D + 0xB) & ((unsigned long)(1L << 48) - 1);
        // Use the seed for something meaningful, like seeding another PRNG or generating random numbers
    }
}

void init_system() {
    pthread_t crypto_thread;
    unsigned long seed = time(NULL);

    // Initialize records with random amounts
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
