    }

    // Initialize used IDs
    for (int i = 0; i < MAX_IDS; i++) {
        used_ids[i] = 0;
    }

    // Start cryptographic PRNG thread
    pthread_create(&crypto_thread, NULL, cryptographic_prng, &seed);
    pthread_detach(crypto_thread);

    // Populate cache with frequently accessed records
    for (int i = 0; i < 100; i++) {
        int id = rand() % MAX_RECORDS;
        cache[i] = records[id]->transaction_amount;
    }
