    if (id >= 0 && id < MAX_IDS && used_ids[id]) {
        // Access record from cache or database
        printf("Accessing record with ID %d, Amount: %d\n", id, cache[id]);
    } else {
        printf("Invalid ID or not used\n");
    }
    return NULL;
}

void cleanup() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i]);
    }
}

