    int ids_to_access[] = {1, 2, 3, 4, 5}; // Example IDs to access
    for (int i = 0; i < sizeof(ids_to_access) / sizeof(int); i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, access_record, &ids_to_access[i]);
        pthread_join(thread, NULL);
    }

    cleanup();
    return 0;
}
