import java.io.File;
import java.io.IOException;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class DirectoryManager {
    private ConcurrentHashMap<String, File> directories = new ConcurrentHashMap<>();
    private long totalStorageLimit;
    private SecureRandom prng = new SecureRandom();

    public DirectoryManager(long totalStorageLimit) {
        this.totalStorageLimit = totalStorageLimit;
    }

    public String createDirectory(String datasetMetadata, int maxSizeBytes) throws IOException {
        // Ensure atomicity for concurrent access
        return directories.computeIfAbsent(generateUniqueName(datasetMetadata), name -> {
            File dir = new File(name);
            if (!dir.mkdir() || !dir.setExecutable(true, false) || !dir.setReadable(true, false) || !dir.setWritable(true, false)) {
                throw new IOException("Failed to create directory: " + name);
            }
            // Monitor and log storage usage
            monitorStorageUsage();
            return dir;
        });
    }

    public void cleanupUnusedDirectories() {
        directories.entrySet().removeIf(entry -> !entry.getValue().exists());
    }

    private String generateUniqueName(String datasetMetadata) {
        byte[] uniqueBytes = new byte[16];
        prng.nextBytes(uniqueBytes);
        // Combine metadata and random bytes to form a unique directory name
        return "dataset_" + datasetMetadata.hashCode() + "_" + java.util.Base64.getEncoder().encodeToString(uniqueBytes);
    }

    private void monitorStorageUsage() {
        long usedSpace = calculateUsedSpace();
        if (usedSpace >= totalStorageLimit) {
            handleDiskSpaceExhaustion(usedSpace);
        }
    }

    private void handleDiskSpaceExhaustion(long usedSpace) {
        // Implement robust error recovery and partial operation rollback strategies
        // Log the issue for troubleshooting and compliance with auditing standards
        System.err.println("Disk space exhausted! Used: " + usedSpace + "/" + totalStorageLimit);
    }

    private long calculateUsedSpace() {
        return directories.values().stream()
                .mapToLong(File::length)
                .sum();
    }
}
