#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

record* records[MAX_KEYS];
int offsets[MAX_KEYS];
int keys[MAX_KEYS];

int used_keys[MAX_KEYS] = {0};
int key_count = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_arrays() {
    srand(time(NULL));
    while (key_count < MAX_KEYS) {
        int key = rand() % MAX_KEYS;
        if (!used_keys[key]) {
            used_keys[key] = 1;
            offsets[key_count] = key * sizeof(record);
            keys[key_count] = key;
            records[key_count++] = malloc(sizeof(record));
        }
    }

    for (int i = 0; i < key_count; i++) {
        records[i]->value = rand() % 1000 + 1;
    }
}

void free_memory() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < key_count; i++) {
        free(records[i]);
    }
    pthread_mutex_unlock(&mutex);
}

double find_median(int* array, int size) {
    if (size % 2 == 0) {
        return (array[size / 2 - 1] + array[size / 2]) / 2.0;
    } else {
        return array[size / 2];
    }
}

void* read_input(void* arg) {
    int size = *(int*)arg;
    int input[size];

    for (int i = 0; i < size; i++) {
        scanf("%d", &input[i]);
    }

    qsort(input, size, sizeof(int), (int (*)(const void *, const void *))compare);

    printf("Median: %f\n", find_median(input, size));

    pthread_exit(NULL);
}

int compare(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    init_arrays();

    int input_size;
    scanf("%d", &input_size);

    pthread_t thread;
    pthread_create(&thread, NULL, read_input, &input_size);

    pthread_join(thread, NULL);

    free_memory();

    return 0;
}
