import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class DistributedTempDirectoryManager {

    private static final SecureRandom RANDOM = new SecureRandom();
    private final ConcurrentHashMap<String, Long> directoryUsage = new ConcurrentHashMap<>();
    private long totalCapacity;
    private int maxDirectories;

    public DistributedTempDirectoryManager(long totalCapacity, int maxDirectories) {
        this.totalCapacity = totalCapacity;
        this.maxDirectories = maxDirectories;
    }

    public Path createDirectory() throws IOException {
        if (directoryUsage.size() >= maxDirectories) {
            throw new IllegalStateException("Maximum number of directories reached.");
        }
        String uniqueName = generateUniqueName();
        Path directoryPath = Paths.get(uniqueName);
        Files.createDirectory(directoryPath);
        long currentCapacity = directoryUsage.putIfAbsent(uniqueName, 0L);
        if (currentCapacity == null) {
            return directoryPath;
        }
        throw new IOException("Failed to create unique directory.");
    }

    public void deleteDirectory(Path directoryPath) throws IOException {
        String directoryName = directoryPath.getFileName().toString();
        Long currentUsage = directoryUsage.remove(directoryName);
        if (currentUsage != null) {
            Files.deleteIfExists(directoryPath);
        }
    }

    public long getDirectorySize(Path directoryPath) {
        return directoryUsage.getOrDefault(directoryPath.toString(), 0L);
    }

    public void setDirectorySize(Path directoryPath, long size) {
        directoryUsage.put(directoryPath.toString(), size);
        checkCapacity();
    }

    private String generateUniqueName() {
        byte[] bytes = new byte[16];
        RANDOM.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    private void checkCapacity() throws IOException {
        long usedCapacity = directoryUsage.values().stream().mapToLong(Long::longValue).sum();
        if (usedCapacity > totalCapacity) {
            throw new IOException("Total capacity exceeded.");
        }
    }
}
