int *keys;
record *records;
int num_records = 0;
pthread_mutex_t key_mutex;
pthread_cond_t key_condition;
int used_keys[MAX_KEYS];
int max_records = 1000;
void (*cache_lookup)(int, void*);
void (*cache_store)(int, void*);

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int generate_unique_key(int *used_keys) {
    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (used_keys[key]);
    used_keys[key] = 1;
    return key;
}

void initialize_offset_array(long **offsets, size_t size) {
    *offsets = malloc(size * sizeof(long));
    if (*offsets == NULL) {
        log_error("Failed to allocate memory for offset array");
        exit(EXIT_FAILURE);
    }
    memset(*offsets, 0, size * sizeof(long));
}

void initialize_key_array(int **keys, int max_records) {
    *keys = malloc(max_records * sizeof(int));
    if (*keys == NULL) {
        log_error("Failed to allocate memory for key array");
        exit(EXIT_FAILURE);
    }
    memset(*keys, 0, max_records * sizeof(int));
}

void initialize_record_array(record **records, int max_records) {
    *records = malloc(max_records * sizeof(record));
    if (*records == NULL) {
        log_error("Failed to allocate memory for record array");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (int i = 0; i < max_records; ++i) {
        do {
            (*records)[i].value = rand() % 1000 + 1;
        } while (find_record(*records, num_records, (*records)[i].value) != -1);
    }
}

void initialize_key_mutex_and_condition_variable(pthread_mutex_t *key_mutex, pthread_cond_t *key_condition) {
    if (pthread_mutex_init(key_mutex, NULL) != 0 || pthread_cond_init(key_condition, NULL) != 0) {
        log_error("Failed to initialize mutex or condition variable");
        exit(EXIT_FAILURE);
    }
}

void clean_up_memory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int find_record(record *records, int count, int value) {
    for (int i = 0; i < count; ++i) {
        if (records[i].value == value) {
            return i;
        }
    }
    return -1;
}

void cache_init(void (*lookup)(int, void*), void (*store)(int, void*)) {
    cache_lookup = lookup;
    cache_store = store;
}

void *key_generator_thread(void *arg) {
    int key;
    while (num_records < max_records) {
        pthread_mutex_lock(&key_mutex);
        while (num_records >= max_records) {
            pthread_cond_wait(&key_condition, &key_mutex);
        }
        key = generate_unique_key(used_keys);
        if (cache_lookup(key, NULL)) {
            records[num_records].value = key;
            cache_store(key, &records[num_records]);
            num_records++;
        }
        pthread_mutex_unlock(&key_mutex);
    }
    return NULL;
}

int main() {
    initialize_offset_array(&offsets, max_records);
    initialize_key_array(&keys, max_records);
    initialize_record_array(&records, max_records);
    initialize_key_mutex_and_condition_variable(&key_mutex, &key_condition);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, key_generator_thread, NULL) != 0) {
        log_error("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    clean_up_memory(offsets, keys, records);
    pthread_mutex_destroy(&key_mutex);
    pthread_cond_destroy(&key_condition);

    return 0;
}
