    int num_records;
    pthread_mutex_t lock;
    int used_keys[MAX_KEYS];
} config_system;

int prng() {
    // Custom PRNG implementation
}

unsigned long generate_session_id() {
    return (unsigned long)prng();
}

int generate_config_key(config_system *sys, int device_id) {
    static int last_key = 0;
    pthread_mutex_lock(&sys->lock);
    while (1) {
        last_key = (last_key + 1) % MAX_KEYS;
        if (!sys->used_keys[last_key]) {
            sys->used_keys[last_key] = 1;
            break;
        }
    }
    pthread_mutex_unlock(&sys->lock);
    return last_key + device_id * MAX_KEYS; // Ensure uniqueness across devices
}

int initialize_config_system(config_system *sys, int device_id) {
    if (pthread_mutex_init(&sys->lock, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        return -1;
    }
    sys->session_id = generate_session_id();
    time_t now = time(NULL);
    if (now == -1) {
        perror("time");
        pthread_mutex_destroy(&sys->lock);
        return -1;
    }
    sys->creation_time = now;
    sys->num_records = 0;

    // Allocate memory for records
    sys->config_data = malloc(MAX_KEYS * sizeof(record));
    if (sys->config_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&sys->lock);
        return -1;
    }

    // Initialize records with random values and unique keys
    for (int i = 0; i < MAX_KEYS; i++) {
        do {
            sys->config_data[i].value = prng() % 1001;
        } while (sys->config_data[i].value <= 0);
        int key = generate_config_key(sys, device_id);
        if (key == -1) {
            free(sys->config_data);
            pthread_mutex_destroy(&sys->lock);
            return -1;
        }
        sys->config_data[i].value = key; // Assign the unique key as the value
    }

    sys->num_records = MAX_KEYS;

    return 0;
}

void cleanup_config_system(config_system *sys) {
    free(sys->config_data);
    pthread_mutex_destroy(&sys->lock);
}
