import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class TempDirManager {
    private static final SecureRandom PRNG = new SecureRandom();
    private static final ConcurrentHashMap<String, Long> DIR_STORAGE_USAGE = new ConcurrentHashMap<>();
    private static long totalStorageLimit = 1024 * 1024 * 1024; // 1GB initial limit
    private static final String TMP_DIR_PREFIX = "tmp_dir_";

    public static Path createTempDir(String datasetId, long sizeLimit) throws IOException {
        if (totalStorageUsage.values().stream().mapToLong(Long::longValue).sum() + sizeLimit > totalStorageLimit) {
            throw new IOException("Insufficient storage capacity.");
        }

        String dirName = TMP_DIR_PREFIX + PRNG.nextLong();
        Path dirPath = Files.createTempDirectory(dirName);
        DIR_STORAGE_USAGE.put(dirName, 0L);

        // Prefetch necessary files and optimize for concurrent access
        prefetchFiles(datasetId, dirPath);

        return dirPath;
    }

    public static void deleteTempDir(String dirName) throws IOException {
        Path dirPath = Paths.get(dirName);
        if (Files.exists(dirPath)) {
            Files.walk(dirPath)
                 .sorted(java.util.Comparator.reverseOrder())
                 .map(Path::toFile)
                 .forEach(File::delete);

            DIR_STORAGE_USAGE.remove(dirName);
        }
    }

    public static void adjustDirSize(String dirName, long newSizeLimit) throws IOException {
        if (!DIR_STORAGE_USAGE.containsKey(dirName)) {
            throw new IllegalArgumentException("Directory not found.");
        }

        if (totalStorageUsage.values().stream().mapToLong(Long::longValue).sum() - DIR_STORAGE_USAGE.get(dirName) + newSizeLimit > totalStorageLimit) {
            throw new IOException("Insufficient storage capacity.");
        }

        // Log the resizing operation
        System.out.println("Resizing directory " + dirName + " to new limit: " + newSizeLimit);
    }

    public static long getDirUsage(String dirName) {
        return DIR_STORAGE_USAGE.getOrDefault(dirName, 0L);
    }

    private static void prefetchFiles(String datasetId, Path dirPath) throws IOException {
        // Implement logic to prefetch necessary files for the dataset
        System.out.println("Prefetching files for dataset " + datasetId + " in directory " + dirPath);
    }
}
```

