#define MAX_KEYS 1024
#define RECORD_COUNT 1000

typedef struct {
    int value;
} record;

long *offsets;
int *keys;
record *records;
int used_keys[MAX_KEYS];
pthread_mutex_t used_key_mutex;

void initialize_arrays() {
    offsets = (long *)malloc(MAX_KEYS * sizeof(long));
    keys = (int *)malloc(MAX_KEYS * sizeof(int));
    records = (record *)malloc(RECORD_COUNT * sizeof(record));

    pthread_mutex_init(&used_key_mutex, NULL);
}

void generate_random_records() {
    srand(time(NULL));
    int values[RECORD_COUNT];
    for (int i = 0; i < RECORD_COUNT; ++i) {
        do {
            values[i] = rand() % 1000 + 1;
        } while (i > 0 && values[i] == values[i - 1]);
    }

    for (int i = 0; i < RECORD_COUNT; ++i) {
        records[i].value = values[i];
    }
}

void *generate_unique_key(void *arg) {
    int key;
    do {
        key = rand() % MAX_KEYS + 1;
        pthread_mutex_lock(&used_key_mutex);
    } while (used_keys[key - 1]);
    used_keys[key - 1] = 1;
    pthread_mutex_unlock(&used_key_mutex);

    // Simulate work with the key
    offsets[key - 1] = key;

    return NULL;
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&used_key_mutex);
}

int main() {
    initialize_arrays();
    generate_random_records();

    pthread_t threads[MAX_KEYS];
    for (int i = 0; i < MAX_KEYS; ++i) {
        pthread_create(&threads[i], NULL, generate_unique_key, NULL);
    }

    for (int i = 0; i < MAX_KEYS; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup();

    return 0;
}
