import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.security.SecureRandom;
import java.util.HashSet;
import java.util.Set;

public class RemoteConnectionHandler {

    private static final int MAX_KEYS = 1024;
    private static final double PRECISION_RANGE = Math.pow(10, 308);
    private static Set<Integer> usedKeys = new HashSet<>();

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int[] intArray = readIntegers(reader);
            double[] doubleArray = readDoubles(reader);

            int maxInteger = findMaxInteger(intArray);
            double maxDouble = findMaxDouble(doubleArray);

            System.out.println("Largest Integer: " + maxInteger);
            System.out.println("Largest Double: " + maxDouble);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void handleConnection(SocketChannel channel, ByteBuffer buffer) throws IOException {
        long[] offsetValues = new long[1024];
        int[] keyValues = new int[MAX_KEYS];
        double[] precisionValues = new double[MAX_KEYS];

        SecureRandom random = new SecureRandom();
        for (int i = 0; i < MAX_KEYS; ) {
            int key;
            do {
                key = random.nextInt(MAX_KEYS);
            } while (!usedKeys.add(key));

            double value = PRECISION_RANGE * (random.nextDouble() - 0.5);

            if (i >= keyValues.length) {
                break;
            }

            keyValues[i] = key;
            precisionValues[i++] = value;

            // Simulate network communication
            buffer.putLong(offsetValues[key]);
            buffer.putInt(key);
            buffer.putDouble(value);
        }

        // Simulate reading from channel
        while (channel.read(buffer) > 0) {
            buffer.flip();
            // Process data received from the channel
            buffer.clear();
        }
    }

    private static int[] readIntegers(BufferedReader reader) throws IOException {
        String[] input = reader.readLine().split(" ");
        int[] result = new int[input.length];
        for (int i = 0; i < input.length; i++) {
            result[i] = Integer.parseInt(input[i]);
        }
        return result;
    }

    private static double[] readDoubles(BufferedReader reader) throws IOException {
        String[] input = reader.readLine().split(" ");
        double[] result = new double[input.length];
        for (int i = 0; i < input.length; i++) {
            result[i] = Double.parseDouble(input[i]);
        }
        return result;
    }

    private static int findMaxInteger(int[] array) {
        if (array == null || array.length == 0) {
            throw new IllegalArgumentException("Array must not be empty");
        }
        int max = array[0];
        for (int value : array) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }

    private static double findMaxDouble(double[] array) {
        if (array == null || array.length == 0) {
            throw new IllegalArgumentException("Array must not be empty");
        }
        double max = array[0];
        for (double value : array) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }

    // Add logging and resource management as needed
}
