#define MAX_KEYS 1024
#define RECORD_COUNT 1000000

typedef struct {
    int value;
} Record;

long* allocate_and_init_offsets(int count) {
    long* offsets = (long*)malloc(count * sizeof(long));
    if (!offsets) return NULL;
    memset(offsets, 0, count * sizeof(long));
    return offsets;
}

int* allocate_and_init_keys(int* used_keys, int max_keys, int count) {
    int* keys = (int*)malloc(count * sizeof(int));
    if (!keys) return NULL;

    for (int i = 0; i < count; ++i) {
        while (1) {
            RAND_bytes((unsigned char*)&keys[i], sizeof(int));
            keys[i] = abs(keys[i]) % max_keys;
            if (!used_keys[keys[i]]) {
                used_keys[keys[i]] = 1;
                break;
            }
        }
    }

    return keys;
}

Record* allocate_and_init_records(int count) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) return NULL;

    for (int i = 0; i < count; ++i) {
        while (1) {
            RAND_bytes((unsigned char*)&records[i].value, sizeof(int));
            records[i].value = abs(records[i].value) % 1001;
            int found_duplicate = 0;
            for (int j = 0; j < i; ++j) {
                if (records[j].value == records[i].value) {
                    found_duplicate = 1;
                    break;
                }
            }
            if (!found_duplicate) break;
        }
    }

    return records;
}

long generate_random_number() {
    long number;
    RAND_bytes((unsigned char*)&number, sizeof(long));
    return abs(number);
}

void clean_up_memory(void* ptr, void (*cleanup_func)(void*)) {
    if (ptr) {
        cleanup_func(ptr);
    }
}

int main() {
    int used_keys[MAX_KEYS] = {0};
    long* offsets = allocate_and_init_offsets(RECORD_COUNT);
    if (!offsets) return -1;

    int* keys = allocate_and_init_keys(used_keys, MAX_KEYS, RECORD_COUNT);
    if (!keys) {
        clean_up_memory(offsets, free);
        return -1;
    }

    Record* records = allocate_and_init_records(RECORD_COUNT);
    if (!records) {
        clean_up_memory(keys, free);
        clean_up_memory(offsets, free);
        return -1;
    }

    // Process the records
    for (int i = 0; i < RECORD_COUNT; ++i) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }

    // Clean up memory
    clean_up_memory(records, free);
    clean_up_memory(keys, free);
    clean_up_memory(offsets, free);

    return 0;
}
