#define RECORD_SIZE sizeof(record)
#define ARRAY_SIZE 1000

typedef struct {
    long offset;
    int key;
    uint32_t counter;
} record;

void initialize_records(record *records, int array_size);
void randomize_counters(record *records, int array_size, uint32_t min_value, uint32_t max_value);
void process_records(record *records, int array_size, unsigned long delay_ms);
void checkpoint_log(const char *log_state, int iteration);
void reset_counters(record *records, int array_size);

int main() {
    record records[ARRAY_SIZE];
    srand(time(NULL)); // Seed for random number generator

    initialize_records(records, ARRAY_SIZE);
    randomize_counters(records, ARRAY_SIZE, 10, 1000);

    for (unsigned long i = 0; i < 100000; ++i) {
        process_records(records, ARRAY_SIZE, 5); // Simulate network latency
        checkpoint_log("Checkpoint", i);
        if (i % 1000 == 0) { // Reset counters every 10,000 iterations
            reset_counters(records, ARRAY_SIZE);
        }
    }

    return 0;
}

void initialize_records(record *records, int array_size) {
    for (int i = 0; i < array_size; ++i) {
        records[i].offset = i * RECORD_SIZE;
        records[i].key = i + 1;
        records[i].counter = 0;
    }
}

void randomize_counters(record *records, int array_size, uint32_t min_value, uint32_t max_value) {
    for (int i = 0; i < array_size; ++i) {
        records[i].counter = (rand() % (max_value - min_value + 1)) + min_value;
    }
}

void process_records(record *records, int array_size, unsigned long delay_ms) {
    for (int i = 0; i < array_size; ++i) {
        // Simulate record processing
        records[i].counter++;
        usleep(delay_ms * 1000); // Delay in microseconds
    }
}

void checkpoint_log(const char *log_state, int iteration) {
    printf("Log State: %s, Iteration: %d\n", log_state, iteration);
}

void reset_counters(record *records, int array_size) {
    for (int i = 0; i < array_size; ++i) {
        records[i].counter = 0;
    }
}
