import java.io.*;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ConcurrentChannelManager {

    private static final int MAX_KEYS = 1024;
    private static final Logger logger = Logger.getLogger(ConcurrentChannelManager.class.getName());

    public static void main(String[] args) throws IOException, InterruptedException {
        // Initialize the manager
        ConcurrentChannelManager manager = new ConcurrentChannelManager();

        // Start processing records from standard input
        manager.processInputRecords();
    }

    private int[] allocateKeys() {
        int[] keys = new int[MAX_KEYS];
        Arrays.fill(keys, -1);
        return keys;
    }

    private long[] allocateOffsets(int numberOfRecords) {
        return new long[numberOfRecords];
    }

    private void processInputRecords() throws IOException, InterruptedException {
        Scanner scanner = new Scanner(System.in);
        List<Integer> inputNumbers = new ArrayList<>();
        while (scanner.hasNextInt()) {
            int number = scanner.nextInt();
            if (number >= 1 && number <= 1000) {
                inputNumbers.add(number);
            } else {
                logger.warning("Invalid integer: " + number);
            }
        }

        int[] keys = allocateKeys();
        long[] offsets = allocateOffsets(inputNumbers.size());

        for (int i = 0; i < inputNumbers.size(); i++) {
            int key = findUniqueKey(keys, MAX_KEYS);
            keys[key] = key;
            offsets[i] = generateRandomOffset();
            processRecord(key, offsets[i], inputNumbers.get(i));
        }

        printLargestNumber(inputNumbers);
    }

    private int findUniqueKey(int[] keys, int maxKeys) {
        Random random = new Random();
        while (true) {
            int key = random.nextInt(maxKeys);
            if (keys[key] == -1) {
                return key;
            }
        }
    }

    private long generateRandomOffset() {
        Random random = new Random();
        return random.nextLong();
    }

    private void processRecord(int key, long offset, int value) throws IOException, InterruptedException {
        // Simulate processing record
        logger.info("Processing record with key: " + key + ", offset: " + offset + ", value: " + value);
        Thread.sleep(100); // Simulate processing time
    }

    private void printLargestNumber(List<Integer> numbers) {
        int max = Collections.max(numbers, Comparator.naturalOrder());
