#include <stdlib.h>
#include <pthread.h>

#define MAX_IDS 1024

typedef struct {
    int amount;
} record;

long* offsets;
int* keys;
record* transactions;
pthread_mutex_t id_lock;
unsigned long next_id;

void init_transaction_system() {
    offsets = (long*)malloc(MAX_IDS * sizeof(long));
    keys = (int*)malloc(MAX_IDS * sizeof(int));
    transactions = (record*)malloc(MAX_IDS * sizeof(record));
    pthread_mutex_init(&id_lock, NULL);
    next_id = 0;
}

unsigned long fast_prng(unsigned long seed) {
    return seed * 1664525 + 1013904223;
}

int get_unique_transaction_id() {
    unsigned long id;
    do {
        pthread_mutex_lock(&id_lock);
        id = next_id++;
        pthread_mutex_unlock(&id_lock);
    } while (keys[id] != 0);
    return id;
}

int process_transaction(int transaction_amount) {
    int id;
    if ((id = get_unique_transaction_id()) >= MAX_IDS) {
        return -1; // Transaction ID out of range
    }
    keys[id] = 1;
    offsets[id] = (long)transactions + id * sizeof(record);
    transactions[id].amount = transaction_amount;
    return id;
}

void cleanup_transaction_system() {
    free(offsets);
    free(keys);
    free(transactions);
    pthread_mutex_destroy(&id_lock);
}
