void* initialize_memory(void* arg) {
    long* offset_array = (long*)malloc(MAX_KEYS * sizeof(long));
    int* key_array = (int*)malloc(MAX_KEYS * sizeof(int));
    record* record_array = (record*)malloc(MAX_RECORDS * sizeof(record));

    if (!offset_array || !key_array || !record_array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit(NULL);
    }

    // Initialize key array with unique keys between 0 and 1023
    for (int i = 0; i < MAX_KEYS; i++) {
        key_array[i] = i;
    }

    // Initialize record array with random values between 1 and 1000
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        int value;
        do {
            value = rand() % 1000 + 1;
        } while (value == record_array[i - 1].value);
        record_array[i].value = value;
    }

    // Initialize offset array with pseudo-random offsets
    unsigned long seed = time(NULL);
    for (int i = 0; i < MAX_KEYS; i++) {
        offset_array[i] = ((seed * i) + 123456789) % 1024;
    }

    pthread_exit(NULL);
}

void find_and_print_largest() {
    int input[MAX_RECORDS];
    int count = 0;

    printf("Enter integers (negative to stop): ");
    while (scanf("%d", &input[count]) == 1 && input[count] >= 0) {
        count++;
    }

    if (count == 0) {
        printf("No valid input.\n");
        return;
    }

    int largest = input[0];
    for (int i = 1; i < count; i++) {
        if (input[i] > largest) {
            largest = input[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_memory, NULL) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Thread join failed\n");
        return EXIT_FAILURE;
    }

    find_and_print_largest();

    return EXIT_SUCCESS;
}
