#define NUM_TRANSACTIONS 1000

typedef struct {
    long* offset_values;
    int* keys;
    unsigned long* transaction_amounts;
    pthread_mutex_t key_mutex;
    pthread_mutex_t id_mutex;
    int used_keys[NUM_TRANSACTIONS];
    int used_ids[NUM_TRANSACTIONS];
} TransactionSystem;

unsigned long fast_prng(unsigned long seed) {
    // Fast, non-cryptographic PRNG algorithm
    return (seed * 1664525 + 1013904223) % UINT_MAX;
}

int init_transaction_system(TransactionSystem* ts, unsigned int range_start, unsigned int range_end) {
    pthread_mutex_init(&ts->key_mutex, NULL);
    pthread_mutex_init(&ts->id_mutex, NULL);

    ts->offset_values = malloc(NUM_TRANSACTIONS * sizeof(long));
    if (!ts->offset_values) return -1;

    ts->keys = malloc(NUM_TRANSACTIONS * sizeof(int));
    if (!ts->keys) {
        free(ts->offset_values);
        return -1;
    }

    ts->transaction_amounts = malloc(NUM_TRANSACTIONS * sizeof(unsigned long));
    if (!ts->transaction_amounts) {
        free(ts->keys);
        free(ts->offset_values);
        return -1;
    }

    unsigned long seed = time(NULL);
    for (int i = 0; i < NUM_TRANSACTIONS; ) {
        unsigned long amount = fast_prng(seed++);
        if (amount >= range_start && amount <= range_end) {
            ts->transaction_amounts[i] = amount;
            pthread_mutex_lock(&ts->id_mutex);
            int id = fast_prng(seed++) % 1024;
            while (ts->used_ids[id]) {
                id = fast_prng(seed++) % 1024;
            }
            ts->used_ids[id] = 1;
            ts->keys[i] = id;
            pthread_mutex_unlock(&ts->id_mutex);
            ts->offset_values[i] = i; // Placeholder for actual offset logic
            i++;
        }
    }

    return 0;
}

void cleanup_transaction_system(TransactionSystem* ts) {
    free(ts->offset_values);
    free(ts->keys);
    free(ts->transaction_amounts);
    pthread_mutex_destroy(&ts->key_mutex);
    pthread_mutex_destroy(&ts->id_mutex);
}

int main() {
    TransactionSystem ts;
    if (init_transaction_system(&ts, 100, 999)) {
        printf("Failed to initialize transaction system\n");
        return 1;
    }

    // Use the transaction system...

    cleanup_transaction_system(&ts);
    return 0;
}
