import java.nio.file.Files;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class DirectoryManager {
    private static final int MAX_DIRS = 10_000;
    private static final SecureRandom PRNG = new SecureRandom();
    private final ConcurrentHashMap<String, Long> directorySizes = new ConcurrentHashMap<>();
    private final AtomicInteger indexGenerator = new AtomicInteger(0);

    public String createDirectory(String prefix, long maxSize) throws IOException {
        while (true) {
            long seed = PRNG.nextLong();
            String dirName = prefix + seed;
            if (!directoryExists(dirName)) {
                Files.createDirectories(new File(dirName).toPath());
                directorySizes.put(dirName, 0L);
                return dirName;
            }
        }
    }

    private boolean directoryExists(String dirName) {
        return new File(dirName).exists();
    }

    public void addDataToDirectory(String dirName, long size) throws IOException {
        long newSize = directorySizes.getOrDefault(dirName, 0L) + size;
        if (newSize > getMaxSizeForDirectory()) {
            throw new IllegalStateException("Directory " + dirName + " exceeds its size limit.");
        }
        directorySizes.put(dirName, newSize);
    }

    public void deleteDirectory(String dirName) throws IOException {
        Files.walk(new File(dirName).toPath()).sorted(java.util.Comparator.reverseOrder())
             .map(java.nio.file.Path::toFile)
             .forEach(File::delete);
        directorySizes.remove(dirName);
    }

    private long getMaxSizeForDirectory() {
        // Implement logic to determine the maximum size for a directory based on usage trends, cluster configuration, etc.
        return 1_073_741_824L; // Example: 1GB
    }

    public void monitorAndLogUsage() {
        // Implement logic to monitor and log the usage of each directory.
    }

