#define MAX_ID 18446744073709551615ULL // 2^64 - 1

typedef struct {
    unsigned long id;
    char buffer[1024];
} Buffer;

unsigned long *id_table = NULL;
Buffer *buffer_pool = NULL;
pthread_mutex_t id_lock, buffer_lock;
int buffer_count = 0;

void init_id_system() {
    id_table = (unsigned long *)malloc(sizeof(unsigned long) * MAX_ID);
    buffer_pool = (Buffer *)malloc(sizeof(Buffer) * 1024); // Assuming a maximum of 1024 buffers
    if (!id_table || !buffer_pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&id_lock, NULL);
    pthread_mutex_init(&buffer_lock, NULL);

    for (unsigned long i = 0; i < MAX_ID; ++i) {
        id_table[i] = 0;
    }
}

void destroy_id_system() {
    free(id_table);
    free(buffer_pool);
    pthread_mutex_destroy(&id_lock);
    pthread_mutex_destroy(&buffer_lock);
}

unsigned long generate_unique_id() {
    unsigned long id;
    while (1) {
        id = rand(); // Using rand for simplicity, use a secure PRNG in production
        pthread_mutex_lock(&id_lock);
        if (!id_table[id]) {
            id_table[id] = 1;
            pthread_mutex_unlock(&id_lock);
            return id;
        }
        pthread_mutex_unlock(&id_lock);
    }
}

void *generate_buffer(void *arg) {
    unsigned long id = generate_unique_id();
    Buffer *buf = &buffer_pool[buffer_count++];
    buf->id = id;
    // Initialize buffer
    buf->buffer[0] = '\0';
    return NULL;
}

void print_longest_string() {
    pthread_mutex_lock(&buffer_lock);
    int max_len = 0;
    for (int i = 0; i < buffer_count; ++i) {
        if (strlen(buffer_pool[i].buffer) > max_len) {
            max_len = strlen(buffer_pool[i].buffer);
            printf("Longest string: %s\n", buffer_pool[i].buffer);
        }
    }
    pthread_mutex_unlock(&buffer_lock);
}

int main() {
    srand(time(NULL));
    init_id_system();

    // Example usage
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, generate_buffer, NULL);
    }
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    print_longest_string();
    destroy_id_system();

    return 0;
}
