#define MAX_KEYS 1024
#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

int key_pool[MAX_KEYS];
int key_count = 0;
pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

Record records[MAX_RECORDS];

void initialize_key_pool() {
    for (int i = 0; i < MAX_KEYS; i++) {
        key_pool[i] = -1;
    }
}

int get_unique_key() {
    int key;
    while (1) {
        if (!RAND_bytes((unsigned char *)&key, sizeof(key))) {
            // Handle error
            return -1;
        }
        key = abs(key) % MAX_KEYS; // Ensure the key is less than 1024 and non-negative
        pthread_mutex_lock(&key_lock);
        if (key_pool[key] == -1) {
            key_pool[key] = 0;
            pthread_mutex_unlock(&key_lock);
            return key;
        }
        pthread_mutex_unlock(&key_lock);
    }
}

void release_key(int key) {
    pthread_mutex_lock(&key_lock);
    key_pool[key] = -1;
    pthread_mutex_unlock(&key_lock);
}

void initialize_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = -1;
    }
}

int get_unique_record_value() {
    int value;
    while (1) {
        if (!RAND_bytes((unsigned char *)&value, sizeof(value))) {
            // Handle error
            return -1;
        }
        value = abs(value) % MAX_RECORDS + 1; // Ensure the value is between 1 and 1000
        int found = 0;
        for (int i = 0; i < MAX_RECORDS; i++) {
            if (records[i].value == value) {
                found = 1;
                break;
            }
        }
        if (!found) {
            return value;
        }
    }
}

void initialize_record(int index, int value) {
    records[index].value = value;
}

// Additional cryptographic utility functions can be implemented here

