    if (key != -1) {
        printf("Unique key: %d\n", key);
        release_key(key);
    }

    int record_value = get_unique_record_value();
    if (record_value != -1) {
        printf("Unique record value: %d\n", record_value);
        initialize_record(0, record_value);
    }

    return 0;
}
