#define MAX_KEYS 2048

int keys[MAX_KEYS];
int key_count = 0;
pthread_mutex_t keys_mutex;

unsigned long get_random_offset() {
    static pthread_mutex_t offset_mutex = PTHREAD_MUTEX_INITIALIZER;
    unsigned long offset;
    pthread_mutex_lock(&offset_mutex);
    srand(time(NULL));
    offset = rand();
    pthread_mutex_unlock(&offset_mutex);
    return offset;
}

float generate_unique_transaction_amount(Transaction transactions[], int transaction_count) {
    float amount;
    do {
        amount = (rand() % 9001) + 100; // Random between 100 and 10000
    } while (transaction_exists(transactions, transaction_count, amount));
    return amount;
}

int key_exists(int keys[], int count, int key) {
    for (int i = 0; i < count; i++) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

void add_key(int *keys, int *count, int key) {
    pthread_mutex_lock(&keys_mutex);
    if (!key_exists(keys, *count, key)) {
        keys[*count] = key;
        (*count)++;
    }
    pthread_mutex_unlock(&keys_mutex);
}

Transaction* create_transactions(int transaction_count) {
    Transaction *transactions = (Transaction*)malloc(transaction_count * sizeof(Transaction));
    if (!transactions) return NULL;

    for (int i = 0; i < transaction_count; i++) {
        transactions[i].amount = generate_unique_transaction_amount(transactions, i);
    }

    return transactions;
}

void destroy_transactions(Transaction *transactions, int transaction_count) {
    free(transactions);
}

void* process_transactions(void *arg) {
    // Simulate processing
    printf("Processing transactions...\n");
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[MAX_KEYS];
    Transaction *transactions = create_transactions(MAX_KEYS);

    if (!transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        add_key(keys, &key_count, i);
        pthread_create(&threads[i], NULL, process_transactions, NULL);
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_transactions(transactions, MAX_KEYS);

    return 0;
}
