import java.security.SecureRandom;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class SessionTokenManager {

    private final ExecutorService executorService;
    private final SecureRandom prng;
    private final Cache<String, String> tokenCache;
    private final AtomicInteger tokenCounter;
    private final int maxTokens;
    private final int loadThreshold;
    private final long expirationTimeMillis;
    private final Logger logger;

    public SessionTokenManager(int corePoolSize, int maximumPoolSize, int maxTokens, int loadThreshold, long expirationTimeMillis) {
        this.executorService = Executors.newCachedThreadPool();
        this.prng = new SecureRandom();
        this.tokenCache = Caffeine.newBuilder()
                .expireAfterWrite(expirationTimeMillis, TimeUnit.MILLISECONDS)
                .maximumSize(maxTokens)
                .build();
        this.tokenCounter = new AtomicInteger(0);
        this.maxTokens = maxTokens;
        this.loadThreshold = loadThreshold;
        this.expirationTimeMillis = expirationTimeMillis;
        this.logger = Logger.getLogger(SessionTokenManager.class.getName());
    }

    public String generateSessionToken() {
        return executorService.submit(() -> {
            lock.lock();
            try {
                if (tokenCounter.get() >= maxTokens) {
                    logger.log(Level.WARNING, "Token exhaustion detected. Rate limiting new requests.");
                    return CompletableFuture.failedFuture(new Exception("Token exhaustion"));
                }
                String token = generateUniqueToken(prng);
                tokenCache.put(token, token);
                tokenCounter.incrementAndGet();
                logger.log(Level.INFO, "Token generated: " + token);
                return CompletableFuture.completedFuture(token);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error generating token", e);
                return CompletableFuture.failedFuture(e);
            } finally {
                lock.unlock();
            }
        }).join();
    }

    private String generateUniqueToken(SecureRandom prng) {
        // Generate a cryptographically strong token
        byte[] bytes = new byte[16];
        prng.nextBytes(bytes);
        return Base64.getEncoder().encodeToString(bytes);
    }

    public void invalidateSessionToken(String token) {
        executorService.submit(() -> {
            lock.lock();
            try {
                if (tokenCache.invalidate(token)) {
                    tokenCounter.decrementAndGet();
                    logger.log(Level.INFO, "Token invalidated: " + token);
                } else {
                    logger.log(Level.WARNING, "Attempt to invalidate non-existent token: " + token);
                }
            } finally {
                lock.unlock();
            }
        }).join();
    }

    public CompletableFuture<String> regenerateSessionToken(String token) {
        return CompletableFuture.supplyAsync(() -> {
            // Implement regeneration logic here
            return generateUniqueToken(prng);
        }, executorService);
    }

    private final Lock lock = new ReentrantLock();

    // Additional methods for handling system dependencies, error handling, etc.
}
```

