    }

    println!("Task distribution complete.");
}

fn calculate_median(numbers: &[i32]) -> f64 {
    let mut sorted_numbers = numbers.to_vec();
    sorted_numbers.sort_unstable();

    let mid = sorted_numbers.len() / 2;
    if sorted_numbers.len() % 2 == 0 {
        (sorted_numbers[mid - 1] as f64 + sorted_numbers[mid] as f64) / 2.0
    } else {
        sorted_numbers[mid] as f64
    }
}

fn generate_unique_task_id(used_task_ids: Arc<Mutex<HashSet<i32>>>) -> Option<i32> {
    let mut rng = rand::thread_rng();
    loop {
        let new_id: i32 = rng.next_u32() as i32 % 1024;
        if !used_task_ids.lock().unwrap().contains(&new_id) {
            return Some(new_id);
        }
    }
}
