import java.io.File;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class TemporaryDirectoryManager {
    private static final int MAX_DIRECTORY_COUNT = 100;
    private static final long TOTAL_SIZE_LIMIT = 10L * 1024L * 1024L * 1024L; // 10 GB
    private static final double RETENTION_POLICY = 0.75;
    private SecureRandom secureRandom = new SecureRandom();
    private ConcurrentHashMap<String, Directory> directories = new ConcurrentHashMap<>();
    private Lock lock = new ReentrantLock();

    public String createDirectory(String prefix) {
        lock.lock();
        try {
            if (directories.size() >= MAX_DIRECTORY_COUNT || getTotalSizeUsage() >= TOTAL_SIZE_LIMIT) {
                throw new IllegalStateException("Cannot create more directories or disk space is exhausted");
            }
            String uniqueName;
            do {
                uniqueName = prefix + secureRandom.nextLong();
            } while (directories.containsKey(uniqueName));
            Directory directory = new Directory(uniqueName, 0);
            directories.put(uniqueName, directory);
            return uniqueName;
        } finally {
            lock.unlock();
        }
    }

    public void deleteDirectory(String name) {
        lock.lock();
        try {
            if (!directories.containsKey(name)) {
                throw new IllegalArgumentException("Directory not found");
            }
            Directory directory = directories.get(name);
            directory.cleanup();
            directories.remove(name);
        } finally {
            lock.unlock();
        }
    }

    private long getTotalSizeUsage() {
        return directories.values().stream()
                         .mapToLong(Directory::getSize)
                         .sum();
    }

    public void prefetchData(String directoryName, String data) {
        Directory directory = directories.get(directoryName);
        if (directory == null) {
            throw new IllegalArgumentException("Directory not found");
        }
        directory.prefetchData(data);
    }

    private class Directory {
        private final String name;
        private long size;
        private Lock lock = new ReentrantLock();

        public Directory(String name, long size) {
            this.name = name;
            this.size = size;
        }

        public void prefetchData(String data) {
            lock.lock();
            try {
                if (size + data.length() > 1024 * 1024 * 1024) { // Limit to 1 GB per directory
                    throw new IllegalStateException("Directory size limit exceeded");
                }
                size += data.length();
            } finally {
                lock.unlock();
            }
        }

        public long getSize() {
            return size;
        }

        public void cleanup() {
            size = 0;
        }
    }

    // Additional methods for monitoring, logging, and configuration management
}
