void* init_pool(void* seed_ptr) {
    unsigned long seed = *(unsigned long*)seed_ptr;
    srand(seed);

    pthread_mutex_init(&pool_lock, NULL);

    for (int i = 0; i < MAX_RECORDS; i++) {
        Record rec;
