        rec.key = i;
        rec.value = rand() % 1000 + 1;
        pool[i] = rec;
        record_count++;
    }

    return NULL;
}

void* print_smallest(int arr[], int size) {
    if (size == 0 || arr[0] < 0) {
        printf("Invalid input or empty array\n");
        return NULL;
    }

    int min = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }

    printf("Smallest integer: %d\n", min);
    return NULL;
}

