import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.security.SecureRandom;
import java.util.HashSet;
import java.util.Set;

public class RemoteServerConnector {

    private static final int MAX_KEYS = 1024;
    private static final SecureRandom SECURE_RANDOM = new SecureRandom();
    private Set<Integer> usedKeys = new HashSet<>();

    public void connectAndProcess(String serverAddress, int port) {
        try (SocketChannel channel = SocketChannel.open(new InetSocketAddress(serverAddress, port));
             Selector selector = Selector.open()) {

            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_CONNECT);

            while (!Thread.currentThread().isInterrupted()) {
                selector.select();
                Set<SelectionKey> selectedKeys = selector.selectedKeys();
                for (SelectionKey key : selectedKeys) {
                    if (key.isConnectable()) {
                        connect(key);
                    }
                }
                selectedKeys.clear();
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void connect(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        try {
            if (channel.finishConnect()) {
                key.interestOps(SelectionKey.OP_READ);
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                while (channel.read(buffer) > 0) {
                    processBuffer(buffer);
                }
                channel.close();
            }
        } catch (IOException e) {
            channel.close();
        }
    }

    private void processBuffer(ByteBuffer buffer) {
        buffer.flip();
        while (buffer.hasRemaining()) {
            int value = buffer.getInt();
            if (value > 0 && value < MAX_KEYS && usedKeys.add(value)) {
                handleValue(value);
            } else {
                System.err.println("Invalid or duplicate key: " + value);
            }
        }
    }

    private void handleValue(int value) {
        // Implement the logic to handle each valid and unique key
    }

    public static void main(String[] args) {
        RemoteServerConnector connector = new RemoteServerConnector();
        connector.connectAndProcess("remote.server.address", 12345);
    }
}
