typedef struct {
    int value;
    char *str;
} record;

record* create_records(long offset_count, int key_count, size_t total_memory_limit) {
    // Calculate memory requirements
    size_t offset_size = offset_count * sizeof(long);
    size_t key_size = key_count * sizeof(int);
    size_t record_size = key_count * sizeof(record);
    size_t str_size = key_count * 256;
    size_t total_size = offset_size + key_size + record_size + str_size;

    if (total_size > total_memory_limit) {
        return NULL; // Memory allocation limit exceeded
    }

    // Allocate memory for arrays and structures
    long *offsets = malloc(offset_size);
    int *keys = malloc(key_size);
    record *records = malloc(record_size);
    char *str_buffer = malloc(str_size);

    if (offsets == NULL || keys == NULL || records == NULL || str_buffer == NULL) {
        free(offsets);
        free(keys);
        free(records);
        free(str_buffer);
        return NULL; // Memory allocation failed
    }

    // Initialize random seed from external data source or use current time as fallback
    if (external_data_source_available()) {
        srand(external_data_source_get_seed());
    } else {
        srand(time(NULL));
    }

    // Initialize arrays and structures with random values
    for (size_t i = 0; i < offset_count; i++) {
        offsets[i] = rand();
    }
    for (size_t i = 0; i < key_count; i++) {
        keys[i] = rand() % 1000 - 500; // Random int between -1000 and 1000
        records[i].value = rand() % 2001 - 1000; // Random int between -1000 and 1000
        records[i].str = str_buffer + i * 256;
    }

    // Initialize string fields with random null-terminated strings
    for (size_t i = 0; i < key_count; i++) {
        for (int j = 0; j < 255; j++) {
            records[i].str[j] = 'a' + rand() % 26; // Random lowercase letter
        }
        records[i].str[255] = '\0'; // Null-terminate string
    }

    // Verify initialization and return pointer to records
    for (size_t i = 0; i < key_count; i++) {
        if (records[i].str == NULL || records[i].str[255] != '\0') {
            free(offsets);
            free(keys);
            free(records);
            free(str_buffer);
            return NULL; // Initialization failed
        }
    }

    return records;
}
