            if (input > 0) {
                storeInteger(input);
            }
        }

        scanner.close();
        printLargestInteger();
    }

    private static void initializeArrays() {
        for (int i = 0; i < MAX_RECORDS; i++) {
            OFFSET_VALUES[i] = PRNG.nextLong();
            KEY_VALUES[i] = generateUniqueKey();
            RECORD_ARRAY[i] = new Record(KEY_VALUES[i]);
        }
    }

    private static int generateUniqueKey() {
        int key;
        do {
            key = PRNG.nextInt(MAX_RECORDS);
        } while (keyRegistry.containsKey(key));
        keyRegistry.put(key, true);
        return key;
    }

    private static void storeInteger(int input) {
        for (Record record : RECORD_ARRAY) {
            if (record.getKey() == input) {
                // Process the record
                break;
            }
        }
    }

    private static void printLargestInteger() {
        int largest = Integer.MIN_VALUE;
        for (int key : KEY_VALUES) {
            if (key > largest) {
                largest = key;
            }
        }
        System.out.println("Largest integer: " + largest);
    }

    private static class Record {
        private final int value;

        public Record(int value) {
            this.value = value;
        }

        public int getKey() {
            return value;
        }
    }

    private interface RandomNumberGenerator {
        long nextLong();
        int.nextInt();
    }

    private static class SecureRandomNumberGenerator implements RandomNumberGenerator {
        private final java.security.SecureRandom secureRandom = new java.security.SecureRandom();

        @Override
        public long nextLong() {
            return secureRandom.nextLong();
        }

        @Override
        public int nextInt(int bound) {
            return secureRandom.nextInt(bound);
        }
    }
