#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <fstream>
#include <random>
#include <chrono>

class DatasetManager {
public:
    DatasetManager(size_t maxDatasets, size_t storageThreshold)
        : maxDatasets(maxDatasets), storageThreshold(storageThreshold), currentStorage(0) {}

    void createDataset(size_t sizeLimit) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return currentStorage + sizeLimit <= storageThreshold && datasets.size() < maxDatasets; });

        // Generate unique identifier using PRNG
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100000);
        int id = dis(gen);

        // Simulate dataset allocation and initialization
        datasets[id] = sizeLimit;
        currentStorage += sizeLimit;

        lock.unlock();
        cv.notify_all();

        std::cout << "Dataset with ID " << id << " created with limit " << sizeLimit << std::endl;
    }

    void cleanupDatasets(size_t retentionPolicy) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = datasets.begin(); it != datasets.end();) {
            if ((std::chrono::steady_clock::now() - it->second.lastAccessTime) > retentionPolicy) {
                currentStorage -= it->first;
                it = datasets.erase(it);
            } else {
                ++it;
            }
        }

        lock.unlock();
        cv.notify_all();

        std::cout << "Datasets cleaned up based on retention policy" << std::endl;
    }

private:
    size_t maxDatasets;
    size_t storageThreshold;
    size_t currentStorage;
    std::mutex mutex;
    std::condition_variable cv;
    std::unordered_map<int, struct DatasetInfo> datasets;

    struct DatasetInfo {
        size_t sizeLimit;
        std::chrono::steady_clock::time_point lastAccessTime;
        // Add other necessary members
    };
};

int main() {
    DatasetManager manager(10, 100000);

    std::thread t1([&manager]() { for (int i = 0; i < 5; ++i) manager.createDataset(20000); });
    std::thread t2([&manager]() { for (int i = 0; i < 3; ++i) manager.cleanupDatasets(std::chrono::seconds(1)); });

    t1.join();
    t2.join();

    return 0;
}
```

