import java.util.Set;

public class RemoteConnectionManager {

    private static final SecureRandom random = new SecureRandom();
    private static final Set<Integer> usedKeys = ConcurrentHashMap.newKeySet();

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int maxItems = Integer.parseInt(reader.readLine());
            long[] offsets = new long[maxItems];
            int[] keys = new int[maxItems];
            float[] weights = new float[maxItems];
            Item[] items = new Item[maxItems];

            generateRandomData(offsets, keys, weights, items);

            for (Item item : items) {
                System.out.println(item);
            }

            String mostFrequentString = findMostFrequentString(items);
            System.out.println("Most frequent string: " + mostFrequentString);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void generateRandomData(long[] offsets, int[] keys, float[] weights, Item[] items) throws Exception {
        Set<Integer> uniqueKeys = new HashSet<>();
        while (uniqueKeys.size() < keys.length) {
            int key = random.nextInt(2048);
            if (uniqueKeys.add(key)) {
                keys[uniqueKeys.size() - 1] = key;
                offsets[uniqueKeys.size() - 1] = random.nextLong();
                weights[uniqueKeys.size() - 1] = random.nextFloat() * 0.9f + 0.1f;
            }
        }

        for (int i = 0; i < items.length; i++) {
            int value = random.nextInt(1000) + 1;
            String name = "Item" + value;
            items[i] = new Item(name, value, weights[uniqueKeys.indexOf(keys[i])]);
        }
    }

    private static String findMostFrequentString(Item[] items) {
        Map<String, Integer> frequencyMap = new HashMap<>();
        for (Item item : items) {
            frequencyMap.put(item.getName(), frequencyMap.getOrDefault(item.getName(), 0) + 1);
        }

        return frequencyMap.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey)
                .orElse("No items");
    }
}

class Item {
    private String name;
    private int value;
    private float weight;

    public Item(String name, int value, float weight) {
        this.name = name;
        this.value = value;
        this.weight = weight;
    }

    @Override
    public String toString() {
        return "Item{" +
                "name='" + name + '\'' +
                ", value=" + value +
                ", weight=" + weight +
                '}';
    }

    public String getName() {
        return name;
    }
}
