typedef struct {
    long timestamp;
    int identifier;
} TransactionRecord;

typedef struct {
    TransactionRecord *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TransactionSet;

void initialize_transaction_set(TransactionSet *set, size_t initial_capacity) {
    set->capacity = initial_capacity;
    set->count = 0;
    set->records = malloc(initial_capacity * sizeof(TransactionRecord));
    if (set->records == NULL) {
        // Handle memory allocation error
        perror("Failed to allocate memory for transaction set");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&set->lock, NULL);
}

void destroy_transaction_set(TransactionSet *set) {
    free(set->records);
    pthread_mutex_destroy(&set->lock);
}

int add_transaction_record(TransactionSet *set, long timestamp, int identifier) {
    pthread_mutex_lock(&set->lock);
    if (set->count >= set->capacity) {
        size_t new_capacity = set->capacity == 0 ? 1 : set->capacity * 2;
        TransactionRecord *new_records = realloc(set->records, new_capacity * sizeof(TransactionRecord));
        if (new_records == NULL) {
            pthread_mutex_unlock(&set->lock);
            // Handle memory allocation error
            perror("Failed to reallocate memory for transaction set");
            exit(EXIT_FAILURE);
        }
        set->records = new_records;
        set->capacity = new_capacity;
    }
    set->records[set->count].timestamp = timestamp;
    set->records[set->count].identifier = identifier;
    set->count++;
    pthread_mutex_unlock(&set->lock);
    return 0;
}

