#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    record keys[MAX_KEYS];
    pthread_mutex_t lock;
} data_stream;

data_stream* create_data_stream() {
    data_stream* ds = malloc(sizeof(data_stream));
    if (!ds) return NULL;

    for (int i = 0; i < MAX_KEYS; i++) {
        ds->keys[i].value = rand(); // Initialize with random value
    }

    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroy_data_stream(data_stream* ds) {
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void update_random_value(data_stream* ds, int key, int min, int max) {
    pthread_mutex_lock(&ds->lock);
    if (key >= 0 && key < MAX_KEYS) {
        ds->keys[key].value = rand() % (max - min + 1) + min;
    }
    pthread_mutex_unlock(&ds->lock);
}

int get_random_value(data_stream* ds, int key) {
    int value;
    pthread_mutex_lock(&ds->lock);
    if (key >= 0 && key < MAX_KEYS) {
        value = ds->keys[key].value;
    } else {
        value = -1; // Error case
    }
    pthread_mutex_unlock(&ds->lock);
    return value;
}

int main() {
    srand(time(NULL)); // Seed the PRNG

    data_stream* ds = create_data_stream();
    if (!ds) {
        fprintf(stderr, "Failed to create data stream\n");
        return 1;
    }

    update_random_value(ds, 0, 100, 200);
    printf("Random value for key 0: %d\n", get_random_value(ds, 0));

    destroy_data_stream(ds);

    return 0;
}
```

