import random
from concurrent.futures import ThreadPoolExecutor
from collections import OrderedDict
from logging.handlers import RotatingFileHandler

class RequestDistributor:
    def __init__(self, server_list, max_cache_size=1000):
        self.servers = server_list
        self.cache = OrderedDict()
        self.executor = ThreadPoolExecutor(max_workers=5)
        self.logger = self.setup_logger()

    def setup_logger(self):
        logger = logging.getLogger('RequestLogger')
        handler = RotatingFileHandler('requests.log', maxBytes=1024*1024, backupCount=3)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        logger.setLevel(logging.INFO)
        return logger

    def assign_priority(self):
        return random.random()

    def distribute_request(self, request_value):
        priority = self.assign_priority()
        if len(self.cache) >= self.max_cache_size:
            self.cache.popitem(last=False)
        self.cache[request_value] = priority
        server_to_assign = min(self.servers, key=lambda s: s.process_load())
        self.executor.submit(server_to_assign.handle_request, request_value, priority)

class WebServer:
    def __init__(self):
        self.load = 0

    def process_load(self):
        return self.load

    def handle_request(self, value, priority):
        # Simulate handling a request
        time.sleep(random.uniform(0.1, 1))
        self.load += 1
        print(f"Server processed {value} with priority {priority}")

class PerformanceMonitor:
    @staticmethod
    def monitor_metrics():
        # Placeholder for monitoring logic
        pass

def main():
    servers = [WebServer() for _ in range(3)]
    distributor = RequestDistributor(servers)

    while True:
        new_request = f"Request-{random.randint(1, 100)}"
        distributor.distribute_request(new_request)

if __name__ == "__main__":
    main()
