typedef struct {
    int value;
} Record;

typedef struct {
    int key;
    Record record;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int used_keys[MAX_KEYS] = {0};

int allocate_key() {
    pthread_mutex_lock(&mutex);
    for (int i = 1; i < MAX_KEYS; i++) {
        if (!used_keys[i]) {
            used_keys[i] = 1;
            pthread_mutex_unlock(&mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&mutex);
    return -1; // No available key
}

void deallocate_key(int key) {
    pthread_mutex_lock(&mutex);
    if (key >= 0 && key < MAX_KEYS && used_keys[key]) {
        used_keys[key] = 0;
    }
    pthread_mutex_unlock(&mutex);
}

Record generate_random_record() {
    Record record;
    record.value = rand() % 1000 + 1; // Random value between 1 and 1000
    return record;
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int rx_ue_info_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.key = allocate_key();
    if (pdu.key == -1) {
        // Handle error: No available key
        exit(EXIT_FAILURE);
    }
    pdu.record = generate_random_record();
    pdu.rx_ue_info_tag = rx_ue_info_tag;
    pdu.rnti = rnti;
    return pdu;
}

void clean_up() {
    pthread_mutex_lock(&mutex);
    for (int i = 1; i < MAX_KEYS; i++) {
        if (used_keys[i]) {
            deallocate_key(i);
        }
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL)); // Seed the PRNG

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(RECORD_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < RECORD_SIZE; i++) {
        pdus[i] = create_pdu(i, rand() % 1024); // Random RNTI
    }

    clean_up();
    free(pdus);

    return 0;
}
