#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

#define INITIAL_CAPACITY 1024
#define MAX_KEYS 4096
#define RECORD_COUNT 1000

long* offsetArray = NULL;
int* keyArray = NULL;
record* recordArray = NULL;
int usedKeys[MAX_KEYS] = {0};
int currentCapacity = INITIAL_CAPACITY;

void expandKeyPool() {
    if (currentCapacity >= MAX_KEYS) {
        fprintf(stderr, "Key pool limit reached.\n");
        exit(1);
    }
    int newCapacity = currentCapacity * 2;
    long* newOffsetArray = realloc(offsetArray, newCapacity * sizeof(long));
    int* newKeyArray = realloc(keyArray, newCapacity * sizeof(int));
    if (!newOffsetArray || !newKeyArray) {
        fprintf(stderr, "Memory reallocation failed.\n");
        exit(1);
    }
    offsetArray = newOffsetArray;
    keyArray = newKeyArray;
    currentCapacity = newCapacity;
}

int generateUniqueKey() {
    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (usedKeys[key]);
    usedKeys[key] = 1;
    return key;
}

void initializeRecordArray() {
    srand(time(0));
    recordArray = malloc(RECORD_COUNT * sizeof(record));
    if (!recordArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    for (int i = 0; i < RECORD_COUNT; ) {
        int value = rand() % 1001;
        int foundDuplicate = 0;
        for (int j = 0; j < i; j++) {
            if (recordArray[j].value == value) {
                foundDuplicate = 1;
                break;
            }
        }
        if (!foundDuplicate) {
            recordArray[i].value = value;
            i++;
        }
    }
}

void populateNFAPIList(int N, NFAPI_CRC_INDICATION_PDU_T* list) {
    srand(time(0));
    for (int i = 0; i < N; i++) {
