import java.security.SecureRandom;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.SecretKeyFactory;
import java.nio.ByteBuffer;
import java.util.concurrent.ConcurrentHashMap;

public class SessionManager {
    private static final SecureRandom RANDOM = new SecureRandom();
    private ConcurrentHashMap<String, Session> sessions = new ConcurrentHashMap<>();
    private int sessionIdLength = 16; // Default session ID length

    public String createSessionId() {
        byte[] bytes = new byte[sessionIdLength];
        RANDOM.nextBytes(bytes);
        return bytesToHex(bytes);
    }

    public Session createSession(String userId) {
        String sessionId = createSessionId();
        while (sessions.containsKey(sessionId)) {
            sessionId = createSessionId(); // Retry if ID collision
        }
        Session session = new Session(userId, sessionId);
        sessions.put(sessionId, session);
        return session;
    }

    public void updateSession(String sessionId, String userId) {
        sessions.computeIfPresent(sessionId, (id, session) -> {
            session.setUserId(userId);
            return session;
        });
    }

    public void invalidateSession(String sessionId) {
        sessions.remove(sessionId);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        SessionManager manager = new SessionManager();
        // Example usage
        String sessionId = manager.createSession("user123");
        System.out.println("Created session ID: " + sessionId);
        manager.updateSession(sessionId, "newUser");
        manager.invalidateSession(sessionId);
    }

    static class Session {
        private String userId;
        private String sessionId;

        public Session(String userId, String sessionId) {
            this.userId = userId;
            this.sessionId = sessionId;
        }

        public void setUserId(String userId) {
            this.userId = userId;
        }

        public String getUserId() {
            return userId;
        }

        public String getSessionId() {
            return sessionId;
        }
    }
}
```

