import java.util.concurrent.ConcurrentHashMap;
import java.security.SecureRandom;

public class WorkspaceManager {
    private static final SecureRandom PRNG = new SecureRandom();
    private static final ConcurrentHashMap<String, Workspace> workspaces = new ConcurrentHashMap<>();
    private static final int MAX_WORKSPACES = 1000;
    private static final double RETENTION_POLICY = 0.9;
    private static long totalMemoryUsage = 0;

    public static String createWorkspace(long memoryLimit) {
        if (workspaces.size() >= MAX_WORKSPACES || totalMemoryUsage + memoryLimit > getTotalMemoryThreshold()) {
            throw new IllegalStateException("Maximum number of workspaces reached or memory limit exceeded");
        }

        String workspaceId = generateUniqueIdentifier();
        Workspace workspace = new Workspace(workspaceId, memoryLimit);
        workspaces.put(workspaceId, workspace);

        return workspaceId;
    }

    public static void deleteWorkspace(String workspaceId) {
        if (workspaces.containsKey(workspaceId)) {
            Workspace workspace = workspaces.get(workspaceId);
            totalMemoryUsage -= workspace.getMemoryUsage();
            workspaces.remove(workspaceId);
        }
    }

    private static String generateUniqueIdentifier() {
        byte[] bytes = new byte[16];
        PRNG.nextBytes(bytes);
        return java.util.UUID.nameUUIDFromBytes(bytes).toString();
    }

    private static long getTotalMemoryThreshold() {
        // Implement logic to get total memory threshold based on cluster configuration
        return Runtime.getRuntime().totalMemory() * RETENTION_POLICY;
    }

    private static class Workspace {
        private final String id;
        private final long memoryLimit;
        private long memoryUsage;

        public Workspace(String id, long memoryLimit) {
            this.id = id;
            this.memoryLimit = memoryLimit;
        }

        public String getId() {
            return id;
        }

        public long getMemoryLimit() {
            return memoryLimit;
        }

        public long getMemoryUsage() {
            return memoryUsage;
        }

        public void setMemoryUsage(long memoryUsage) {
            this.memoryUsage = memoryUsage;
            totalMemoryUsage += memoryUsage;
        }
    }
}
