// Define the structures
typedef struct {
    int value;
    char auditLog[256];
} Record;

typedef struct {
    int key;
    Record *entry;
} LongOffset;

typedef struct {
    LongOffset **table;
    size_t size;
    size_t used;
} KeyTable;

// Custom PRNG function
unsigned long custom_prng(unsigned long seed) {
    return (seed * 1103515245 + 12345) % ULONG_MAX;
}

// Initialize the key table
KeyTable* init_key_table(size_t size) {
    KeyTable *table = (KeyTable*)malloc(sizeof(KeyTable));
    if (!table) return NULL;
    table->size = size;
    table->used = 0;
    table->table = (LongOffset**)calloc(size, sizeof(LongOffset*));
    if (!table->table) {
        free(table);
        return NULL;
    }
    return table;
}

// Insert a new key-value pair into the table
int insert_key(KeyTable *table, int key, Record *entry) {
    size_t index = key % table->size;
    while (table->table[index] != NULL) {
        if (table->table[index]->key == key) return -1; // Collision
        index = (index + 1) % table->size;
    }
    table->table[index] = (LongOffset*)malloc(sizeof(LongOffset));
    if (!table->table[index]) return -2; // Memory allocation failure
    table->table[index]->key = key;
    table->table[index]->entry = entry;
    table->used++;
    return 0;
}

// Free the key table
void free_key_table(KeyTable *table) {
    for (size_t i = 0; i < table->size; i++) {
        if (table->table[i]) {
            free(table->table[i]->entry);
            free(table->table[i]);
        }
    }
    free(table->table);
    free(table);
}

int main() {
    size_t max_sessions = 1000;
    KeyTable *key_table = init_key_table(max_sessions);
    if (!key_table) {
        fprintf(stderr, "Failed to initialize key table\n");
        return 1;
    }

    unsigned long seed = time(NULL);
    for (size_t i = 0; i < max_sessions; i++) {
        Record *entry = (Record*)malloc(sizeof(Record));
        if (!entry) {
            fprintf(stderr, "Failed to allocate record entry\n");
            continue;
        }
        entry->value = custom_prng(seed++);
        snprintf(entry->auditLog, sizeof(entry->auditLog), "Audit log for session %zu", i);
        int result = insert_key(key_table, (int)i, entry);
        if (result == -1) {
            fprintf(stderr, "Key collision at session %zu\n", i);
        } else if (result == -2) {
            fprintf(stderr, "Memory allocation failure for session %zu\n", i);
            free(entry);
        }
    }

    free_key_table(key_table);
    return 0;
}
