    RecordEntry *entries;
    int count;
    pthread_mutex_t lock;
} SessionManager;

SessionManager session_manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_session_manager(int max_sessions) {
    if (max_sessions > MAX_SESSIONS) {
        fprintf(stderr, "Error: Maximum sessions exceeded.\n");
        exit(EXIT_FAILURE);
    }
    session_manager.entries = malloc(max_sessions * sizeof(RecordEntry));
    if (!session_manager.entries) {
        perror("Failed to allocate memory for session manager.");
        exit(EXIT_FAILURE);
    }
    session_manager.count = 0;
}

int generate_unique_key(int min, int max) {
    static unsigned long seed = time(NULL);
    pthread_mutex_lock(&session_manager.lock);
    seed = (seed * 1664525 + 1013904223) % UINT_MAX;
    int key = (int)((double)seed / UINT_MAX * (max - min)) + min;
    pthread_mutex_unlock(&session_manager.lock);
    return key;
}

RecordEntry* create_session_entry(int value, const char* audit_log) {
    RecordEntry *entry = malloc(sizeof(RecordEntry));
    if (!entry) {
        perror("Failed to allocate memory for session entry.");
        return NULL;
    }
    entry->key = generate_unique_key(1, MAX_SESSIONS);
    while (session_manager.count > 0 && session_manager.entries[session_manager.count - 1].key == entry->key) {
        entry->key = generate_unique_key(1, MAX_SESSIONS); // Resolve key collision
    }
    entry->value = value;
    snprintf(entry->audit_log, sizeof(entry->audit_log), "%s", audit_log);
    return entry;
}

void add_session_entry(int value, const char* audit_log) {
    if (session_manager.count >= MAX_SESSIONS) {
        fprintf(stderr, "Error: Maximum sessions reached.\n");
        return;
    }
    RecordEntry *entry = create_session_entry(value, audit_log);
    if (!entry) {
        return;
    }
    session_manager.entries[session_manager.count++] = *entry;
    free(entry); // Entry is copied into the manager
}

void* fetch_public_keys(void* arg) {
    // Simulate fetching public keys from an external API
    // This function can be replaced with actual API calls
    printf("Fetching public keys...\n");
    return NULL;
}

