typedef struct {
    int id;
    time_t timestamp;
    int random_value;
} UserSession;

UserSession* create_user_sessions(int max_records, int *error_code) {
    if (max_records <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    UserSession *sessions = malloc(max_records * sizeof(UserSession));
    if (!sessions) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    int *used_ids = calloc(max_records, sizeof(int));
    if (!used_ids) {
        free(sessions);
        *error_code = -3; // Memory allocation failed
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    srand(time(NULL));

    for (int i = 0; i < max_records; ) {
        int id = rand() % max_records;
        if (!used_ids[id]) {
            used_ids[id] = 1;
            sessions[i].id = id;
            sessions[i].timestamp = time(NULL);
            sessions[i].random_value = rand();
            i++;
        }
    }

    free(used_ids);
    pthread_mutex_destroy(&lock);

    *error_code = 0; // Success
    return sessions;
}

void free_user_sessions(UserSession *sessions, int max_records) {
    if (sessions) {
        free(sessions);
    }
}
