#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define RECORD_SIZE 1000

typedef struct {
    int value;
    pthread_mutex_t lock;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    size_t offset_count;
    size_t key_count;
    pthread_mutex_t lock;
} KeyManager;

typedef struct {
    Record records[RECORD_SIZE];
    pthread_mutex_t lock;
} RecordManager;

typedef struct {
    uint64_t seed;
} PRNGState;

void init_key_manager(KeyManager *km) {
    km->offsets = (long *)malloc(sizeof(long) * MAX_KEYS);
    km->keys = (int *)malloc(sizeof(int) * MAX_KEYS);
    pthread_mutex_init(&km->lock, NULL);
}

void free_key_manager(KeyManager *km) {
    free(km->offsets);
    free(km->keys);
    pthread_mutex_destroy(&km->lock);
}

void init_record_manager(RecordManager *rm) {
    for (int i = 0; i < RECORD_SIZE; i++) {
        pthread_mutex_init(&rm->records[i].lock, NULL);
    }
}

void free_record_manager(RecordManager *rm) {
    for (int i = 0; i < RECORD_SIZE; i++) {
        pthread_mutex_destroy(&rm->records[i].lock);
    }
}

void init_prng_state(PRNGState *state) {
    state->seed = time(NULL);
}

uint64_t xorshift128plus(PRNGState *state) {
    uint64_t x = state->seed;
    x ^= x << 23;
    x ^= x >> 17;
    x ^= x << 5;
    state->seed = x + 0xda6d3b225109a9c0ULL;
    return x;
}

int allocate_key(KeyManager *km, int key) {
    pthread_mutex_lock(&km->lock);
    if (key < 0 || key >= MAX_KEYS) {
        pthread_mutex_unlock(&km->lock);
        return -1;
    }
    if (km->keys[key] != -1) {
        pthread_mutex_unlock(&km->lock);
        return -2; // Key already in use
    }
    km->keys[key] = 1;
    km->offsets[key] = km->offset_count++;
    pthread_mutex_unlock(&km->lock);
    return km->offset_count - 1;
}

void deallocate_key(KeyManager *km, int key) {
    pthread_mutex_lock(&km->lock);
    if (key < 0 || key >= MAX_KEYS) {
        pthread_mutex_unlock(&km->lock);
        return;
    }
    km->keys[key] = -1;
    pthread_mutex_unlock(&km->lock);
}

int allocate_record(RecordManager *rm, int value) {
    pthread_mutex_lock(&rm->lock);
    for (int i = 0; i < RECORD_SIZE; i++) {
        if (pthread_mutex_trylock(&rm->records[i].lock) == 0) {
            if (value >= 1 && value <= 1000) {
                rm->records[i].value = value;
                pthread_mutex_unlock(&rm->lock);
                return i;
            }
            pthread_mutex_unlock(&rm->records[i].lock);
        }
    }
    pthread_mutex_unlock(&rm->lock);
    return -1; // No available record
}

void deallocate_record(RecordManager *rm, int index) {
    pthread_mutex_lock(&rm->lock);
    if (index >= 0 && index < RECORD_SIZE) {
        pthread_mutex_unlock(&rm->records[index].lock);
    }
    pthread_mutex_unlock(&rm->lock);
}

int main() {
    KeyManager km;
    RecordManager rm;
    PRNGState state;

    init_key_manager(&km);
    init_record_manager(&rm);
    init_prng_state(&state);

    // Example usage
    int key = 42;
    int value = 789;

    if (allocate_key(&km, key) == -1) {
        printf("Failed to allocate key %d\n", key);
    } else {
        int record_index = allocate_record(&rm, value);
        if (record_index != -1) {
            printf("Allocated record at index %d with value %d\n", record_index, value);
        } else {
            printf("Failed to allocate record for value %d\n", value);
        }
    }

    deallocate_key(&km, key);
    deallocate_record(&rm, record_index);

    free_key_manager(&km);
    free_record_manager(&rm);

    return 0;
}
```

This code provides a basic framework for managing keys and records with concurrency in mind. It includes initialization, allocation, and deallocation functions for keys and records, as well as a simple PRNG. The code is designed to be compiled and run on a Unix-like system. Note that this code does not include memory pool techniques or RAII principles, which would need to be added for full compliance with the requirements.']

