        sessions[i].uniqueID = (char*)malloc(11 * sizeof(char)); // Assuming max length of uniqueID is 10 characters + null terminator
        if (!sessions[i].uniqueID) {
            fprintf(stderr, "Memory allocation failed for uniqueID.\n");
            for (int j = 0; j < i; ++j) {
                free(sessions[j].uniqueID);
