#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define RECORD_SIZE 1000

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
} array_entry;

array_entry* keys_array = NULL;
record* records_array = NULL;
int records_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int prng_state = 1; // Example PRNG state

long generate_unique_key() {
    pthread_mutex_lock(&mutex);
    do {
        prng_state = (prng_state * 214013 + 2531011) % 2147483647;
        keys_array[prng_state % MAX_KEYS].key = prng_state % MAX_KEYS;
    } while (keys_array[prng_state % MAX_KEYS].offset != -1);
    pthread_mutex_unlock(&mutex);
    return prng_state % MAX_KEYS;
}

int find_or_allocate_record(int value) {
    for (int i = 0; i < records_count; ++i) {
        if (records_array[i].value == value)
            return i;
    }
    if (records_count >= RECORD_SIZE) {
        fprintf(stderr, "Record allocation failed: too many records.\n");
        exit(EXIT_FAILURE);
    }
    records_array[records_count++] = (record){value};
    return records_count - 1;
}

void insert_record(long offset, int value) {
    pthread_mutex_lock(&mutex);
    long key = generate_unique_key();
    keys_array[key].offset = offset;
    keys_array[key].key = key;
    records_array[find_or_allocate_record(value)].value = value;
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    pthread_mutex_destroy(&mutex);
    free(keys_array);
    free(records_array);
}

int main() {
    keys_array = malloc(MAX_KEYS * sizeof(array_entry));
    records_array = malloc(RECORD_SIZE * sizeof(record));
    if (!keys_array || !records_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_KEYS; ++i)
        keys_array[i].offset = -1;

    insert_record(12345L, 42);

    cleanup();

    return 0;
}
```

