#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct record {
    int value;
} Record;

typedef struct hash_table_entry {
    int key;
    long offset;
    struct hash_table_entry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **entries;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->entries = (HashTableEntry**)calloc(TABLE_SIZE, sizeof(HashTableEntry*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        HashTableEntry *entry = table->entries[i];
        while (entry != NULL) {
            HashTableEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(table->entries);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int hash_function(int key) {
    return abs(key % TABLE_SIZE);
}

void insert_into_table(HashTable *table, int key, long offset) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(key);
    HashTableEntry *entry = table->entries[index];
    if (entry == NULL || entry->key != key) {
        HashTableEntry *new_entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
        new_entry->key = key;
        new_entry->offset = offset;
        new_entry->next = entry;
        table->entries[index] = new_entry;
    }
    pthread_mutex_unlock(&table->lock);
}

int find_in_table(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(key);
    HashTableEntry *entry = table->entries[index];
    while (entry != NULL) {
        if (entry->key == key) {
            pthread_mutex_unlock(&table->lock);
            return entry->offset;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->lock);
    return -1;
}

Record* create_records(int num_records) {
    Record *records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    HashTable *hash_table = create_hash_table();
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % 1000 + 1;
        } while (find_in_table(hash_table, value) != -1);

        records[i].value = value;
        insert_into_table(hash_table, value, i);
    }

    destroy_hash_table(hash_table);
    return records;
}

int main() {
    int num_records = 1000;
    Record *records = create_records(num_records);

    // Use the records...

    free(records);
    return 0;
}
```

