    if (!storage) return NULL;

    storage->offsets = (long*)malloc(MAX_KEYS * sizeof(long));
    storage->keys = (int*)malloc(MAX_KEYS * sizeof(int));
    storage->records = (Record*)malloc(MAX_KEYS * sizeof(Record));
    storage->weights = (float*)malloc(MAX_KEYS * sizeof(float));
    storage->flags = (bool*)malloc(MAX_KEYS * sizeof(bool));
    if (!storage->offsets || !storage->keys || !storage->records || !storage->weights || !storage->flags) {
