        storage->offsets[i] = -1;
        storage->keys[i] = -1;
        storage->records[i].value = rand() % 1001;
        storage->weights[i] = ((float)rand()) / RAND_MAX;
        storage->flags[i] = (bool)(rand() & 1);
    }

    return storage;
}

