int create_log_directory_and_records(int num_records, long* offsets, int* keys) {
    char cwd[PATH_MAX];
    if (getcwd(cwd, sizeof(cwd)) == NULL) {
        perror("Failed to get current working directory");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y%m%d%H%M%S", tm_info);

    char dir_name[PATH_MAX];
    snprintf(dir_name, sizeof(dir_name), "log_storage_%s", timestamp);

    if (getenv("LOG_DIR") == NULL) {
        char new_log_dir[PATH_MAX];
        snprintf(new_log_dir, sizeof(new_log_dir), "%s/%s", cwd, dir_name);
        mkdir(new_log_dir, 0755);
        setenv("LOG_DIR", new_log_dir, 1);
    }

    struct statvfs fs_info;
    if (statvfs(getenv("LOG_DIR"), &fs_info) != 0) {
        perror("Failed to get file system information");
        return -1;
    }

    off_t free_space = fs_info.f_bfree * fs_info.f_frsize;
    if (free_space < sizeof(record) * num_records) {
        fprintf(stderr, "Insufficient disk space\n");
        return -1;
    }

    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        perror("Failed to allocate memory");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (MAX_RECORD_VALUE - MIN_RECORD_VALUE + 1) + MIN_RECORD_VALUE;
        records[i].value = keys[i];
    }

    // Clean up
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
