    struct tm *tm_info = localtime(&now);
    char dir_name[256];
    sprintf(dir_name, "%s_%d-%02d-%02d_%02d:%02d:%02d", env_var, 
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);
    *log_dir = strdup(dir_name);
    mkdir(*log_dir, 0755);
}

// Function to initialize arrays and allocate memory
void initialize_arrays(long *offsets, int *keys, Record **records, 
                       size_t offset_size, size_t key_size, int value_range) {
    srand(time(NULL));
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % offset_size;
    }
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = rand() % value_range;
    }
    *records = calloc(key_size, sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
}

