#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int random_value;
    char status[50];
} Record;

typedef struct {
    Record* records;
    size_t size;
    size_t capacity;
} LogArray;

void init_log_array(LogArray* log, size_t initial_capacity) {
    log->records = malloc(initial_capacity * sizeof(Record));
    if (log->records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    log->size = 0;
    log->capacity = initial_capacity;
}

void add_record(LogArray* log, time_t timestamp, int random_value, const char* status) {
    if (log->size >= log->capacity) {
        size_t new_capacity = log->capacity * 2;
        Record* new_records = realloc(log->records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed.\n");
            exit(EXIT_FAILURE);
        }
        log->records = new_records;
        log->capacity = new_capacity;
    }
    log->records[log->size].timestamp = timestamp;
    log->records[log->size].random_value = random_value;
    snprintf(log->records[log->size].status, sizeof(log->records[log->size].status), "%s", status);
    log->size++;
}

void free_log_array(LogArray* log) {
    free(log->records);
    log->records = NULL;
    log->size = 0;
    log->capacity = 0;
}

int main() {
    LogArray log;
    init_log_array(&log, 10);

    time_t now = time(NULL);
    add_record(&log, now, rand(), "Processed");

    free_log_array(&log);
    return 0;
}
```

