// Function to initialize the log and allocate memory for offsets, keys, records, and logs
LogEntry* initializeData() {
    LogEntry *logs = (LogEntry*)malloc(sizeof(LogEntry) * NUM_RECORDS);
    if (!logs) {
        fprintf(stderr, "Memory allocation failed for logs\n");
        exit(EXIT_FAILURE);
    }

    Record **records = (Record**)malloc(sizeof(Record*) * NUM_RECORDS);
    if (!records) {
        free(logs);
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }

    int *offsets = (int*)malloc(sizeof(int) * NUM_RECORDS);
    if (!offsets) {
        free(records);
        free(logs);
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }

    int *keys = (int*)malloc(sizeof(int) * NUM_RECORDS);
    if (!keys) {
