#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

int* offsetArray = NULL;
int* keyArray = NULL;
record* records = NULL;
int usedKeys[MAX_KEYS] = {0};
size_t numRecords = 0;

unsigned int customPRNG(unsigned int seed) {
    return (seed * 1664525 + 1013904223) % UINT_MAX;
}

void initArrays(size_t initialCapacity) {
    offsetArray = malloc(initialCapacity * sizeof(long));
    keyArray = malloc(initialCapacity * sizeof(int));
    records = malloc(initialCapacity * sizeof(record));
    if (!offsetArray || !keyArray || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

int generateUniqueKey() {
    unsigned int seed = time(NULL);
    while (1) {
        int key = customPRNG(seed) % MAX_KEYS;
        if (!usedKeys[key]) {
            usedKeys[key] = 1;
            return key;
        }
        seed++;
    }
}

record* addRecord(int value) {
    if (numRecords >= numRecords * 0.75) {
        // Resize arrays
        size_t newCapacity = numRecords * 2;
        initArrays(newCapacity);
    }

    records[numRecords].value = value;
    keyArray[numRecords] = generateUniqueKey();
    offsetArray[numRecords] = (long)&records[numRecords];
    return &records[numRecords++];
}

void freeAll() {
    free(offsetArray);
    free(keyArray);
    free(records);
}

int main() {
    srand(time(NULL));
    initArrays(100);

    for (size_t i = 0; i < 50; i++) {
        int randomValue = customPRNG(rand()) % 1000 + 1;
        record* newRecord = addRecord(randomValue);
        printf("Added record with value: %d, key: %d, offset: %ld\n", newRecord->value, keyArray[numRecords - 1], (long)newRecord);
    }

    freeAll();
    return 0;
}
