bool manage_identifier_metadata(unsigned int id, char *metadata, IdentifierMetadata **identifier_list, size_t *list_size) {
    // Check if the identifier is within the valid range
    if (id > 65535) {
        return false;
    }

    // Allocate memory for the new identifier and metadata
    IdentifierMetadata *new_metadata = realloc(*identifier_list, (*list_size + 1) * sizeof(IdentifierMetadata));
    if (!new_metadata) {
        return false;
    }
    *identifier_list = new_metadata;

    // Store the new identifier and metadata in the list
    (*identifier_list)[*list_size].id = id;
    (*identifier_list)[*list_size].metadata = strdup(metadata);
    if (!(*identifier_list)[*list_size].metadata) {
        free(*identifier_list);
        *identifier_list = NULL;
        return false;
    }
    (*list_size)++;

    return true;
}

// Function to release allocated memory for the list of identifiers and metadata strings
