#include <time.h>
#include <pthread.h>

#define TABLE_SIZE 1024
#define MAX_RECORDS 1000

typedef struct {
    int key;
    long offset;
} record;

record records[MAX_RECORDS];

int hash(int key) {
    return key % TABLE_SIZE;
}

void insert_record(record *table, int key, long offset) {
    int index = hash(key);
    while (table[index].key != 0 && table[index].key != -1) {
        if (table[index].key == key) {
            printf("Key already exists!\n");
            return;
        }
        index = (index + 1) % TABLE_SIZE;
    }
    table[index].key = key;
    table[index].offset = offset;
}

int find_record(record *table, int key) {
    int index = hash(key);
    while (table[index].key != 0) {
        if (table[index].key == key) {
            return index;
        }
        index = (index + 1) % TABLE_SIZE;
    }
    return -1;
}

void *generate_records(void *arg) {
    record *table = (record *)malloc(TABLE_SIZE * sizeof(record));
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key, value;
        while ((key = rand() % 1024) == 0); // Ensure unique and non-zero keys
        value = rand() % 1000 + 1; // Generate random value between 1 and 1000
        insert_record(table, key, value);
    }
    free(table);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_records, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
