#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t num_records;
    pthread_mutex_t lock;
} shared_resource;

shared_resource *resource;

void init_shared_resource() {
    resource = (shared_resource *)malloc(sizeof(shared_resource));
    resource->offsets = (long *)calloc(MAX_KEYS, sizeof(long));
    resource->keys = (int *)calloc(MAX_KEYS, sizeof(int));
    resource->records = (record *)malloc(MAX_KEYS * sizeof(record));
    resource->num_records = 0;
    pthread_mutex_init(&resource->lock, NULL);
}

void cleanup_shared_resource() {
    free(resource->offsets);
    free(resource->keys);
    free(resource->records);
    pthread_mutex_destroy(&resource->lock);
    free(resource);
}

int generate_unique_key() {
    static int last_key = -1;
    int key;
    do {
        key = rand_r((unsigned int *)&last_key) % MAX_KEYS;
    } while (resource->keys[key]);
    resource->keys[key] = 1;
    return key;
}

record *generate_random_records(size_t num_records) {
    record *records = (record *)malloc(num_records * sizeof(record));
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % 1001;
        } while (value == records[i].value);
        records[i].value = value;
    }
    return records;
}

void *process_input(void *arg) {
    pthread_mutex_lock(&resource->lock);
    if (resource->num_records >= MAX_KEYS) {
        printf("Error: Too many records\n");
        pthread_mutex_unlock(&resource->lock);
        return NULL;
    }

    int input;
    while (scanf("%d", &input) == 1) {
        if (input < 0 || input >= 1024) {
            printf("Error: Invalid key range\n");
            continue;
        }
        int key = generate_unique_key();
        if (key == -1) {
            printf("Error: No available keys\n");
            break;
        }
        resource->records[key].value = input;
        resource->offsets[key] = time(NULL);
    }

    pthread_mutex_unlock(&resource->lock);
    return NULL;
}

int main() {
    init_shared_resource();
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_input, NULL);

    pthread_join(thread_id, NULL);
    cleanup_shared_resource();

    return 0;
}
