        } else {
            System.out.println("No valid integers found in input.");
        }

        // Clean up allocated memory
        offsets = null;
        keys = null;
        records = null;
    }

    private int assignUniqueKey(List<Integer> usedKeys, SecureRandom random) {
        int key;
        do {
            key = random.nextInt(MAX_KEYS);
        } while (usedKeys.contains(key));
        usedKeys.add(key);
        return key;
    }

    private int findRecord(Record[] records, int value) {
        for (int i = 0; i < records.length; i++) {
            if (records[i] != null && records[i].value == value) {
                return i;
            }
        }
        return -1;
    }

