#define RECORD_SIZE 100

typedef struct {
    int value;
} record;

record* initialize_records(int num_records, int min_val, int max_val) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Seed PRNG

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        printf("Record %d initialized with value: %d\n", i, records[i].value);
    }

    return records;
}

void reset_records(record* records, int num_records, int default_value) {
    for (int i = 0; i < num_records; i++) {
        records[i].value = default_value;
        printf("Record %d reset to value: %d\n", i, records[i].value);
    }
}

int main() {
    const int num_records = RECORD_SIZE;
    const int min_val = 1;
    const int max_val = 100;

    record* my_records = initialize_records(num_records, min_val, max_val);

    if (my_records) {
        reset_records(my_records, num_records, -1);
        free(my_records);
    }

    return 0;
}
