int generateRandomNumber(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Fallback PRNG function if the primary one fails
int fallbackGenerateRandomNumber(int min, int max) {
    return lrand48() % (max - min + 1) + min;
}

// Initialize PRNG with a seed based on time
void initPRNG() {
    srand(time(NULL));
}

// Fallback mechanism to initialize the PRNG state
