    record* records = (record*)malloc(size * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        records[i].value = generateRandomNumber(0, 100); // Example initialization
    }
    return records;
}

// Reset PRNG state to initial conditions
