typedef struct {
    long id;
    double amount;
} Transaction;

void init_transactions(Transaction **transactions, int count, double min_amount, double max_amount) {
    *transactions = (Transaction *)malloc(count * sizeof(Transaction));
    if (*transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL)); // Seed the PRNG for consistent results
    for (int i = 0; i < count; i++) {
        (*transactions)[i].id = i + 1;
        double amount = min_amount + ((double)rand() / RAND_MAX) * (max_amount - min_amount);
        (*transactions)[i].amount = amount;
        printf("Transaction %d: ID=%ld, Amount=%.2f\n", i + 1, (*transactions)[i].id, (*transactions)[i].amount);
    }
}

void reset_transactions(Transaction *transactions, int count, double default_amount) {
    for (int i = 0; i < count; i++) {
        transactions[i].amount = default_amount;
        printf("Transaction %d reset to amount %.2f\n", transactions[i].id, default_amount);
    }
}

int main() {
    Transaction *transactions;
    int count = 10;
    double min_amount = 10.0;
    double max_amount = 100.0;
    double default_amount = 0.0;

    init_transactions(&transactions, count, min_amount, max_amount);
    reset_transactions(transactions, count, default_amount);

    free(transactions);
    return 0;
}
