import java.util.concurrent.atomic.AtomicLong;

public class DistributedLogIDManager {
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final ConcurrentHashMap<String, AtomicLong> logCounters = new ConcurrentHashMap<>();

    public static String generateLogID(String source) {
        AtomicLong counter = logCounters.computeIfAbsent(source, k -> new AtomicLong());
        long id = counter.getAndIncrement();
        return source + "_" + id;
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(generateLogID("server1"));
        System.out.println(generateLogID("server2"));
    }
