        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.usedKeys = new HashSet<>();
        this.recordList = new ArrayList<>();
        this.maxRecords = maxRecords;
    }

    public void start() {
        serverChannel.accept(null, new CompletionHandler<AsynchronousSocketChannel, Void>() {
            @Override
            public void completed(AsynchronousSocketChannel clientChannel, Void attachment) {
                handleClient(clientChannel);
                serverChannel.accept(null, this);
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                exc.printStackTrace();
                serverChannel.accept(null, this);
            }
        });
    }

    private void handleClient(AsynchronousSocketChannel clientChannel) {
        executorService.submit(() -> {
            try {
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                int bytesRead = clientChannel.read(buffer).get();
                if (bytesRead > 0) {
                    processBuffer(buffer);
                }
                clientChannel.close();
            } catch (IOException | ExecutionException | InterruptedException e) {
                e.printStackTrace();
            }
        });
    }

    private void processBuffer(ByteBuffer buffer) {
        // Implement buffer processing logic here
    }

    public void stop() throws IOException, InterruptedException {
        serverChannel.close();
        executorService.shutdown().awaitTermination(1, TimeUnit.MINUTES);
    }

    private static record Record(int value) {}

    public static void main(String[] args) throws IOException, InterruptedException {
        ConnectionManager manager = new ConnectionManager(8080, 1000);
        manager.start();
        // Add code to handle graceful shutdown
    }
}
