#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
} KeyRecord;

typedef struct {
    KeyRecord *keys[MAX_KEYS];
    pthread_mutex_t lock;
} HashTable;

HashTable *hash_table_create() {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;
    for (int i = 0; i < MAX_KEYS; i++) table->keys[i] = NULL;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void hash_table_free(HashTable *table) {
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < MAX_KEYS; i++) {
        if (table->keys[i]) free(table->keys[i]);
    }
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void hash_table_insert(HashTable *table, long offset, int key) {
    pthread_mutex_lock(&table->lock);
    table->keys[key] = (KeyRecord *)malloc(sizeof(KeyRecord));
    if (!table->keys[key]) {
        fprintf(stderr, "Memory allocation failed for key %d\n", key);
        return;
    }
    table->keys[key]->offset = offset;
    table->keys[key]->key = key;
    pthread_mutex_unlock(&table->lock);
}

int hash_table_lookup(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    if (table->keys[key]) {
        pthread_mutex_unlock(&table->lock);
        return 1;
    }
    pthread_mutex_unlock(&table->lock);
    return 0;
}

Record* generate_records(int count, pthread_mutex_t *mutex) {
    Record *records = (Record *)malloc(count * sizeof(Record));
    if (!records) return NULL;

    unsigned char seed[32];
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp) {
        fread(seed, 1, 32, fp);
        fclose(fp);
    } else {
        srand(time(NULL));
        for (int i = 0; i < 32; i++) seed[i] = rand() % 256;
    }

    unsigned int *state = (unsigned int *)seed;
    for (int i = 0; i < count; i++) {
        records[i].value = xorshift128plus(state);
    }

    pthread_mutex_lock(mutex);
    // Ensure no duplicates
    while (1) {
        int all_unique = 1;
        for (int j = 0; j < i && all_unique; j++) {
            if (records[j].value == records[i].value) all_unique = 0;
        }
        if (all_unique) break;
        records[i].value = xorshift128plus(state);
    }
    pthread_mutex_unlock(mutex);

    return records;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int max_records = 100; // Default value
    if (argc > 1) {
        max_records = atoi(argv[1]);
    }

    // Initialize PRNG and hash table
    pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;
    Record *records = generate_records(max_records, &records_mutex);
    HashTable *table = hash_table_create();

    if (!records || !table) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Populate hash table with keys
    for (int i = 0; i < max_records; i++) {
        int key = rand() % MAX_KEYS;
        while (hash_table_lookup(table, key)) {
            key = rand() % MAX_KEYS;
        }
        hash_table_insert(table, records[i].value, key);
    }

    // Find and print the largest integer
    pthread_mutex_lock(&records_mutex);
    int max_value = records[0].value;
    for (int i = 1; i < max_records; i++) {
        if (records[i].value > max_value) max_value = records[i].value;
    }
    printf("Largest value: %d\n", max_value);
    pthread_mutex_unlock(&records_mutex);

    // Clean up
    hash_table_free(table);
    free(records);

    return 0;
}
