using System.Collections.Concurrent;

public class LargeFileProcessor
{
    private const int ChunkSize = 1024 * 1024; // 1 MB chunk size
    private readonly ConcurrentDictionary<string, byte[]> _hashCache = new();

    public string ProcessLargeFile(string filePath)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, ChunkSize, true))
        {
            var hashAlgorithm = MD5.Create();
            byte[] chunkHash;
            long bytesRead;

            while ((bytesRead = fileStream.Read(Buffer, 0, Buffer.Length)) > 0)
            {
                if (_hashCache.TryGetValue(BitConverter.ToString(Buffer).Replace("-", ""), out chunkHash))
                {
                    // Use cached hash
                }
                else
                {
                    chunkHash = hashAlgorithm.ComputeHash(Buffer);
                    _hashCache.TryAdd(BitConverter.ToString(Buffer).Replace("-", ""), chunkHash);
                }

                // Process chunk hash (e.g., store in database, log, etc.)
            }
        }

        return ComputeFinalHash(_hashCache.Values);
    }

    private byte[] ComputeFinalHash(byte[][] hashes)
    {
        using var finalHashAlgorithm = MD5.Create();
        foreach (var hash in hashes)
        {
            finalHashAlgorithm.TransformBlock(hash, 0, hash.Length, null, 0);
        }
        finalHashAlgorithm.TransformFinalBlock(new byte[0], 0, 0);
        return finalHashAlgorithm.Hash;
    }

    private static readonly byte[] Buffer = new byte[ChunkSize];
}
