    transactions = (Transaction*)malloc(INITIAL_SIZE * sizeof(Transaction));
    used_keys = (unsigned int*)calloc(MAX_KEYS, sizeof(unsigned int));

    if (!long_offsets || !keys || !transactions || !used_keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    key_count = 0;
    transaction_count = 0;
}

