    while (1) {
        if (!RAND_bytes((unsigned char*)&key, sizeof(key))) {
            fprintf(stderr, "Failed to generate random number\n");
            exit(1);
        }

        if (key < MAX_KEYS && !used_keys[key]) {
            used_keys[key] = 1;
            keys[key_count++] = key;
            break;
        }
    }
}

void initialize_transaction() {
    Transaction new_transaction;
    if (!RAND_bytes((unsigned char*)&new_transaction.amount, sizeof(new_transaction.amount))) {
        fprintf(stderr, "Failed to generate random number\n");
