        keys = realloc(keys, 2 * INITIAL_SIZE * sizeof(unsigned int));
        transactions = realloc(transactions, 2 * INITIAL_SIZE * sizeof(Transaction));

        if (!long_offsets || !keys || !transactions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }

        INITIAL_SIZE *= 2;
    }
}

