long* init_offsets(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < size; ++i) {
        offsets[i] = i; // Sequential initialization
    }
    return offsets;
}

int* init_keys(int size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < size; ++i) {
        keys[i] = i; // Sequential initialization
    }
    return keys;
}

record* init_records(int size, int lower_bound, int upper_bound) {
    if (upper_bound <= lower_bound) {
        return NULL; // Handle invalid range input
    }
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }
    unsigned long seed = 123456789ULL;
    for (int i = 0; i < size; ++i) {
        seed = LCG_MULTIPLIER * seed + LCG_INCREMENT;
        int random_value = lower_bound + (seed % (upper_bound - lower_bound + 1));
        records[i].value = random_value;
    }
    return records;
}

