#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t cache_size;
    size_t record_count;
    unsigned long seed;
} memory_manager;

memory_manager* create_memory_manager(size_t record_count, size_t cache_size, int min_value, int max_value) {
    memory_manager *mm = malloc(sizeof(memory_manager));
    if (!mm) return NULL;

    mm->offsets = malloc(record_count * sizeof(long));
    if (!mm->offsets) goto err_free_mm;

    mm->keys = malloc(record_count * sizeof(int));
    if (!mm->keys) goto err_free_offsets;

    mm->records = malloc(record_count * sizeof(record *));
    if (!mm->records) goto err_free_keys;

    for (size_t i = 0; i < record_count; ++i) {
        mm->records[i] = malloc(sizeof(record));
        if (!mm->records[i]) goto err_free_records;
        mm->keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    srand(time(NULL)); // Seed the random number generator
    mm->seed = time(NULL);
    mm->record_count = record_count;
    mm->cache_size = cache_size;

    return mm;

err_free_records:
    for (size_t i = 0; i < i; ++i) free(mm->records[i]);
    free(mm->records);

err_free_keys:
    free(mm->keys);

err_free_offsets:
    free(mm->offsets);

err_free_mm:
    free(mm);
    return NULL;
}

void destroy_memory_manager(memory_manager *mm) {
    for (size_t i = 0; i < mm->record_count; ++i) {
        free(mm->records[i]);
    }
    free(mm->records);
    free(mm->keys);
    free(mm->offsets);
    free(mm);
}

void reset_memory_manager(memory_manager *mm, int min_value, int max_value) {
    srand(time(NULL)); // Reseed the random number generator
    mm->seed = time(NULL);

    for (size_t i = 0; i < mm->record_count; ++i) {
        mm->keys[i] = rand() % (max_value - min_value + 1) + min_value;
        free(mm->records[i]);
        mm->records[i] = malloc(sizeof(record));
    }
}

int main() {
    memory_manager *mm = create_memory_manager(10, 5, 0, 100);
    if (!mm) {
        fprintf(stderr, "Failed to create memory manager\n");
        return EXIT_FAILURE;
    }

    // Use the memory manager here...

    destroy_memory_manager(mm);
    return EXIT_SUCCESS;
}
