    if (sessions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        sessions[i].sessionId = rand();
        sessions[i].expirationTimestamp = time(NULL) + (rand() % 3600); // Random expiration within an hour
        sessions[i].activityCounter = 0;
        sessions[i].activity = rand() % (maxActivity - minActivity + 1) + minActivity; // Pseudo-random activity
    }

    return sessions;
}

void freeSessionArray(userSession* sessions, size_t size) {
    free(sessions);
}

