    srand(time(NULL));
    size_t size = 10;
    int minActivity = 1;
    int maxActivity = 100;

    userSession* sessions = createSessionArray(size, minActivity, maxActivity);
    if (sessions != NULL) {
        for (size_t i = 0; i < size; i++) {
            printf("Session ID: %lu, Expiration: %ld, Activity: %u\n", sessions[i].sessionId, sessions[i].expirationTimestamp, sessions[i].activity);
