#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int key;
    long offset;
    int value;
} record;

record* allocateRecords(int size, long** offsets, int** keys) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) return NULL;

    *offsets = (long*)calloc(size, sizeof(long));
    if (!*offsets) {
        free(records);
        return NULL;
    }

    *keys = (int*)calloc(size, sizeof(int));
    if (!*keys) {
        free(*offsets);
        free(records);
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < size; ++i) {
        records[i].key = rand() % MAX_KEYS;
        while ((*keys)[records[i].key] != 0) {
            records[i].key = rand() % MAX_KEYS;
        }
        (*keys)[records[i].key] = 1;
        records[i].offset = rand();
        records[i].value = rand() % 1000;
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

void freeRecords(record* records, long* offsets, int* keys, int size) {
    free(records);
    free(offsets);
    free(keys);
}

int main() {
    srand(time(NULL));
    record* records = allocateRecords(100, NULL, NULL);
    if (records) {
        // Use the records array
        freeRecords(records, NULL, NULL, 100);
    }
    return 0;
}
```

This code snippet provides a basic structure for managing memory allocation and data population for two arrays: one for 'long' offset values and another for 'int' keys. It includes functions to allocate records with unique keys, ensuring thread safety using mutexes, and freeing the allocated memory upon function exit. The example uses a simple random number generator; for production, consider integrating a high-performance pseudo-random number generator optimized for your platform."]

