typedef struct {
    int key;
} KeyStruct;

typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    pthread_mutex_t lock;
    unsigned char pool[POOL_SIZE];
    size_t used;
} MemoryPool;

MemoryPool pool;

void init_memory_pool() {
    pthread_mutex_init(&pool.lock, NULL);
    pool.used = 0;
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool.lock);
    if (pool.used + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool.lock);
        return NULL; // Memory allocation failed
    }
    void* ptr = &pool.pool[pool.used];
    pool.used += size;
    pthread_mutex_unlock(&pool.lock);
    return ptr;
}

void free_memory_pool() {
    pthread_mutex_destroy(&pool.lock);
}

KeyStruct* allocate_key(int key) {
    KeyStruct* key_struct = (KeyStruct*)allocate_from_pool(sizeof(KeyStruct));
    if (key_struct == NULL) {
        return NULL; // Memory allocation failed
    }
    key_struct->key = key;
    return key_struct;
}

OffsetStruct* allocate_offset(long offset) {
    OffsetStruct* offset_struct = (OffsetStruct*)allocate_from_pool(sizeof(OffsetStruct));
    if (offset_struct == NULL) {
        return NULL; // Memory allocation failed
    }
    offset_struct->offset = offset;
    return offset_struct;
}

void free_key(KeyStruct* key_struct) {
    free(key_struct);
}

void free_offset(OffsetStruct* offset_struct) {
    free(offset_struct);
}
```

This code snippet provides a basic implementation of the memory management and concurrency handling functions as described in the task. It includes initialization, allocation, and deallocation functions for keys and offsets, using a custom memory pool to manage memory fragmentation and overhead. The use of mutexes ensures thread safety during memory allocations. Error handling is included to prevent out-of-memory errors and to provide flexibility in managing memory allocation failures.']

