char* generate_token(size_t length) {
    static const char chars[] = "0123456789abcdef";
    char *token = (char*)malloc(length + 1);
    if (!token) return NULL;

    for (size_t i = 0; i < length; ++i) {
        token[i] = chars[rand() % sizeof(chars)];
    }
    token[length] = '\0';
    return token;
}

SecureRecord* create_secure_records(size_t count, int value_range_start, int value_range_end) {
    if (count == 0 || value_range_start > value_range_end) return NULL;

    long *offsets = (long*)malloc(count * sizeof(long));
    int *keys = (int*)malloc(count * sizeof(int));
    SecureRecord *records = (SecureRecord*)malloc(count * sizeof(SecureRecord));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = i * sizeof(SecureRecord);
        keys[i] = rand() % (value_range_end - value_range_start + 1) + value_range_start;

        records[i].token = generate_token(32);
        if (!records[i].token) {
            for (size_t j = 0; j < i; ++j) {
                free(records[j].token);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        records[i].value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
    }

    return records;
}

void destroy_secure_records(SecureRecord *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].token);
