    pthread_mutex_t lock;
    unsigned char used_ids[256];
    Session sessions[MAX_SESSIONS];
} SessionManager;

SessionManager session_manager;

void init_session_manager() {
    pthread_mutex_init(&session_manager.lock, NULL);
    for (int i = 0; i < 256; i++) {
        session_manager.used_ids[i] = 0;
    }
}

unsigned int generate_random_value() {
    return rand() % RANGE_MAX + RANGE_MIN;
}

int is_session_id_unique(unsigned char id) {
    pthread_mutex_lock(&session_manager.lock);
    int unique = (session_manager.used_ids[id] == 0);
    if (unique) {
        session_manager.used_ids[id] = 1;
    }
    pthread_mutex_unlock(&session_manager.lock);
    return unique;
}

void set_session_value(unsigned int id, unsigned int value) {
    session_manager.sessions[id].value = value;
}

unsigned int get_session_value(unsigned int id) {
    return session_manager.sessions[id].value;
}

void destroy_session_manager() {
    pthread_mutex_destroy(&session_manager.lock);
}

int main() {
    init_session_manager();

    for (int i = 0; i < MAX_SESSIONS; i++) {
        unsigned char id = i % 256;
        if (is_session_id_unique(id)) {
            set_session_value(id, generate_random_value());
        } else {
            printf("Failed to allocate session ID %d\n", id);
        }
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        unsigned char id = i % 256;
        printf("Session ID %d: Value %u\n", id, get_session_value(id));
    }

    destroy_session_manager();
    return 0;
}
