#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define MODULO_VALUE 32

typedef struct {
    int key;
    long offset;
} KeyValue;

typedef struct {
    KeyValue *keys;
    int size;
    pthread_mutex_t lock;
} KeyPool;

KeyPool *key_pool_create() {
    KeyPool *pool = (KeyPool *)malloc(sizeof(KeyPool));
    if (!pool) return NULL;
    pool->keys = (KeyValue *)calloc(MAX_KEYS, sizeof(KeyValue));
    if (!pool->keys) {
        free(pool);
        return NULL;
    }
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

int key_pool_insert(KeyPool *pool, int key, long offset) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (pool->keys[i].key == key || (key % MODULO_VALUE == pool->keys[i].key % MODULO_VALUE)) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
    }
    if (pool->size >= MAX_KEYS) {
        pthread_mutex_unlock(&pool->lock);
        return -2;
    }
    pool->keys[pool->size].key = key;
    pool->keys[pool->size].offset = offset;
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void key_pool_destroy(KeyPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->keys);
    free(pool);
}
