import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class TemporaryDirectoryManager {
    private static final SecureRandom PRNG = new SecureRandom();
    private static final ConcurrentHashMap<String, DirectoryInfo> directoryMap = new ConcurrentHashMap<>();
    private static final AtomicInteger totalUsedSpace = new AtomicInteger(0);
    private static long globalStorageThreshold;
    private static long maxDirectorySize;

    public static void initialize(long threshold, long maxSize) {
        globalStorageThreshold = threshold;
        maxDirectorySize = maxSize;
    }

    public static Path createDirectory(String baseName, long initialSizeLimit) throws IOException {
        if (totalUsedSpace.get() + initialSizeLimit > globalStorageThreshold) {
            throw new IllegalStateException("Global storage threshold exceeded");
        }
        String uniqueName = generateUniqueName(baseName);
        Path directoryPath = Files.createTempDirectory(uniqueName);
        DirectoryInfo dirInfo = new DirectoryInfo(initialSizeLimit, directoryPath);
        if (!directoryMap.putIfAbsent(uniqueName, dirInfo).equals(dirInfo)) {
            throw new IOException("Failed to create unique directory");
        }
        totalUsedSpace.addAndGet(initialSizeLimit);
        return directoryPath;
    }

    private static String generateUniqueName(String baseName) {
        byte[] randomBytes = new byte[16];
        PRNG.nextBytes(randomBytes);
        return baseName + "_" + bytesToHex(randomBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void deleteDirectory(Path directoryPath) throws IOException {
        DirectoryInfo dirInfo = directoryMap.get(directoryPath.toString());
        if (dirInfo != null && dirInfo.directoryPath.equals(directoryPath)) {
            totalUsedSpace.addAndGet(-dirInfo.sizeLimit);
            Files.walkFileTree(directoryPath, new DeletingFileVisitor());
            directoryMap.remove(directoryPath.toString());
        } else {
            throw new IOException("Directory not found or does not match");
        }
    }

    public static void logUsage() {
        for (DirectoryInfo dirInfo : directoryMap.values()) {
            System.out.println("Directory: " + dirInfo.directoryPath + ", Usage: " +
                    dirInfo.getCurrentSize() + "/" + dirInfo.sizeLimit);
        }
    }

    // Additional methods for concurrent access, error handling, cleanup, monitoring, and resource management
}

class DirectoryInfo {
    private final long sizeLimit;
    private final Path directoryPath;
    private AtomicInteger currentSize;

    public DirectoryInfo(long sizeLimit, Path directoryPath) {
        this.sizeLimit = sizeLimit;
        this.directoryPath = directoryPath;
        this.currentSize = new AtomicInteger(0);
    }

    // Getters and setters for sizeLimit, directoryPath, and currentSize
}

// Implement additional classes and methods as per the task requirements
