import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DynamicConnectionManager {

    private final Map<String, SocketChannel> channelMap = new ConcurrentHashMap<>();
    private final Selector selector;
    private final int maxRecords;
    private final int latencyThreshold;
    private final long reconnectionInterval;
    private final DistributedCache cache;

    public DynamicConnectionManager(int maxRecords, int latencyThreshold, long reconnectionInterval, DistributedCache cache) throws IOException {
        this.maxRecords = maxRecords;
        this.latencyThreshold = latencyThreshold;
        this.reconnectionInterval = reconnectionInterval;
        this.cache = cache;
        this.selector = Selector.open();
    }

    public void manageConnections(Map<String, String> addressMap) throws IOException {
        for (Map.Entry<String, String> entry : addressMap.entrySet()) {
            connect(entry.getKey(), entry.getValue());
        }
        processConnections();
    }

    private void connect(String key, String address) throws IOException {
        if (channelMap.containsKey(key)) {
            return;
        }
        SocketChannel channel = SocketChannel.open(new InetSocketAddress(address));
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT);
        channelMap.put(key, channel);
    }

    private void processConnections() throws IOException {
        while (!Thread.currentThread().isInterrupted()) {
            selector.select();
            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();
                keys.remove();
                if (key.isConnectable()) {
                    connect(key);
                } else if (key.isReadable()) {
                    readData(key);
                }
            }
        }
    }

    private void connect(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        try {
            boolean connected = channel.finishConnect();
            if (connected) {
                System.out.println("Connected to " + channel.getRemoteAddress());
                channel.register(selector, SelectionKey.OP_READ);
            }
        } catch (IOException e) {
            System.err.println("Connection failed: " + channel.getRemoteAddress());
            key.cancel();
        }
    }

    private void readData(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int bytesRead = channel.read(buffer);
        if (bytesRead == -1) {
            System.out.println("Connection closed: " + channel.getRemoteAddress());
            key.cancel();
            return;
        }
        // Process data
    }

    public void close() throws IOException {
        selector.close();
        for (SocketChannel channel : channelMap.values()) {
            channel.close();
        }
    }
}
