} Record;

typedef struct {
    Record** records;
    int* keys;
    int* offsets;
    int size;
    int count;
} Group;

Group* create_group(int group_size, int key_range_start, int key_range_end, int offset_min, int offset_max) {
    Group* group = (Group*)malloc(sizeof(Group));
    if (!group) {
        fprintf(stderr, "Memory allocation failed for group\n");
        return NULL;
    }

    group->records = (Record**)malloc(group_size * sizeof(Record*));
    if (!group->records) {
        fprintf(stderr, "Memory allocation failed for records array\n");
        free(group);
        return NULL;
    }

    group->keys = (int*)malloc(group_size * sizeof(int));
    if (!group->keys) {
        fprintf(stderr, "Memory allocation failed for keys array\n");
        free(group->records);
        free(group);
        return NULL;
    }

    group->offsets = (int*)malloc(group_size * sizeof(int));
    if (!group->offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array\n");
        free(group->keys);
        free(group->records);
        free(group);
        return NULL;
    }

    group->size = group_size;
    group->count = 0;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < group_size; i++) {
        int key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        while (i > 0 && key == group->keys[i - 1]) { // Ensure uniqueness
            key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        }

        int offset = rand() % (offset_max - offset_min + 1) + offset_min;

        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed for record\n");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(group->records[j]);
            }
            free(group->offsets);
            free(group->keys);
            free(group->records);
            free(group);
            return NULL;
        }

        record->value = rand(); // Cryptographically strong pseudo-random number

        group->records[i] = record;
        group->keys[i] = key;
        group->offsets[i] = offset;

        group->count++;
    }

    return group;
}

void free_group(Group* group) {
    for (int i = 0; i < group->count; i++) {
        free(group->records[i]);
    }
    free(group->keys);
    free(group->offsets);
    free(group->records);
    free(group);
}

int main() {
    Group* group = create_group(10, 1, 100, 0, 50);
    if (group) {
        for (int i = 0; i < group->count; i++) {
            printf("Record %d: Key=%d, Offset=%d, Value=%d\n", i, group->keys[i], group->offsets[i], group->records[i]->value);
        }
        free_group(group);
    }
    return 0;
}
