#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define data structure
typedef struct {
    int value;
    long offset;
    char label;
} Data;

// PRNG function (Mersenne Twister example)
unsigned long fast_prng(unsigned long *seed) {
    static unsigned long m = 2365897148913L, a = 0x1BD1F5E6ED18C74FL;
    *seed = (*seed * m) + a;
    return *seed & 0xFFFFFFFFUL;
}

int main() {
    // Initialize arrays
    long *offsets = (long *)malloc(2048 * sizeof(long));
    int *keys = (int *)malloc(2048 * sizeof(int));
    char *labels = (char *)malloc(2048 * sizeof(char));

    if (!offsets || !keys || !labels) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Populate arrays
    for (int i = 0; i < 2048; i++) {
        offsets[i] = i;
        keys[i] = i / 32;
        labels[i] = 'A' + i % ('Z' - 'A');
    }

    // Initialize data structures with PRNG
    Data *data = (Data *)malloc(1024 * sizeof(Data));
    unsigned long seed = time(NULL);
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(labels);
        return 1;
    }

    for (int i = 0; i < 1024; i++) {
        data[i].value = fast_prng(&seed) % 1024;
        data[i].offset = offsets[data[i].value];
        data[i].label = labels[data[i].value];
    }

    // Binary search for key 128
    int found_index = -1;
    int left = 0, right = 2047;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (keys[mid] == 128) {
            found_index = mid;
            break;
        } else if (keys[mid] < 128) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    // Check result
    if (found_index != -1) {
        printf("Key found at index %d\n", found_index);
    } else {
        printf("Key not found\n");
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(labels);
    free(data);

    return 0;
}
