#define MAX_SEEDS 10000
#define MAX_UNIQUE_INDICES 10000
#define MAX_TRANSACTIONS 1000
#define MAX_MEASUREMENTS 1000
#define MAX_RECORDS 1024

typedef struct {
    float amount;
} Transaction;

typedef struct {
    double value;
} Measurement;

typedef struct {
    long timestamp;
    float activity_level;
} Record;

typedef struct {
    pthread_mutex_t lock;
    int* used_keys;
    int size;
    int capacity;
} KeyList;

KeyList key_list = {PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0};

void init_key_list() {
    pthread_mutex_lock(&key_list.lock);
    if (key_list.capacity == 0) {
        key_list.capacity = 16;
        key_list.used_keys = malloc(key_list.capacity * sizeof(int));
        if (!key_list.used_keys) {
            perror("Failed to allocate memory for used keys");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&key_list.lock);
}

void free_key_list() {
    pthread_mutex_lock(&key_list.lock);
    free(key_list.used_keys);
    key_list.capacity = 0;
    key_list.size = 0;
    pthread_mutex_unlock(&key_list.lock);
}

int get_unique_index(int seed) {
    int index;
    do {
        index = rand_r((unsigned int*)&seed) % MAX_UNIQUE_INDICES;
    } while (index < 0 || index >= MAX_UNIQUE_INDICES || key_list.used_keys[index]);
    key_list.used_keys[index] = 1;
    return index;
}

void reset_key(int index) {
    pthread_mutex_lock(&key_list.lock);
    if (index >= 0 && index < MAX_UNIQUE_INDICES) {
        key_list.used_keys[index] = 0;
    }
    pthread_mutex_unlock(&key_list.lock);
}

Record* manage_memory(long seed, int unique_index, Transaction* transactions, Measurement* measurements, int num_transactions, double* measurements_values, int num_measurements) {
    Record* records = malloc(num_transactions * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (int i = 0; i < num_transactions; ++i) {
        long timestamp = time(NULL);
        records[i].timestamp = timestamp;
        records[i].activity_level = transactions[i].amount + measurements_values[unique_index];
    }

    free_key_list();
    init_key_list();

    return records;
}

int main() {
    int seed;
    scanf("%ld", &seed);

    Transaction* transactions = malloc(MAX_TRANSACTIONS * sizeof(Transaction));
    Measurement* measurements = malloc(MAX_MEASUREMENTS * sizeof(Measurement));
    double* measurements_values = malloc(MAX_MEASUREMENTS * sizeof(double));

    // Read transactions and measurements from standard input
    for (int i = 0; i < MAX_TRANSACTIONS; ++i) {
        scanf("%f", &transactions[i].amount);
    }
    for (int i = 0; i < MAX_MEASUREMENTS; ++i) {
        scanf("%lf", &measurements_values[i]);
    }

    int unique_index = get_unique_index(seed);
    Record* records = manage_memory(seed, unique_index, transactions, measurements, MAX_TRANSACTIONS, measurements_values, MAX_MEASUREMENTS);

    if (records) {
        // Process records
        free(records);
    }

    free(transactions);
    free(measurements);
    free(measurements_values);

    return 0;
}
