int used_keys[MAX_KEYS];

unsigned long fast_prng(unsigned long seed) {
    return (seed * 6364136223858366245ULL + 1) % UINT_MAX;
}

void initialize_records(record **records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        records[i] = (record *)malloc(sizeof(record));
        if (records[i]) {
            records[i]->value = rand() % 1001;
        }
    }
