unsigned long get_next_key(unsigned long *seed) {
    return fast_prng(*seed++);
}

int find_unique_key(unsigned long seed, int num_records) {
    unsigned long key;
    do {
        key = get_next_key(&seed);
    } while (used_keys[key] || (key >= MAX_KEYS && key < 0));
    used_keys[key] = 1;
    return key;
}

void insert_record(record *record, int key) {
    hash_table[key % TABLE_SIZE] = record;
}

int lookup_record(int key) {
    if (hash_table[key % TABLE_SIZE]) {
        return hash_table[key % TABLE_SIZE]->value;
    }
    return -1;
}

void cleanup_records(record **records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
}

void seed_prng() {
    unsigned long seed = getpid() + time(NULL);
#ifdef _SC_NPROCESSORS_ONLN
    seed += sysconf(_SC_NPROCESSORS_ONLN);
#endif
    srand(seed);
