    pthread_mutex_t rng_mutex = PTHREAD_MUTEX_INITIALIZER;
    int seed = time(NULL);

    void* random_number_generator(void* arg) {
        pthread_mutex_lock(&rng_mutex);
        int thread_id = *(int*)arg;
        records[thread_id].value = MIN_VALUE + rand_r((unsigned int*)&seed) % (MAX_VALUE - MIN_VALUE + 1);
        pthread_mutex_unlock(&rng_mutex);
        return NULL;
