#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define ARRAY_SIZE 100

typedef struct {
    int id;
} Record;

// Pseudo-random number generator state
unsigned long long seed = 0;
pthread_mutex_t prng_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_prng() {
    // Seed the PRNG with time-varying data
    pthread_mutex_lock(&prng_mutex);
    if (seed == 0) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        seed = ((unsigned long long)ts.tv_sec << 32) | ts.tv_nsec;
    }
    pthread_mutex_unlock(&prng_mutex);
}

unsigned long long xorshift128plus() {
    static unsigned long long x = 1234567890123456ULL, y = 9876543210987654ULL;
    pthread_mutex_lock(&prng_mutex);
    unsigned long long t = x ^ (x << 11);
    x = y;
    y = y ^ (y >> 8) ^ t ^ (t >> 19);
    seed = y + 0x6D2B7A4F3585A1EDULL; // Update the global seed
    pthread_mutex_unlock(&prng_mutex);
    return seed;
}

int prng_range(int min, int max) {
    unsigned long long range = (unsigned long long)(max - min + 1);
    return (int)((xorshift128plus() % range) + min);
}

void *allocate_and_initialize_arrays(void *arg) {
    long *offsets = malloc(ARRAY_SIZE * sizeof(long));
    int *keys = malloc(ARRAY_SIZE * sizeof(int));
    Record *records = malloc(ARRAY_SIZE * sizeof(Record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    init_prng();

    for (int i = 0; i < ARRAY_SIZE; i++) {
        offsets[i] = prng_range(0, 1000);
        keys[i] = prng_range(-500, 500);
        records[i].id = prng_range(1000, 9999);
    }

    // Simulate external data source seed
    FILE *random_file = fopen("/dev/urandom", "rb");
    if (random_file) {
        fread(&seed, sizeof(seed), 1, random_file);
        fclose(random_file);
    } else {
        fprintf(stderr, "Failed to open /dev/urandom for seeding\n");
        // Fallback to local entropy pool
    }

    pthread_mutex_lock(&prng_mutex);
    seed = xorshift128plus(); // Re-seed PRNG with new entropy
    pthread_mutex_unlock(&prng_mutex);

    // Free allocated memory (not shown here)

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_and_initialize_arrays, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Failed to join thread\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
