    if (index >= 624) {
        for (int i = 0; i < 624; ++i) {
            unsigned long y = (mt[i] & 0x80000000) + (mt[(i + 1) % 624] & 0x7fffffff);
            mt[i] = mt[(i + 397) % 624] ^ (y >> 1);
