unsigned long secure_rand();
void initialize_records(record *records);
void check_and_add_key(int key, int *used_keys, int used_count);

int main() {
    // Allocate and initialize arrays
    unsigned long *offsets = (unsigned long *)malloc(sizeof(unsigned long) * MAX_KEYS);
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return 1;
    }

    int *keys = (int *)malloc(sizeof(int) * MAX_KEYS);
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return 1;
    }

    record *records = (record *)malloc(sizeof(record) * RECORD_COUNT);
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return 1;
    }

    // Initialize keys and offsets
    srand(time(NULL));
    for (int i = 0; i < MAX_KEYS; i++) {
        keys[i] = secure_rand() % MAX_KEYS;
        offsets[i] = secure_rand();
    }

    // Initialize records
    initialize_records(records);

    // Check and add unique keys to a used_keys array
    int *used_keys = (int *)calloc(MAX_KEYS, sizeof(int));
    if (!used_keys) {
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Memory allocation failed for used keys.\n");
        return 1;
    }

    for (int i = 0; i < RECORD_COUNT; i++) {
        check_and_add_key(records[i].value, used_keys, MAX_KEYS);
    }

    // Clean up allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(used_keys);

    return 0;
}

// Secure random number generator function using a combination of system-specific data and hardware timestamp
unsigned long secure_rand() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    unsigned long seed = (unsigned long)ts.tv_sec * 1000000000ULL + ts.tv_nsec + getpid();
    srand(seed);
    return rand();
}

// Initialize records with random values from 1 to 1000
void initialize_records(record *records) {
    for (int i = 0; i < RECORD_COUNT; i++) {
        do {
            records[i].value = secure_rand() % 1000 + 1;
        } while (!is_unique(records, i));
    }
}

// Helper function to check if a value is unique in the records array
int is_unique(record *records, int index) {
    for (int i = 0; i < index; i++) {
        if (records[i].value == records[index].value) {
            return 0;
        }
    }
    return 1;
}

// Function to check and add a unique key to the used_keys array
void check_and_add_key(int key, int *used_keys, int used_count) {
    for (int i = 0; i < used_count; i++) {
        if (used_keys[i] == key) {
            fprintf(stderr, "Key collision detected. Exiting.\n");
            exit(1);
        }
    }
    used_keys[used_count] = key;
}
