import java.util.*;
import java.util.concurrent.*;

public class TaskManager {

    private static final int MAX_TASK_ID = 1024;
    private static final float[] priorityLevels = new float[10];
    private static final Random random = new Random();
    private static Set<Integer> usedTaskIds = ConcurrentHashMap.newKeySet();
    private static List<Integer> inputList = new ArrayList<>();
    private static int maxTasks;

    public static void main(String[] args) {
        // Initialize priority levels
        for (int i = 0; i < priorityLevels.length; i++) {
            priorityLevels[i] = random.nextFloat() * 10 + 1;
        }

        // Set maximum number of tasks from configuration
        maxTasks = Integer.parseInt(System.getProperty("maxTasks", "500"));

        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter list of integers (comma separated):");
        String input = scanner.nextLine();
        String[] numbers = input.split(",");
        for (String num : numbers) {
            try {
                int value = Integer.parseInt(num.trim());
                if (value >= 0 && value < MAX_TASK_ID) {
                    inputList.add(value);
                }
            } catch (NumberFormatException e) {
                // Ignore invalid integers
            }
        }

        float median = findMedian(inputList);
        System.out.println("Median: " + median);

        // Simulate task distribution
        distributeTasks();
    }

    private static float findMedian(List<Integer> list) {
        Collections.sort(list);
        int size = list.size();
        if (size % 2 == 0) {
            return (list.get(size / 2 - 1) + list.get(size / 2)) / 2.0f;
        } else {
            return list.get(size / 2);
        }
    }

    private static void distributeTasks() {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletionService<Void> completionService = new ExecutorCompletionService<>(executor);

        for (int i = 0; i < inputList.size(); i++) {
            int taskId = getUniqueTaskId();
            if (taskId == -1) {
                System.out.println("No available task IDs.");
                return;
            }
            Task task = new Task(taskId, priorityLevels[i]);
            completionService.submit(() -> {
                try {
                    processTask(task);
                    logTaskSuccess(taskId);
                } catch (Exception e) {
                    logTaskFailure(taskId);
                }
                return null;
            });
        }

        int completedTasks = 0;
        while (completedTasks < inputList.size()) {
            try {
                completionService.take().get();
                completedTasks++;
            } catch (InterruptedException | ExecutionException e) {
                System.out.println("Error in task processing.");
            }
        }

        executor.shutdown();
    }

    private static int getUniqueTaskId() {
        while (true) {
            int taskId = random.nextInt(MAX_TASK_ID);
            if (usedTaskIds.add(taskId)) {
                return taskId;
            }
        }
    }

    private static void processTask(Task task) throws Exception {
        // Simulate task processing
        Thread.sleep((long) (1000 * (task.getPriority() / 5.0)));
    }

    private static void logTaskSuccess(int taskId) {
        System.out.println("Task " + taskId + " completed successfully.");
    }

    private static void logTaskFailure(int taskId) {
        System.out.println("Task " + taskId + " failed.");
    }
}

class Task {
    private int id;
    private float priority;

    public Task(int id, float priority) {
        this.id = id;
        this.priority = priority;
    }

    public int getId() {
        return id;
    }

    public float getPriority() {
        return priority;
    }
}
```

