    long key = rand() % MAX_KEYS;
    pthread_mutex_lock(mutex);
    while (used_keys[key]) {
        key = (key + 1) % MAX_KEYS;
    }
    used_keys[key] = 1;
    pthread_mutex_unlock(mutex);
    return key;
}

void initialize_records(Record **records, int *used_keys, pthread_mutex_t *mutex, int num_records) {
