        }
        records[i]->value = rand() % 1000 + 1;
    }
}

void clean_up_records(Record **records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
}

int main() {
    srand(time(NULL));
    pthread_mutex_t used_keys_mutex = PTHREAD_MUTEX_INITIALIZER;

    Record *records[1000];
    int used_keys[MAX_KEYS] = {0};
    int num_records = 1000;

    initialize_records(records, used_keys, &used_keys_mutex, num_records);

    // Perform operations on records...

    clean_up_records(records, num_records);

    return 0;
}
