#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct {
    int key;
    long offset;
} Record;

struct HashTable {
    Record* records[TABLE_SIZE];
};

struct HashTable* createHashTable() {
    struct HashTable* table = (struct HashTable*)malloc(sizeof(struct HashTable));
    for (int i = 0; i < TABLE_SIZE; i++) {
        table->records[i] = NULL;
    }
    return table;
}

void insertRecord(struct HashTable* table, int key, long offset) {
    int index = key % TABLE_SIZE;
    while (table->records[index] != NULL && table->records[index]->key != key) {
        index = (index + 1) % TABLE_SIZE; // Linear probing
    }
    if (table->records[index] == NULL) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->key = key;
        record->offset = offset;
        table->records[index] = record;
    }
}

int getRandomNumber() {
    static int seed = 42; // Example seed
    return rand_r((unsigned int*)&seed) % 1001; // Random between 0 and 1000
}

void* generateRecords(void* arg) {
    struct HashTable* table = (struct HashTable*)arg;
    for (int i = 0; i < 1024; i++) {
        int key = getRandomNumber();
        long offset = (long)i * 1000L; // Example offset calculation
        insertRecord(table, key, offset);
    }
    return NULL;
}

void cleanupHashTable(struct HashTable* table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (table->records[i] != NULL) {
            free(table->records[i]);
            table->records[i] = NULL;
        }
    }
    free(table);
}

int main() {
    struct HashTable* table = createHashTable();
    pthread_t thread;
    pthread_create(&thread, NULL, generateRecords, (void*)table);
    pthread_join(thread, NULL);
    cleanupHashTable(table);
    return 0;
}
