int is_key_used(int* used_keys, int size, int key) {
    for (int i = 0; i < size; i++) {
        if (used_keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

record* allocate_and_initialize_records(int num_elements, pthread_mutex_t* lock) {
    record* records = malloc(num_elements * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    int used_keys[MAX_SIZE] = {0};
    int key_count = 0;

    srand(time(NULL));

    for (int i = 0; i < num_elements; i++) {
        int key;
        do {
            key = rand() % 1024 + 1;
        } while (is_key_used(used_keys, key_count, key));
        used_keys[key_count++] = key;

        records[i].offset = i * sizeof(record);
        records[i].key = key;
    }

    return records;
}

void free_records(record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int num_elements = 100; // Example number of elements
