typedef struct user_profile {
    long id;
    int uid;
    double score;
} user_profile;

typedef struct hash_table_entry {
    user_profile *profile;
    struct hash_table_entry *next;
} hash_table_entry;

typedef struct hash_table {
    size_t capacity;
    hash_table_entry **buckets;
    pthread_mutex_t lock;
} hash_table;

hash_table *create_hash_table(size_t capacity) {
    hash_table *table = (hash_table *)malloc(sizeof(hash_table));
    if (!table) return NULL;

    table->capacity = capacity;
    table->buckets = (hash_table_entry **)calloc(capacity, sizeof(hash_table_entry *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(hash_table *table) {
    for (size_t i = 0; i < table->capacity; i++) {
        hash_table_entry *entry = table->buckets[i];
        while (entry) {
            hash_table_entry *next = entry->next;
            free(entry->profile);
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void insert_user_profile(hash_table *table, user_profile *profile) {
    size_t index = profile->uid % table->capacity;
    hash_table_entry *entry = (hash_table_entry *)malloc(sizeof(hash_table_entry));
    if (!entry) return;

    entry->profile = profile;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
}

user_profile *find_user_profile(hash_table *table, int uid) {
    size_t index = uid % table->capacity;
    hash_table_entry *entry = table->buckets[index];
    while (entry) {
        if (entry->profile->uid == uid) return entry->profile;
        entry = entry->next;
    }
    return NULL;
}

user_profile *generate_user_profile(long id, int uid) {
    user_profile *profile = (user_profile *)malloc(sizeof(user_profile));
    if (!profile) return NULL;

    profile->id = id;
    profile->uid = uid;
    profile->score = drand48() * 100.0;
    return profile;
}

void initialize_user_profile_management_system(size_t capacity) {
    hash_table *table = create_hash_table(capacity);
    if (!table) {
        fprintf(stderr, "Failed to allocate memory for hash table.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize user profiles here
    for (int i = 1; i <= 65535; i++) {
        long id = time(NULL); // Example ID generation
        user_profile *profile = generate_user_profile(id, i);
        if (!profile) {
            fprintf(stderr, "Failed to allocate memory for user profile.\n");
            destroy_hash_table(table);
            exit(EXIT_FAILURE);
        }
        insert_user_profile(table, profile);
    }

    // Simulate concurrent access and modifications
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, user_management_thread_function, table) != 0) {
            fprintf(stderr, "Failed to create thread.\n");
            destroy_hash_table(table);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_hash_table(table);
}

void *user_management_thread_function(void *arg) {
    hash_table *table = (hash_table *)arg;

    // Perform read and write operations on the user profiles here
    // Example: Find a user profile and update its score
    int uid = rand() % 65536;
    pthread_mutex_lock(&table->lock);
    user_profile *profile = find_user_profile(table, uid);
    if (profile) {
        profile->score = drand48() * 100.0;
    }
    pthread_mutex_unlock(&table->lock);

    return NULL;
}
