#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int timeout;
    int retry_interval;
    int max_connections;
    unsigned long prng_seed;
} Config;

// Pseudo-random number generator function
unsigned long xorshift32(unsigned long *x) {
    unsigned long t = (*x ^= (*x << 13));
    t ^= (t >> 7);
    return (*x ^= (t << 17));
}

int init_config(Config *config, int timeout, int retry_interval, int max_connections, unsigned long prng_seed) {
    if (timeout <= 0 || retry_interval <= 0 || max_connections <= 0) {
        fprintf(stderr, "Invalid configuration parameters.\n");
        return -1;
    }

    config->timeout = timeout;
    config->retry_interval = retry_interval;
    config->max_connections = max_connections;

    // Seed the PRNG with the provided seed or get entropy from hardware
    if (prng_seed == 0) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        prng_seed = ts.tv_nsec ^ ts.tv_sec;
    }

    config->prng_seed = prng_seed;

    return 0;
}

int main() {
