        if ((*records)[i] == NULL) {
            for (size_t j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return -4; // Memory allocation failed
        }

        (*records)[i]->str = (char *)malloc(RECORD_SIZE * sizeof(char));
        if ((*records)[i]->str == NULL) {
            for (size_t j = 0; j <= i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            return -5; // Memory allocation failed
        }

        (*records)[i]->value = rand();
    }

    srand(time(NULL)); // Seed PRNG with time for better randomness

    return 0; // Success
