    private static void processConnection(Socket socket, ConnectionManager manager, DatabaseClient db) {
        try (
            InputStream in = socket.getInputStream();
            OutputStream out = socket.getOutputStream()
        ) {
            int[] sequence = readSequence(in);
            long sum = computeSumOfEvens(sequence);
            sendResult(out, sum);
            storeInDatabase(db, sum);
        } catch (IOException e) {
            e.printStackTrace();
        }
