        return Arrays.stream(sequence).filter(n -> n % 2 == 0).sum();
    }

    private static void sendResult(OutputStream out, long sum) throws IOException {
        // Simulate sending the result to the output stream
        out.write(String.valueOf(sum).getBytes());
        out.flush();
    }

    private static void storeInDatabase(DatabaseClient db, long sum) {
