size_t array_size;

pthread_mutex_t used_keys_mutex;
int* used_keys;
size_t used_keys_size;

unsigned long xorshift64star() {
    static unsigned long x = 1234567890123456789ULL;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    return x * 268589151UL;
}

void init_arrays(size_t size) {
    array_size = size;
    offset_array = malloc(array_size * sizeof(long));
    key_array = malloc(array_size * sizeof(int));
    record_array = malloc(array_size * sizeof(record));

    used_keys_size = 0;
    pthread_mutex_init(&used_keys_mutex, NULL);
}

void init_records() {
    for (size_t i = 0; i < array_size; ++i) {
        do {
            key_array[i] = xorshift64star() % 1024;
        } while (key_exists(key_array[i]));

        record_array[i].value = xorshift64star() % 1000 + 1;

        mark_key_as_used(key_array[i]);
    }
}

int key_exists(int key) {
    for (size_t i = 0; i < used_keys_size; ++i) {
        if (used_keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

void mark_key_as_used(int key) {
    used_keys_size++;
    used_keys = realloc(used_keys, used_keys_size * sizeof(int));
    used_keys[used_keys_size - 1] = key;
}

void clean_up() {
    free(offset_array);
    free(key_array);
    free(record_array);
    pthread_mutex_destroy(&used_keys_mutex);
    free(used_keys);
}

int read_integers_and_find_median(size_t* count) {
    int value;
    *count = 0;

    while (scanf("%d", &value) == 1) {
        (*count)++;
    }

    int* integers = malloc(*count * sizeof(int));
    rewind(stdin); // Reset input stream

    for (size_t i = 0; i < *count; ++i) {
        scanf("%d", &integers[i]);
    }

    qsort(integers, *count, sizeof(int), (int (*)(const void *, const void *))compare);

    int median;
    if (*count % 2 == 0) {
        median = (integers[*count / 2 - 1] + integers[*count / 2]) / 2;
    } else {
        median = integers[*count / 2];
    }

    free(integers);
    return median;
}

int compare(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

void* worker(void* arg) {
    size_t local_count;
    int local_median = read_integers_and_find_median(&local_count);

    // Handle concurrent access and locking
    pthread_mutex_lock(&used_keys_mutex);
    printf("Median: %d\n", local_median);
    pthread_mutex_unlock(&used_keys_mutex);

    return NULL;
}

int main() {
    size_t num_threads;
    printf("Enter number of threads: ");
    scanf("%zu", &num_threads);

    init_arrays(num_threads * 10); // Assuming each thread needs around 10 records
    init_records();

    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    clean_up();
    free(threads);

    return 0;
}
