#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct Record {
    int value;
    struct Record *next;
} Record;

typedef struct KeyNode {
    long offset;
    struct KeyNode *next;
} KeyNode;

typedef struct KeyManager {
    pthread_mutex_t lock;
    KeyNode *head;
    int used_keys[MAX_KEYS];
} KeyManager;

void init_key_manager(KeyManager *km) {
    pthread_mutex_init(&km->lock, NULL);
    km->head = NULL;
    for (int i = 0; i < MAX_KEYS; i++) {
        km->used_keys[i] = 0;
    }
}

void add_key(KeyManager *km, long offset, int key) {
    pthread_mutex_lock(&km->lock);
    if (key < 0 || key >= MAX_KEYS || km->used_keys[key]) {
        pthread_mutex_unlock(&km->lock);
        return; // Key out of range or already used
    }
    KeyNode *new_node = (KeyNode *)malloc(sizeof(KeyNode));
    new_node->offset = offset;
    new_node->next = km->head;
    km->head = new_node;
    km->used_keys[key] = 1;
    pthread_mutex_unlock(&km->lock);
}

void remove_key(KeyManager *km, int key) {
    pthread_mutex_lock(&km->lock);
    if (key < 0 || key >= MAX_KEYS || !km->used_keys[key]) {
        pthread_mutex_unlock(&km->lock);
        return; // Key out of range or not used
    }
    KeyNode **current = &km->head;
    while (*current) {
        if ((*current)->offset == key) {
            KeyNode *temp = *current;
            *current = (*current)->next;
            free(temp);
            break;
        }
        current = &(*current)->next;
    }
    km->used_keys[key] = 0;
    pthread_mutex_unlock(&km->lock);
}

int main() {
    KeyManager km;
    init_key_manager(&km);

    // Example usage
    add_key(&km, 123456789L, 42);
    remove_key(&km, 42);

    return 0;
}
