import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

public class FileManager {
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final ConcurrentHashMap<String, Boolean> usedFileNames = new ConcurrentHashMap<>();
    private static String tempDirPath = null;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.println("Enter the number of files:");
        int n = Integer.parseInt(reader.readLine());

        List<String> fileNames = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            String fileName = generateUniqueFileName();
            usedFileNames.put(fileName, true);
            fileNames.add(fileName);
        }

        System.out.println("Longest common prefix: " + findLongestCommonPrefix(fileNames));

        System.out.println("Enter directory name:");
        String dirName = reader.readLine();
        createDirectoryAndSetEnvVar(dirName);

        cleanUpUsedFileNames();
    }

    private static String generateUniqueFileName() {
        while (true) {
            String fileName = generateRandomFileName();
            if (usedFileNames.putIfAbsent(fileName, true) == null) {
                return fileName;
            }
        }
    }

    private static String generateRandomFileName() {
        byte[] bytes = new byte[16];
        RANDOM.nextBytes(bytes);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return "temp-" + sb.toString();
    }

    private static String findLongestCommonPrefix(List<String> strings) {
        if (strings == null || strings.size() == 0)
            return "";

        Collections.sort(strings);
        String first = strings.get(0);
        String last = strings.get(strings.size() - 1);
        int c;
        for (c = 0; c < first.length(); c++) {
            if (first.charAt(c) != last.charAt(c))
                break;
        }
        return first.substring(0, c);
    }

    private static void createDirectoryAndSetEnvVar(String dirName) {
        tempDirPath = System.getenv("TEMP_DIR");
        if (tempDirPath == null || !tempDirPath.equals(dirName)) {
            tempDirPath = dirName;
            System.setProperty("TEMP_DIR", dirName);
        }
    }

    private static void cleanUpUsedFileNames() {
        for (String fileName : usedFileNames.keySet()) {
            usedFileNames.put(fileName, false);
        }
    }
}
