        id = rand() % 65535;
    } while (isIdentifierUsed(id));
    markIdentifierAsUsed(id);
    return id;
}

int isIdentifierUsed(short id) {
    for (int i = 0; i < usedCount; i++) {
        if (usedIdentifiers[i].id == id) {
            return 1;
        }
    }
    return 0;
}

void markIdentifierAsUsed(short id) {
    if (usedCount >= capacity) {
        capacity *= 2;
        usedIdentifiers = realloc(usedIdentifiers, capacity * sizeof(Identifier));
        manageMemory(capacity * sizeof(Identifier));
    }
    Identifier newId = {id};
    usedIdentifiers[usedCount++] = newId;
}

