import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class TaskManager {

    private ConcurrentHashMap<Integer, Integer> taskPriorityMap = new ConcurrentHashMap<>();
    private Set<Integer> usedTaskIds = new HashSet<>();
    private int maxTasks;
    private static final String LOG_LEVEL = "DEBUG";

    public TaskManager(int maxTasks) {
        this.maxTasks = maxTasks;
    }

    public void distributeTasks() {
        if (usedTaskIds.size() >= maxTasks) {
            System.out.println("Max tasks limit reached. Cannot allocate more tasks.");
            return;
        }

        try {
            int taskId = generateUniqueId();
            int priority = generateRandomPriority();

            taskPriorityMap.put(taskId, priority);
            usedTaskIds.add(taskId);

            if (LOG_LEVEL.equals("DEBUG")) {
                System.out.println("Task " + taskId + " with priority " + priority + " allocated.");
            }
        } catch (Exception e) {
            handleAllocationFailure(e);
        }
    }

    private int generateUniqueId() throws Exception {
        while (true) {
            int id = ThreadLocalRandom.current().nextInt(1024);
            if (!usedTaskIds.contains(id)) {
                return id;
            }
        }
    }

    private int generateRandomPriority() {
        return ThreadLocalRandom.current().nextInt(1, 11);
    }

    private void handleAllocationFailure(Exception e) {
        System.err.println("Failed to allocate task: " + e.getMessage());
        // Rollback any partial operations
    }

    public void readAndPrintMedianFromInput() {
        try (Scanner scanner = new Scanner(System.in)) {
            List<Integer> numbers = new ArrayList<>();
            while (scanner.hasNextInt()) {
                numbers.add(scanner.nextInt());
            }

            Collections.sort(numbers);
            double median = calculateMedian(numbers);
            System.out.println("Median: " + median);
        }
    }

    private double calculateMedian(List<Integer> numbers) {
        int size = numbers.size();
        if (size % 2 == 0) {
            return (numbers.get(size / 2 - 1) + numbers.get(size / 2)) / 2.0;
        } else {
            return numbers.get(size / 2);
        }
    }

    public void cleanup() {
        taskPriorityMap.clear();
        usedTaskIds.clear();
        System.out.println("All resources cleaned up.");
    }

    // Additional methods and configurations can be added here
}
```

