    unsigned long x1 = *x;
    *x = x1 ^ (x1 << 11);
    x1 ^= (x1 >> 8);
    return *x = x1 ^ (x1 >> 19);
}

int init_records(Record **records, long **offsets, int *keys, int num_records, unsigned long seed) {
    *records = malloc(num_records * sizeof(Record));
    *offsets = malloc(num_records * sizeof(long));
