#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

long* offset_array;
int* key_array;
record** record_array;
size_t array_size;
size_t allocated_size;
pthread_mutex_t lock;

void initialize_arrays(size_t size) {
    if (size <= 0) return;

    pthread_mutex_init(&lock, NULL);
    array_size = size;
    allocated_size = size * 2; // Allocate extra space for potential growth

    offset_array = malloc(allocated_size * sizeof(long));
    key_array = malloc(allocated_size * sizeof(int));
    record_array = malloc(allocated_size * sizeof(record*));

    if (!offset_array || !key_array || !record_array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < allocated_size; ++i) {
        offset_array[i] = -1;
        key_array[i] = -1;
        record_array[i] = NULL;
    }
}

void* allocate_record(size_t index, int value) {
    pthread_mutex_lock(&lock);
    if (index >= allocated_size) {
        printf("Attempted to access out-of-bounds index\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    if (record_array[index] != NULL) {
        printf("Record at index %zu is already allocated\n", index);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    record* new_record = malloc(sizeof(record));
    if (!new_record) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    new_record->value = value;
    record_array[index] = new_record;

    printf("Record at index %zu allocated with value %d\n", index, value);
    pthread_mutex_unlock(&lock);

    return new_record;
}

void free_record(size_t index) {
    pthread_mutex_lock(&lock);
    if (index >= allocated_size || record_array[index] == NULL) {
        printf("Attempted to free unallocated or out-of-bounds index\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    free(record_array[index]);
    record_array[index] = NULL;

    printf("Record at index %zu freed\n", index);
    pthread_mutex_unlock(&lock);
}

void cleanup_unused_records() {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < allocated_size; ++i) {
        if (record_array[i] != NULL && key_array[i] == -1) {
            free(record_array[i]);
            record_array[i] = NULL;
            printf("Unused record at index %zu freed\n", i);
        }
    }
    pthread_mutex_unlock(&lock);
}

void log_memory_event(const char* event, size_t index) {
    printf("%s at index %zu\n", event, index);
}
