    private final ConcurrentMap<Integer, Future<?>> futures;

    public ConnectionManager(int maxRecords) throws IOException {
        this.selector = Selector.open();
        this.maxRecords = maxRecords;
        this.offsetArray = new long[maxRecords];
        this.keyArray = new int[maxRecords];
        this.recordArray = new Record[maxRecords];
        this.random = new SecureRandom();
        this.channels = new ConcurrentHashMap<>();
        this.futures = new ConcurrentHashMap<>();

        initializeKeyArray();
        initializeRecordArray();
    }

    private void initializeKeyArray() {
        Set<Integer> usedKeys = new HashSet<>();
        for (int i = 0; i < maxRecords; i++) {
            int key;
            do {
                key = random.nextInt(1024);
            } while (!usedKeys.add(key));
            keyArray[i] = key;
        }
    }

    private void initializeRecordArray() {
        Set<Integer> usedValues = new HashSet<>();
        for (int i = 0; i < maxRecords; i++) {
            int value;
            do {
                value = random.nextInt(1001);
            } while (!usedValues.add(value));
            recordArray[i] = new Record(value);
        }
    }

    public void connectToRemoteAddresses(List<String> addresses) throws IOException {
        for (String address : addresses) {
            SocketChannel channel = SocketChannel.open(new InetSocketAddress(address, 8080));
            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_CONNECT);
            channels.put(address, channel);
        }
    }

    public void handleConnections() throws IOException {
        while (true) {
            selector.select();
            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();
                if (key.isConnectable()) {
                    SocketChannel channel = (SocketChannel) key.channel();
                    try {
                        channel.finishConnect();
                        System.out.println("Connected to " + channel.getRemoteAddress());
                        // Handle successful connection
                    } catch (IOException e) {
                        System.err.println("Failed to connect to " + channel.getRemoteAddress());
                        channels.remove(channel.getRemoteAddress(), channel);
                    }
                }
                keys.remove();
            }
        }
    }

    public void pauseProcessing(String address) {
        SocketChannel channel = channels.get(address);
        if (channel != null && channel.isConnected()) {
            channel.keyFor(selector).cancel();
        }
    }

    public void resumeProcessing(String address) throws IOException {
        SocketChannel channel = SocketChannel.open(new InetSocketAddress(address, 8080));
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT);
        channels.put(address, channel);
    }

    public void shutdown() throws IOException {
        for (SocketChannel channel : channels.values()) {
            channel.close();
        }
        selector.close();
    }

    private static class Record {
        int value;

        Record(int value) {
            this.value = value;
        }
    }
}
