#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define RECORD_SIZE 10

typedef struct {
    int value;
} record;

long* offset_values;
int* keys;
record** records;
unsigned long long seed = time(NULL);
pthread_mutex_t used_keys_lock;
int* used_keys;

void initialize_arrays() {
    offset_values = (long*)malloc(MAX_KEYS * sizeof(long));
    keys = (int*)malloc(MAX_KEYS * sizeof(int));
    records = (record**)malloc(RECORD_SIZE * sizeof(record*));

    pthread_mutex_init(&used_keys_lock, NULL);
    used_keys = (int*)calloc(MAX_KEYS, sizeof(int));

    srand(seed);
}

void refresh_prng_seed() {
    seed += time(NULL);
    srand(seed);
}

record* allocate_record() {
    record* new_record = (record*)malloc(sizeof(record));
    new_record->value = rand() % 1000 + 1;
    return new_record;
}

int find_unique_key() {
    int key;
    while (1) {
        key = rand() % MAX_KEYS;
        pthread_mutex_lock(&used_keys_lock);
        if (!used_keys[key]) {
            used_keys[key] = 1;
            pthread_mutex_unlock(&used_keys_lock);
            return key;
        }
        pthread_mutex_unlock(&used_keys_lock);
    }
}

void allocate_records() {
    for (int i = 0; i < RECORD_SIZE; i++) {
        int unique_key = find_unique_key();
        records[i] = allocate_record();
        keys[unique_key] = records[i]->value;
        offset_values[unique_key] = (long)i;
    }
}

void cleanup() {
    for (int i = 0; i < RECORD_SIZE; i++) {
        free(records[i]);
    }
    pthread_mutex_destroy(&used_keys_lock);
    free(offset_values);
    free(keys);
    free(records);
    free(used_keys);
}

void* thread_function(void* arg) {
    allocate_records();
    refresh_prng_seed();
    return NULL;
}

int main() {
    initialize_arrays();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup();

    return 0;
}
