import java.io.IOException;
import java.nio.file.*;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class TemporaryDirectoryManager {
    private final SecureRandom random = new SecureRandom();
    private final ConcurrentHashMap<Path, Long> directoryUsage = new ConcurrentHashMap<>();
    private final ReentrantLock lock = new ReentrantLock();
    private long totalSizeLimit;
    private long maxDirectorySize;
    private long cleanupThreshold;
    private Path baseDir;

    public TemporaryDirectoryManager(Path baseDir, long totalSizeLimit, long maxDirectorySize, long cleanupThreshold) {
        this.baseDir = baseDir;
        this.totalSizeLimit = totalSizeLimit;
        this.maxDirectorySize = maxDirectorySize;
        this.cleanupThreshold = cleanupThreshold;
    }

    public Path createDirectory() throws IOException {
        lock.lock();
        try {
            long remainingSpace = totalSizeLimit - directoryUsage.values().stream().reduce(0L, Long::sum);
            if (remainingSpace < maxDirectorySize) {
                throw new IOException("No space left to create a new directory.");
            }
            Path dir;
            do {
                byte[] randomBytes = new byte[16];
                random.nextBytes(randomBytes);
                String dirName = Base64.getEncoder().encodeToString(randomBytes);
                dir = baseDir.resolve(dirName);
            } while (Files.exists(dir));
            Files.createDirectory(dir);
            directoryUsage.put(dir, 0L);
            return dir;
        } finally {
            lock.unlock();
        }
    }

    public void deleteDirectory(Path dir) throws IOException {
        lock.lock();
        try {
            if (!directoryUsage.containsKey(dir)) {
                throw new FileNotFoundException("Directory not found.");
            }
            Files.delete(dir);
            directoryUsage.remove(dir);
        } finally {
            lock.unlock();
        }
    }

    public void updateUsage(Path dir, long sizeChange) throws IOException {
        lock.lock();
        try {
            if (!directoryUsage.containsKey(dir)) {
                throw new FileNotFoundException("Directory not found.");
            }
            long newUsage = directoryUsage.get(dir) + sizeChange;
            if (newUsage < 0 || newUsage > maxDirectorySize) {
                throw new IllegalArgumentException("Invalid usage change.");
            }
            directoryUsage.put(dir, newUsage);
        } finally {
            lock.unlock();
        }
    }

    public void monitorAndLog() {
        // Implement monitoring and logging logic here
    }

    public void cleanupUnusedDirectories() {
        lock.lock();
        try {
            directoryUsage.entrySet().removeIf(entry -> entry.getValue() == 0 && System.currentTimeMillis() - entry.getKey().lastModifiedTime().toMillis() > cleanupThreshold);
        } finally {
            lock.unlock();
        }
    }

    // Add additional methods as needed for integration with distributed data processing framework and machine learning model deployment pipeline
}
