#define MAX_KEYS 4096

typedef struct {
    int value;
} record;

long* offset_array;
int* key_array;
record* record_array;
pthread_mutex_t used_keys_lock;
int used_keys[MAX_KEYS];
int next_available_key = 1;

void initialize_arrays() {
    offset_array = (long*)malloc(MAX_KEYS * sizeof(long));
    key_array = (int*)malloc(MAX_KEYS * sizeof(int));
    record_array = (record*)malloc(MAX_KEYS * sizeof(record));

    pthread_mutex_init(&used_keys_lock, NULL);
}

void cleanup_memory() {
    free(offset_array);
    free(key_array);
    free(record_array);
    pthread_mutex_destroy(&used_keys_lock);
}

int generate_random_key() {
    while (next_available_key < MAX_KEYS) {
        if (used_keys[next_available_key] == 0) {
            used_keys[next_available_key] = 1;
            return next_available_key++;
        }
        next_available_key++;
    }
    return -1; // No more available keys
}

void initialize_records() {
    for (int i = 0; i < MAX_KEYS; i++) {
        record_array[i].value = rand() % 5000 + 1;
    }
}

void* worker_thread(void* arg) {
    int key = generate_random_key();
    if (key != -1) {
        pthread_mutex_lock(&used_keys_lock);
        used_keys[key] = 0; // Mark as available after use
        pthread_mutex_unlock(&used_keys_lock);
    }
    return NULL;
}

void read_and_print_largest() {
    int n;
    scanf("%d", &n);

    if (n <= 0) {
        printf("Invalid input.\n");
        return;
    }

    int* numbers = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &numbers[i]);
    }

    int largest = numbers[0];
    for (int i = 1; i < n; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }

    printf("Largest number: %d\n", largest);

    free(numbers);
}

int main() {
    srand(time(NULL));
    initialize_arrays();
    initialize_records();

    pthread_t threads[MAX_KEYS];
    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_join(threads[i], NULL);
    }

    read_and_print_largest();

    cleanup_memory();
    return 0;
}
