#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

#define MAX_RECORDS 1024

typedef struct Record {
    int key;
    long offset;
} Record;

Record *record_pool[MAX_RECORDS];
int pool_index = 0;
pthread_mutex_t pool_lock;

unsigned long prng_state = time(NULL);

unsigned long custom_prng() {
    prng_state = (prng_state * 1664525 + 1013904223) % 4294967296;
    return prng_state >> 16;
}

Record* allocate_record(int key) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index >= MAX_RECORDS) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Handle error: pool full
    }
    Record *record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Handle error: allocation failed
    }
    record->key = key;
    record->offset = custom_prng();
    record_pool[pool_index++] = record;
    pthread_mutex_unlock(&pool_lock);
    return record;
}

void free_records() {
    for (int i = 0; i < pool_index; i++) {
        free(record_pool[i]);
    }
    pool_index = 0;
}

int main() {
    // Example usage
    Record *record1 = allocate_record(42);
    if (record1) {
        printf("Allocated record with key: %d, offset: %ld\n", record1->key, record1->offset);
    } else {
        printf("Failed to allocate record\n");
    }

    // Cleanup
    free_records();

    return 0;
}
