Entry** create_array(int* capacity) {
    *capacity = INIT_CAPACITY;
    Entry** array = (Entry**)malloc(*capacity * sizeof(Entry*));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

void free_array(Entry** array, int size) {
    for (int i = 0; i < size; ++i) {
        free(array[i]->string);
        free(array[i]);
    }
    free(array);
}

long generate_random_id() {
    static bool seeded = false;
    if (!seeded) {
        srand(time(NULL));
        seeded = true;
    }
    return rand();
}

void resize_array(Entry*** array, int* capacity, int new_capacity) {
    Entry** new_array = (Entry**)realloc(*array, new_capacity * sizeof(Entry*));
    if (!new_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *capacity = new_capacity;
}

void add_entry(Entry*** array, int* size, int* capacity) {
    if (*size == *capacity) {
        resize_array(array, capacity, *capacity * 2);
    }
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int length = rand() % (MAX_IDENTIFIER_LENGTH - 1) + 1;
    entry->string = (char*)malloc((length + 1) * sizeof(char));
    if (!entry->string) {
        free(entry);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Generate random alphanumeric string
    for (int i = 0; i < length; ++i) {
        entry->string[i] = 'A' + rand() % 62;
    }
    entry->string[length] = '\0';

    (*array)[*size++] = entry;
}

int main() {
    Entry** array = create_array(&capacity);
    int size = 0;

    // Example usage
    for (int i = 0; i < 100; ++i) {
        add_entry(&array, &size, &capacity);
    }

    // Free allocated memory
    free_array(array, size);

    return 0;
}
