    manager->records[manager->used_count].timestamp = time(NULL);
    manager->used_keys[manager->used_keys_count++] = key;
    manager->used_count++;
    pthread_mutex_unlock(&manager->lock);
    return key;
}

Record* get_record(RecordManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->used_count; ++i) {
        if (manager->records[i].key == key) {
