typedef struct {
    UserSession sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
    uint16_t next_session_id;
} SessionManager;

void init_session_manager(SessionManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        manager->sessions[i].session_id = UINT16_MAX;
        manager->sessions[i].metadata = NULL;
    }
    manager->next_session_id = 1; // Start IDs from 1 to avoid 0 as a valid ID
}

uint16_t generate_unique_session_id(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    uint16_t id = manager->next_session_id++;
    if (manager->next_session_id == UINT16_MAX) {
        manager->next_session_id = 1; // Wrap around to start from 1 again
    }
    pthread_mutex_unlock(&manager->lock);
    return id;
}

int add_user_session(SessionManager* manager, uint16_t session_id, void* metadata) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i].session_id == UINT16_MAX) {
            manager->sessions[i].session_id = session_id;
            manager->sessions[i].metadata = metadata;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // No available slots
}

void remove_user_session(SessionManager* manager, uint16_t session_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i].session_id == session_id) {
            manager->sessions[i].session_id = UINT16_MAX;
            manager->sessions[i].metadata = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_session_manager(SessionManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i].metadata != NULL) {
            // Free metadata
            free(manager->sessions[i].metadata);
            manager->sessions[i].session_id = UINT16_MAX;
            manager->sessions[i].metadata = NULL;
        }
    }
}
