long* long_offsets = NULL;
int* int_keys = NULL;
record** records = NULL;
int used_keys[4096] = {0};
time_t timestamps[NUM_RECORDS];
pthread_mutex_t key_lock, record_lock, pool_lock;
void* record_pool = NULL;
size_t record_pool_size = 0;

void init_memory() {
    long_offsets = (long*)malloc(NUM_RECORDS * sizeof(long));
    int_keys = (int*)malloc(NUM_RECORDS * sizeof(int));
    records = (record**)malloc(NUM_RECORDS * sizeof(record*));
    pthread_mutex_init(&key_lock, NULL);
    pthread_mutex_init(&record_lock, NULL);
    pthread_mutex_init(&pool_lock, NULL);
}

void init_prng() {
    unsigned char seed[32];
    size_t seed_len = 0;
    if (RAND_poll(seed, sizeof(seed), &seed_len, sizeof(seed)) <= 0) {
        fprintf(stderr, "Failed to initialize PRNG\n");
        exit(EXIT_FAILURE);
    }
    RAND_seed(seed, seed_len);
}

record* allocate_record() {
    pthread_mutex_lock(&pool_lock);
    if (record_pool == NULL || record_pool_size < sizeof(record)) {
        // Allocate new pool or expand existing one
        // For simplicity, assume fixed-size for this example
        record_pool = realloc(record_pool, 2 * record_pool_size + sizeof(record));
        record_pool_size += sizeof(record);
    }
    record* new_record = (record*)record_pool;
    record_pool += sizeof(record);
    pthread_mutex_unlock(&pool_lock);
    return new_record;
}

void free_record(record* rec) {
    // Record can be safely freed back to the pool
    pthread_mutex_lock(&pool_lock);
    record* tmp = rec;
    *tmp = *((record*)record_pool); // Copy next record into current position
    record_pool = (char*)tmp + sizeof(record); // Move pool pointer forward
    pthread_mutex_unlock(&pool_lock);
}

void generate_random_numbers() {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        int_keys[i] = arc4random_uniform(4096);
        while (used_keys[int_keys[i]]) {
            int_keys[i] = arc4random_uniform(4096);
        }
        used_keys[int_keys[i]] = 1;
        records[i] = allocate_record();
        records[i]->value = arc4random_uniform(5000) + 1;
        records[i]->timestamp = time(NULL);
    }
}

void cleanup() {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (records[i] != NULL) {
            free_record(records[i]);
        }
    }
    free(long_offsets);
    free(int_keys);
    free(records);
    pthread_mutex_destroy(&key_lock);
    pthread_mutex_destroy(&record_lock);
    pthread_mutex_destroy(&pool_lock);
    free(record_pool);
}

int main() {
    init_memory();
    init_prng();
    generate_random_numbers();
    // Use the records and offsets as needed
    cleanup();
    return 0;
}
