#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

long* offset_values;
int* keys;
record* records;
int used_keys[MAX_KEYS];
int key_count = 0;
pthread_mutex_t key_lock;

void init_arrays() {
    offset_values = (long*)malloc(MAX_KEYS * sizeof(long));
    keys = (int*)malloc(MAX_KEYS * sizeof(int));
    records = (record*)malloc(MAX_KEYS * sizeof(record));

    if (!offset_values || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&key_lock, NULL);
}

void generate_random_numbers() {
    srand(time(0));

    for (int i = 0; i < MAX_KEYS; i++) {
        while (1) {
            int random_key = rand();
            if (random_key >= 0 && random_key < MAX_KEYS && used_keys[random_key] == 0) {
                keys[i] = random_key;
                used_keys[random_key] = 1;
                key_count++;
                break;
            }
        }

        records[i].value = rand() % 1000 + 1; // Random number between 1 and 1000
    }
}

void cleanup() {
    free(offset_values);
    free(keys);
    free(records);
    pthread_mutex_destroy(&key_lock);
}

void* read_input(void* arg) {
    int* input_array = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!input_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int count = 0;
    while (1) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        if (value < 0 || value >= MAX_KEYS || used_keys[value] == 1) {
            printf("Invalid input\n");
            continue;
        }
        keys[count++] = value;
        used_keys[value] = 1;
    }

    *(int*)arg = count;

    return NULL;
}

void find_largest_integer(int key_count, int* keys) {
    if (key_count == 0) {
        printf("No input provided\n");
        return;
    }

    int largest = keys[0];
    for (int i = 1; i < key_count; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

int main() {
    init_arrays();
    generate_random_numbers();

    pthread_t thread;
    pthread_create(&thread, NULL, read_input, &key_count);

    // Simulate concurrent access to shared resource
    for (int i = 0; i < key_count; i++) {
        pthread_mutex_lock(&key_lock);
        used_keys[keys[i]] = 1;
        pthread_mutex_unlock(&key_lock);
    }

    pthread_join(thread, NULL);

    find_largest_integer(key_count, keys);
    cleanup();

    return 0;
}
