use std::env;
use std::fs;
use std::io;
use std::sync::{Arc, Mutex};
use std::thread;
use tokio::sync::Mutex as AsyncMutex;
use tracing::{error, info, instrument};

// Define a struct to manage directory operations with concurrent control
struct DirectoryManager {
    root_dir: String,
    external_service_client: ExternalServiceClient,
}

impl DirectoryManager {
    pub fn new(root_dir: &str) -> Self {
        DirectoryManager {
            root_dir: root_dir.to_string(),
            external_service_client: ExternalServiceClient::new(),
        }
    }

    #[instrument]
    pub async fn create_directory(&self, directory_name: &str) -> io::Result<()> {
        let full_path = format!("{}/{}", self.root_dir, sanitize_directory_name(directory_name));

        // Check if the directory already exists using an external service
        if self.external_service_client.directory_exists(&full_path).await? {
            info!("Directory {} already exists", full_path);
            return Ok(());
        }

        // Create the directory with concurrent control
        let mutex = Arc::new(Mutex::new(false));
        let mut lock = mutex.lock().unwrap();

        if !*lock {
            *lock = true;
            match fs::create_dir_all(&full_path) {
                Ok(_) => {
                    info!("Directory {} created successfully", full_path);
                    Ok(())
                }
                Err(e) => {
                    error!("Failed to create directory {}: {}", full_path, e);
                    Err(io::Error::new(io::ErrorKind::Other, e))
                }
            } finally {
                *lock = false;
            }
        } else {
            info!("Directory creation is in progress for {}", full_path);
            Ok(())
        }
    }
}

// Function to sanitize directory name
fn sanitize_directory_name(name: &str) -> String {
    // Add your sanitization logic here
    name.replace('/', "_").replace('\\', "_")
}

