#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    unsigned int id;
    double amount;
} transaction;

typedef struct {
    transaction *transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} transaction_pool;

void init_transaction_pool(transaction_pool *pool, size_t initial_capacity) {
    pool->transactions = malloc(initial_capacity * sizeof(transaction));
    if (!pool->transactions) {
        fprintf(stderr, "Failed to allocate memory for transaction pool\n");
        exit(1);
    }
    pool->count = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);
}

void free_transaction_pool(transaction_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->transactions);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

unsigned int generate_transaction_id(transaction_pool *pool, unsigned int seed) {
    // Custom PRNG algorithm
    return (seed * 1664525 + 1013904223) % UINT_MAX;
}

void add_transaction(transaction_pool *pool, time_t timestamp, double amount) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        pool->capacity *= 2;
        pool->transactions = realloc(pool->transactions, pool->capacity * sizeof(transaction));
        if (!pool->transactions) {
            fprintf(stderr, "Failed to reallocate memory for transaction pool\n");
            exit(1);
        }
    }
    unsigned int seed = time(NULL);
    unsigned int id = generate_transaction_id(pool, seed);
    // Validate uniqueness
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->transactions[i].id == id) {
            while (1) {
                id = generate_transaction_id(pool, seed++);
                if (i == pool->count) break; // Exit loop if ID is unique
            }
        }
    }
    pool->transactions[pool->count++] = (transaction){timestamp, id, amount};
    pthread_mutex_unlock(&pool->lock);
}

void *process_transactions(void *arg) {
    transaction_pool *pool = (transaction_pool *)arg;
    time_t now = time(NULL);
    double amount = 100.0; // Example amount
    add_transaction(pool, now, amount);
    return NULL;
}

int main() {
    transaction_pool pool;
    init_transaction_pool(&pool, 10);

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, process_transactions, &pool) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(1);
        }
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_transaction_pool(&pool);
    return 0;
}
