    srand(time(NULL));
    pthread_mutex_init(&used_keys_lock, NULL);

    transactions = (Transaction*)malloc(MAX_TRANSACTIONS * sizeof(Transaction));
    records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    used_keys = (int*)calloc(1024, sizeof(int));

    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        init_transaction(&transactions[i]);
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        init_record(&records[i]);
    }

