import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentSkipListSet;

public class SessionManager {
    private static final int SESSION_ID_RANGE = 65536;
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final ConcurrentHashMap<Integer, Long> sessionMap = new ConcurrentHashMap<>();
    private static final ConcurrentSkipListSet<Integer> usedIds = new ConcurrentSkipListSet<>();

    public static String createSession(int userId) {
        if (userId < 0) {
            throw new IllegalArgumentException("Invalid user ID");
        }

        int sessionId;
        do {
            sessionId = RANDOM.nextInt(SESSION_ID_RANGE);
        } while (!usedIds.add(sessionId));

        long expirationTimestamp = System.currentTimeMillis() + 3600000; // 1 hour
        sessionMap.put(sessionId, expirationTimestamp);

        return String.format("%d:%s", userId, Integer.toHexString(sessionId));
    }

    public static boolean validateSession(String sessionId) {
        if (sessionId == null || !sessionId.contains(":")) {
            return false;
        }

        String[] parts = sessionId.split(":");
        int userId = Integer.parseInt(parts[0]);
        int parsedSessionId = Integer.parseInt(parts[1], 16);

        Long expirationTimestamp = sessionMap.get(parsedSessionId);
        if (expirationTimestamp == null || System.currentTimeMillis() > expirationTimestamp) {
            usedIds.remove(parsedSessionId);
            sessionMap.remove(parsedSessionId);
            return false;
        }

        return userId == parts[0].hashCode();
    }

    public static void cleanup() {
        sessionMap.clear();
        usedIds.clear();
    }
}
