typedef struct {
    long* offsets;
    int* keys;
    size_t offset_count;
    size_t key_count;
    pthread_mutex_t lock;
} memory_manager;

memory_manager* create_memory_manager() {
    memory_manager* mm = (memory_manager*)malloc(sizeof(memory_manager));
    if (!mm) return NULL;
    mm->offsets = (long*)calloc(MAX_KEYS, sizeof(long));
    mm->keys = (int*)calloc(MAX_KEYS, sizeof(int));
    if (!mm->offsets || !mm->keys) {
        free(mm);
        return NULL;
    }
    pthread_mutex_init(&mm->lock, NULL);
    mm->offset_count = 0;
    mm->key_count = 0;
    return mm;
}

void destroy_memory_manager(memory_manager* mm) {
    if (mm) {
        free(mm->offsets);
        free(mm->keys);
        pthread_mutex_destroy(&mm->lock);
        free(mm);
    }
}

int allocate_key(memory_manager* mm) {
    pthread_mutex_lock(&mm->lock);
    for (size_t i = 0; i < MAX_KEYS; ++i) {
        if (mm->keys[i] == -1) {
            mm->keys[i] = 1;
            mm->key_count++;
            pthread_mutex_unlock(&mm->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&mm->lock);
    return -1;
}

void free_key(memory_manager* mm, int key_index) {
    pthread_mutex_lock(&mm->lock);
    if (key_index >= 0 && key_index < MAX_KEYS && mm->keys[key_index] == 1) {
        mm->keys[key_index] = -1;
        mm->key_count--;
    }
    pthread_mutex_unlock(&mm->lock);
}

