#include <unistd.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    int used_keys[MAX_KEYS];
    int next_key;
} key_cache;

key_cache* init_key_cache() {
    key_cache* cache = (key_cache*)malloc(sizeof(key_cache));
    pthread_mutex_init(&cache->lock, NULL);
    for (int i = 0; i < MAX_KEYS; ++i) {
        cache->used_keys[i] = 0;
    }
    cache->next_key = 0;
    return cache;
}

int get_next_key(key_cache* cache) {
    pthread_mutex_lock(&cache->lock);
    int key = -1;
    for (int i = 0; i < MAX_KEYS; ++i) {
        if (!cache->used_keys[i]) {
            cache->used_keys[i] = 1;
            key = i;
            break;
        }
    }
    if (key == -1 && cache->next_key < MAX_KEYS) {
        key = cache->next_key++;
        cache->used_keys[key] = 1;
    }
    pthread_mutex_unlock(&cache->lock);
    return key;
}

void free_key(key_cache* cache, int key) {
    pthread_mutex_lock(&cache->lock);
    if (key >= 0 && key < MAX_KEYS) {
        cache->used_keys[key] = 0;
    }
    pthread_mutex_unlock(&cache->lock);
}

record* init_records(int num_records) {
    record* records = (record*)malloc(num_records * sizeof(record));
    srand(time(NULL) + getpid());
    for (int i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % 1001;
        } while (find_record(records, num_records, value) != -1);
        records[i].value = value;
    }
    return records;
}

int find_record(record* records, int num_records, int value) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i].value == value) {
            return i;
        }
    }
    return -1;
}

void free_records(record* records, int num_records) {
    free(records);
}

int read_largest_integer() {
    int size;
    printf("Enter the number of integers: ");
    scanf("%d", &size);

    int* arr = (int*)malloc(size * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; ++i) {
        scanf("%d", &arr[i]);
    }

    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    free(arr);
    return largest;
}

void clean_up(key_cache* cache, record* records) {
    pthread_mutex_destroy(&cache->lock);
    free_key_cache(cache);
    free_records(records, num_records);
}

int main() {
    key_cache* cache = init_key_cache();
    int num_records = 10; // Example number of records
    record* records = init_records(num_records);

    printf("Largest integer: %d\n", read_largest_integer());

    clean_up(cache, records);
    return 0;
}
