    if (count < MIN_TRANSACTIONS || count > MAX_TRANSACTIONS) {
        fprintf(stderr, "Invalid transaction count. Must be between %d and %d.\n", MIN_TRANSACTIONS, MAX_TRANSACTIONS);
        return NULL;
    }

    Transaction* transactions = malloc(count * sizeof(Transaction));
    if (transactions == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        transactions[i].transaction_id = i + 1;
        transactions[i].amount = ((double)rand() / RAND_MAX) * currency_range;
        transactions[i].timestamp = time(NULL);
    }

    return transactions;
}

void free_transactions(Transaction* transactions, int count) {
    if (transactions != NULL) {
        free(transactions);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    int transaction_count = 100; // Example count of transactions
    long currency_range = 1000.0; // Example currency range

    Transaction* transactions = create_transactions(transaction_count, currency_range);
    if (transactions != NULL) {
        for (int i = 0; i < transaction_count; i++) {
            printf("Transaction ID: %d, Amount: %.2f, Timestamp: %ld\n", 
                   transactions[i].transaction_id, transactions[i].amount, transactions[i].timestamp);
        }
        free_transactions(transactions, transaction_count);
    }

    return 0;
}
