void initializeSessionArray(Session *sessions, int numSessions) {
    if (sessions == NULL || numSessions <= 0) return;

    // Seed PRNG with external data source
    FILE *fp = fopen("/dev/urandom", "r"); // Use /dev/urandom for non-blocking seeding
    if (fp != NULL) {
        unsigned long seed;
        fread(&seed, sizeof(seed), 1, fp);
        fclose(fp);
        srand(seed);
    } else {
        srand(time(NULL)); // Fallback to time-based seeding if external source fails
    }

    for (int i = 0; i < numSessions; i++) {
        sessions[i].id = i + 1; // Unique identifier for each session
        snprintf(sessions[i].token, sizeof(sessions[i].token), "session%d", sessions[i].id);
        for (int j = 0; j < 32; j++) {
            sessions[i].token[j] += rand() % 32; // Add a pseudo-random number to each character
        }
    }
}

