import java.io.File;
import java.nio.file.Files;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class DatasetManager {
    private ConcurrentHashMap<String, Long> directorySizeMap = new ConcurrentHashMap<>();
    private SecureRandom prng = new SecureRandom();
    private long totalStorageQuota;
    private int maxDirectories;
    private long cleanupThreshold;

    public DatasetManager(long totalStorageQuota, int maxDirectories, long cleanupThreshold) {
        this.totalStorageQuota = totalStorageQuota;
        this.maxDirectories = maxDirectories;
        this.cleanupThreshold = cleanupThreshold;
    }

    public String createDataset(long sizeLimit) throws IOException {
        if (directorySizeMap.size() >= maxDirectories || getTotalUsedSpace() + sizeLimit > totalStorageQuota) {
            throw new IllegalStateException("Cannot create more directories or exceed storage quota.");
        }
        String directoryName = generateUniqueDirectoryName();
        Files.createDirectory(Paths.get(directoryName));
        directorySizeMap.put(directoryName, sizeLimit);
        return directoryName;
    }

    private String generateUniqueDirectoryName() {
        byte[] randomBytes = new byte[16];
        prng.nextBytes(randomBytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);
    }

    public void deleteDataset(String directoryName) throws IOException {
        if (directorySizeMap.containsKey(directoryName)) {
            Files.walk(Paths.get(directoryName)).sorted(Comparator.reverseOrder()).map(Path::toFile).forEach(File::delete);
            directorySizeMap.remove(directoryName);
        }
    }

    public long getTotalUsedSpace() {
        return directorySizeMap.values().stream().reduce(0L, Long::sum);
    }

    // Additional methods for monitoring, logging, error handling, compression,
    // distributed data processing, concurrent access, real-time adjustments,
    // cloud storage integration, network failure handling, caching, and REST API
}
