        return NULL; // Handle allocation failure
    }
    srand(time(NULL)); // Seed the PRNG for better randomness
    for (int i = 0; i < size; ++i) {
        keys[i] = rand() % range;
        // Simple check to avoid duplicates, not perfect but efficient enough for this task
        for (int j = 0; j < i; ++j) {
            if (keys[j] == keys[i]) {
                --i; // Repeat the iteration
                break;
            }
        }
    }
    return keys;
}

record* allocate_records(int offset_size, int key_size, int range) {
    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = generate_keys(key_size, range);
    if (offsets == NULL || keys == NULL) {
        free(offsets); // Clean up allocated memory on failure
        free(keys);
        return NULL; // Handle allocation failure
    }
    record* records = malloc(key_size * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL; // Handle allocation failure
    }
    for (int i = 0; i < key_size; ++i) {
        records[i].key = keys[i];
        // Initialize other fields of record as needed
    }
    free(offsets); // Free redundant offsets array, not used in final structure
    free(keys);
    return records;
}

void deallocate_records(record* records, int size) {
    free(records);
}
