#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1024

typedef struct {
    int value;
} Record;

typedef struct Node {
    int key;
    Record *record;
    struct Node *next;
} Node;

typedef struct HashTable {
    Node *table[TABLE_SIZE];
    pthread_mutex_t lock;
} HashTable;

void init_hash_table(HashTable *ht) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        ht->table[i] = NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);
}

void insert_record(HashTable *ht, int key, Record *record) {
    pthread_mutex_lock(&ht->lock);
    int index = key % TABLE_SIZE;
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->key = key;
    new_node->record = record;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
    pthread_mutex_unlock(&ht->lock);
}

Record* find_record(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    int index = key % TABLE_SIZE;
    Node *node = ht->table[index];
    while (node != NULL) {
        if (node->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return node->record;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void cleanup_hash_table(HashTable *ht) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node *node = ht->table[i];
        while (node != NULL) {
            Node *temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&ht->lock);
}

void print_largest_integer(int *array, int size) {
    if (size == 0) {
        printf("Array is empty.\n");
        return;
    }
    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

int main() {
    HashTable ht;
    init_hash_table(&ht);

    // Example usage
    int keys[] = {123, 456, 789};
    Record records[3];
    srand(time(NULL));
    for (int i = 0; i < 3; ++i) {
        records[i].value = rand() % 1000 + 1;
        insert_record(&ht, keys[i], &records[i]);
    }

    int *array = (int *)malloc(5 * sizeof(int));
    array[0] = 500;
    array[1] = 200;
    array[2] = 700;
    array[3] = 100;
    array[4] = 800;

    print_largest_integer(array, 5);

    free(array);
    cleanup_hash_table(&ht);

    return 0;
}
