typedef struct {
    int value;
} record;

record* create_initialized_array(size_t size, int min_val, int max_val, unsigned long seed) {
    record* arr = (record*)malloc(size * sizeof(record));
    if (arr == NULL) {
        return NULL; // Memory allocation failed
    }

    if (seed != 0) {
        srand(seed); // Seed the PRNG for consistent results
    } else {
        srand(time(NULL)); // Use current time as a seed
    }

    for (size_t i = 0; i < size; ++i) {
        arr[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    return arr;
}

void free_record_array(record* arr, size_t size) {
    if (arr != NULL) {
        free(arr);
    }
}
