void init_logging_system() {
    events = (Event*)malloc(MAX_EVENTS * sizeof(Event));
    if (!events) {
        fprintf(stderr, "Failed to allocate memory for events\n");
        exit(1);
    }
    memset(events, 0, MAX_EVENTS * sizeof(Event));

    audits = (Audit*)malloc(MAX_AUDITS * sizeof(Audit));
    if (!audits) {
