typedef struct {
    int value;
} record;

struct allocated_memory {
    long *offsets;
    int *keys;
    record *records;
};

struct allocated_memory* allocate_and_initialize_memory(size_t limit, size_t num_records, int min_value, int max_value) {
    if (num_records > limit / sizeof(record)) {
        return NULL; // Not enough space for records
    }

    struct allocated_memory *mem = malloc(sizeof(struct allocated_memory));
    if (!mem) {
        return NULL; // Memory allocation failed
    }

    mem->offsets = malloc(num_records * sizeof(long));
    mem->keys = malloc(num_records * sizeof(int));
    mem->records = malloc(num_records * sizeof(record));

    if (!(mem->offsets && mem->keys && mem->records)) {
        free(mem);
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < num_records; ++i) {
        mem->offsets[i] = i * sizeof(long); // Example initialization of offsets
        mem->keys[i] = rand() % (max_value - min_value + 1) + min_value; // Initialize keys with random values
        mem->records[i].value = mem->keys[i]; // Copy the key value to the record
    }

    long expected_sum = num_records * (min_value + max_value) / 2;
    long actual_sum = 0;
    for (size_t i = 0; i < num_records; ++i) {
        actual_sum += mem->records[i].value;
    }

    if (actual_sum != expected_sum) {
        free(mem->offsets);
        free(mem->keys);
        free(mem->records);
        free(mem);
        return NULL; // Integrity check failed
    }

    return mem;
}

int main() {
    size_t limit = 1024 * 1024; // Example limit of 1MB
    size_t num_records = 1000;
    int min_value = 0, max_value = 99;

    struct allocated_memory *mem = allocate_and_initialize_memory(limit, num_records, min_value, max_value);
    if (mem) {
        printf("Memory allocation and initialization successful.\n");
        // Use the allocated memory here
        free(mem->offsets);
        free(mem->keys);
        free(mem->records);
        free(mem);
    } else {
        printf("Memory allocation or integrity check failed.\n");
    }

    return 0;
}
