// Define the transaction structure
typedef struct {
    double amount;
    char status;
} Transaction;

// Custom PRNG state
unsigned long long prng_state = 1234567890;

// Function to initialize the PRNG with a seed (if needed)
void init_prng(unsigned long long seed) {
    prng_state = seed;
}

// Custom pseudo-random number generator using XORShift
unsigned long long xorshift128plus(void) {
    unsigned long long x = prng_state;
    prng_state ^= x << 23;
    x ^= x >> 17;
    return x += (x << 5);
}

// Function to generate a unique timestamp-based identifier
long generate_timestamp_id(long min, long max) {
    return xorshift128plus() % (max - min + 1) + min;
}

// Function to generate a random key code
int generate_key_code(int min, int max) {
    return xorshift128plus() % (max - min + 1) + min;
}

// Function to generate a transaction record with a random amount and status flag
Transaction generate_transaction(double min_amount, double max_amount, char status_flag[]) {
    Transaction t;
    t.amount = ((xorshift128plus() / (double)RAND_MAX) * (max_amount - min_amount)) + min_amount;
    snprintf(t.status, 2, "%c", status_flag[xorshift128plus() % strlen(status_flag)]);
    return t;
}

// Function to allocate memory for three arrays
int allocate_arrays(long** timestamps, int** keys, Transaction*** transactions, long num_entries) {
    *timestamps = (long*)malloc(num_entries * sizeof(long));
    *keys = (int*)malloc(num_entries * sizeof(int));
    *transactions = (Transaction**)malloc(num_entries * sizeof(Transaction*));

    if (*timestamps == NULL || *keys == NULL || *transactions == NULL) {
        return -1; // Memory allocation failed
    }

    for (long i = 0; i < num_entries; i++) {
        (*transactions)[i] = (Transaction*)malloc(sizeof(Transaction));
        if ((*transactions)[i] == NULL) {
            free(*timestamps);
            free(*keys);
            for (long j = 0; j < i; j++) {
                free((*transactions)[j]);
            }
            free(*transactions);
            return -1; // Memory allocation failed
        }
    }

    return 0; // Allocation successful
}

// Function to initialize arrays with generated values
void initialize_arrays(long** timestamps, int** keys, Transaction*** transactions, long num_entries, long min_id, long max_id, int min_key, int max_key, double min_amount, double max_amount, char status_flag[]) {
    for (long i = 0; i < num_entries; i++) {
        (*timestamps)[i] = generate_timestamp_id(min_id, max_id);
        (*keys)[i] = generate_key_code(min_key, max_key);
        (*transactions)[i] = &generate_transaction(min_amount, max_amount, status_flag);
    }
}

// Function to reset the PRNG state
void reset_prng() {
    prng_state = 1234567890; // Reset to a known initial state
}

int main() {
    long num_entries = 1000;
    long min_id = 1, max_id = 100000;
    int min_key = 10, max_key = 100;
    double min_amount = 0.01, max_amount = 1000.0;
    char status_flag[] = "ABCD";

    long* timestamps;
    int* keys;
    Transaction** transactions;

    if (allocate_arrays(&timestamps, &keys, &transactions, num_entries) == -1) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_arrays(&timestamps, &keys, &transactions, num_entries, min_id, max_id, min_key, max_key, min_amount, max_amount, status_flag);

    // Use the generated arrays here

    // Free allocated memory
    free(timestamps);
    free(keys);
    for (long i = 0; i < num_entries; i++) {
        free(transactions[i]);
    }
    free(transactions);

    return 0;
}
