typedef struct Entry {
    char* str;
    int key;
    long offset;
} Entry;

typedef struct Collection {
    Entry** entries;
    size_t capacity;
    size_t size;
} Collection;

unsigned long customPRNG(unsigned long seed) {
    return seed * 63289UL + 1;
}

Collection* createCollection(size_t initialCapacity) {
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    collection->entries = (Entry**)calloc(initialCapacity, sizeof(Entry*));
    collection->capacity = initialCapacity;
    collection->size = 0;
    return collection;
}

void addEntry(Collection* collection, char* str, int key, long offset) {
    if (collection->size >= collection->capacity) {
        // Resize the collection
        size_t newCapacity = collection->capacity * 2;
        Entry** newEntries = (Entry**)realloc(collection->entries, newCapacity * sizeof(Entry*));
        if (newEntries == NULL) {
            // Handle memory allocation failure gracefully
            return;
        }
        collection->entries = newEntries;
        collection->capacity = newCapacity;
    }

    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->str = str;
    entry->key = key;
    entry->offset = offset;
    collection->entries[collection->size++] = entry;
}

void freeCollection(Collection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->entries[i]);
    }
    free(collection->entries);
    free(collection);
}
