#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Custom PRNG structure
typedef struct {
    uint64_t seed;
} PRNG;

// Initialize PRNG with a given seed
void prng_init(PRNG *prng, uint64_t seed) {
    prng->seed = seed;
}

// Generate the next unique transaction ID using Xorshift PRNG
uint64_t prng_next_transaction_id(PRNG *prng) {
    prng->seed ^= prng->seed >> 12;
    prng->seed ^= prng->seed << 25;
    prng->seed ^= prng->seed >> 27;
    return prng->seed;
}

// Generate random transaction amount between 0.01 and 1000.00
double prng_generate_transaction_amount() {
    static PRNG prng;
    static int initialized = 0;

    if (!initialized) {
        prng_init(&prng, time(NULL));
        initialized = 1;
    }

    return ((double)rand() / RAND_MAX) * 999.99 + 0.01;
}

// Simulate external payment processing service response
int simulate_payment_service(uint64_t transaction_id) {
    // Simulate random delay and success/failure
    int delay = rand() % 50; // Random delay up to 50ms
    usleep(delay * 1000);
    return (rand() % 2 == 0); // Simulate 50% chance of success
}

// Process transaction and handle errors
void process_transaction(PRNG *prng, uint64_t *transaction_id, double *amount) {
    while (1) {
        *transaction_id = prng_next_transaction_id(prng);
        *amount = prng_generate_transaction_amount();

        if (simulate_payment_service(*transaction_id)) {
            printf("Transaction ID: %llu, Amount: %.2f - Success\n", *transaction_id, *amount);
            break;
        } else {
            printf("Transaction ID: %llu, Amount: %.2f - Failed, retrying...\n", *transaction_id, *amount);
        }
    }
}

int main() {
    PRNG prng;
    uint64_t transaction_id;
    double amount;

    prng_init(&prng, time(NULL));

    for (int i = 0; i < 10; i++) {
        process_transaction(&prng, &transaction_id, &amount);
    }

    return 0;
}
