                channel.write(ByteBuffer.wrap(BitConverter.GetBytes(offsets[i].length)));
                for (long offset : offsets[i]) {
                    channel.write(ByteBuffer.wrap(BitConverter.GetBytes(offset)));
                }
                channel.write(ByteBuffer.wrap(BitConverter.GetBytes(records[i].value)));
            }
            channel.close();
        }
    }

