import java.io.File;
import java.io.IOException;
import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class TempDirectoryManager {
    private static final SecureRandom prng = new SecureRandom();
    private final ConcurrentHashMap<String, Long> directoryUsage = new ConcurrentHashMap<>();
    private long totalUsedSpace = 0;
    private final long maxTotalSpace;
    private final int maxDirectories;

    public TempDirectoryManager(long maxTotalSpace, int maxDirectories) {
        this.maxTotalSpace = maxTotalSpace;
        this.maxDirectories = maxDirectories;
    }

    public File createDirectory(String datasetId, long maxSize) throws IOException {
        if (directoryUsage.size() >= maxDirectories) {
            throw new IOException("Maximum number of directories reached.");
        }
        if (totalUsedSpace + maxSize > maxTotalSpace) {
            throw new IOException("Not enough space to create directory for dataset: " + datasetId);
        }

        String dirName = generateUniqueDirName();
        File directory = new File(dirName);
        if (!directory.mkdir()) {
            throw new IOException("Failed to create directory: " + dirName);
        }

        directoryUsage.put(datasetId, maxSize);
        totalUsedSpace += maxSize;
        return directory;
    }

    public void deleteDirectory(String datasetId) throws IOException {
        Long size = directoryUsage.remove(datasetId);
        if (size == null) {
            throw new IOException("No directory found for dataset: " + datasetId);
        }
        File directory = new File(datasetId);
        if (!deleteRecursively(directory)) {
            throw new IOException("Failed to delete directory: " + datasetId);
        }

        totalUsedSpace -= size;
    }

    public void updateDirectorySize(String datasetId, long newSize) throws IOException {
        Long oldSize = directoryUsage.get(datasetId);
        if (oldSize == null) {
            throw new IOException("No directory found for dataset: " + datasetId);
        }
        if (totalUsedSpace - oldSize + newSize > maxTotalSpace) {
            throw new IOException("Not enough space to update directory size for dataset: " + datasetId);
        }

        directoryUsage.put(datasetId, newSize);
        totalUsedSpace -= oldSize;
        totalUsedSpace += newSize;
    }

    public long getDirectoryUsage(String datasetId) {
        return directoryUsage.getOrDefault(datasetId, 0L);
    }

    private String generateUniqueDirName() {
        byte[] bytes = new byte[16];
        prng.nextBytes(bytes);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return "tmp_" + sb.toString();
    }

    private boolean deleteRecursively(File directory) {
        if (!directory.isDirectory()) {
            return directory.delete();
        }
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (!deleteRecursively(file)) {
                    return false;
                }
            }
        }
        return directory.delete();
    }

    public void logUsage() {
        System.out.println("Total used space: " + totalUsedSpace);
        System.out.println("Directory usage:");
        for (ConcurrentHashMap.Entry<String, Long> entry : directoryUsage.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }

    public static void main(String[] args) throws IOException {
        TempDirectoryManager manager = new TempDirectoryManager(1024 * 1024 * 1024, 10); // 1GB total space, max 10 directories
        File dir1 = manager.createDirectory("dataset1", 512 * 1024 * 1024); // Create a directory for dataset1 with size 512MB
        System.out.println("Directory created: " + dir1.getAbsolutePath());

        long usage = manager.getDirectoryUsage("dataset1");
        System.out.println("Dataset1 usage: " + usage);

        manager.updateDirectorySize("dataset1", 768 * 1024 * 1024); // Update size to 768MB
        System.out.println("Updated dataset1 usage: " + manager.getDirectoryUsage("dataset1"));

        manager.deleteDirectory("dataset1"); // Delete the directory for dataset1
        System.out.println("Dataset1 directory deleted.");

        manager.logUsage();
    }
}
