void ensure_uniqueness(int* keys, int* values, int count) {
    for (int i = 0; i < count; i++) {
        while (i != 0 && keys[i] == keys[i-1]) {
            keys[i] = rand() % 4096;
        }
        for (int j = 0; j < i; j++) {
            if (values[i] == values[j]) {
                values[i] = rand() % 10000;
                j = -1; // Restart the loop
            }
        }
    }
}

