void initArrays(long** offsets, int** keys, size_t numRecords) {
    *offsets = (long*)malloc(numRecords * sizeof(long));
    *keys = (int*)malloc(numRecords * sizeof(int));

    // Initialize with unique keys and offsets
    for (size_t i = 0; i < numRecords; ++i) {
        (*keys)[i] = i % 1024; // Unique key less than 1024
        (*offsets)[i] = i * sizeof(long); // Example offset calculation
    }
}

// Function to initialize record array with random values
void initRecords(Record* records, size_t numRecords) {
    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < numRecords; ++i) {
        int value;
        do {
            value = rand() % 1001; // Random integer between 1 and 1000
        } while (isDuplicate(records, numRecords, value));
        records[i].value = value;
    }
}

// Function to check for duplicate values in records
int isDuplicate(Record* records, size_t numRecords, int value) {
    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i].value == value) return 1;
    }
    return 0;
}

// Function to generate random numbers using a selected PRNG
int generateRandomNumber(int min, int max) {
    return rand() % (max - min + 1) + min; // Random number between min and max
}

// Function to simulate high load conditions
void simulateHighLoad(Record* records, size_t numRecords, int iterations) {
    for (int i = 0; i < iterations; ++i) {
        for (size_t j = 0; j < numRecords; ++j) {
            // Simulate usage of records
            records[j].value = generateRandomNumber(1, 1000);
        }
    }
}

