typedef struct {
    int field;
} record;

unsigned long xorshift128plus(unsigned long *x, unsigned long *y) {
    static const unsigned long mask = 0xFFFFFFFFFFFFFFFFUL;
    unsigned long s0 = *x;
    unsigned long s1 = *y;
    unsigned long result = (s0 + s1) & mask;
    s0 ^= s1;
    s1 = (s1 << 24u) | (s1 >> 8u);
    s1 ^= s0 ^ (s0 << 31u);
    *x = s0;
    *y = s1;
    return result;
}

void allocate_and_initialize(int count, int min_val, int max_val, long **offsets, int **keys, record **records) {
    if (count <= 0 || min_val >= max_val) {
        fprintf(stderr, "Invalid input values.\n");
        exit(EXIT_FAILURE);
    }

    *offsets = (long *)malloc(count * sizeof(long));
    *keys = (int *)malloc(count * sizeof(int));
    *records = (record *)malloc(count * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    unsigned long seed[2] = {time(NULL), clock()};
    for (int i = 0; i < count; ++i) {
        (*keys)[i] = xorshift128plus(&seed[0], &seed[1]) % (max_val - min_val + 1) + min_val;
        (*records)[i].field = xorshift128plus(&seed[0], &seed[1]) % (max_val - min_val + 1) + min_val;
    }

    // Simulate some offset calculation
    for (int i = 0; i < count; ++i) {
        (*offsets)[i] = i * 8; // Example offset calculation
    }
}

void free_all(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
