typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int used_keys[1024];
} data_storage;

data_storage* create_data_storage(size_t initial_capacity) {
    data_storage *storage = (data_storage*)malloc(sizeof(data_storage));
    storage->offsets = (long*)malloc(initial_capacity * sizeof(long));
    storage->keys = (int*)malloc(initial_capacity * sizeof(int));
    storage->records = (record*)malloc(initial_capacity * sizeof(record));
    storage->capacity = initial_capacity;
    pthread_mutex_init(&storage->mutex, NULL);
    pthread_cond_init(&storage->cond, NULL);
    for (int i = 0; i < 1024; i++) {
        storage->used_keys[i] = 0;
    }
    srand(time(NULL));
    return storage;
}

void destroy_data_storage(data_storage *storage) {
    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    pthread_mutex_destroy(&storage->mutex);
    pthread_cond_destroy(&storage->cond);
    free(storage);
}

int add_record(data_storage *storage, int value) {
    pthread_mutex_lock(&storage->mutex);
    while (1) {
        int key = rand() % 1024;
        if (!storage->used_keys[key]) {
            storage->used_keys[key] = 1;
            break;
        }
    }
    size_t index = storage->capacity++;
    storage->offsets[index] = key * sizeof(int);
    storage->keys[index] = key;
    storage->records[index].value = value;
    pthread_mutex_unlock(&storage->mutex);
    return index;
}

void* thread_func(void *arg) {
    data_storage *storage = (data_storage*)arg;
    int value = rand() % 1001 + 1; // Random between 1 and 1000
    add_record(storage, value);
    return NULL;
}

int main() {
    data_storage *storage = create_data_storage(10);
    pthread_t threads[20];
    for (int i = 0; i < 20; i++) {
        pthread_create(&threads[i], NULL, thread_func, storage);
    }
    for (int i = 0; i < 20; i++) {
        pthread_join(threads[i], NULL);
    }
    destroy_data_storage(storage);
    return 0;
}
