#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct Record {
    int key;
    int value;
} Record;

typedef struct HashTable {
    Record *table[TABLE_SIZE];
    pthread_mutex_t mutexes[TABLE_SIZE];
} HashTable;

HashTable* create_hash_table() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    for (int i = 0; i < TABLE_SIZE; ++i) {
        ht->table[i] = NULL;
        pthread_mutex_init(&ht->mutexes[i], NULL);
    }
    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Record *record = ht->table[i];
        while (record != NULL) {
            Record *next = record->next;
            free(record);
            record = next;
        }
        pthread_mutex_destroy(&ht->mutexes[i]);
    }
    free(ht);
}

void insert_record(HashTable *ht, int key, int value) {
    int index = key % TABLE_SIZE;
    pthread_mutex_lock(&ht->mutexes[index]);
    Record *record = ht->table[index];
    if (record == NULL) {
        record = (Record*)malloc(sizeof(Record));
        record->key = key;
        record->value = value;
        record->next = NULL;
        ht->table[index] = record;
    } else {
        // Handle collision using chaining
        Record *prev = NULL;
        while (record != NULL) {
            if (record->key == key) {
                // Key already exists, update value
                record->value = value;
                break;
            }
            prev = record;
            record = record->next;
        }
        if (record == NULL) {
            record = (Record*)malloc(sizeof(Record));
            record->key = key;
            record->value = value;
            record->next = NULL;
            prev->next = record;
        }
    }
    pthread_mutex_unlock(&ht->mutexes[index]);
}

int lookup_record(HashTable *ht, int key) {
    int index = key % TABLE_SIZE;
    pthread_mutex_lock(&ht->mutexes[index]);
    Record *record = ht->table[index];
    while (record != NULL) {
        if (record->key == key) {
            pthread_mutex_unlock(&ht->mutexes[index]);
            return record->value;
        }
        record = record->next;
    }
    pthread_mutex_unlock(&ht->mutexes[index]);
    return -1; // Key not found
}

void remove_record(HashTable *ht, int key) {
    int index = key % TABLE_SIZE;
    pthread_mutex_lock(&ht->mutexes[index]);
    Record *record = ht->table[index];
    Record *prev = NULL;
    while (record != NULL) {
        if (record->key == key) {
            if (prev == NULL) {
                ht->table[index] = record->next;
            } else {
                prev->next = record->next;
            }
            free(record);
            break;
        }
        prev = record;
        record = record->next;
    }
    pthread_mutex_unlock(&ht->mutexes[index]);
}

int main() {
    HashTable *ht = create_hash_table();
    insert_record(ht, 123, 456);
    printf("Value for key 123: %d\n", lookup_record(ht, 123));
    remove_record(ht, 123);
    printf("Value for key 123 after removal: %d\n", lookup_record(ht, 123));
    destroy_hash_table(ht);
    return 0;
}
