} key_value_store;

key_value_store *create_key_value_store(size_t initial_size) {
    key_value_store *store = (key_value_store *)malloc(sizeof(key_value_store));
    if (!store) return NULL;

    store->offsets = (long *)malloc(initial_size * sizeof(long));
    store->keys = (int *)malloc(initial_size * sizeof(int));
    store->offsets_size = 0;
    store->keys_size = 0;
    store->max_size = initial_size;

    if (!store->offsets || !store->keys) {
        free(store->offsets);
        free(store->keys);
        free(store);
        return NULL;
    }

    return store;
}

void destroy_key_value_store(key_value_store *store) {
    if (store) {
        free(store->offsets);
        free(store->keys);
        free(store);
    }
}

int is_key_used(int key, int *used_keys, size_t used_size) {
    for (size_t i = 0; i < used_size; ++i) {
        if (used_keys[i] == key) return 1;
    }
    return 0;
}

int add_new_key(key_value_store *store, int new_key, int **used_keys, size_t *used_size, size_t *max_used_size) {
    if (is_key_used(new_key, *used_keys, *used_size)) return -1;

    if (*used_size == *max_used_size) {
        *max_used_size *= 2;
        int *new_used_keys = realloc(*used_keys, *max_used_size * sizeof(int));
        if (!new_used_keys) return -1;
        *used_keys = new_used_keys;
    }

    (*used_keys)[*used_size] = new_key;
    ++(*used_size);
    return 0;
}

double generate_random_amount() {
    static int seeded = 0;
    if (!seeded) {
        srand(time(NULL));
        seeded = 1;
    }
    return (double(rand()) / RAND_MAX) * 999.0 + 1.0;
}

transaction *generate_transactions(key_value_store *store, size_t count, int **used_keys, size_t *used_size, size_t *max_used_size) {
    if (count > store->max_size - store->offsets_size) return NULL;

    transaction *transactions = (transaction *)malloc(count * sizeof(transaction));
    if (!transactions) return NULL;

    for (size_t i = 0; i < count; ++i) {
        int new_key;
        do {
            new_key = rand() % MAX_KEYS;
        } while (is_key_used(new_key, *used_keys, *used_size));

        if (add_new_key(store, new_key, used_keys, used_size, max_used_size) != 0) {
            free(transactions);
            return NULL;
        }

        transactions[i].amount = generate_random_amount();
        snprintf(transactions[i].description, sizeof(transactions[i].description), "Transaction %zu", i + 1);
    }

    store->offsets_size += count;
    store->keys_size += count;

    return transactions;
}

int main() {
