    size_t used_size = 0;
    size_t max_used_size = MAX_KEYS;

    transaction *transactions = generate_transactions(store, 50, &used_keys, &used_size, &max_used_size);
    if (!transactions) {
        fprintf(stderr, "Failed to generate transactions\n");
        destroy_key_value_store(store);
        free(used_keys);
        return 1;
    }

