pthread_mutex_t transaction_lock = PTHREAD_MUTEX_INITIALIZER;
long used_keys[MAX_KEYS] = {0};
long used_transactions[MAX_TRANSACTIONS] = {0};

int validate_key(int key) {
    pthread_mutex_lock(&key_lock);
    if (used_keys[key]) {
        pthread_mutex_unlock(&key_lock);
        return 0; // Key already in use
    }
    used_keys[key] = 1;
    pthread_mutex_unlock(&key_lock);
    return 1;
}

long generate_random_amount() {
