    static long seed = time(NULL);
    seed = (seed * 25214903917 + 11) % 2147483647;
    return 1 + seed % 10000;
}

void process_transaction(int key, Transaction transaction) {
    pthread_mutex_lock(&transaction_lock);
    if (used_transactions[transaction.amount]) {
        pthread_mutex_unlock(&transaction_lock);
        printf("Transaction amount already used\n");
        return;
    }
    used_transactions[transaction.amount] = 1;
    // Simulate processing the transaction
    printf("Processing transaction %c with amount %ld for key %d\n", transaction.operation, transaction.amount, key);
    pthread_mutex_unlock(&transaction_lock);
}

