        return NULL;
    }

    Transaction transaction;
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transaction.operation = 'D'; // Assuming deposit operation
        transaction.amount = generate_random_amount();
        process_transaction(key, transaction);
    }

    pthread_mutex_lock(&key_lock);
    used_keys[key] = 0;
    pthread_mutex_unlock(&key_lock);

    return NULL;
}

int main() {
    int keys[MAX_KEYS];
    for (int i = 0; i < MAX_KEYS; i++) {
        keys[i] = i % MAX_KEYS; // Example key values
    }

    pthread_t threads[MAX_KEYS];
    for (int i = 0; i < MAX_KEYS; i++) {
        int* key_ptr = malloc(sizeof(int));
        *key_ptr = keys[i];
        pthread_create(&threads[i], NULL, payment_processing, key_ptr);
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    pthread_mutex_destroy(&key_lock);
    pthread_mutex_destroy(&transaction_lock);

    return 0;
}
