['```java
import java.security.SecureRandom;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class SessionManagementService {
    private static final SecureRandom secureRandom = new SecureRandom();
    private Map<String, SessionData> sessionStore = new HashMap<>();
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public String createSession(User user) {
        String sessionId = generateUniqueId();
        sessionStore.put(sessionId, new SessionData(user));
        return sessionId;
    }

    public SessionData getSession(String sessionId) {
        return sessionStore.get(sessionId);
    }

    private String generateUniqueId() {
        byte[] bytes = new byte[16];
        secureRandom.nextBytes(bytes);
        return bytesToHex(bytes);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void startSessionCleanup() {
        scheduler.scheduleAtFixedRate(() -> {
            long currentTime = System.currentTimeMillis();
            sessionStore.values().removeIf(session -> currentTime - session.getLastAccessTime() > 3600 * 1000);
        }, 5, 5, TimeUnit.MINUTES);
    }

    public void stopSessionCleanup() {
        scheduler.shutdownNow();
    }

    // Nested class to hold session data
    public static class SessionData {
        private User user;
        private long lastAccessTime;

        public SessionData(User user) {
            this.user = user;
            updateLastAccessTime();
        }

        public void updateLastAccessTime() {
            lastAccessTime = System.currentTimeMillis();
        }

        // Getters for session data
        public User getUser() {
            return user;
        }

        public long getLastAccessTime() {
            return lastAccessTime;
        }
    }

    // Placeholder class for user information
    public static class User {
        private String username;
        private String permissions;

        public User(String username, String permissions) {
            this.username = username;
            this.permissions = permissions;
        }

        // Getters for user data
        public String getUsername() {
            return username;
        }

        public String getPermissions() {
            return permissions;
        }
    }

    public static void main(String[] args) {
        SessionManagementService sessionManager = new SessionManagementService();
        User user = new User("john_doe", "admin");
        String sessionId = sessionManager.createSession(user);
        System.out.println("Created session ID: " + sessionId);

        SessionData sessionData = sessionManager.getSession(sessionId);
        if (sessionData != null) {
            System.out.println("User: " + sessionData.getUser().getUsername() + ", Permissions: " + sessionData.getUser().getPermissions());
        } else {
            System.out.println("Session not found.");
        }

        sessionManager.startSessionCleanup();
    }
}
