import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Scanner;

public class DistributedStorage {

    private static final int MAX_RECORDS = 10_000_000;
    private static final int KEY_RANGE = 1000;
    private static HashSet<Integer> usedKeys = new HashSet<>();
    private static Random random = new SecureRandom();
    private static SocketChannel channel;

    public static void main(String[] args) {
        try {
            connectToRemote("remote_address", 12345);
            int[] records = readRecordsFromInput();
            storeRecords(records);
            findAndPrintLargestInteger(records);
        } catch (IOException e) {
            System.err.println("Error occurred: " + e.getMessage());
            // Clean up resources
            cleanupResources();
        }
    }

    private static void connectToRemote(String address, int port) throws IOException {
        channel = SocketChannel.open(new InetSocketAddress(address, port));
        // Ensure non-blocking mode or handle blocking as needed
    }

    private static int[] readRecordsFromInput() {
        Scanner scanner = new Scanner(System.in);
        List<Integer> integers = scanner.useDelimiter("\\D").tokens().map(Integer::parseInt).collect(Collectors.toList());
        return integers.stream().mapToInt(i -> i).toArray();
    }

    private static void storeRecords(int[] records) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(records.length * 12); // Assuming int is 4 bytes, long is 8 bytes
        for (int record : records) {
            buffer.putInt(record);
            buffer.putLong(random.nextLong()); // Generate a random offset value
            buffer.putInt(random.nextInt(KEY_RANGE));
        }
        buffer.flip();
        channel.write(buffer);
    }

    private static void findAndPrintLargestInteger(int[] records) {
        Arrays.sort(records);
        System.out.println("Largest integer: " + records[records.length - 1]);
    }

    private static void cleanupResources() {
        if (channel != null && channel.isOpen()) {
            try {
                channel.close();
            } catch (IOException e) {
                System.err.println("Error closing channel: " + e.getMessage());
            }
        }
        usedKeys.clear();
        // Clean up other resources as needed
    }

    private static int generateUniqueKey() {
        int key;
        do {
            key = random.nextInt(KEY_RANGE);
        } while (usedKeys.contains(key));
        usedKeys.add(key);
        return key;
    }
}
