#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1024
#define ID_RANGE 1000000

typedef struct {
    unsigned long id;
    char ref_num[50];
    int amount;
} Transaction;

typedef struct {
    long* transaction_ids;
    char** user_names;
    Transaction* transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} Database;

unsigned long generate_id() {
    // Implement a custom PRNG for unique transaction IDs
    static unsigned long seed = 123456789;
    seed = seed * 1103515245 + 12345; // LCG
    return seed % ID_RANGE;
}

void initialize_database(Database* db) {
    pthread_mutex_init(&db->lock, NULL);
    db->transaction_ids = malloc(MAX_RECORDS * sizeof(long));
    db->user_names = malloc(MAX_RECORDS * sizeof(char*));
    db->transactions = malloc(MAX_RECORDS * sizeof(Transaction));
    if (db->transaction_ids == NULL || db->user_names == NULL || db->transactions == NULL) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    db->count = 0;
    db->capacity = MAX_RECORDS;
}

void add_transaction(Database* db, char* user_name, int amount) {
    pthread_mutex_lock(&db->lock);

    if (db->count >= db->capacity) {
        // Dynamically resize arrays
        size_t new_capacity = db->capacity * 2;
        long* new_ids = realloc(db->transaction_ids, new_capacity * sizeof(long));
        char** new_names = realloc(db->user_names, new_capacity * sizeof(char*));
        Transaction* new_transactions = realloc(db->transactions, new_capacity * sizeof(Transaction));
        if (new_ids == NULL || new_names == NULL || new_transactions == NULL) {
            // Handle allocation failure
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
        db->transaction_ids = new_ids;
        db->user_names = new_names;
        db->transactions = new_transactions;
        db->capacity = new_capacity;
    }

    Transaction* new_transaction = &db->transactions[db->count];
    new_transaction->id = generate_id();
    snprintf(new_transaction->ref_num, sizeof(new_transaction->ref_num), "%lu", new_transaction->id);
    new_transaction->amount = amount;

    db->user_names[db->count] = strdup(user_name);
    if (db->user_names[db->count] == NULL) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation for user name failed\n");
        exit(1);
    }

    db->count++;
    pthread_mutex_unlock(&db->lock);
}

void free_database(Database* db) {
    pthread_mutex_lock(&db->lock);

    for (size_t i = 0; i < db->count; i++) {
        free(db->user_names[i]);
    }
    free(db->transaction_ids);
    free(db->user_names);
    free(db->transactions);
    pthread_mutex_unlock(&db->lock);
}

int main() {
    Database db;
    initialize_database(&db);

    add_transaction(&db, "JohnDoe", 100);
    add_transaction(&db, "JaneSmith", 200);

    free_database(&db);

    return 0;
}
