import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RemoteConnectionManager {

    private static final int MAX_KEYS = 1024;
    private static final SecureRandom random = new SecureRandom();
    private static final Map<Integer, Record> records = new ConcurrentHashMap<>();
    private static final List<Integer> usedKeys = Collections.synchronizedList(new ArrayList<>());

    public void establishConnection(String host, int port) throws IOException {
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.connect(new InetSocketAddress(host, port));

        Selector selector = Selector.open();
        channel.register(selector, SelectionKey.OP_CONNECT);

        while (true) {
            selector.select();
            for (SelectionKey key : selector.selectedKeys()) {
                if (key.isConnectable()) {
                    finishConnection(key, channel);
                }
            }
        }
    }

    private void finishConnection(SelectionKey key, SocketChannel channel) throws IOException {
        if (channel.finishConnect()) {
            ByteBuffer buffer = ByteBuffer.allocate(Long.BYTES + Integer.BYTES);
            long offset = generateRandomOffset();
            int key = generateUniqueKey();

            records.put(key, new Record(generateRandomValue()));
            usedKeys.add(key);

            buffer.putLong(offset);
            buffer.putInt(key);
            channel.write(buffer);
        }
    }

    private long generateRandomOffset() {
        return random.nextLong();
    }

    private int generateUniqueKey() throws IOException {
        int key;
        do {
            key = random.nextInt(MAX_KEYS);
        } while (usedKeys.contains(key));
        return key;
    }

    private int generateRandomValue() {
        return random.nextInt(1000) + 1;
    }

    public void cleanup() {
        records.clear();
        usedKeys.clear();
    }

    // Additional methods for error handling, logging, and microservices integration would be implemented here.
}

class Record {
    private final int value;

    public Record(int value) {
        this.value = value;
    }

    public int getValue() {
        return value;
    }
}
