#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

// Custom pseudo-random number generator (PRNG)
int custom_prng(int seed, int range) {
    return ((seed * 214013 + 2531011) % 65536) % range;
}

void manage_memory(int pool_size, int num_records, long **offsets, int **keys, Record **records) {
    if (pool_size < sizeof(long) * num_records + sizeof(int) * num_records + sizeof(Record) * num_records) {
        fprintf(stderr, "Insufficient memory in the pool.\n");
        return;
    }

    // Allocate memory from the specified pool
    char *pool = (char *)malloc(pool_size);
    if (!pool) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Initialize PRNG seed
    srand(time(NULL));

    *offsets = (long *)pool;
    *keys = (int *)(pool + sizeof(long) * num_records);
    *records = (Record *)(pool + sizeof(long) * num_records + sizeof(int) * num_records);

    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = i * 10; // Example offset calculation
        (*keys)[i] = custom_prng(i, range); // Initialize key with a uniform distribution
        (*records)[i].value = custom_prng(i, 100); // Initialize record value with a uniform distribution within range [0, 99]
    }

    printf("Memory management successful.\n");
}

int main() {
    int pool_size = 1024 * 1024; // 1 MB
    int num_records = 100;
    int range = 100;

    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    manage_memory(pool_size, num_records, &offsets, &keys, &records);

    free(offsets); // Free allocated memory when done

    return 0;
}
