#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    long *offsets;
    int *keys;
    record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->offsets = calloc(initial_capacity, sizeof(long));
    pool->keys = calloc(initial_capacity, sizeof(int));
    pool->records = calloc(initial_capacity, sizeof(record *));
    if (pool->offsets == NULL || pool->keys == NULL || pool->records == NULL) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool == NULL) return;

    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->records[i]);
    }

    free(pool->offsets);
    free(pool->keys);
    free(pool->records);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int resize_memory_pool(MemoryPool *pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return -1;

    long *new_offsets = reallocarray(pool->offsets, new_capacity, sizeof(long));
    int *new_keys = reallocarray(pool->keys, new_capacity, sizeof(int));
    record **new_records = reallocarray(pool->records, new_capacity, sizeof(record *));
    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        return -1;
    }

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->records = new_records;

    pthread_mutex_lock(&pool->lock);
    pool->capacity = new_capacity;
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

int add_record(MemoryPool *pool, long offset, int key, record *rec) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity && resize_memory_pool(pool, pool->capacity * 2) != 0) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->offsets[pool->size] = offset;
    pool->keys[pool->size] = key;
    pool->records[pool->size++] = rec;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void *performance_test_thread(void *arg) {
    MemoryPool *pool = (MemoryPool *) arg;
    // Perform statistical test and decide on PRNG switch
    return NULL;
}

int main() {
    MemoryPool *pool = create_memory_pool(1024);
    if (pool == NULL) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    pthread_t test_thread;
    pthread_create(&test_thread, NULL, performance_test_thread, pool);

    record *rec = malloc(sizeof(record));
    if (add_record(pool, 42, 7, rec) != 0) {
        fprintf(stderr, "Failed to add record\n");
        destroy_memory_pool(pool);
        return 1;
    }

    pthread_join(test_thread, NULL);
    destroy_memory_pool(pool);

    free(rec);
    return 0;
}
```

This code snippet provides a basic structure for a multi-threaded memory pool management system in C. It includes functions to create and destroy the memory pool, resize it dynamically, add records, and perform a performance test asynchronously. The actual implementation of the PRNG and statistical test is left as an exercise for the junior developer to complete based on their understanding of randomness and concurrent programming.']

