#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define POOL_SIZE 1024

typedef struct {
    int user_id;
    time_t expiration_timestamp;
    unsigned long session_token;
} Session;

Session memory_pool[POOL_SIZE];
int pool_index = 0;

// Custom PRNG function
unsigned long custom_prng() {
    static unsigned long seed = 0xdeadbeef;
    seed ^= seed << 13;
    seed ^= seed >> 7;
    seed ^= seed << 17;
    return seed;
}

Session* create_session(int user_id, time_t expiration_timestamp) {
    if (pool_index >= POOL_SIZE) {
        printf("Memory pool is exhausted.\n");
        return NULL;
    }
    Session* session = &memory_pool[pool_index++];
    session->user_id = user_id;
    session->expiration_timestamp = expiration_timestamp;
    session->session_token = custom_prng();
    return session;
}

void destroy_session(Session* session) {
    if (session >= memory_pool && session < &memory_pool[POOL_SIZE]) {
        // Reset the session fields to prevent dangling pointers
        session->user_id = -1;
        session->expiration_timestamp = 0;
        session->session_token = 0;
        pool_index--;
    }
}

int main() {
    srand(time(NULL)); // Seed for PRNG

    time_t now = time(NULL);
    Session* session = create_session(12345, now + 3600); // Example user ID and expiration
    if (session != NULL) {
        printf("Session created with token: %lu\n", session->session_token);
        destroy_session(session);
    }

    return 0;
}
```

