import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class DataProcessingPipeline {
    private static final int COOLDOWN_PERIOD = 100; // milliseconds
    private static SecureRandom secureRandom = new SecureRandom();
    private ConcurrentHashMap<String, DataUnit> dataUnits = new ConcurrentHashMap<>();
    private AtomicInteger lastActionIndex = new AtomicInteger(0);

    public void processDataStream(DataStream stream) {
        if (stream == null || stream.isEmpty()) {
            System.err.println("Invalid or empty data stream received.");
            return;
        }

        for (DataUnit unit : stream.getUnits()) {
            try {
                handleDataUnit(unit);
            } catch (Exception e) {
                System.err.println("Failed to process data unit: " + e.getMessage());
            }
        }
    }

    private void handleDataUnit(DataUnit unit) throws Exception {
        String uniqueId = generateUniqueId();
        if (!dataUnits.containsKey(uniqueId)) {
            unit.setRandomValue(secureRandom.nextDouble());
            unit.setStatusIndicator(Status.REGISTERED);
            dataUnits.put(uniqueId, unit);

            if (shouldInvokeCooldown()) {
                invokeAction(unit.getTimestamp(), unit.getRandomValue());
            }
        } else {
            System.err.println("Duplicate data unit detected with ID: " + uniqueId);
        }
    }

    private String generateUniqueId() {
        return Long.toString(System.currentTimeMillis(), 36) + secureRandom.nextInt(1000);
    }

    private boolean shouldInvokeCooldown() {
        long currentTime = System.currentTimeMillis();
        if (currentTime % COOLDOWN_PERIOD == 0) {
            lastActionIndex.incrementAndGet();
            return true;
        }
        return false;
    }

    private void invokeAction(long timestamp, double randomValue) throws Exception {
        int actionIndex = Math.abs(lastActionIndex.get()) % 2;
        if (actionIndex == 0) {
            performActionA(timestamp, randomValue);
        } else {
            performActionB(timestamp, randomValue);
        }
    }

    private void performActionA(long timestamp, double randomValue) throws Exception {
        // Logic for action A
    }

    private void performActionB(long timestamp, double randomValue) throws Exception {
        // Logic for action B
    }

    public void releaseResources() {
        dataUnits.clear();
        secureRandom = null;
    }
}

class DataStream {
    private List<DataUnit> units;

    public DataStream(List<DataUnit> units) {
        this.units = units;
    }

    public boolean isEmpty() {
        return units == null || units.isEmpty();
    }

    public List<DataUnit> getUnits() {
        return units;
    }
}

class DataUnit {
    private long timestamp;
    private double randomValue;
    private Status statusIndicator;

    public DataUnit(long timestamp) {
        this.timestamp = timestamp;
    }

    public void setRandomValue(double randomValue) {
        this.randomValue = randomValue;
    }

    public void setStatusIndicator(Status statusIndicator) {
        this.statusIndicator = statusIndicator;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public double getRandomValue() {
        return randomValue;
    }
}

enum Status {
    REGISTERED,
    PROCESSED
}
