import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Server {

    private static final int MAX_CONNECTIONS = 1000;
    private static final int KEY_RANGE = 1024;
    private Set<Integer> usedKeys;
    private ExecutorService executorService;
    private AsynchronousServerSocketChannel serverSocketChannel;

    public void start() throws IOException {
        usedKeys = new HashSet<>();
        executorService = Executors.newFixedThreadPool(MAX_CONNECTIONS);
        serverSocketChannel = AsynchronousServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress("localhost", 8080));
        acceptConnections();
    }

    private void acceptConnections() {
        while (true) {
            Future<AsynchronousSocketChannel> future = serverSocketChannel.accept();
            try {
                AsynchronousSocketChannel clientChannel = future.get();
                executorService.submit(() -> handleClient(clientChannel));
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }
    }

    private void handleClient(AsynchronousSocketChannel clientChannel) {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        try {
            while (clientChannel.read(buffer).get() != -1) {
                // Handle client data
            }
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            try {
                clientChannel.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public void stop() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        try {
            serverSocketChannel.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) throws IOException {
        Server server = new Server();
        server.start();
    }
}
