struct RecordStore {
    record* records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
};

void initRecordStore(struct RecordStore* store, size_t initial_capacity) {
    store->records = (record*)malloc(initial_capacity * sizeof(record));
    if (!store->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    store->count = 0;
    store->capacity = initial_capacity;
    pthread_mutex_init(&store->lock, NULL);
}

void freeRecordStore(struct RecordStore* store) {
    pthread_mutex_destroy(&store->lock);
    free(store->records);
}

int addRandomRecord(struct RecordStore* store, long offset) {
    pthread_mutex_lock(&store->lock);

    if (store->count == store->capacity) {
        size_t new_capacity = store->capacity * 2;
        record* new_records = (record*)realloc(store->records, new_capacity * sizeof(record));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&store->lock);
            return -1;
        }
        store->records = new_records;
        store->capacity = new_capacity;
    }

    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (key < 0 || key >= MAX_KEYS);

    store->records[store->count].offset = offset;
    store->records[store->count].key = key;
    store->count++;

    pthread_mutex_unlock(&store->lock);
    return 0;
}

int main() {
    srand(time(NULL));
    struct RecordStore record_store;
    initRecordStore(&record_store, 16);

