// Define constants
#define MAX_KEYS 1024

// Define data structure for key-value pairs
typedef struct {
    int key;
    long offset;
} KeyValuePair;

// Define global variables
KeyValuePair *keyValuePairs = NULL;
int numKeys = 0;

// Function to generate a cryptographically strong pseudo-random number
int generateKey() {
    static int seed = time(NULL);
    seed = (seed * 134775813 + 12345) % MAX_KEYS;
    return seed;
}

// Function to add a key-value pair to the data structure
void addKeyValue(int key, long offset) {
    if (numKeys >= MAX_KEYS) {
        printf("Error: Maximum number of keys reached\n");
        return;
    }
    keyValuePairs[numKeys].key = key;
    keyValuePairs[numKeys].offset = offset;
    numKeys++;
}

// Function to find the largest integer in the input list
int findLargestInteger() {
    if (numKeys == 0) {
        printf("Error: No keys found\n");
        return -1;
    }
    int largest = keyValuePairs[0].key;
    for (int i = 1; i < numKeys; i++) {
        if (keyValuePairs[i].key > largest) {
            largest = keyValuePairs[i].key;
        }
    }
    return largest;
}

// Function to safely release allocated memory
void freeMemory() {
    if (keyValuePairs != NULL) {
        free(keyValuePairs);
        keyValuePairs = NULL;
        numKeys = 0;
    }
}

