        printf("Enter key %d and offset: ", i + 1);
        scanf("%d %ld", &key, &offset);
        addKeyValue(key, offset);
    }

    // Find and print the largest integer from the input list
    int largest = findLargestInteger();
    if (largest != -1) {
        printf("The largest integer is: %d\n", largest);
    }

    // Free allocated memory
    freeMemory();

    return 0;
}
