typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    pthread_mutex_t lock;
    int size;
    int capacity;
} shared_resource;

shared_resource *init_shared_resource(int initial_capacity) {
    shared_resource *res = (shared_resource *)malloc(sizeof(shared_resource));
    if (!res) return NULL;

    res->offsets = (long *)calloc(initial_capacity, sizeof(long));
    res->keys = (int *)calloc(initial_capacity, sizeof(int));
    pthread_mutex_init(&res->lock, NULL);
    res->size = 0;
    res->capacity = initial_capacity;

    if (!res->offsets || !res->keys) {
        free(res);
        return NULL;
    }

    return res;
}

int add_key(shared_resource *res, int key) {
    pthread_mutex_lock(&res->lock);
    for (int i = 0; i < res->size; i++) {
        if (res->keys[i] == key) {
            pthread_mutex_unlock(&res->lock);
            return -1;
        }
    }
    if (res->size >= res->capacity) {
        res->offsets = realloc(res->offsets, sizeof(long) * res->capacity * 2);
        res->keys = realloc(res->keys, sizeof(int) * res->capacity * 2);
        if (!res->offsets || !res->keys) {
            pthread_mutex_unlock(&res->lock);
            return -1;
        }
        res->capacity *= 2;
    }
    res->keys[res->size++] = key;
    pthread_mutex_unlock(&res->lock);
    return 0;
}

record *generate_records(shared_resource *res, int count, long seed, int range) {
    record *records = (record *)malloc(sizeof(record) * count);
    if (!records) return NULL;

    srand(seed);
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % range;
    }

    return records;
}

void cleanup(shared_resource *res, record *records) {
    pthread_mutex_destroy(&res->lock);
    free(res->offsets);
    free(res->keys);
    free(records);
}
