        identifiers[i].id = -1;
        memset(identifiers[i].offsets, 0, sizeof(OffsetStruct*) * MAX_IDENTIFIER_LENGTH);
    }
    return 0;
}

int allocate_identifier(int session_id) {
    if (identifiers[session_id].id != -1) {
        return -1; // Identifier already allocated
    }

    for (short id = 0; id < MAX_IDENTIFIER_LENGTH; id++) {
        if (identifiers[session_id].offsets[id] == NULL) {
            identifiers[session_id].id = id;
            identifiers[session_id].offsets[id] = (OffsetStruct*)malloc(sizeof(OffsetStruct));
            return 0;
        }
    }

    return -1; // No available identifier
}

void free_identifier(int session_id) {
