typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    size_t size;
    pthread_mutex_t mutex;
} key_manager;

key_manager* create_key_manager(size_t initial_size) {
    key_manager *km = (key_manager*)malloc(sizeof(key_manager));
    if (!km) return NULL;

    km->offsets = (long*)calloc(initial_size, sizeof(long));
    km->keys = (int*)calloc(initial_size, sizeof(int));
    if (!km->offsets || !km->keys) {
        free(km);
        return NULL;
    }

    km->size = initial_size;
    pthread_mutex_init(&km->mutex, NULL);
    return km;
}

bool add_key(key_manager *km, int key) {
    pthread_mutex_lock(&km->mutex);
    for (size_t i = 0; i < km->size; ++i) {
        if (km->keys[i] == key) {
            pthread_mutex_unlock(&km->mutex);
            return false;
        }
    }
    if (km->size % 2 == 0) { // Double the size if full
        long *new_offsets = (long*)realloc(km->offsets, km->size * 2 * sizeof(long));
        int *new_keys = (int*)realloc(km->keys, km->size * 2 * sizeof(int));
        if (!new_offsets || !new_keys) {
            pthread_mutex_unlock(&km->mutex);
            free(new_offsets);
            free(new_keys);
            return false;
        }
        km->offsets = new_offsets;
        km->keys = new_keys;
        km->size *= 2;
    }
    km->keys[km->size - 1] = key;
    pthread_mutex_unlock(&km->mutex);
    return true;
}

void destroy_key_manager(key_manager *km) {
    if (km) {
        free(km->offsets);
        free(km->keys);
        pthread_mutex_destroy(&km->mutex);
        free(km);
    }
}

record* create_records(size_t size, int (*prng)(int)) {
    record *records = (record*)malloc(size * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = prng(i);
    }

    return records;
}

int linear_congruential_generator(int seed, int a, int c, int m) {
    static int current_seed = seed;
    current_seed = (a * current_seed + c) % m;
    return current_seed;
}

