    for (int i = 0; i < MAX_KEYS; i++) {
        dynamicList.records[i].key = -1;
    }
    pthread_mutex_init(&dynamicList.lock, NULL);
}

int generateKey() {
    // Use a high-performance PRNG here
    return rand() % MAX_KEYS;
}

int insertRecord(int key, long offset) {
    if (key < 0 || key >= MAX_KEYS) {
        return -1; // Key out of range
    }
    pthread_mutex_lock(&dynamicList.lock);
    if (dynamicList.records[key].key != -1) {
        pthread_mutex_unlock(&dynamicList.lock);
        return -2; // Collision or occupied
    }
    dynamicList.records[key].key = key;
    dynamicList.records[key].offset = offset;
    pthread_mutex_unlock(&dynamicList.lock);
    return 0;
}

int findOffset(int key) {
    if (key < 0 || key >= MAX_KEYS) {
        return -1; // Key out of range
    }
    pthread_mutex_lock(&dynamicList.lock);
    int offset = dynamicList.records[key].offset;
    pthread_mutex_unlock(&dynamicList.lock);
    if (offset == -1) {
        return -2; // Key not found
    }
    return offset;
}

void cleanup() {
    pthread_mutex_destroy(&dynamicList.lock);
}

int main() {
