    do {
        if (!RAND_bytes((unsigned char *)&key, sizeof(key))) {
            fprintf(stderr, "Failed to generate random number\n");
            exit(EXIT_FAILURE);
        }
        key = abs(key) % 1024;
    } while (used_keys && memchr(used_keys, key, used_count * sizeof(int)));
    return key;
}

