    pthread_mutex_lock(&key_mutex);
    for (int i = 0; i < key_count; ++i) {
        if (keys[i] == key) {
            offsets[i] = 0;
            keys[i] = -1;
            break;
        }
    }
    pthread_mutex_unlock(&key_mutex);

