import java.util.*;
import java.util.concurrent.*;

public class TaskManager {
    private final long[] timestamps;
    private final int[] taskIDs;
    private final float[] priorityLevels;
    private final Set<Integer> usedTaskIDs = ConcurrentHashMap.newKeySet();
    private final ExecutorService executorService;
    private final Logger logger;

    public TaskManager(int maxTasks, int loggingLevel) {
        this.timestamps = new long[maxTasks];
        this.taskIDs = new int[maxTasks];
        this.priorityLevels = new float[maxTasks];
        this.executorService = Executors.newFixedThreadPool(maxTasks);
        this.logger = LoggerFactory.getLogger(TaskManager.class);
        logger.setLevel(loggingLevel == 1 ? Level.INFO : Level.DEBUG);
    }

    public void distributeTasks(List<Integer> taskValues) {
        int taskIdCounter = 0;
        for (int value : taskValues) {
            if (taskIdCounter >= timestamps.length) {
                throw new IllegalStateException("Maximum number of tasks reached");
            }
            int uniqueID = getUniqueTaskID();
            if (uniqueID == -1) {
                logger.error("Failed to allocate a unique task ID");
                return; // Rollback partial operations
            }
            timestamps[taskIdCounter] = System.currentTimeMillis();
            taskIDs[taskIdCounter] = uniqueID;
            priorityLevels[taskIdCounter] = calculatePriority(value);
            executorService.submit(() -> processTask(uniqueID, value));
            taskIdCounter++;
        }
    }

    private int getUniqueTaskID() {
        Random random = new Random();
        while (true) {
            int id = random.nextInt(1024);
            if (usedTaskIDs.add(id)) {
                return id;
            }
        }
    }

    private float calculatePriority(int value) {
        // Implement priority calculation logic
        return value / 10.0f;
    }

    private void processTask(int taskId, int taskValue) {
        try {
            logger.info("Processing task ID: {}", taskId);
            Thread.sleep(taskValue * 10); // Simulate task processing time
            logger.info("Completed task ID: {}", taskId);
        } catch (InterruptedException e) {
            logger.warn("Task processing interrupted for ID: {}", taskId, e);
        }
    }

    public void findAndPrintMedian(List<Integer> values) {
        Collections.sort(values);
        int size = values.size();
        if (size % 2 == 0) {
            double median = (values.get(size / 2 - 1) + values.get(size / 2)) / 2.0;
            logger.info("Median value: {}", median);
        } else {
            int medianIndex = size / 2;
            logger.info("Median value: {}", values.get(medianIndex));
        }
    }

    public void cleanup() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int maxTasks = 1000;
        int loggingLevel = 2; // INFO level
        TaskManager taskManager = new TaskManager(maxTasks, loggingLevel);

        System.out.println("Enter a list of integers (comma-separated):");
        String input = scanner.nextLine();
        List<Integer> taskValues = Arrays.stream(input.split(","))
                                          .map(Integer::parseInt)
                                          .collect(Collectors.toList());

        try {
            taskManager.distributeTasks(taskValues);
            List<Integer> values = new ArrayList<>(taskValues);
            taskManager.findAndPrintMedian(values);
        } catch (Exception e) {
            logger.error("Error during task distribution or median calculation", e);
        } finally {
            taskManager.cleanup();
        }
    }
}
