        return NULL; 
    }

    // Initialize keys array with pseudo-random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (num_records * 2) + 1;
    }

    // Allocate memory for records array
    record *records = (record *)malloc(num_records * sizeof(record));
    if (records == NULL) {
        free(offsets); // Free allocated memory in case of failure
        free(keys);
        return NULL; 
    }

    // Initialize records array with pseudo-random values and unique keys
    int used_keys[num_records];
    for (int i = 0; i < num_records; i++) {
        used_keys[i] = 0;
    }
    for (int i = 0; i < num_records; i++) {
        do {
            records[i].value = rand() % (num_records * 2) + 1;
        } while (used_keys[records[i].value - 1]);
        used_keys[records[i].value - 1] = 1;
    }

    // Sort records based on offset values
    for (int i = 0; i < num_records - 1; i++) {
        for (int j = 0; j < num_records - i - 1; j++) {
            if (offsets[j] > offsets[j + 1]) {
                long temp_offset = offsets[j];
                record temp_record = records[j];
                offsets[j] = offsets[j + 1];
                records[j] = records[j + 1];
                offsets[j + 1] = temp_offset;
                records[j + 1] = temp_record;
            }
        }
    }

    // Return sorted array of records
    return records;
}
