int* generate_user_ids(int count, unsigned long seed) {
    int* user_ids = (int*)malloc(count * sizeof(int));
    if (!user_ids) {
        // Handle memory allocation failure
        return NULL;
    }
    srand(seed);
    for (int i = 0; i < count; ++i) {
        user_ids[i] = rand(); // Example: Random user ID
    }
    return user_ids;
}

Session* generate_sessions(int count, unsigned long seed, int min_id, int max_id) {
    Session* sessions = (Session*)malloc(count * sizeof(Session));
    if (!sessions) {
        // Handle memory allocation failure
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < count; ++i) {
        do {
            sessions[i].session_id = rand() % (max_id - min_id + 1) + min_id;
        } while (i > 0 && sessions[i].session_id == sessions[i - 1].session_id); // Ensure uniqueness
    }

    return sessions;
}

Session* filter_sessions(Session* sessions, int count, unsigned long start_time, unsigned long end_time) {
    Session* filtered = NULL;
    int filtered_count = 0;

    for (int i = 0; i < count; ++i) {
        if (sessions[i].session_id >= start_time && sessions[i].session_id <= end_time) {
            filtered = realloc(filtered, (filtered_count + 1) * sizeof(Session));
            if (!filtered) {
                // Handle memory allocation failure
                return NULL;
            }
            memcpy(&filtered[filtered_count], &sessions[i], sizeof(Session));
            ++filtered_count;
        }
    }

    return filtered;
}

Session* sort_sessions(Session* sessions, int count) {
    qsort(sessions, count, sizeof(Session), compare_sessions);
    return sessions;
}

int compare_sessions(const void* a, const void* b) {
    Session* session_a = (Session*)a;
    Session* session_b = (Session*)b;
    if (session_a->session_id < session_b->session_id) return -1;
    if (session_a->session_id > session_b->session_id) return 1;
    return 0;
}

Session** process_sessions(int count, unsigned long start_time, unsigned long end_time) {
    unsigned long* timestamps = generate_timestamps(count);
    int* user_ids = generate_user_ids(count, time(NULL));
    Session* sessions = generate_sessions(count, time(NULL), 1, 1000); // Example: Generate session IDs between 1 and 1000

    if (!timestamps || !user_ids || !sessions) {
        free(timestamps);
        free(user_ids);
        free(sessions);
        return NULL; // Handle error
    }

    Session* filtered = filter_sessions(sessions, count, start_time, end_time);
    free(sessions); // Free original sessions array

    if (!filtered) {
        free(timestamps);
        free(user_ids);
        return NULL; // Handle error
    }

    free(timestamps);
    free(user_ids);

    Session** result = (Session**)malloc((count + 1) * sizeof(Session*));
    if (!result) {
        free(filtered);
        return NULL; // Handle memory allocation failure
    }
    memcpy(result, filtered, count * sizeof(Session*));
    result[count] = NULL;

    return result;
}
