import java.util.*;
import java.security.SecureRandom;
import java.util.concurrent.*;
import java.io.*;

public class DistributedCacheManager {
    private static final int MAX_KEY_LENGTH = 2048;
    private static final int CACHE_SIZE = 10000;
    private static final String LOG_FILE = "cache_manager.log";

    private long[] timestamps;
    private String[] keys;
    private cacheRecord[] records;
    private SecureRandom randomGenerator;
    private ExecutorService executorService;
    private Logger logger;

    public DistributedCacheManager() {
        timestamps = new long[CACHE_SIZE];
        keys = new String[CACHE_SIZE];
        records = new cacheRecord[CACHE_SIZE];
        randomGenerator = new SecureRandom();
        executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        logger = new Logger(LOG_FILE);
        initializeCache();
    }

    private void initializeCache() {
        Set<String> keySet = new HashSet<>();
        while (keySet.size() < CACHE_SIZE) {
            String key = generateRandomKey();
            if (!keySet.contains(key)) {
                keySet.add(key);
            }
        }
        int index = 0;
        for (String key : keySet) {
            records[index] = new cacheRecord(generateRandomValue(), timestamps[index]);
            keys[index] = key;
            index++;
        }
    }

    private String generateRandomKey() {
        byte[] bytes = new byte[MAX_KEY_LENGTH];
        randomGenerator.nextBytes(bytes);
        return Base64.getEncoder().encodeToString(bytes).substring(0, MAX_KEY_LENGTH - 1);
    }

    private int generateRandomValue() {
        return randomGenerator.nextInt(60000) + 1;
    }

    public void put(String key, String value) {
        if (key.length() > MAX_KEY_LENGTH || !isValidString(key)) {
            logger.log("Invalid key length or characters: " + key, LogLevel.WARNING);
            return;
        }
        int index = getIndexForKey(key);
        if (index == -1) {
            logger.log("Key not found in cache: " + key, LogLevel.ERROR);
            return;
        }
        records[index].value = value;
        timestamps[index] = System.currentTimeMillis();
        logger.log("Updated key: " + key + ", new value: " + value, LogLevel.INFO);
    }

    public String get(String key) {
        int index = getIndexForKey(key);
        if (index == -1) {
            logger.log("Key not found in cache: " + key, LogLevel.ERROR);
            return null;
        }
        long currentTime = System.currentTimeMillis();
        if (currentTime - timestamps[index] > 60000) { // Cache entry expired
            records[index].value = generateRandomValue() + "";
            timestamps[index] = currentTime;
            logger.log("Cache entry expired, updated key: " + key + ", new value: " + records[index].value, LogLevel.INFO);
        }
        return records[index].value;
    }

    private int getIndexForKey(String key) {
        for (int i = 0; i < keys.length; i++) {
            if (keys[i].equals(key)) {
                return i;
            }
        }
        return -1;
    }

    private boolean isValidString(String str) {
        return !str.matches(".*[^a-zA-Z0-9].*");
    }

    public void close() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        logger.log("Cache manager closed", LogLevel.INFO);
    }

    public static void main(String[] args) {
        DistributedCacheManager cacheManager = new DistributedCacheManager();
        // Example usage
        cacheManager.put("key1", "value1");
        String value = cacheManager.get("key1");
        System.out.println("Retrieved value: " + value);
        cacheManager.close();
    }
}

class cacheRecord {
    String value;
    long timestamp;

    public cacheRecord(String value, long timestamp) {
        this.value = value;
        this.timestamp = timestamp;
    }
}

enum LogLevel {
    INFO,
    WARNING,
    ERROR
}

class Logger {
    private String logFile;

    public Logger(String logFile) {
        this.logFile = logFile;
    }

    public void log(String message, LogLevel level) {
        try (PrintWriter writer = new PrintWriter(new FileWriter(logFile, true))) {
            writer.println(System.currentTimeMillis() + " [" + level + "] " + message);
        } catch (IOException e) {
            System.err.println("Failed to write to log file: " + logFile);
        }
    }
}
