        int len = strlen(info->input);
        if (len > info->lengthLimit - 1) {
            // Truncate string and append slash
            info->input[info->lengthLimit - 2] = '/';
            info->input[info->lengthLimit - 1] = '\0';
        } else {
            // Append slash at the end if no truncation is needed
            info->input[len] = '/';
            info->input[len + 1] = '\0';
        }
    }
}

