    ProcessStringData data = {"example_string", MAX_LENGTH};
    int rc = pthread_create(&thread, NULL, (void *(*)(void *)) processString, &data);
    if (rc) {
        printf("Error: unable to create thread\n");
        return 1;
    }
    pthread_join(thread, NULL);
    printf("Processed string: %s\n", data.input);
    return 0;
