import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class TransactionManager {

    private static final int IDENTIFIER_RANGE = 65536;
    private static final AtomicInteger nextIdentifier = new AtomicInteger(0);
    private static final ConcurrentHashMap<Integer, Boolean> usedIdentifiers = new ConcurrentHashMap<>();
    private SocketChannel channel;

    public void manageConnectionAndTransactions(String serverAddress, int serverPort) {
        try {
            // Initialize connection
            channel = SocketChannel.open();
            channel.connect(new InetSocketAddress(serverAddress, serverPort));

            // Allocate and initialize arrays
            long[] timestamps = new long[1000];
            short[] identifiers = new short[1000];
            Transaction[] transactions = new Transaction[1000];

            // Populate arrays with unique identifiers and transactions
            for (int i = 0; i < transactions.length; i++) {
                short id;
                do {
                    id = (short) nextIdentifier.getAndIncrement() % IDENTIFIER_RANGE;
                } while (!usedIdentifiers.putIfAbsent(id, true));
                timestamps[i] = System.currentTimeMillis();
                identifiers[i] = id;
                transactions[i] = new Transaction(timestamps[i], id, generateRandomTransactionAmount());
            }

            // Send transactions to the server
            for (Transaction transaction : transactions) {
                ByteBuffer buffer = ByteBuffer.allocate(16);
                buffer.putLong(transaction.getTimestamp());
                buffer.putShort(transaction.getIdentificationNumber());
                buffer.putFloat(transaction.getAmount());
                channel.write(buffer);
            }

            // Calculate and print average transaction amount
            float averageAmount = calculateAverageTransactionAmount(transactions);
            System.out.println("Average Transaction Amount: $" + averageAmount);

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                if (channel != null && channel.isOpen()) {
                    channel.close();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private float generateRandomTransactionAmount() {
        // Implement a PRNG optimized for performance and reliability
        return (float) (Math.random() * 1000.00);
    }

    private float calculateAverageTransactionAmount(Transaction[] transactions) {
        float sum = 0;
        for (Transaction transaction : transactions) {
            sum += transaction.getAmount();
        }
        return sum / transactions.length;
    }

    static class Transaction {
        private long timestamp;
        private short identificationNumber;
        private float amount;

        public Transaction(long timestamp, short identificationNumber, float amount) {
            this.timestamp = timestamp;
            this.identificationNumber = identificationNumber;
            this.amount = amount;
        }

        public long getTimestamp() {
            return timestamp;
        }

        public short getIdentificationNumber() {
            return identificationNumber;
        }

        public float getAmount() {
            return amount;
        }
    }
}
