void initialize_key_database() {
    offsets = (long *)malloc(KEY_DB_SIZE * sizeof(long));
    keys = (int *)malloc(KEY_DB_SIZE * sizeof(int));
    records = (record *)malloc(RECORD_POOL_SIZE * sizeof(record));

    pthread_rwlock_init(&key_db_lock, NULL);
    PRNG_init(&prng_state);

    for (int i = 0; i < KEY_DB_SIZE; i++) {
        used_keys[i] = 0;
    }
}

void generate_random_records() {
    srand(time(NULL));
    int values[RECORD_POOL_SIZE];
    int count = 0;

    while (count < RECORD_POOL_SIZE) {
        int random_value = PRNG_generate(&prng_state, 1, 1000);
        if (!record_exists(random_value)) {
            records[count].value = random_value;
            values[count] = random_value;
            count++;
        }
    }

    for (int i = 0; i < RECORD_POOL_SIZE; i++) {
        record *current_record = &records[i];
        current_record->value = values[i];
    }
}

void lock_key_database() {
    pthread_rwlock_wrlock(&key_db_lock);
}

void unlock_key_database() {
    pthread_rwlock_unlock(&key_db_lock);
}

int record_exists(int value) {
    for (int i = 0; i < RECORD_POOL_SIZE; i++) {
        if (records[i].value == value) {
            return 1;
        }
    }
    return 0;
}

void cleanup() {
    free(offsets);
    free(keys);
    free(records);
    PRNG_cleanup(&prng_state);
    pthread_rwlock_destroy(&key_db_lock);
