#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_KEY_SIZE 32
#define MAX_BLOCK_SIZE 16

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB
} CipherMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[MAX_KEY_SIZE];
    unsigned char iv[MAX_BLOCK_SIZE];
    CipherMode mode;
} CryptoTransform;

CryptoTransform* create_transform(CipherMode mode, const unsigned char *key, size_t key_len) {
    CryptoTransform *ct = (CryptoTransform*)malloc(sizeof(CryptoTransform));
    ct->ctx = EVP_CIPHER_CTX_new();
    ct->mode = mode;
    memcpy(ct->key, key, key_len);
    memset(ct->iv, 0, MAX_BLOCK_SIZE);
    return ct;
}

void set_iv(CryptoTransform *ct, const unsigned char *iv) {
    if (ct->mode == ECB)
        return;
    memcpy(ct->iv, iv, EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ct->ctx)));
}

void encrypt_data(CryptoTransform *ct, const unsigned char *input, size_t input_len, unsigned char *output, size_t output_len) {
    EVP_EncryptInit_ex(ct->ctx, EVP_CIPHER_CTX_cipher(ct->ctx), NULL, ct->key, ct->iv);
    int len;
    EVP_EncryptUpdate(ct->ctx, output, &len, input, input_len);
    memcpy(output + len, output, EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ct->ctx)));
    EVP_EncryptFinal_ex(ct->ctx, output + len, &len);
}

void decrypt_data(CryptoTransform *ct, const unsigned char *input, size_t input_len, unsigned char *output, size_t output_len) {
    EVP_DecryptInit_ex(ct->ctx, EVP_CIPHER_CTX_cipher(ct->ctx), NULL, ct->key, ct->iv);
    int len;
    EVP_DecryptUpdate(ct->ctx, output, &len, input, input_len);
    memcpy(output + len, output, EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ct->ctx)));
    EVP_DecryptFinal_ex(ct->ctx, output + len, &len);
}

void free_transform(CryptoTransform *ct) {
    EVP_CIPHER_CTX_free(ct->ctx);
    free(ct);
}
