#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->data = (int*)calloc(initial_capacity, sizeof(int));
    if (!collection->data) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    srand(time(NULL)); // Initialize random seed
    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->data[i] = rand() % 1000; // Generate random numbers between 0 and 999
    }

    return collection;
}

void destroy_collection(RecordCollection *collection) {
    free(collection->data);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_record(RecordCollection *collection, int value) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        int *new_data = (int*)realloc(collection->data, new_capacity * sizeof(int));
        if (!new_data) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }
    collection->data[collection->size++] = value;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int get_record(RecordCollection *collection, size_t index) {
    if (index >= collection->size) {
        return -1; // Invalid index
    }
    pthread_mutex_lock(&collection->mutex);
    int result = collection->data[index];
    pthread_mutex_unlock(&collection->mutex);
    return result;
}

int resize_collection(RecordCollection *collection, size_t new_capacity) {
    pthread_mutex_lock(&collection->mutex);
    int *new_data = (int*)realloc(collection->data, new_capacity * sizeof(int));
    if (!new_data) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Memory allocation failed
    }
    collection->data = new_data;
    collection->capacity = new_capacity;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}
