typedef struct {
    int field;
    unsigned long timestamp;
} record;

record* create_records(size_t num_records, int min_int, int max_int, size_t timestamp_precision) {
    if (num_records == 0 || min_int >= max_int || timestamp_precision == 0) {
        errno = EINVAL;
        return NULL;
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].field = min_int + rand() % (max_int - min_int + 1);
        clock_gettime(CLOCK_MONOTONIC, &records[i].timestamp);

        // Adjust timestamp to match the desired precision
        while (records[i].timestamp.tv_nsec % timestamp_precision != 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &records[i].timestamp) == -1) {
                free(records);
                return NULL; // Error in getting time
            }
        }
    }

    return records;
}
