        record_array[i] = (Record*)malloc(sizeof(Record));
        if (!record_array[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        record_array[i]->key = rand();
        do {
            record_array[i]->offset = rand();
        } while (record_array[i]->offset == 0); // Ensure non-zero offset
        record_array[i]->value = rand();
    }

    return record_array;
}

void resize_record_array(Record*** record_array, size_t* capacity) {
    *capacity *= GROWTH_FACTOR;
    *record_array = (Record**)realloc(*record_array, (*capacity) * sizeof(Record*));
    if (!*record_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = *capacity / GROWTH_FACTOR; i < *capacity; ++i) {
        (*record_array)[i] = (Record*)malloc(sizeof(Record));
        if (!(*record_array)[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    srand(time(NULL));
    for (size_t i = *capacity / GROWTH_FACTOR; i < *capacity; ++i) {
        (*record_array)[i]->key = rand();
        do {
            (*record_array)[i]->offset = rand();
        } while ((*record_array)[i]->offset == 0); // Ensure non-zero offset
        (*record_array)[i]->value = rand();
    }
}

void free_record_array(Record*** record_array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        free((*record_array)[i]);
    }
    free(*record_array);
}

int main() {
    size_t capacity = INITIAL_CAPACITY;
    Record** record_array = initialize_record_array(capacity);

    // Example usage
    printf("Record Key: %d, Offset: %ld, Value: %d\n", record_array[0]->key, record_array[0]->offset, record_array[0]->value);

    free_record_array(&record_array, capacity);
    return 0;
}
