record* allocate_and_populate_records(size_t num_records, long min_offset, long max_offset, int min_key, int max_key) {
    if (num_records == 0 || min_offset > max_offset || min_key > max_key) {
        return NULL;
    }

    // Allocate memory for the arrays
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    record* records = malloc(num_records * sizeof(record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Seed the PRNG
    srand(time(NULL));

    // Populate the arrays with random values
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
        keys[i] = rand() % (max_key - min_key + 1) + min_key;

        // Ensure integer overflow does not occur for flags
        char flag_value = (char)(rand() % (CHAR_MAX - CHAR_MIN + 1)) + CHAR_MIN;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].flag = flag_value;
    }

    // Return the pointers to the allocated arrays
    return records;
}
