#define MAX_RECORDS 10000

typedef struct {
    int key;
    long offset;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t records_lock;

void initialize_records_system() {
    pthread_mutex_init(&records_lock, NULL);
    srand(time(NULL));
}

int add_record(int min_value, int max_value) {
    if (record_count >= MAX_RECORDS) return -1; // Error: Maximum number of records reached

    int key;
    do {
        key = rand() % (max_value - min_value + 1) + min_value;
    } while (key < min_value || key > max_value);

    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            pthread_mutex_unlock(&records_lock);
            return -2; // Error: Key already exists
        }
    }

    records[record_count].key = key;
    records[record_count].offset = rand() % 1000000L; // Example offset
    record_count++;
    pthread_mutex_unlock(&records_lock);

    return key;
}

int get_record_by_key(int key, long *offset) {
    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            *offset = records[i].offset;
            pthread_mutex_unlock(&records_lock);
            return 1; // Success
        }
    }
    pthread_mutex_unlock(&records_lock);
    return -3; // Error: Key not found
}

void cleanup_records_system() {
    pthread_mutex_destroy(&records_lock);
}
