    for (int i = 0; i < max_keys; ++i) {
        offsets[i] = (long)(rand() % max_keys) * keys[i];
    }

    // Populate record structures using a custom PRNG
    unsigned int seed = time(NULL);
    for (int i = 0; i < max_keys; ++i) {
        records[i].value = (seed += 123456789) % max_keys;
        records[i].offset = offsets[i];
    }

    // Ensure the function completes within the budget
    clock_t start = clock();
    while ((clock() - start) / CLOCKS_PER_SEC * 1000 < budget_ms) {
        // Busy-wait to simulate work within the budget
    }

    return records;
}
