// Function to read integers from stdin until a non-numeric character is encountered
int* readIntegers() {
    int capacity = 10;
    int* array = (int*)malloc(capacity * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    int count = 0;
    char input[256];
    while (fgets(input, sizeof(input), stdin)) {
        char* token = strtok(input, " \t\n");
        while (token != NULL) {
            if (sscanf(token, "%d", &array[count]) == 1) {
                count++;
                if (count >= capacity) {
                    capacity *= 2;
                    int* new_array = (int*)realloc(array, capacity * sizeof(int));
                    if (!new_array) {
                        fprintf(stderr, "Memory reallocation failed.\n");
                        free(array);
                        exit(EXIT_FAILURE);
                    }
                    array = new_array;
                }
            } else {
                // Stop reading on encountering a non-numeric character
                break;
            }
            token = strtok(NULL, " \t\n");
        }
    }
    array = (int*)realloc(array, count * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory reallocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

// Function to find and print the largest integer in the array
void printLargestInteger(int* array, int count) {
    if (count == 0) {
        printf("No integers provided.\n");
        return;
    }
    int max = INT_MIN;
    for (int i = 0; i < count; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Main function to demonstrate the usage of above functions
int main() {
    int* integers = readIntegers();
    printLargestInteger(integers, count);

    // Clean up allocated memory
    free(integers);

    return 0;
}
