#include <stdlib.h>
#include <time.h>
#include <stdint.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

uint32_t calculate_checksum(record *arr, size_t size) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        checksum += arr[i].offset + arr[i].key + arr[i].value;
    }
    return checksum;
}

void init_records(record **arr, size_t size, int min_val, int max_val, unsigned seed) {
    if (*arr != NULL) {
        free(*arr);
    }

    *arr = (record *)malloc(size * sizeof(record));
    if (*arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(seed);

    for (size_t i = 0; i < size; ++i) {
        (*arr)[i].offset = (long)i;
        (*arr)[i].key = (int)i + 1;
        (*arr)[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    (*arr)[0].value = calculate_checksum(*arr, size);
}

void validate_records(record *arr, size_t size, uint32_t expected_checksum) {
    if (arr == NULL || size == 0) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    uint32_t computed_checksum = calculate_checksum(arr, size);

    if (computed_checksum != expected_checksum) {
        fprintf(stderr, "Checksum mismatch: Expected %u, got %u\n", expected_checksum, computed_checksum);
    } else {
        printf("Validation passed!\n");
    }
}

int main() {
    record *records;
    size_t array_size = 1000;
    int min_val = 10, max_val = 100;
    unsigned seed = time(NULL);

    init_records(&records, array_size, min_val, max_val, seed);
    validate_records(records, array_size, records[0].value);

    free(records);

    return 0;
}
