#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <dirent.h>

typedef struct {
    char *path;
    pthread_mutex_t lock;
} TempFile;

TempFile* create_temp_file(const char *prefix) {
    TempFile *temp = malloc(sizeof(TempFile));
    temp->path = mkdtemp(strdup(prefix));
    if (temp->path == NULL) {
        perror("Failed to create temporary directory");
        free(temp);
        return NULL;
    }
    pthread_mutex_init(&temp->lock, NULL);
    return temp;
}

void delete_temp_file(TempFile *temp) {
    pthread_mutex_lock(&temp->lock);
    DIR *dir = opendir(temp->path);
    if (dir != NULL) {
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", temp->path, entry->d_name);
            unlink(path);
        }
        closedir(dir);
    }
    rmdir(temp->path);
    pthread_mutex_unlock(&temp->lock);
    free(temp->path);
    pthread_mutex_destroy(&temp->lock);
    free(temp);
}

void *write_to_temp_file(void *arg) {
    TempFile *temp = (TempFile *)arg;
    FILE *file;
    char buffer[1024];

    pthread_mutex_lock(&temp->lock);
    file = fopen(strcat(temp->path, "/data"), "w");
    if (file == NULL) {
        perror("Failed to open temporary file for writing");
        pthread_mutex_unlock(&temp->lock);
        return NULL;
    }

    while (fgets(buffer, sizeof(buffer), stdin)) {
        fprintf(file, "%s", buffer);
    }

    fclose(file);
    pthread_mutex_unlock(&temp->lock);

    return NULL;
}

int main() {
    TempFile *temp = create_temp_file("/tmp/myappXXXXXX");
    if (temp == NULL) {
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, write_to_temp_file, temp) != 0) {
        perror("Failed to create thread");
        delete_temp_file(temp);
        return 1;
    }

    pthread_join(thread, NULL);

    delete_temp_file(temp);
    return 0;
}
```

This code provides a basic structure for a temporary file management utility library in C. It includes functions to create and delete temporary files, write data to them, and handle concurrent access using mutexes. The `create_temp_file` function creates a new temporary directory with the specified prefix, while the `delete_temp_file` function recursively deletes all files within the directory and removes it.

The `write_to_temp_file` function demonstrates how to open a file for writing within a thread-safe context. It reads data from standard input and writes it to the temporary file.

This code is intended as a starting point for a more robust implementation that includes additional features, error handling, performance optimizations, and compatibility considerations for different operating systems and environments.']

