import java.security.SecureRandom;
import java.util.concurrent.atomic.AtomicLong;

public class SessionIdGenerator {
    private static final SecureRandom secureRandom = new SecureRandom();
    private static final AtomicLong counter = new AtomicLong(0);

    public static String generateSessionId() {
        long uniquePart = counter.getAndIncrement();
        byte[] randomBytes = new byte[6];
        secureRandom.nextBytes(randomBytes);
        return encodeBase32(uniquePart, randomBytes);
    }

    private static String encodeBase32(long number, byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append((char) ((b & 0x1f) + 'A'));
        }
        return sb.toString().substring(0, 6);
    }

    public static void main(String[] args) throws InterruptedException {
        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                String sessionId = generateSessionId();
                System.out.println(Thread.currentThread().getName() + ": " + sessionId);
            }
        };

        Thread[] threads = new Thread[10];
        for (int i = 0; i < threads.length; i++) {
            threads[i] = new Thread(task, "Thread-" + i);
            threads[i].start();
        }

        for (Thread thread : threads) {
            thread.join();
        }
    }
}
