<?php
class UserAccountManager {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function handleRequest($_REQUEST) {
        $response = ['message' => 'error'];

        if (isset($_REQUEST['id'])) {
            if ($_REQUEST['sub_action'] === 'delete') {
                if ($this->deleteUserAccount($_REQUEST['id'])) {
                    $response = ['message' => 'success'];
                }
            } else {
                $user = $this->Get($_REQUEST['id']);
                if ($user) {
                    $updatedData = $this->validateAndUpdate($user, $_REQUEST);
                    if ($updatedData) {
                        if ($this->saveUserAccount($updatedData)) {
                            $response = ['message' => 'success'];
                        }
                    }
                }
            }
        } else {
            $userData = $this->validateAndCreate($_REQUEST);
            if ($userData) {
                if ($this->saveUserAccount($userData)) {
                    $response = ['message' => 'success'];
                }
            }
        }

        // Handle async tasks
        if (isset($_REQUEST['async_task']) && $_REQUEST['sub_action'] === 'async') {
            $taskParams = $_REQUEST['task_params'];
            $this->queueAsyncTask($_REQUEST['async_task'], $taskParams);
        }

        return json_encode($response);
    }

    private function validateAndUpdate($user, $request) {
        // Validate and update user data
        if ($this->validateUser($request)) {
            $user->name = $request['name'];
            $user->email = $request['email'];
            $user->password = password_hash($request['password'], PASSWORD_DEFAULT);
            return $user;
        }
        return null;
    }

    private function validateAndCreate($request) {
        // Validate and create user data
        if ($this->validateUser($request)) {
            return (object) [
                'name' => $request['name'],
                'email' => $request['email'],
                'password' => password_hash($request['password'], PASSWORD_DEFAULT)
            ];
        }
        return null;
    }

    private function validateUser($data) {
        // Validate user data
        if (filter_var($data['email'], FILTER_VALIDATE_EMAIL) === false) {
            return false;
        }
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[A-Za-z\d]{8,}$/', $data['password'])) {
            return false;
        }
        return true;
    }

    private function saveUserAccount($user) {
        // Save user data to the database
        try {
            if (isset($user->id)) {
                $this->db->update('users', ['name' => $user->name, 'email' => $user->email, 'password' => $user->password], ['id' => $user->id]);
            } else {
                $this->db->insert('users', ['name' => $user->name, 'email' => $user->email, 'password' => $user->password]);
            }
            return true;
        } catch (Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    private function deleteUserAccount($id) {
        // Delete user account
        try {
            $this->db->delete('users', ['id' => $id]);
            return true;
        } catch (Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    private function Get($id) {
        // Retrieve user data from the database
        try {
            $user = $this->db->get('users', ['id' => $id]);
            if ($user) {
                return (object) $user;
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
        }
        return null;
    }

    private function validateRedirectUrl($url) {
