using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public class PageService
{
    private readonly IElementService _elementService;
    private readonly ILogger _logger;
    private readonly INotificationService _notificationService;
    private readonly IRateLimiter _rateLimiter;
    private static readonly ConcurrentDictionary<int, string> UsedKeys = new();

    public PageService(IElementService elementService, ILogger logger, INotificationService notificationService, IRateLimiter rateLimiter)
    {
        _elementService = elementService;
        _logger = logger;
        _notificationService = notificationService;
        _rateLimiter = rateLimiter;
    }

    public async Task<IActionResult> UpdateElementContentAsync(string userId, string pageSectionId, int elementId, string htmlContent)
    {
        if (!_rateLimiter.AllowRequest(userId))
        {
            return new BadRequestObjectResult("Rate limit exceeded");
        }

        if (!int.TryParse(pageSectionId, out var parsedPageSectionId) || parsedPageSectionId <= 0)
        {
            return new BadRequestObjectResult("Invalid page section ID");
        }

        if (elementId <= 0)
        {
            return new BadRequestObjectResult("Invalid element ID");
        }

        if (!string.IsNullOrEmpty(htmlContent))
        {
            try
            {
                await _rateLimiter.ValidateUserIdAsync(userId);
                var result = await _elementService.UpdateElementContentAsync(elementId, htmlContent);

                if (result)
                {
                    _logger.LogInformation($"User {userId} updated element ID {elementId} on page section {parsedPageSectionId}");
                    return new OkObjectResult("Page refresh required");
                }
                else
                {
                    _notificationService.NotifyElementUpdateFailure(userId);
                    return new NotFoundObjectResult("Element not found");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating element content");
                return new StatusCodeResult(500);
            }
        }

        return new BadRequestObjectResult("Invalid HTML content");
    }
}
