#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILE_PATH 256
#define MAX_UNIQUE_ID_LENGTH 32

typedef struct {
    long* offsetValues;
    int* keys;
    char** uniqueIDs;
} SessionData;

SessionData* allocateAndInitializeSessionData(int numSessions, const char* rootDirectory) {
    SessionData* sessionData = (SessionData*)malloc(numSessions * sizeof(SessionData));
    if (!sessionData) {
        perror("Failed to allocate memory for SessionData");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < numSessions; ++i) {
        sessionData[i].offsetValues = (long*)malloc(numSessions * sizeof(long));
        if (!sessionData[i].offsetValues) {
            perror("Failed to allocate memory for offsetValues");
            free(sessionData);
            return NULL;
        }

        sessionData[i].keys = (int*)malloc(numSessions * sizeof(int));
        if (!sessionData[i].keys) {
            perror("Failed to allocate memory for keys");
            free(sessionData[i].offsetValues);
            free(sessionData);
            return NULL;
        }

        char uniqueID[MAX_UNIQUE_ID_LENGTH];
        snprintf(uniqueID, MAX_UNIQUE_ID_LENGTH, "SID_%d", rand() % 100000);

        sessionData[i].uniqueIDs = (char**)malloc(sizeof(char*) * numSessions);
        if (!sessionData[i].uniqueIDs) {
            perror("Failed to allocate memory for uniqueIDs");
            free(sessionData[i].offsetValues);
            free(sessionData[i].keys);
            free(sessionData);
            return NULL;
        }

        sessionData[i].uniqueIDs[i] = (char*)malloc(strlen(uniqueID) + 1);
        if (!sessionData[i].uniqueIDs[i]) {
            perror("Failed to allocate memory for uniqueID string");
            free(sessionData[i].offsetValues);
            free(sessionData[i].keys);
            for (int j = 0; j < i; ++j) {
                free(sessionData[j].uniqueIDs[j]);
            }
            free(sessionData[i].uniqueIDs);
            free(sessionData);
            return NULL;
        }

        strcpy(sessionData[i].uniqueIDs[i], uniqueID);
    }

    return sessionData;
}

void freeSessionData(SessionData* sessionData, int numSessions) {
    for (int i = 0; i < numSessions; ++i) {
        free(sessionData[i].offsetValues);
        free(sessionData[i].keys);
        for (int j = 0; j < numSessions; ++j) {
            free(sessionData[j].uniqueIDs[j]);
        }
        free(sessionData[i].uniqueIDs);
    }
    free(sessionData);
}
