// Define the StreamingDataHandler class
class StreamingDataHandler {
    constructor(maxConcurrentStreams, maxResourceUsage) {
        this.maxConcurrentStreams = maxConcurrentStreams;
        this.maxResourceUsage = maxResourceUsage;
        this.activeStreams = 0;
        this.resourceUsage = 0;
        this.streams = [];
        this.paused = false;
    }

    // Method to start a new data stream
    addStream(stream) {
        if (this.activeStreams >= this.maxConcurrentStreams || this.resourceUsage + stream.usage > this.maxResourceUsage) {
            throw new Error("Resource limits exceeded");
        }
        this.streams.push(stream);
        this.activeStreams++;
        this.resourceUsage += stream.usage;
        console.log(`Stream added. Active streams: ${this.activeStreams}`);
    }

    // Method to remove a data stream
    removeStream(streamId) {
        const stream = this.streams.find(s => s.id === streamId);
        if (stream) {
            this.streams.splice(this.streams.indexOf(stream), 1);
            this.activeStreams--;
            this.resourceUsage -= stream.usage;
            console.log(`Stream removed. Active streams: ${this.activeStreams}`);
        } else {
            throw new Error("Stream not found");
        }
    }

    // Method to pause data collection
    pause() {
        if (!this.paused) {
            this.paused = true;
            console.log("Data collection paused");
        }
    }

    // Method to resume data collection
    resume() {
        if (this.paused) {
            this.paused = false;
            this.streams.forEach(stream => {
                if (stream.status !== "paused") {
                    stream.start();
                }
            });
            console.log("Data collection resumed");
        }
    }

    // Method to simulate starting and stopping the service with random delay
    simulateService() {
        const action = Math.random() < 0.5 ? "start" : "stop";
        setTimeout(() => {
            if (action === "start") {
                this.streams.forEach(stream => stream.start());
                console.log("Service started");
            } else {
                this.pause();
                console.log("Service stopped");
            }
            this.simulateService();
        }, Math.floor(Math.random() * 2000) + 1000);
    }
}

// Define the DataStream class
class DataStream {
    constructor(id, usage, status = "running") {
        this.id = id;
        this.usage = usage;
        this.status = status;
    }

    start() {
        if (this.status === "paused") return;
        console.log(`Stream ${this.id} started`);
        // Simulate data collection
        setInterval(() => {
            if (!this.paused) {
                console.log(`Data collected from stream ${this.id}`);
            }
        }, 1000);
    }

    pause() {
        this.status = "paused";
        console.log(`Stream ${this.id} paused`);
    }

    resume() {
        this.status = "running";
        console.log(`Stream ${this.id} resumed`);
    }
}

// Example usage
const handler = new StreamingDataHandler(3, 50);
handler.addStream(new DataStream("1", 20));
handler.addStream(new DataStream("2", 15));
handler.simulateService();
