// Task 1: Load environment variables based on the configuration file
function loadEnvironmentVariables($env) {
    $filename = "config/{$env}.env";
    if (file_exists($filename)) {
        $lines = file($filename, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
        foreach ($lines as $line) {
            list($key, $value) = explode('=', $line, 2);
            putenv("$key=$value");
        }
    } else {
        throw new Exception("Configuration file for {$env} not found.");
    }
}

// Task 2: Initialize autoloading mechanism
spl_autoload_register(function ($class) {
    $prefix = 'Namespace\\';
    $base_dir = __DIR__ . '/vendor/autoload/';
    $len = strlen($prefix);

    if (strncmp($prefix, $class, $len) !== 0) {
        return;
    }

    $relative_class = substr($class, $len);
    $file = $base_dir . str_replace('\\', '/', $relative_class) . '.php';

    if (file_exists($file)) {
        require $file;
    } else {
        throw new Exception("Class {$class} not found.");
    }
});

