import jwt
from datetime import datetime, timedelta
from functools import wraps
import time
from sqlalchemy import create_engine, Column, Integer, String, DateTime
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

Base = declarative_base()

class User(Base):
    __tablename__ = 'users'
    id = Column(Integer, primary_key=True)
    username = Column(String, unique=True)
    email = Column(String, unique=True)
    last_modified_ip = Column(String)
    last_modified_date = Column(DateTime)

engine = create_engine('sqlite:///users.db')
Session = sessionmaker(bind=engine)

TRUSTED_IPS = ['192.168.1.1', '10.0.0.1']
JWT_SECRET_KEY = 'your_jwt_secret_key'

def require_trusted_ip(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        ip_address = kwargs.get('ip_address')
        if ip_address not in TRUSTED_IPS:
            raise ValueError("IP address is not trusted")
        return f(*args, **kwargs)
    return decorated_function

def require_valid_jwt_token(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        token = kwargs.get('token')
        try:
            payload = jwt.decode(token, JWT_SECRET_KEY, algorithms=['HS256'])
            session_id = payload['session_id']
            # Validate session and refresh if needed
        except jwt.ExpiredSignatureError:
            raise ValueError("JWT token is expired")
        except jwt.InvalidTokenError:
            raise ValueError("Invalid JWT token")
        return f(*args, **kwargs)
    return decorated_function

def rate_limit(max_calls=10, period=300):
    def decorator(f):
        from collections import defaultdict
        last_calls = defaultdict(int)

        @wraps(f)
        def decorated_function(*args, **kwargs):
            current_time = time.time()
            caller_ip = kwargs.get('ip_address')
            if caller_ip in last_calls and current_time - last_calls[caller_ip] < period:
                raise ValueError("Rate limit exceeded")
            last_calls[caller_ip] = current_time
            return f(*args, **kwargs)
        return decorated_function
    return decorator

@require_trusted_ip
@require_valid_jwt_token
@rate_limit(max_calls=10, period=300)
def update_user_profile(username, new_email, token, ip_address):
    session = Session()
    try:
        user = session.query(User).filter_by(username=username).first()
        if not user:
            raise ValueError("User does not exist")

        user.email = new_email
        user.last_modified_ip = ip_address
        user.last_modified_date = datetime.now()
        session.commit()

        # Send acknowledgment email
        send_acknowledgment_email(user.email)

        # Log update attempt
        log_update_attempt(username, 'success')

        return "Profile updated successfully"
    except Exception as e:
        log_update_attempt(username, str(e))
        raise ValueError("Failed to update profile")
    finally:
        session.close()

def send_acknowledgment_email(email):
    try:
        # Code to send email
        pass
    except Exception as e:
        print(f"Failed to send acknowledgment email: {e}")

def log_update_attempt(username, result):
    with open('update_log.txt', 'a') as log_file:
        log_file.write(f"{datetime.now()} - User: {username} - Result: {result}\n")
