#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

// Define a structure for employee details
typedef struct {
    char name[100];
    char city[50];
    char address[200];
} Employee;

// Cache to store employee details by supervisor ID
typedef struct {
    int id;
    Employee *employees;
    int count;
    pthread_mutex_t lock;
} SupervisorCache;

SupervisorCache cache[100]; // Assuming a maximum of 100 unique supervisor IDs

// Function to retrieve employee details from API endpoint
int fetchEmployeeDetails(int supervisorID, Employee **employees, int *count) {
    CURL *curl;
    CURLcode res;
    char url[256];

    snprintf(url, sizeof(url), "https://api.example.com/employees?supervisor_id=%d", supervisorID);

    curl = curl_easy_init();
    if(curl) {
        struct MemoryStruct chunk;
        chunk.memory = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        else {
            // Parse JSON response and populate employee details
            *employees = parseJSONResponse(chunk.memory, count);
        }

        free(chunk.memory);  // don't forget to free the memory again
        curl_easy_cleanup(curl);
    }

    return res == CURLE_OK ? 0 : -1;
}

// Function to handle cache operations
int getEmployeeDetails(int supervisorID, Employee **employees, int *count) {
    pthread_mutex_lock(&cache[supervisorID].lock);

    if(cache[supervisorID].count > 0) {
        *employees = cache[supervisorID].employees;
        *count = cache[supervisorID].count;
        pthread_mutex_unlock(&cache[supervisorID].lock);
        return 0; // Cache hit
    }

    int res = fetchEmployeeDetails(supervisorID, employees, count);
    if(res == 0) {
        cache[supervisorID].id = supervisorID;
        cache[supervisorID].employees = *employees;
        cache[supervisorID].count = *count;
        pthread_mutex_unlock(&cache[supervisorID].lock);
    }

    return res;
}

// Example usage
int main() {
    Employee *employees;
    int count;

    int supervisorID = 12345; // Example supervisor ID

    if(getEmployeeDetails(supervisorID, &employees, &count) == 0) {
        for(int i = 0; i < count; i++) {
            printf("Name: %s, City: %s, Address: %s\n", employees[i].name, employees[i].city, employees[i].address);
        }
    } else {
        printf("Failed to retrieve employee details.\n");
    }

    return 0;
}
```

