import java.util.Random;

public class FactorialCalculator {
    private static Random prng = new Random();

    public static long factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input must be non-negative");
        }
        if (n == 0 || n == 1) {
            return 1;
        }
        return n * factorial(n - 1);
    }

    public static void main(String[] args) {
        int seed = prng.nextInt();
        System.out.println("Using seed: " + seed);
        prng.setSeed(seed);

        // Unit tests
        assert factorial(0) == 1 : "Factorial of 0 should be 1";
        assert factorial(5) == 120 : "Factorial of 5 should be 120";
        assert factorial(10) == 3628800 : "Factorial of 10 should be 3628800";

        try {
            System.out.println("Factorial of -1: " + factorial(-1));
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage()); // Expected exception
        }

        System.out.println("Factorial of 20: " + factorial(20));
    }
}
```

