void generate_new_filename(const char *input_filename, const char *file_type) {
    size_t input_length = strlen(input_filename);
    if (input_length >= MAX_FILENAME_LENGTH - 10) {
        // Handle edge case: filename too long
        return;
    }
    char new_filename[MAX_FILENAME_LENGTH];
    strcpy(new_filename, input_filename);
    for (size_t i = 0; i < input_length; ++i) {
        if (input_filename[i] == '.') {
            new_filename[i + 1] = 'r';
            size_t num_digits = input_length - i - 1;
            char digits[10];
            snprintf(digits, sizeof(digits), "%lu", rand() % ((long)pow(10, num_digits)));
            strncat(new_filename, digits, MAX_FILENAME_LENGTH - strlen(new_filename) - 1);
            new_filename[MAX_FILENAME_LENGTH - 1] = '\0';
            break;
