// Function to derive key and IV from password using SHA-256
void derive_key_and_iv(const char *password, unsigned char *key, unsigned char *iv) {
    SHA256_CTX sha256;
    unsigned char hash[SHA256_DIGEST_LENGTH];

    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(hash, &sha256);

    memcpy(key, hash, AES_KEY_SIZE); // Use first 32 bytes for key
    memcpy(iv, hash + AES_KEY_SIZE, AES_BLOCK_SIZE); // Next 16 bytes for IV
}

// Function to initialize AES-256-GCM cipher using OpenSSL
AES_CIPHER_CTX *init_aes_cipher(const char *password) {
    AES_CIPHER_CTX *ctx = AES_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];

    derive_key_and_iv(password, key, iv);

    if (AES_set_encrypt_key(key, 256, ctx) != 0 || AES_GCM_SetIV(ctx, iv, AES_BLOCK_SIZE) != 0) {
        AES_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

