using System;
using System.IO;
using System.Security.Cryptography;

public struct ConnectionDetails
{
    public string Title;
    // Other fields...
}

public delegate void CallbackFunction();

public struct DataPacket
{
    public string Password;
    public string UserId;
    public ConnectionDetails ConnDetails;
    public CallbackFunction Callback;
    public byte[] EncryptedData;
    public Config Config;
}

public struct Config
{
    public byte[] Key;
    public byte[] IV;
}

public enum ErrorCode
{
    Success = 0,
    EmptyPassword,
    NullUserId,
    InvalidConnectionTitle,
    NullCallback,
    NullConfig,
    InvalidDecryptionKeyIV,
    DecryptionFailure,
    InvalidString
}

public class DataProcessor
{
    private static readonly log4net.ILog log = log4net.LogManager.GetLogger(typeof(DataProcessor));

    public ErrorCode ProcessDataPacket(ref DataPacket packet)
    {
        try
        {
            if (string.IsNullOrEmpty(packet.Password))
            {
                log.Error("Empty password");
                return ErrorCode.EmptyPassword;
            }

            if (packet.UserId == null)
            {
                log.Error("Null user ID");
                return ErrorCode.NullUserId;
            }

            if (string.IsNullOrEmpty(packet.ConnDetails.Title))
            {
                log.Error("Invalid connection title");
                return ErrorCode.InvalidConnectionTitle;
            }

            if (packet.Callback == null)
            {
                log.Error("Null callback function");
                return ErrorCode.NullCallback;
            }

            if (packet.Config == null || packet.Config.Key == null || packet.Config.IV == null)
            {
                log.Error("Invalid configuration");
                return ErrorCode.InvalidDecryptionKeyIV;
            }

            byte[] decryptedData = Decrypt(packet.EncryptedData, packet.Config.Key, packet.Config.IV);
            if (decryptedData == null)
            {
                log.Error("Decryption failure");
                return ErrorCode.DecryptionFailure;
            }

            string decryptedString = System.Text.Encoding.UTF8.GetString(decryptedData);
            if (string.IsNullOrEmpty(decryptedString))
            {
                log.Error("Invalid decrypted string");
                return ErrorCode.InvalidString;
            }

            // Process the decrypted data...
        }
        catch (Exception ex)
        {
            log.Error($"Unexpected error: {ex.Message}");
            return ErrorCode.DecryptionFailure;
        }

        return ErrorCode.Success;
    }

    private byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (TripleDES des = TripleDES.Create())
        {
            des.Key = key;
            des.IV = iv;
            des.Mode = CipherMode.CBC;
            des.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = des.CreateDecryptor();
            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[encryptedData.Length];
                    int bytesRead = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes;
                }
            }
        }
    }
}
```

This code defines a `DataProcessor` class with a `ProcessDataPacket` method that performs the required checks and decrypts the data packet. It uses Triple DES encryption for decryption and log4net for logging. The method returns an `ErrorCode` indicating the result of the operation.']

