typedef struct {
    long offset;
    int key;
    char flag;
} Record;

Record* generate_records(long max_offset, int max_key, int sum_limit, unsigned seed) {
    srand(seed);

    // Allocate memory for the arrays
    long* offsets = (long*)malloc(max_key * sizeof(long));
    if (!offsets) return NULL;

    int* keys = (int*)malloc(max_key * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    Record* records = (Record*)malloc(max_key * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    int sum = 0;
    for (int i = 0; i < max_key; i++) {
        offsets[i] = rand() % (max_offset + 1);
        keys[i] = rand() % (sum_limit / max_key + 1);
        sum += keys[i];

        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].flag = rand() % (CHAR_MAX - CHAR_MIN + 1) + CHAR_MIN;
    }

    if (sum > sum_limit) {
        // Free allocated memory and return NULL if sum exceeds the limit
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    return records;
}

void free_records(Record* records, int max_key) {
    if (records) free(records);
}
