#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 2048

typedef struct {
    long offset;
    int key;
    char flag;
} record;

int is_key_used(int *used_keys, int used_count, int key) {
    for (int i = 0; i < used_count; ++i) {
        if (used_keys[i] == key) return 1;
    }
    return 0;
}

int get_unused_key(int *used_keys, int used_count) {
    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (is_key_used(used_keys, used_count, key));
    return key;
}

record* create_records(int num_records, pthread_mutex_t *lock) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) return NULL;

    int *used_keys = calloc(MAX_KEYS / 8, sizeof(int)); // Assuming 32 bits per int for simplicity
    if (!used_keys) {
        free(records);
        return NULL;
    }

    srand(time(NULL));

    pthread_mutex_lock(lock);

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = get_unused_key(used_keys, used_count);
        records[i].flag = (char)(rand() % 256);
        used_keys[records[i].key / 32] |= (1 << (records[i].key % 32));
    }

    pthread_mutex_unlock(lock);

    free(used_keys);
    return records;
}

void destroy_records(record *records, int num_records) {
    if (records) {
        free(records);
    }
}
