    public static void processAndExecute(String command, String filePath) throws IOException {
        // Check if file exists and delete it
        File file = new File(filePath);
        if (file.exists()) {
            Files.deleteIfExists(file.toPath());
        }

        try {
            // Dynamically allocate memory for long offset values and int keys arrays
            final int size = 1000; // Example size
            long[] offsets = new long[size];
            int[] keys = new int[size];

            SecureRandom secureRandom = new SecureRandom();
            Random random = new Random();

            // Initialize arrays with random values using a cryptographically strong PRNG
            for (int i = 0; i < size; i++) {
                offsets[i] = secureRandom.nextLong();
                keys[i] = secureRandom.nextInt(1000); // Example range
            }

            // Allocate and initialize an array of Record objects with random values
            Record[] records = new Record[size];
            for (int i = 0; i < size; i++) {
                records[i] = new Record(random.nextInt(1000)); // Example range
            }

            // Execute system command with appropriate input/output/error redirection
            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            processBuilder.redirectInput(ProcessBuilder.Redirect.INHERIT);
            processBuilder.redirectOutput(ProcessBuilder.Redirect.to(file));
            processBuilder.redirectError(ProcessBuilder.Redirect.to(new File(filePath + ".err")));

            Process process = processBuilder.start();
            int exitCode = process.waitFor();

            if (exitCode == 0) {
                System.out.println("Command executed successfully.");
            } else {
                System.err.println("Command execution failed with exit code: " + exitCode);
            }

        } catch (InterruptedException e) {
