typedef struct {
    long *offsets;
    int *keys;
    size_t count;
    size_t capacity;
} RecordArray;

RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray *array = (RecordArray*)malloc(sizeof(RecordArray));
    array->offsets = (long*)calloc(initial_capacity, sizeof(long));
    array->keys = (int*)calloc(initial_capacity, sizeof(int));
    array->count = 0;
    array->capacity = initial_capacity;
    return array;
}

void destroy_record_array(RecordArray *array) {
    free(array->offsets);
    free(array->keys);
    free(array);
}

void expand_record_array(RecordArray *array) {
    size_t new_capacity = array->capacity * 2;
    long *new_offsets = (long*)realloc(array->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(array->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        // Handle memory allocation failure
        return;
    }

    array->offsets = new_offsets;
    array->keys = new_keys;
    array->capacity = new_capacity;
}

void add_record(RecordArray *array, long offset, int key) {
    if (array->count >= array->capacity) {
        expand_record_array(array);
    }

    array->offsets[array->count] = offset;
    array->keys[array->count++] = key;
}

