import java.util.*;
import java.security.SecureRandom;

public class InputHandler {

    private static final int MAX_INT_VALUE = 1024;
    private static final SecureRandom secureRandom = new SecureRandom();
    private Set<Integer> usedKeys;

    public void handleInput() {
        usedKeys = ConcurrentHashMap.newKeySet();

        try (Scanner scanner = new Scanner(System.in)) {
            while (scanner.hasNext()) {
                if (scanner.hasNextInt()) {
                    int intValue = scanner.nextInt();
                    if (!isValidInteger(intValue)) {
                        System.err.println("Invalid integer: " + intValue);
                        continue;
                    }
                    storeInteger(intValue);
                } else if (scanner.hasNextDouble()) {
                    double doubleValue = scanner.nextDouble();
                    // Store double value
                } else {
                    System.err.println("Invalid input: " + scanner.next());
                }
            }
        } catch (OutOfMemoryError e) {
            System.err.println("Out of memory error. Rolling back.");
            cleanup();
        }

        cleanup();
    }

    private boolean isValidInteger(int value) {
        return value >= 0 && value < MAX_INT_VALUE;
    }

    private void storeInteger(int value) {
        int key = generateUniqueKey();
        if (key == -1) {
            System.err.println("Failed to generate unique key. Rolling back.");
            cleanup();
        }
        // Store the integer with the generated key
    }

    private int generateUniqueKey() {
        while (true) {
            int key = secureRandom.nextInt(MAX_INT_VALUE);
            if (!usedKeys.contains(key)) {
                usedKeys.add(key);
                return key;
            }
        }
    }

    private void cleanup() {
        usedKeys.clear();
    }
}
