Record* allocateRecords(int numRecords, int range) {
    if (numRecords <= 0 || range <= 0) {
        return NULL;
    }

    Record* records = malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        return NULL;
    }

    if (!RAND_load_file("/dev/urandom", 1024)) {
        free(records);
        return NULL;
    }

    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = i * sizeof(Record);
        records[i].key = rand() % range;
        if (!RAND_bytes((unsigned char*)&records[i].randomValue, sizeof(records[i].randomValue))) {
            free(records);
            return NULL;
        }
    }

    return records;
}

void freeRecords(Record* records) {
    free(records);
}
