int initialize_records(int start_range, int end_range, long *offsets, int *keys, record **records, size_t num_records) {
    if (num_records <= 0) {
        fprintf(stderr, "Number of records must be greater than zero.\n");
        return -1;
    }

    offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets.");
        return -1;
    }

    keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys.");
        return -1;
    }

    *records = (record *)malloc(num_records * sizeof(record));
    if (!*records) {
        free(keys);
        free(offsets);
        perror("Failed to allocate memory for records.");
        return -1;
    }

    srand(time(NULL)); // Seed the PRNG with current time

    size_t initialized_count = 0;
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (end_range - start_range + 1) + start_range;
        keys[i] = rand() % (end_range - start_range + 1) + start_range;

        (*records)[i].value = rand() % (end_range - start_range + 1) + start_range;
        if ((*records)[i].value != 0) {
            ++initialized_count;
        }
    }

    return initialized_count;
}

void free_resources(long *offsets, int *keys, record *records, size_t num_records) {
    free(offsets);
    free(keys);
    free(records);
}
