#include <stdlib.h>
#include <stdio.h>

typedef struct Record {
    int value;
    struct Record *next;
} Record;

typedef struct List {
    Record *head;
    Record *tail;
    size_t count;
} List;

void list_init(List *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

void list_insert(List *list, int value) {
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_record->value = value;
    new_record->next = NULL;

    if (list->tail) {
        list->tail->next = new_record;
    } else {
        list->head = new_record;
    }
    list->tail = new_record;
    list->count++;
}

void list_free(List *list) {
    Record *current = list->head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }
    list_init(list);
}
