Record* create_records(size_t count, int min_range, int max_range) {
    if (count == 0 || min_range > max_range) return NULL;

    Record* records = malloc(count * sizeof(Record));
    if (!records) return NULL;

    if (!RAND_load_file("/dev/urandom", 1024)) {
        free(records);
        return NULL;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    for (size_t i = 0; i < count; ++i) {
        records[i].timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
        records[i].identifier = i;

        if (!RAND_bytes((unsigned char*)&records[i].random_value, sizeof(records[i].random_value))) {
            free(records);
            return NULL;
        }

        records[i].random_value = min_range + (records[i].random_value % (max_range - min_range + 1));
    }

    return records;
}

void free_records(Record* records) {
    if (records) free(records);
}
