#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

long* create_offsets(long size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (offsets == NULL) return NULL;
    for (long i = 0; i < size; ++i) {
        offsets[i] = i;
    }
    return offsets;
}

int* create_keys(int N, int minN, int maxN) {
    if (N <= 0 || N > maxN || minN < 1 || maxN < minN) return NULL;
    int* keys = (int*)malloc(N * sizeof(int));
    if (keys == NULL) return NULL;
    for (int i = 0; i < N; ++i) {
        keys[i] = minN + i;
    }
    return keys;
}

record* create_records(int N, int minValue, int maxValue) {
    record* records = (record*)malloc(N * sizeof(record));
    if (records == NULL) return NULL;
    srand(time(0)); // Seed PRNG
    for (int i = 0; i < N; ++i) {
        records[i].value = minValue + rand() % (maxValue - minValue + 1);
    }
    return records;
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long size = 1024;
    int N = 500, minN = 1, maxN = 1000;

    long* offsets = create_offsets(size);
    int* keys = create_keys(N, minN, maxN);
    record* records = create_records(N, minValue, maxValue);

    if (offsets && keys && records) {
        // Use the allocated memory
        free_memory(offsets, keys, records);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
