import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;

public class PaymentTransactionManager {
    private static final SecureRandom secureRandom = new SecureRandom();
    private static final ConcurrentHashMap<Long, TransactionDetails> transactionMap = new ConcurrentHashMap<>();
    private static final int MAX_TRANSACTION_ID = 2147483647;

    public static synchronized long generateUniqueTransactionID() {
        long transactionID;
        do {
            transactionID = secureRandom.nextLong();
            if (transactionID < 0) {
                transactionID = -transactionID; // Ensure positive
            }
        } while (!allocateUniqueID(transactionID));
        return transactionID;
    }

    private static boolean allocateUniqueID(long id) {
        return !transactionMap.containsKey(id);
    }

    public static void storeTransactionDetails(long transactionID, String userID, double amount, TransactionStatus status) {
        if (userID == null || userID.isEmpty()) {
            throw new IllegalArgumentException("Invalid user ID");
        }
        TransactionDetails details = new TransactionDetails(userID, amount, status);
        transactionMap.put(transactionID, details);
    }

    public static TransactionDetails getTransactionDetails(long transactionID) {
        return transactionMap.getOrDefault(transactionID, null);
    }

    public static void cleanup() {
        transactionMap.clear();
    }
}

class TransactionDetails {
    private String userID;
    private double amount;
    private TransactionStatus status;

    public TransactionDetails(String userID, double amount, TransactionStatus status) {
        this.userID = userID;
        this.amount = amount;
        this.status = status;
    }

    // Getters and setters
}

enum TransactionStatus {
    PENDING,
    COMPLETED,
    FAILED
}
