    DataStorage *storage = (DataStorage *)malloc(sizeof(DataStorage));
    storage->offsets = (long *)calloc(MAX_KEYS, sizeof(long));
    storage->keys = (int *)calloc(MAX_KEYS, sizeof(int));
    storage->records = (Record *)malloc(1024 * sizeof(Record));
    storage->record_count = 0;
    pthread_mutex_init(&storage->lock, NULL);
    return storage;
