void data_storage_free(DataStorage *storage) {
    free(storage->offsets);
    free(storage->keys);
    for (int i = 0; i < storage->record_count; i++) {
        // Free any allocated resources within records if necessary
    }
    free(storage->records);
    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

int data_storage_add_record(DataStorage *storage, int value) {
    pthread_mutex_lock(&storage->lock);
    for (int i = 0; i < storage->record_count; i++) {
        if (storage->records[i].value == value) {
            pthread_mutex_unlock(&storage->lock);
            return -1; // Duplicate value
        }
    }
    if (storage->record_count >= 1024) {
        pthread_mutex_unlock(&storage->lock);
        return -2; // No more space
    }
    storage->records[storage->record_count].value = value;
    storage->record_count++;
    pthread_mutex_unlock(&storage->lock);
    return 0;
}

int data_storage_find_largest(DataStorage *storage) {
    pthread_mutex_lock(&storage->lock);
    int largest = -1;
    for (int i = 0; i < storage->record_count; i++) {
        if (storage->records[i].value > largest) {
            largest = storage->records[i].value;
        }
    }
    pthread_mutex_unlock(&storage->lock);
    return largest;
}

