#include <time.h>

#define TABLE_SIZE 1024

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    int key;
    struct Node* next;
} Node;

Node* table[TABLE_SIZE] = {NULL};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_table() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        table[i] = NULL;
    }
}

unsigned int hash(int key) {
    return key % TABLE_SIZE;
}

Node* create_node(int key) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node != NULL) {
        node->key = key;
        node->next = NULL;
    }
    return node;
}

void insert_key(int key) {
    pthread_mutex_lock(&lock);
    int index = hash(key);
    Node* new_node = create_node(key);
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&lock);
        return;
    }
    new_node->next = table[index];
    table[index] = new_node;
    pthread_mutex_unlock(&lock);
}

void* generate_records(void* arg) {
    int num_records = *(int*)arg;
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % 1001;
        } while (is_record_allocated(value));

        records[i].value = value;
    }

    // Simulate processing of records
    for (int i = 0; i < num_records; ++i) {
        printf("Record value: %d\n", records[i].value);
    }

    free(records);
    return NULL;
}

int is_record_allocated(int value) {
    pthread_mutex_lock(&lock);
    int index = hash(value);
    Node* current = table[index];
    while (current != NULL) {
        if (current->key == value) {
            pthread_mutex_unlock(&lock);
            return 1;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return 0;
}

void cleanup() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node* current = table[i];
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
}

int main() {
    init_table();

    int num_records = 1000;
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, generate_records, &num_records) != 0) {
        perror("Failed to create thread");
        cleanup();
        return EXIT_FAILURE;
    }

    if (pthread_join(thread_id, NULL) != 0) {
        perror("Failed to join thread");
        cleanup();
        return EXIT_FAILURE;
    }

    cleanup();

    return EXIT_SUCCESS;
}
