import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

public class RemoteServiceConnection {

    private static final int MAX_KEYS = 1024;
    private static final SecureRandom secureRandom = new SecureRandom();
    private static final ConcurrentHashMap<Integer, Boolean> usedKeys = new ConcurrentHashMap<>();
    private SocketChannel channel;

    public void establishConnection(String serverAddress, int port) throws IOException {
        channel = SocketChannel.open();
        channel.connect(new InetSocketAddress(serverAddress, port));
    }

    public long allocateOffset() {
        while (true) {
            long offset = secureRandom.nextLong();
            if (offset >= 0 && !usedKeys.containsKey((int) offset)) {
                usedKeys.put((int) offset, true);
                return offset;
            }
        }
    }

    public int[] generateUniqueKeys(int count) throws InterruptedException {
        if (count > MAX_KEYS) {
            throw new IllegalArgumentException("Cannot generate more than " + MAX_KEYS + " unique keys");
        }

        List<Integer> keys = new ArrayList<>();
        while (keys.size() < count) {
            int key;
            do {
                key = secureRandom.nextInt(MAX_KEYS);
            } while (!usedKeys.putIfAbsent(key, true) == null);
            keys.add(key);
        }
        return keys.stream().mapToInt(Integer::intValue).toArray();
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        RemoteServiceConnection connection = new RemoteServiceConnection();
        connection.establishConnection("example.com", 8080);

        int[] inputArray = readInputArray(System.in);
        int maxNumber = findMaxNumber(inputArray);
        System.out.println("The largest number is: " + maxNumber);

        connection.cleanup();
    }

    private static int[] readInputArray(java.io.InputStream input) throws IOException {
        List<Integer> numbers = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(input))) {
            String line;
            while ((line = reader.readLine()) != null) {
                for (String token : line.split("\\s+")) {
                    try {
                        numbers.add(Integer.parseInt(token));
                    } catch (NumberFormatException e) {
                        System.err.println("Malformed integer input: " + token);
                    }
                }
            }
        }
        return numbers.stream().mapToInt(Integer::intValue).toArray();
    }

    private static int findMaxNumber(int[] array) {
        if (array.length == 0) {
            throw new IllegalArgumentException("Input array cannot be empty");
        }
        return IntStream.of(array).max().getAsInt();
    }

    public void cleanup() throws IOException {
        usedKeys.clear();
        channel.close();
    }
}
