import java.util.*;
import java.nio.channels.*;
import java.math.*;

public class FinancialTransactionProcessor {

    private static final int MAX_TRANSACTION_ID_LENGTH = 1024;
    private static Set<String> usedIds = Collections.synchronizedSet(new HashSet<>());

    public void processTransactions() {
        try (Channel channel = SocketChannel.open()) {
            // Connect to the financial transaction database
            channel.connect(new InetSocketAddress("localhost", 8080));

            // Read a list of integers from standard input
            Scanner scanner = new Scanner(System.in);
            int[] numbers = Arrays.stream(scanner.nextLine().split(","))
                                  .mapToInt(Integer::parseInt)
                                  .toArray();

            // Find and print the sum of all positive integers in the array
            System.out.println("Sum of positive integers: " + findSumOfPositives(numbers));

            while (true) {
                // Asynchronously read transaction data from network
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                channel.read(buffer);

                // Process each transaction
                processTransaction(buffer);
            }
        } catch (IOException e) {
            System.err.println("Error processing transactions: " + e.getMessage());
        }
    }

    private int findSumOfPositives(int[] numbers) {
        return Arrays.stream(numbers)
                      .filter(n -> n > 0)
                      .sum();
    }

    private void processTransaction(ByteBuffer buffer) throws IOException {
        Random random = new SecureRandom();
        while (buffer.hasRemaining()) {
            double amount = random.nextInt(10000) + 1;
            String id = generateUniqueId();

            if (!usedIds.contains(id)) {
                usedIds.add(id);
                // Write transaction data to the financial transaction database
                writeToDatabase(amount, id);
            } else {
                throw new IOException("Duplicate transaction ID generated");
            }
        }
    }

    private void writeToDatabase(double amount, String id) throws IOException {
        // Simulate writing to a database using network communication
        try (Channel channel = SocketChannel.open()) {
            channel.connect(new InetSocketAddress("localhost", 9090));
            ByteBuffer buffer = ByteBuffer.allocate(128);
            buffer.putDouble(amount);
            buffer.putInt(id.length());
            buffer.put(id.getBytes(), 0, id.length());
            buffer.flip();
            channel.write(buffer);
        }
    }

    private String generateUniqueId() {
        return UUID.randomUUID().toString().substring(0, MAX_TRANSACTION_ID_LENGTH);
    }

    public static void main(String[] args) {
        FinancialTransactionProcessor processor = new FinancialTransactionProcessor();
        processor.processTransactions();
    }
}
