    if (records == NULL) {
        free(*keys);
        free(*offsets);
        free(key_set);
        return NULL;
    }

    for (int i = 0; i < size; ) {
        int key = rand() % key_range;
        if (!key_set[key]) {
            (*keys)[i] = key;
            key_set[key] = 1;

            records[i].value = rand();
            (*offsets)[i++] = (long)records + i * sizeof(record);
        }
    }

    free(key_set);
    return records;
}

void destroy_records(int size, long* offsets, int* keys, record* records) {
    if (records != NULL) free(records);
    if (keys != NULL) free(keys);
