#define INITIAL_CAPACITY 16

typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
    size_t size;
} HashTable;

typedef struct {
    int value;
} Record;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->size = 0;
    table->offsets = (long*)calloc(initial_capacity, sizeof(long));
    table->keys = (int*)calloc(initial_capacity, sizeof(int));
    return table;
}

void destroy_hash_table(HashTable *table) {
    free(table->offsets);
    free(table->keys);
    free(table);
}

size_t hash_function(int key, size_t capacity) {
    return ((key * 23) % capacity + 1) % capacity;
}

int insert_into_hash_table(HashTable *table, int key, long offset) {
    size_t index = hash_function(key, table->capacity);
    for (size_t i = index; ; i = (i + 1) % table->capacity) {
        if (table->keys[i] == -1) {
            table->keys[i] = key;
            table->offsets[i] = offset;
            table->size++;
            return 0;
        }
    }
}

Record* generate_records(size_t count, int range, pthread_mutex_t *mutex) {
    Record *records = (Record*)malloc(count * sizeof(Record));
    for (size_t i = 0; i < count; i++) {
        records[i].value = rand_r(&seed) % range;
    }
    return records;
}

void reset_prng(unsigned int seed) {
    srand(seed);
}

void* thread_function(void *arg) {
    pthread_mutex_t *mutex = (pthread_mutex_t*)arg;
    pthread_mutex_lock(mutex);
    // Perform PRNG operations
    pthread_mutex_unlock(mutex);
    return NULL;
}

int main() {
