public class RemoteServerConnection {

    private AsynchronousServerSocketChannel serverChannel;
    private ConcurrentHashMap<String, Record> recordMap;
    private SecureRandom secureRandom;

    public RemoteServerConnection(int port) throws IOException {
        this.serverChannel = AsynchronousServerSocketChannel.open();
        this.recordMap = new ConcurrentHashMap<>();
        this.secureRandom = new SecureRandom();
        serverChannel.bind(new InetSocketAddress(port));
        AsynchronousChannelGroup group = AsynchronousChannelGroup.withFixedThreadPool(10);
        serverChannel.getExecutor().execute(() -> {
            while (true) {
                try {
                    AsynchronousSocketChannel clientChannel = serverChannel.accept().get();
                    handleClientConnection(clientChannel);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        });
    }

    private void handleClientConnection(AsynchronousSocketChannel clientChannel) throws IOException, InterruptedException {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        while (clientChannel.read(buffer).get() > 0) {
            buffer.flip();
            String data = new String(buffer.array(), 0, buffer.limit());
            // Process the data and handle requests
