    private static final int MAX_RECORDS_PER_CONNECTION = 10000;
    private ExecutorService executor;
    private AsynchronousServerSocketChannel serverChannel;
    private Map<String, List<Long>> keyToRecordsMap;
    private ConcurrentHashMap<Long, Integer> recordValues;

    public ConnectionPoolManager() throws IOException {
        this.executor = Executors.newFixedThreadPool(POOL_SIZE);
        this.serverChannel = AsynchronousServerSocketChannel.open();
        this.keyToRecordsMap = new ConcurrentHashMap<>();
        this.recordValues = new ConcurrentHashMap<>();
        // Initialize connections and start server
    }

    private void initializeConnections() {
        IntStream.range(0, POOL_SIZE).forEach(i -> {
            executor.submit(() -> handleClientConnection());
        });
    }

    private void handleClientConnection() {
        try (AsynchronousSocketChannel clientChannel = serverChannel.accept().get()) {
            ByteBuffer buffer = ByteBuffer.allocate(1024);
            while (clientChannel.read(buffer).get() != -1) {
                buffer.flip();
                // Process data from client
                buffer.clear();
            }
        } catch (Exception e) {
            // Handle exceptions
        }
    }

