        Random random = new SecureRandom(seed);
        for (int i = 0; i < MAX_RECORDS_PER_CONNECTION; i++) {
            long recordKey = Math.abs(random.nextLong()) % 1024;
            if (!recordValues.containsKey(recordKey)) {
                recordValues.put(recordKey, random.nextInt());
                keyToRecordsMap.computeIfAbsent(key, k -> new ArrayList<>()).add(recordKey);
            }
        }
    }

    private int findMaxValue() {
        return recordValues.values().stream().max(Integer::compare).orElse(0);
    }

    private int findMinValue() {
        return recordValues.values().stream().min(Integer::compare).orElse(0);
    }

    public void closeConnections() throws InterruptedException, ExecutionException {
        executor.shutdown();
        serverChannel.close();
        for (Future<?> future : executor.shutdownNow()) {
            future.get();
        }
    }

