using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;

public class CustomSymmetricEncryption
{
    private readonly ConcurrentDictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>();
    private SymmetricAlgorithm _algorithm;
    private byte[] _fallbackKey;
    private byte[] _fallbackIV;
    private bool _enableFallback;
    private ILogger _logger;

    public CustomSymmetricEncryption(byte[] key, byte[] iv, bool enableFallback)
    {
        Initialize(key, iv, enableFallback);
    }

    public void Initialize(byte[] key, byte[] iv, bool enableFallback)
    {
        if (key == null || iv == null)
            throw new ArgumentException("Key and IV cannot be null.");

        // Validate key and IV lengths
        if ((key.Length != 32 && key.Length != 64) || iv.Length != 16)
            throw new ArgumentException("Invalid key or IV length.");

        _algorithm = Aes.Create();
        _fallbackKey = enableFallback ? key : null;
        _fallbackIV = enableFallback ? iv : null;
        _enableFallback = enableFallback;

        // Initialize logger
        _logger = LoggerFactory.GetLogger(typeof(CustomSymmetricEncryption));
    }

    public byte[] Encrypt(byte[] data)
    {
        using (ICryptoTransform encryptor = _algorithm.CreateEncryptor(_algorithm.Key, _algorithm.IV))
        {
            return TransformData(data, encryptor);
        }
    }

    public byte[] Decrypt(string key, string iv, byte[] data)
    {
        if (_enableFallback && (string.IsNullOrEmpty(key) || string.IsNullOrEmpty(iv)))
        {
            key = Encoding.UTF8.GetString(_fallbackKey);
            iv = Encoding.UTF8.GetString(_fallbackIV);
        }

        byte[] keyBytes;
        byte[] ivBytes;

        try
        {
            keyBytes = Convert.FromBase64String(key);
            ivBytes = Convert.FromBase64String(iv);
        }
        catch (FormatException)
        {
            _logger.LogError("Invalid key or IV format.");
            throw new ArgumentException("Invalid key or IV format.");
        }

        using (ICryptoTransform decryptor = _algorithm.CreateDecryptor(keyBytes, ivBytes))
        {
            return TransformData(data, decryptor);
        }
    }

    private byte[] TransformData(byte[] data, ICryptoTransform transform)
    {
        // Check for size limits
        if (data.Length > 1048576) // 1MB limit
            throw new InvalidOperationException("Data size exceeds the maximum allowed.");

        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, transform, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
            }
            return ms.ToArray();
        }
    }

    public void ClearCache()
    {
        _cache.Clear();
    }

    // Implement logger interface and factory
    public interface ILogger
    {
        void LogError(string message);
    }

    public class LoggerFactory
    {
        public static ILogger GetLogger(Type type)
        {
            return new ConsoleLogger();
        }
    }

    public class ConsoleLogger : ILogger
    {
        public void LogError(string message)
        {
            Console.Error.WriteLine(message);
        }
    }
}
