#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define SESSION_ID_LEN 10

typedef struct {
    char session_id[SESSION_ID_LEN];
    time_t timestamp;
    unsigned int sequence_number;
} Session;

Session* allocate_sessions(int num_sessions, int* error_code) {
    if (num_sessions <= 0) {
        *error_code = -1; // Invalid number of sessions
        return NULL;
    }

    Session* sessions = malloc(num_sessions * sizeof(Session));
    if (!sessions) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_sessions; i++) {
        sprintf(sessions[i].session_id, "S%04d", i);
        sessions[i].timestamp = time(NULL);
        sessions[i].sequence_number = rand_r((unsigned int*)&i); // Pseudo-random number generator
    }

    pthread_mutex_unlock(&mutex);

    *error_code = 0; // Success
    return sessions;
}

void free_sessions(Session* sessions) {
    if (sessions) {
        free(sessions);
    }
}
