#define MAX_RECORDS 1024

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
    size_t capacity;
    unsigned long seed;
} MemoryManager;

void init_memory_manager(MemoryManager *mm, unsigned long seed) {
    mm->offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    mm->keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    mm->records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    if (!mm->offsets || !mm->keys || !mm->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    mm->size = 0;
    mm->capacity = MAX_RECORDS;
    mm->seed = seed;
}

void free_memory_manager(MemoryManager *mm) {
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
}

unsigned long xorshift128plus(unsigned long *x, unsigned long *y) {
    unsigned long s0 = x[0];
    unsigned long s1 = y[0];
    unsigned long result = s0 + s1;

    s0 ^= s0 << 17;
    s0 -= s0 >> 31;
    x[0] = s0;

    s1 ^= s1 << 7;
    s1 -= s1 >> 29;
    y[0] = s1;

    return result + s1;
}

void add_record(MemoryManager *mm, int key, long offset) {
    if (mm->size == mm->capacity) {
        size_t new_capacity = mm->capacity * 2;
        long *new_offsets = (long *)realloc(mm->offsets, new_capacity * sizeof(long));
        int *new_keys = (int *)realloc(mm->keys, new_capacity * sizeof(int));
        Record *new_records = (Record *)realloc(mm->records, new_capacity * sizeof(Record));

        if (!new_offsets || !new_keys || !new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }

        mm->offsets = new_offsets;
        mm->keys = new_keys;
        mm->records = new_records;
        mm->capacity = new_capacity;
    }

    mm->offsets[mm->size] = offset;
    mm->keys[mm->size] = key;

    static unsigned long s0 = 123456789, s1 = 987654321;
    for (size_t i = 0; i < mm->size; ++i) {
        unsigned long rand_val = xorshift128plus(&s0, &s1);
        mm->records[i].value = rand_val;
    }

    mm->size++;
}

void print_records(MemoryManager *mm) {
    for (size_t i = 0; i < mm->size; ++i) {
        printf("Key: %d, Offset: %ld, Record Value: %d\n", 
               mm->keys[i], mm->offsets[i], mm->records[i].value);
    }
}

int main() {
    unsigned long seed = time(NULL); // Use current time as default seed
    MemoryManager mm;
    init_memory_manager(&mm, seed);

    add_record(&mm, 10, 20L);
    add_record(&mm, 30, 40L);

    print_records(&mm);

    free_memory_manager(&mm);
    return 0;
}
