void initialize_directory(Directory* dir, size_t size) {
    dir->data = malloc(size * sizeof(char*));
    dir->lengths = malloc(size * sizeof(size_t));
    dir->used_size = 0;
    dir->total_size = size;
}

void free_directory(Directory* dir) {
    for (size_t i = 0; i < dir->used_size; ++i) {
        free(dir->data[i]);
    }
    free(dir->data);
    free(dir->lengths);
}

int create_directory() {
    if (num_dirs >= MAX_DIRS) return -1;
    initialize_directory(&directories[num_dirs], THRESHOLD);
    num_dirs++;
    return num_dirs - 1;
}

void delete_directory(int dir_index) {
    if (dir_index < 0 || dir_index >= num_dirs) return;
    free_directory(&directories[dir_index]);
    num_dirs--;
}

int main() {
    // Example usage
    int dir_index = create_directory();
    if (dir_index != -1) {
        printf("Directory created at index %d\n", dir_index);
    } else {
        printf("Failed to create directory\n");
    }
    delete_directory(dir_index);
    return 0;
}
