['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t num_records;
    pthread_mutex_t key_lock;
    int used_keys[MAX_KEYS];
} shared_resource;

shared_resource *init_shared_resource(size_t num_records) {
    shared_resource *res = (shared_resource *)malloc(sizeof(shared_resource));
    if (!res) return NULL;

    res->offsets = (long *)calloc(num_records, sizeof(long));
    res->keys = (int *)calloc(num_records, sizeof(int));
    res->records = (record *)calloc(num_records, sizeof(record));
    res->num_records = num_records;
    pthread_mutex_init(&res->key_lock, NULL);

    for (size_t i = 0; i < MAX_KEYS; ++i) {
        res->used_keys[i] = -1;
    }

    return res;
}

void free_shared_resource(shared_resource *res) {
    if (res) {
        free(res->offsets);
        free(res->keys);
        free(res->records);
        pthread_mutex_destroy(&res->key_lock);
        free(res);
    }
}

int generate_random_key() {
    static int seed = 0;
    if (!seed) {
        seed = time(NULL);
        srand(seed);
    }
    return rand() % MAX_KEYS;
}

void add_record(shared_resource *res, record value) {
    pthread_mutex_lock(&res->key_lock);
    int key;
    do {
        key = generate_random_key();
    } while (res->used_keys[key] != -1);

    res->keys[res->num_records] = key;
    res->offsets[res->num_records] = (long)value.value;
    res->records[res->num_records++] = value;

    res->used_keys[key] = 0;
    pthread_mutex_unlock(&res->key_lock);
}

void resize_shared_resource(shared_resource *res, size_t new_size) {
    record *new_records = (record *)realloc(res->records, new_size * sizeof(record));
    if (!new_records) return;

    res->records = new_records;
    for (size_t i = res->num_records; i < new_size; ++i) {
        add_record(res, (record){rand() % 1001});
    }
}

int main() {
