#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/rand.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} Record;

typedef struct {
    // Define the structure for NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

struct UsedKeyNode {
    int key;
    struct UsedKeyNode* next;
};

typedef struct {
    pthread_mutex_t lock;
    struct UsedKeyNode* head;
} KeyPool;

void initialize_key_pool(KeyPool* pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->head = NULL;
}

int get_unused_key(KeyPool* pool) {
    int key;
    while (1) {
        if (RAND_bytes((unsigned char*)&key, sizeof(key)) != 1) {
            fprintf(stderr, "Failed to generate random number\n");
            exit(EXIT_FAILURE);
        }
        key &= 0x3FF; // Ensure the key is less than 1024

        pthread_mutex_lock(&pool->lock);
        struct UsedKeyNode* current = pool->head;
        while (current) {
            if (current->key == key) {
                pthread_mutex_unlock(&pool->lock);
                continue;
            }
            current = current->next;
        }

        // Key is unused, add it to the list
        struct UsedKeyNode* new_node = malloc(sizeof(struct UsedKeyNode));
        if (!new_node) {
            perror("Failed to allocate memory for key node");
            exit(EXIT_FAILURE);
        }
        new_node->key = key;
        new_node->next = pool->head;
        pool->head = new_node;

        pthread_mutex_unlock(&pool->lock);
        return key;
    }
}

void free_key(KeyPool* pool, int key) {
    pthread_mutex_lock(&pool->lock);
    struct UsedKeyNode* current = pool->head;
    struct UsedKeyNode* prev = NULL;
    while (current) {
        if (current->key == key) {
            if (prev) {
                prev->next = current->next;
            } else {
                pool->head = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&pool->lock);
}

Record* allocate_records(int n, KeyPool* key_pool) {
    Record* records = malloc(n * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        records[i].value = get_unused_key(key_pool);
    }

    return records;
}

void free_records(int n, Record* records, KeyPool* key_pool) {
    for (int i = 0; i < n; ++i) {
        free_key(key_pool, records[i].value);
    }
    free(records);
}

NFAPI_CRC_INDICATION_PDU_T* create_ndapi_pdu(KeyPool* key_pool, int n) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate memory for PDU");
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        pdu[i].RX_UE_INFORMATION_TAG = get_unused_key(key_pool);
        pdu[i].RNTI = get_unused_key(key_pool);
        if (!RAND_bytes((unsigned char*)&pdu[i].CRC_INDICATION_REL8_TAG.CRCFLAG, sizeof(pdu[i].CRC_INDICATION_REL8_TAG.CRCFLAG))) {
            fprintf(stderr, "Failed to generate random number\n");
            free_pdu(n, pdu, key_pool);
            return NULL;
        }
    }

    return pdu;
}

void free_pdu(int n, NFAPI_CRC_INDICATION_PDU_T* pdu, KeyPool* key_pool) {
    for (int i = 0; i < n; ++i) {
        free_key(key_pool, pdu[i].RX_UE_INFORMATION_TAG);
        free_key(key_pool, pdu[i].RNTI);
    }
    free(pdu);
}

void cleanup(KeyPool* pool) {
    struct UsedKeyNode* current = pool->head;
    while (current) {
        struct UsedKeyNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool->lock);
}

int main() {
    KeyPool key_pool;
    initialize_key_pool(&key_pool);

    Record* records = allocate_records(10, &key_pool);
    if (!records) {
        fprintf(stderr, "Failed to allocate records\n");
        cleanup(&key_pool);
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = create_ndapi_pdu(&key_pool, 5);
    if (!pdu) {
        fprintf(stderr, "Failed to create PDU\n");
        free_records(10, records, &key_pool);
        cleanup(&key_pool);
        return EXIT_FAILURE;
    }

    // Use the allocated resources...

    free_records(10, records, &key_pool);
    free_pdu(5, pdu, &key_pool);

    cleanup(&key_pool);
    return EXIT_SUCCESS;
}
