#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEYS 1024
#define RECORD_SIZE sizeof(record)

typedef struct {
    int value;
} record;

typedef struct {
    long* offset_values;
    int* keys;
    pthread_mutex_t used_keys_lock;
    int* used_keys;
    size_t num_records;
    size_t max_records;
} RecordManager;

RecordManager* create_record_manager(size_t max_records) {
    RecordManager* manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->offset_values = malloc(max_records * sizeof(long));
    if (!manager->offset_values) {
        free(manager);
        return NULL;
    }

    manager->keys = malloc(max_records * sizeof(int));
    if (!manager->keys) {
        free(manager->offset_values);
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->used_keys_lock, NULL);

    manager->used_keys = calloc(MAX_KEYS, sizeof(int));
    if (!manager->used_keys) {
        pthread_mutex_destroy(&manager->used_keys_lock);
        free(manager->keys);
        free(manager->offset_values);
        free(manager);
        return NULL;
    }

    manager->num_records = 0;
    manager->max_records = max_records;

    return manager;
}

int generate_random_key(RecordManager* manager) {
    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (manager->used_keys[key]);
    manager->used_keys[key] = 1;
    return key;
}

record* allocate_record(RecordManager* manager) {
    if (manager->num_records >= manager->max_records) return NULL;

    int key = generate_random_key(manager);
    record* new_record = malloc(RECORD_SIZE);
    if (!new_record) return NULL;

    new_record->value = rand() % 1001; // Random value between 0 and 1000

    manager->offset_values[manager->num_records] = (long)new_record;
    manager->keys[manager->num_records] = key;
    manager->num_records++;

    return new_record;
}

void destroy_record_manager(RecordManager* manager) {
    free(manager->used_keys);
    pthread_mutex_destroy(&manager->used_keys_lock);
    free(manager->keys);
    for (size_t i = 0; i < manager->num_records; i++) {
        free((record*)manager->offset_values[i]);
    }
    free(manager->offset_values);
    free(manager);
}

int main() {
    srand(time(NULL));
    RecordManager* manager = create_record_manager(100); // Limit to 100 records
    if (!manager) return -1;

    record* new_record = allocate_record(manager);
    while (new_record) {
        printf("Allocated record with value: %d\n", new_record->value);
        free(new_record);
        new_record = allocate_record(manager);
    }

    destroy_record_manager(manager);
    return 0;
}
```

