int init_transaction_manager(TransactionManager* manager, size_t initial_size) {
    manager->offsets = (long*)calloc(initial_size, sizeof(long));
    manager->keys = (int*)calloc(initial_size, sizeof(int));
    pthread_mutex_init(&manager->mutex, NULL);
    memset(manager->key_map, 0, MAX_KEYS * sizeof(uint8_t));

    if (!manager->offsets || !manager->keys) {
        free(manager->offsets);
        free(manager->keys);
        return -1;
    }

    return 0;
}

int allocate_transaction_id(TransactionManager* manager, uint64_t* id) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < MAX_KEYS; i++) {
        if (!manager->key_map[i]) {
            *id = rand() % UINT64_MAX;
            while (*id == 0 || manager->key_map[*id % MAX_KEYS] != 0) {
                *id = rand() % UINT64_MAX;
            }

            manager->key_map[*id % MAX_KEYS] = 1;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // No available keys
}

