void initialize_arrays() {
    offsets = (unsigned long *)malloc(MAX_KEYS * sizeof(unsigned long));
    keys = (short *)malloc(MAX_KEYS * sizeof(short));
    weights = (float *)malloc(MAX_KEYS * sizeof(float));
    items = (item *)malloc(MAX_KEYS * sizeof(item));

    if (!offsets || !keys || !weights || !items) {
        // Handle allocation failure
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        keys[i] = -1;
        weights[i] = -1.0f;
        used_keys[i] = 0;
    }
}

short generate_unique_key() {
    short key;
    do {
        key = rand() % MAX_KEYS;
    } while (keys[key] != -1);
    return key;
}

float generate_random_value() {
    return (float)rand() / RAND_MAX;
}

void add_item(short key, float weight) {
    if (key < 0 || key >= MAX_KEYS || weight <= 0.0f || weight >= 1.0f) {
        // Handle invalid input
