        return -1; // Key out of range or no space
    }

    pthread_mutex_lock(&manager->lock);

    size_t index = manager->used_keys_count;
    manager->keys[index] = key;
    manager->records[index] = record;

    pthread_mutex_unlock(&manager->lock);
    return index;
}

Record* get_record(MemoryManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->used_keys_count; ++i) {
        if (manager->keys[i] == key) {
            Record* record = manager->records[i];
            pthread_mutex_unlock(&manager->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int populate_records(MemoryManager* manager, int min_value, int max_value) {
    for (size_t i = 0; i < manager->used_keys_count; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for record");
            return -1;
        }
        record->value = manager->prng(max_value - min_value + 1) + min_value;
        manager->records[i] = record;
    }
    return 0;
}

