        if (records[i].key == key) {
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lock);
    return 1;
}

void allocate_record(int key, long offset) {
    if (allocated_keys >= MAX_KEYS) {
        log_error("Record limit reached");
        return;
    }

    pthread_mutex_lock(&lock);
    records[allocated_keys].key = key;
    records[allocated_keys].offset = offset;
    allocated_keys++;
    clock_t current_time = clock();
    double time_diff = (double)(current_time - last_alloc_time) / CLOCKS_PER_SEC;
    if (time_diff > 1.0) {
        log_performance("Allocation Rate", allocated_keys / time_diff);
        last_alloc_time = current_time;
    }
    pthread_mutex_unlock(&lock);
}

void cleanup_records() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < allocated_keys; ++i) {
        records[i].key = -1;
        records[i].offset = 0;
    }
    allocated_keys = 0;
    pthread_mutex_unlock(&lock);
}

void *thread_function(void *arg) {
    int key;
    long offset;
    while (scanf("%d", &key) == 1) {
        if (!is_key_available(key)) {
            continue;
        }
        offset = get_random_offset();
        allocate_record(key, offset);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    last_alloc_time = clock();

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, thread_function, NULL);

    pthread_join(thread_id, NULL);

    cleanup_records();
    log_performance("Total Allocations", allocated_keys);
    return 0;
}
