    transaction_arrays = (Transaction **)malloc(num_transaction_arrays * sizeof(Transaction *));
    if (!transaction_arrays) {
        perror("Failed to allocate memory for transaction arrays");
        free(used_keys);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_transaction_arrays; i++) {
        transaction_arrays[i] = (Transaction *)malloc(MAX_KEYS * sizeof(Transaction));
        if (!transaction_arrays[i]) {
            perror("Failed to allocate memory for transaction array");
            free(used_keys);
            for (int j = 0; j < i; j++)
                free(transaction_arrays[j]);
            exit(EXIT_FAILURE);
        }
    }

    srand(time(NULL));
}

unsigned int generate_unique_key() {
