    int size;
    int capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_array(DynamicArray* array, int initial_capacity) {
    array->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!array->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

void resize_array(DynamicArray* array) {
    int new_capacity = array->capacity * 2;
    Record* new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->records = new_records;
    array->capacity = new_capacity;
}

void add_record(DynamicArray* array, int key, long offset) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        resize_array(array);
    }
    Record record = {key, offset, rand() % 1001};
    array->records[array->size++] = record;
    pthread_mutex_unlock(&array->lock);
}

int find_largest_key(DynamicArray* array) {
    int max_key = -1;
    for (int i = 0; i < array->size; ++i) {
        if (array->records[i].key > max_key) {
            max_key = array->records[i].key;
        }
    }
    return max_key;
}

void free_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->records);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}
