#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <limits.h>

#define MAX_TRANSACTIONS 1000000
#define PRNG_MULTIPLIER 6364136223809651135ULL

typedef struct {
    uint64_t id;
    double amount;
} transaction;

typedef struct {
    transaction *table;
    size_t capacity;
    pthread_mutex_t lock;
} transaction_manager;

void init_transaction_manager(transaction_manager *manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->table = malloc(initial_capacity * sizeof(transaction));
    if (manager->table == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_transaction_manager(transaction_manager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->table);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int add_transaction(transaction_manager *manager, uint64_t id, double amount) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->table[i].id == UINT64_MAX) {
            manager->table[i].id = id;
            manager->table[i].amount = amount;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Capacity exceeded
}

double get_transaction_amount(transaction_manager *manager, uint64_t id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->table[i].id == id) {
            double amount = manager->table[i].amount;
            pthread_mutex_unlock(&manager->lock);
            return amount;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1.0; // Transaction not found
}

int validate_id(uint64_t id) {
    if (id < UINT64_MAX && id > 0) {
        return 1;
    }
    return 0;
}

uint64_t next_prng_value(uint64_t *state) {
    *state = (*state * PRNG_MULTIPLIER) + 1;
    return *state;
}

int main() {
    transaction_manager manager;
    init_transaction_manager(&manager, MAX_TRANSACTIONS);

    uint64_t state = time(NULL);
    for (size_t i = 0; i < manager.capacity; ++i) {
        manager.table[i].id = UINT64_MAX;
    }

    while (1) {
        uint64_t id;
        double amount;
        if (scanf("%lu %lf", &id, &amount) != 2 || !validate_id(id)) {
            break;
        }
        if (add_transaction(&manager, id, amount) == -1) {
            printf("Transaction limit reached\n");
            break;
        }
    }

    double total_amount = 0.0;
    for (size_t i = 0; i < manager.capacity; ++i) {
        if (manager.table[i].id != UINT64_MAX) {
            total_amount += get_transaction_amount(&manager, manager.table[i].id);
        }
    }

    printf("Total amount: %.2f\n", total_amount);

    destroy_transaction_manager(&manager);
    return 0;
}
