#define MAX_RECORDS 100
#define MAX_ELEMENTS 100
#define MAX_VALUE 50

typedef struct {
    int id;
    int offset;
    long* values;
} record;

record* create_records(int num_records, int seed) {
    if (num_records > MAX_RECORDS) {
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < num_records; ++i) {
        records[i].id = rand();
        records[i].offset = rand() % (MAX_ELEMENTS + 1);
        records[i].values = malloc(records[i].offset * sizeof(long));
        if (!records[i].values) {
            for (int j = 0; j < i; ++j) {
                free(records[j].values);
            }
            free(records);
            return NULL;
        }

        long sum = 0;
        for (int j = 0; j < records[i].offset - 1; ++j) {
            records[i].values[j] = rand() % (MAX_VALUE + 1);
            sum += records[i].values[j];
        }
        records[i].values[records[i].offset - 1] = rand() % (MAX_VALUE + 1);
        while (sum > MAX_VALUE) {
            records[i].values[records[i].offset - 2] -= (sum - MAX_VALUE);
            sum = MAX_VALUE;
        }
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].values);
    }
    free(records);
}
