#define MAX_RECORDS 1000
#define MAX_LONGS 100

typedef struct {
    int intValue;
    long *longArray;
    size_t arraySize;
} record;

double generateRandomDouble(double min, double max) {
    return min + (rand() / (RAND_MAX / (max - min)));
}

int generateRandomInt(int min, int max) {
    return min + rand() % (max - min + 1);
}

record *allocateRecords(size_t numRecords, size_t *totalLongs) {
    record *records = malloc(numRecords * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    *totalLongs = 0;
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].intValue = generateRandomInt(1, 100);
        records[i].arraySize = generateRandomInt(1, MAX_LONGS);
        while (records[i].intValue > 1000) {
            records[i].arraySize--;
        }
        *totalLongs += records[i].arraySize;
        records[i].longArray = malloc(records[i].arraySize * sizeof(long));
        if (!records[i].longArray) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
    return records;
}

void freeRecords(record *records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i].longArray);
    }
    free(records);
}

double calculateAverageLongs(record *records, size_t numRecords, size_t totalLongs) {
    double sum = 0;
    for (size_t i = 0; i < numRecords; ++i) {
        for (size_t j = 0; j < records[i].arraySize; ++j) {
            sum += records[i].longArray[j];
        }
    }
    return sum / totalLongs;
}

int main() {
    srand(time(NULL));

    size_t numRecords = generateRandomInt(1, MAX_RECORDS);
    record *records = allocateRecords(numRecords, NULL);

    for (size_t i = 0; i < numRecords; ++i) {
        for (size_t j = 0; j < records[i].arraySize; ++j) {
            records[i].longArray[j] = generateRandomInt(1, 50);
        }
    }

    double averageLongs = calculateAverageLongs(records, numRecords, numRecords * MAX_LONGS);
    printf("Average value of long elements: %f\n", averageLongs);

    freeRecords(records, numRecords);

    return 0;
}
