#include <time.h>

#define MAX_RECORDS 1000
#define MAX_LONGS 100
#define MAX_VALUE 50
#define TOTAL_SUM 1000

typedef struct {
    int id;
    long* values;
} record;

int prng(int seed) {
    return (seed * 214013 + 2531011) % RAND_MAX;
}

record* create_records(int num_records, int* total_size, int seed) {
    if (num_records <= 0 || num_records > MAX_RECORDS) {
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    srand(seed);
    int current_sum = 0;
    for (int i = 0; i < num_records; ++i) {
        records[i].id = i + 1;
        int offset = prng(i) % MAX_LONGS + 1;
        records[i].values = (long*)malloc(offset * sizeof(long));
        if (!records[i].values) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j].values);
            }
            free(records);
            return NULL;
        }

        current_sum = 0;
        for (int j = 0; j < offset; ++j) {
            long value = prng(j) % MAX_VALUE + 1;
            records[i].values[j] = value;
            current_sum += value;
            if (current_sum > TOTAL_SUM) {
                records[i].values[j] -= current_sum - TOTAL_SUM;
                break;
            }
        }

        *total_size += offset;
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].values);
    }
    free(records);
}
