#define INITIAL_CAPACITY 1024

typedef struct {
    unsigned char hash;
    long offset;
} encryption_record;

encryption_record* allocate_encryption_records(int capacity) {
    encryption_record* records = (encryption_record*)malloc(capacity * sizeof(encryption_record));
    if (!records) {
        perror("Failed to allocate memory for encryption records");
        return NULL;
    }
    return records;
}

unsigned char generate_pseudo_random_byte() {
    static unsigned int seed = 0;
    if (seed == 0) seed = time(NULL); // Seed once
    seed = seed * 1664525 + 1013904223; // Minimalistic PRNG
    return (unsigned char)(seed >> 24);
}

int validate_records(encryption_record* records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i].hash > 255 || records[i].offset <= 0) {
            fprintf(stderr, "Validation error at index %d: hash=%d, offset=%ld\n", i, records[i].hash, records[i].offset);
            return 0;
        }
    }
    return 1;
}

encryption_record* resize_encryption_records(encryption_record* old_records, int old_capacity, int new_capacity) {
    encryption_record* new_records = allocate_encryption_records(new_capacity);
    if (!new_records) {
        fprintf(stderr, "Failed to reallocate memory for encryption records\n");
        return old_records;
    }
    int min_count = (old_capacity < new_capacity) ? old_capacity : new_capacity;
    for (int i = 0; i < min_count; i++) {
        new_records[i] = old_records[i];
    }
    free(old_records);
    return new_records;
}

void initialize_encryption_records(encryption_record* records, int count) {
    srand(time(NULL)); // Seed for rand()
    for (int i = 0; i < count; i++) {
        records[i].hash = generate_pseudo_random_byte();
        records[i].offset = ((long)i + 1) * 8; // Example offset logic
    }
}

void log_event(const char* message, ...) {
    va_list args;
    va_start(args, message);
    vprintf(message, args);
    va_end(args);
    printf("\n");
}

int main() {
    int capacity = INITIAL_CAPACITY;
    encryption_record* records = allocate_encryption_records(capacity);
    if (!records) return 1;

    initialize_encryption_records(records, capacity);

    if (validate_records(records, capacity)) {
        log_event("Encryption records initialized successfully");
    }

    // Simulate dynamic resizing
    capacity *= 2;
    records = resize_encryption_records(records, capacity / 2, capacity);
    if (!records) return 1;

    initialize_encryption_records(records + capacity / 2, capacity / 2);

    if (validate_records(records, capacity)) {
        log_event("Encryption records resized successfully");
    }

    free(records);
    return 0;
}
