typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct DataStructure {
    Record* records;
    size_t capacity;
    size_t size;
} DataStructure;

void init_data_structure(DataStructure* ds, size_t initial_capacity) {
    ds->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!ds->records) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    ds->capacity = initial_capacity;
    ds->size = 0;
}

void resize_data_structure(DataStructure* ds, size_t new_capacity) {
    Record* new_records = (Record*)realloc(ds->records, new_capacity * sizeof(Record));
    if (!new_records) {
        // Handle memory allocation failure
        free(ds->records);
        exit(EXIT_FAILURE);
    }
    ds->records = new_records;
    ds->capacity = new_capacity;
}

void insert_record(DataStructure* ds, int key, long offset) {
    if (ds->size >= ds->capacity) {
        resize_data_structure(ds, ds->capacity * 2);
    }
    ds->records[ds->size].key = key;
    ds->records[ds->size].offset = offset;
    ds->size++;
}

void retrieve_record(DataStructure* ds, int key, long* offset) {
    for (size_t i = 0; i < ds->size; i++) {
        if (ds->records[i].key == key) {
            *offset = ds->records[i].offset;
            return;
        }
    }
    // Handle record not found
}

void delete_record(DataStructure* ds, int key) {
    for (size_t i = 0; i < ds->size; i++) {
        if (ds->records[i].key == key) {
            for (size_t j = i + 1; j < ds->size; j++) {
                ds->records[j - 1] = ds->records[j];
            }
            ds->size--;
            return;
        }
    }
    // Handle record not found
}

void free_data_structure(DataStructure* ds) {
    free(ds->records);
    ds->records = NULL;
    ds->capacity = 0;
    ds->size = 0;
}

int main() {
    DataStructure ds;
    init_data_structure(&ds, 10);

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < 20; i++) {
        int key = rand();
        long offset = rand();
        insert_record(&ds, key, offset);
    }

    long retrieved_offset;
    retrieve_record(&ds, ds.records[5].key, &retrieved_offset);

    delete_record(&ds, ds.records[10].key);

    free_data_structure(&ds);
    return 0;
}
