typedef struct {
    unsigned char hash;
    long offset;
} encryption_record;

unsigned char prng(unsigned int *seed, unsigned char range) {
    *seed = (*seed * 1664525 + 1013904223) % UINT_MAX;
    return (*seed >> (8 - range)) & 0xFF;
}

int initialize_arrays(long offset_range, int key_range, unsigned char byte_range, encryption_record **encryption_records, long **long_offsets, int **int_keys, unsigned char **unsigned_chars, unsigned int *prng_seed) {
    if (offset_range <= 0 || key_range <= 0 || byte_range <= 0) {
        return -1; // Invalid range
    }

    *long_offsets = malloc(offset_range * sizeof(long));
    *int_keys = malloc(key_range * sizeof(int));
    *unsigned_chars = malloc(byte_range * sizeof(unsigned char));
    *encryption_records = malloc(byte_range * sizeof(encryption_record));

    if (*long_offsets == NULL || *int_keys == NULL || *unsigned_chars == NULL || *encryption_records == NULL) {
        return -2; // Memory allocation failed
    }

    for (size_t i = 0; i < byte_range; i++) {
        long random_offset = rand() % offset_range;
        int random_key = rand() % key_range;
        unsigned char random_hash = prng(prng_seed, byte_range);
        (*encryption_records)[i].hash = random_hash;
        (*encryption_records)[i].offset = random_offset;
        (*long_offsets)[i] = random_offset;
        (*int_keys)[i] = random_key;
        (*unsigned_chars)[i] = random_hash;
    }

    return 0; // Success
}

void free_arrays(long *long_offsets, int *int_keys, unsigned char *unsigned_chars, encryption_record *encryption_records) {
    if (long_offsets != NULL) {
        free(long_offsets);
    }
    if (int_keys != NULL) {
        free(int_keys);
    }
    if (unsigned_chars != NULL) {
        free(unsigned_chars);
    }
    if (encryption_records != NULL) {
        free(encryption_records);
    }
}

int main() {
    unsigned int prng_seed = time(NULL); // Seed for PRNG
    long *long_offsets;
    int *int_keys;
    unsigned char *unsigned_chars;
    encryption_record *encryption_records;

    int result = initialize_arrays(100, 50, 256, &encryption_records, &long_offsets, &int_keys, &unsigned_chars, &prng_seed);

    if (result == 0) {
        printf("Arrays initialized successfully.\n");
        // Use the arrays here
        free_arrays(long_offsets, int_keys, unsigned_chars, encryption_records);
    } else if (result == -1) {
        printf("Invalid range provided.\n");
    } else if (result == -2) {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
