#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

#define MAX_INDICES 4096
#define MIN_AMOUNT 50
#define MAX_AMOUNT 5000

typedef struct {
    unsigned int amount;
} transaction;

unsigned long* seed_values;
int* indices;
transaction* transactions;
pthread_mutex_t index_lock;
int used_indices[MAX_INDICES];

void initialize_arrays() {
    srand(time(NULL));
    for (int i = 0; i < MAX_INDICES; ++i) {
        indices[i] = i;
        used_indices[i] = 0;
    }
}

unsigned long generate_unique_seed() {
    while (1) {
        unsigned long seed = rand();
        if (!used_indices[seed % MAX_INDICES]) {
            used_indices[seed % MAX_INDICES] = 1;
            return seed;
        }
    }
}

transaction* initialize_transactions(int num_transactions) {
    transaction* trans = malloc(num_transactions * sizeof(transaction));
    if (trans == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int amounts[MAX_AMOUNT - MIN_AMOUNT + 1];
    for (int i = 0; i < MAX_AMOUNT - MIN_AMOUNT + 1; ++i) {
        amounts[i] = MIN_AMOUNT + i;
    }

    for (int i = 0; i < num_transactions; ++i) {
        int random_index = rand() % (MAX_AMOUNT - MIN_AMOUNT + 1);
        trans[i].amount = amounts[random_index];
        amounts[random_index] = amounts[MAX_AMOUNT - MIN_AMOUNT - i]; // Swap to remove duplicates
    }

    return trans;
}

void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = 0; i < MAX_INDICES / pthread_num_threads(); ++i) {
        pthread_mutex_lock(&index_lock);
        unsigned long seed = generate_unique_seed();
        pthread_mutex_unlock(&index_lock);

        // Process the seed
        printf("Thread %d processed seed: %lu\n", thread_id, seed);
    }
    return NULL;
}

void cleanup() {
    free(seed_values);
    free(indices);
    free(transactions);
    for (int i = 0; i < MAX_INDICES; ++i) {
        if (used_indices[i]) {
            fprintf(stderr, "Memory leak detected at index %d\n", i);
        }
    }
}

int main() {
    int num_threads = 4;
    int num_transactions = 10;

    seed_values = malloc(num_threads * sizeof(unsigned long));
    indices = malloc(MAX_INDICES * sizeof(int));
    transactions = initialize_transactions(num_transactions);

    if (seed_values == NULL || indices == NULL || transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    pthread_mutex_init(&index_lock, NULL);

    for (int i = 0; i < num_threads; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup();
    pthread_mutex_destroy(&index_lock);

    return 0;
}
