#define MAX_KEYS 1024
#define RECORD_COUNT 1000

typedef struct {
    int value;
} Record;

unsigned long xorshift32(unsigned long *state) {
    unsigned long x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

void generate_keys(unsigned long *keys, int count, pthread_mutex_t *mutex) {
    static unsigned long state = time(NULL);
    pthread_mutex_lock(mutex);
    for (int i = 0; i < count; ++i) {
        keys[i] = xorshift32(&state) % MAX_KEYS;
    }
    pthread_mutex_unlock(mutex);
}

Record* generate_records(int count, pthread_mutex_t *mutex) {
    Record *records = malloc(count * sizeof(Record));
    if (!records) return NULL;

    int used_values[1001] = {0};
    pthread_mutex_lock(mutex);

    for (int i = 0; i < count; ++i) {
        unsigned long value;
        do {
            value = xorshift32(&state) % 1001 + 1;
        } while (used_values[value]);
        used_values[value] = 1;
        records[i].value = value;
    }

    pthread_mutex_unlock(mutex);
    return records;
}

void clean_up(Record *records, unsigned long *keys, int count) {
    free(records);
    free(keys);
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Record *records = generate_records(RECORD_COUNT, &mutex);
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    unsigned long *keys = malloc(MAX_KEYS * sizeof(unsigned long));
    if (!keys) {
        clean_up(records, keys, RECORD_COUNT);
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    generate_keys(keys, MAX_KEYS, &mutex);

    // Use records and keys

    clean_up(records, keys, RECORD_COUNT);
    pthread_mutex_destroy(&mutex);
    return EXIT_SUCCESS;
}
