    int used_keys[MAX_KEYS];
} SystemState;

SystemState* initialize_system(size_t num_records) {
    SystemState* state = (SystemState*)malloc(sizeof(SystemState));
    if (!state) return NULL;

    state->offsets = (long*)calloc(num_records, sizeof(long));
    state->keys = (int*)calloc(num_records, sizeof(int));
    state->records = (Record*)calloc(num_records, sizeof(Record));
    if (!state->offsets || !state->keys || !state->records) {
        free(state->offsets);
        free(state->keys);
        free(state->records);
        free(state);
        return NULL;
    }

    state->num_records = num_records;
    pthread_mutex_init(&state->key_pool_lock, NULL);

    for (int i = 0; i < MAX_KEYS; ++i) {
        state->used_keys[i] = 0;
    }

    // Initialize records with unique values
    for (size_t i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % MAX_KEYS;
        } while (state->used_keys[key]);
        state->keys[i] = key;
        state->records[i].value = rand() % 1000 + 1;
        state->used_keys[key] = 1;
    }

    return state;
}

void cleanup_system(SystemState* state) {
    if (state) {
        free(state->offsets);
        free(state->keys);
        free(state->records);
        pthread_mutex_destroy(&state->key_pool_lock);
        free(state);
    }
}

