import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class SessionTokenManager {
    private static final SecureRandom secureRandom = new SecureRandom();
    private ConcurrentHashMap<String, Token> tokenMap = new ConcurrentHashMap<>();
    private ScheduledExecutorService scheduler;

    public SessionTokenManager() {
        scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(this::renewExpiredTokens, 60, 60, TimeUnit.SECONDS);
    }

    public String generateSessionToken(String userId) {
        byte[] tokenBytes = new byte[32];
        secureRandom.nextBytes(tokenBytes);
        String token = bytesToHex(tokenBytes);
        long expirationTime = System.currentTimeMillis() + (15 * 60 * 1000); // 15 minutes
        tokenMap.put(token, new Token(userId, expirationTime));
        return token;
    }

    public boolean validateSessionToken(String token) {
        if (!tokenMap.containsKey(token)) {
            return false;
        }
        Token sessionToken = tokenMap.get(token);
        long currentTime = System.currentTimeMillis();
        if (currentTime > sessionToken.expirationTime) {
            tokenMap.remove(token); // Invalidate expired tokens
            return false;
        }
        return true;
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }

    private void renewExpiredTokens() {
        long currentTime = System.currentTimeMillis();
        tokenMap.entrySet().removeIf(entry -> entry.getValue().expirationTime < currentTime);
    }

    public void shutdown() {
        scheduler.shutdownNow();
    }

    private static class Token {
        String userId;
        long expirationTime;

        Token(String userId, long expirationTime) {
            this.userId = userId;
            this.expirationTime = expirationTime;
        }
    }
}
