#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset() {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (dataset == NULL) return NULL;
    dataset->head = NULL;
    pthread_mutex_init(&dataset->lock, NULL);
    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    Node* current = dataset->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int insert_record(Dataset* dataset, int key, long offset) {
    pthread_mutex_lock(&dataset->lock);
    Node* current = dataset->head;
    while (current != NULL) {
        if (current->record.key == key) {
            pthread_mutex_unlock(&dataset->lock);
            return -1; // Duplicate key
        }
        current = current->next;
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&dataset->lock);
        return -2; // Memory allocation failed
    }
    new_node->record.key = key;
    new_node->record.offset = offset;
    new_node->next = dataset->head;
    dataset->head = new_node;
    pthread_mutex_unlock(&dataset->lock);
    return 0;
}
