#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define the record structure
typedef struct {
    long timestamp;
    double measurement;
} Record;

// Define the event structure
typedef struct Event {
    int type;
    char* message;
    Record data;
    struct Event* next;
} Event;

// Function to allocate and initialize memory for arrays and structures
void initializeMemory(long** offsets, int** keys, Record** records) {
    // Allocate memory for arrays and structures here
    *offsets = (long*)malloc(100 * sizeof(long));
    *keys = (int*)malloc(100 * sizeof(int));
    *records = (Record*)malloc(100 * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays and structures here
}

// Function to create a new event node
Event* createEvent(int type, const char* message, Record data) {
    Event* newNode = (Event*)malloc(sizeof(Event));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    newNode->type = type;
    newNode->message = strdup(message); // Duplicate the string
    newNode->data = data;
    newNode->next = NULL;

    return newNode;
}

// Function to add an event to the queue (thread-safe)
void enqueue(Event** head, Event* newEvent) {
    if (*head == NULL) {
        *head = newEvent;
    } else {
        Event* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newEvent;
    }
}

// Function to serialize the queue to disk
void serializeQueue(Event* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    Event* temp = head;
    while (temp != NULL) {
        fwrite(&temp->type, sizeof(int), 1, file);
        fwrite(temp->message, strlen(temp->message) + 1, 1, file);
        fwrite(&temp->data.timestamp, sizeof(long), 1, file);
        fwrite(&temp->data.measurement, sizeof(double), 1, file);

        temp = temp->next;
    }

    fclose(file);
}

// Function to deserialize the queue from disk
Event* deserializeQueue(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading.\n");
        return NULL;
    }

    Event* head = NULL;

    while (!feof(file)) {
        int type;
        fread(&type, sizeof(int), 1, file);

        char* message = (char*)malloc(256); // Assuming message length
        fread(message, strlen(message) + 1, 1, file);

        long timestamp;
        double measurement;
        fread(&timestamp, sizeof(long), 1, file);
        fread(&measurement, sizeof(double), 1, file);

        Record data = {timestamp, measurement};
        Event* newEvent = createEvent(type, message, data);
        enqueue(&head, newEvent);

        free(message); // Free the allocated memory for the message
    }

    fclose(file);
    return head;
}

// Function to clean up and free all allocated memory
void cleanup(Event** head) {
    while (*head != NULL) {
        Event* temp = *head;
        *head = (*head)->next;
        free(temp->message); // Free the message string
        free(temp);
    }
}
