        if (!is_key_exists(key)) {
            dataset[dataset_size++] = (Record){key, offset};
        }
        pthread_rwlock_unlock(&rwlock);
    }
    return NULL;
}

int is_key_exists(int key) {
    for (int i = 0; i < dataset_size; i++) {
        if (dataset[i].key == key) {
            return 1;
        }
    }
    return 0;
}

void* update_dataset(void* arg) {
    int new_key = rand() % MAX_DATASET_SIZE;
    long new_offset = rand();
    pthread_rwlock_wrlock(&rwlock);
    if (!is_key_exists(new_key)) {
        dataset[dataset_size++] = (Record){new_key, new_offset};
    }
    pthread_rwlock_unlock(&rwlock);
    return NULL;
}

