import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ThreadLocalRandom;

public class DataHandler {

    private static final int MAX_KEYS = 1024;
    private static final ConcurrentHashMap<Integer, Boolean> usedKeys = new ConcurrentHashMap<>();

    public static void main(String[] args) throws IOException {
        // Establish connection
        SocketChannel channel = SocketChannel.open(new InetSocketAddress("remote_address", 8080));

        // Initialize arrays and records
        long[] offsets = new long[1000];
        int[] keys = generateUniqueKeys(1000);
        double[] timestamps = new double[1000];
        Record[] records = new Record[1000];

        for (int i = 0; i < 1000; i++) {
            offsets[i] = i * 8L;
            timestamps[i] = System.currentTimeMillis() + i;
            records[i] = new Record(ThreadLocalRandom.current().nextInt(1, 10000), timestamps[i], "Event_" + i);
        }

        // Read input and find largest integer
        int[] inputArray = readInput();
        int largestNumber = findLargest(inputArray);
        System.out.println("Largest number: " + largestNumber);

        // Close connection
        channel.close();
    }

    private static int[] generateUniqueKeys(int count) {
        List<Integer> keyList = new ArrayList<>();
        while (keyList.size() < count) {
            int key = ThreadLocalRandom.current().nextInt(MAX_KEYS);
            if (usedKeys.putIfAbsent(key, true) == null) {
                keyList.add(key);
            }
        }
        return keyList.stream().mapToInt(Integer::intValue).toArray();
    }

    private static int[] readInput() {
        List<Integer> inputList = new ArrayList<>();
        try {
            while (true) {
                String line = System.in.readLine();
                if (line == null || line.trim().isEmpty()) break;
                try {
                    int num = Integer.parseInt(line.trim());
                    inputList.add(num);
                } catch (NumberFormatException e) {
                    // Handle invalid integers
                }
            }
        } catch (IOException e) {
            // Handle IO errors
        }
        return inputList.stream().mapToInt(Integer::intValue).toArray();
    }

    private static int findLargest(int[] array) {
        if (array.length == 0) return Integer.MIN_VALUE;
        return java.util.Arrays.stream(array).max().getAsInt();
    }

    static class Record {
        int eventId;
        double timestamp;
        String description;

        public Record(int eventId, double timestamp, String description) {
            this.eventId = eventId;
            this.timestamp = timestamp;
            this.description = description;
        }
    }
}
