#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENT_IDS 1024

typedef struct {
    unsigned long timestamp;
    unsigned int id;
} Event;

Event eventPool[MAX_EVENT_IDS];
unsigned int usedIDs[MAX_EVENT_IDS] = {0};
int nextID = 0;
pthread_mutex_t idMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t idCond = PTHREAD_COND_INITIALIZER;

// Initialize the system
void initSystem() {
    srand(time(NULL));
}

// Generate a unique event ID
unsigned int generateUniqueID() {
    unsigned int id;
    pthread_mutex_lock(&idMutex);
    do {
        id = rand() % MAX_EVENT_IDS + 1;
    } while (usedIDs[id]);
    usedIDs[id] = 1;
    nextID++;
    if (nextID >= MAX_EVENT_IDS) {
        nextID = 0;
    }
    pthread_mutex_unlock(&idMutex);
    return id;
}

// Allocate memory for an event
Event* allocateEvent() {
    Event *event = malloc(sizeof(Event));
    if (event == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    event->timestamp = time(NULL);
    event->id = generateUniqueID();
    return event;
}

// Free memory for an event
void freeEvent(Event *event) {
    free(event);
}

// Process events concurrently
void* processEvents(void *arg) {
    Event *events[MAX_EVENT_IDS];
    int count = 0;

    while (count < MAX_EVENT_IDS) {
        pthread_mutex_lock(&idMutex);
        if (usedIDs[nextID]) {
            pthread_cond_wait(&idCond, &idMutex);
        }
        usedIDs[nextID] = 1;
        pthread_mutex_unlock(&idMutex);

        events[count] = allocateEvent();
        count++;
    }

    for (int i = 0; i < count; i++) {
        freeEvent(events[i]);
    }

    return NULL;
}

// Main function
int main() {
    initSystem();

    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, processEvents, NULL);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
