#define MAX_KEYS 1024

typedef struct {
    double value;
} Data;

long* long_array;
int* int_array;
double* double_array;
Data* data_array;

pthread_mutex_t key_mutex;

void initialize_arrays() {
    long_array = (long*)malloc(sizeof(long) * MAX_KEYS);
    int_array = (int*)malloc(sizeof(int) * MAX_KEYS);
    double_array = (double*)malloc(sizeof(double) * MAX_KEYS);
    data_array = (Data*)malloc(sizeof(Data) * MAX_KEYS);

    pthread_mutex_init(&key_mutex, NULL);
}

void* generate_random_number(void* arg) {
    int index = *(int*)arg;
    srand(time(NULL) + pthread_self()); // Seed PRNG with time and thread ID
    double random_value = (double)rand() / RAND_MAX;
    data_array[index].value = random_value;
    free(arg);
    return NULL;
}

void generate_random_numbers(int num_threads) {
    pthread_t threads[num_threads];
    int* indices = (int*)malloc(sizeof(int) * num_threads);

    for (int i = 0; i < num_threads; ++i) {
        indices[i] = i;
        pthread_create(&threads[i], NULL, generate_random_number, &indices[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(indices);
}

double find_smallest(double* array, int size) {
    double smallest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] < smallest) {
            smallest = array[i];
        }
    }
    return smallest;
}

void clean_up() {
    free(long_array);
    free(int_array);
    free(double_array);
    free(data_array);
    pthread_mutex_destroy(&key_mutex);
}

int main() {
    initialize_arrays();
    generate_random_numbers(10); // Example with 10 threads

    double* input_array = (double*)malloc(sizeof(double) * 5);
    input_array[0] = 3.14;
    input_array[1] = 2.71;
    input_array[2] = -1.0;
    input_array[3] = 0.5;
    input_array[4] = 42.0;

    double smallest_number = find_smallest(input_array, 5);
    printf("Smallest number: %f\n", smallest_number);

    clean_up();
    free(input_array);

    return 0;
}
