#define MAX_METADATA_LENGTH 10

typedef struct {
    uint32_t id;
    char metadata[MAX_METADATA_LENGTH];
} Record;

void customPRNG(uint32_t *seed, uint32_t *out) {
    // Implement a fast but robust PRNG
    // Example: XORShift generator
    *seed ^= *seed << 13;
    *seed ^= *seed >> 7;
    *seed ^= *seed << 17;
    *out = *seed;
}

int initRecords(Record **records, size_t count, uint32_t seed, const char *configPath) {
    if (count == 0 || records == NULL) return -1;

    json_object *root = json_read_file(configPath);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON config\n");
        return -1;
    }

    json_object *rangeObj;
    if (json_object_object_get_ex(root, "range", &rangeObj) && json_object_get_type(rangeObj) == json_type_int) {
        int range = json_object_get_int(rangeObj);
        if (range <= 0) {
            fprintf(stderr, "Invalid range value in config\n");
            json_object_put(root);
            return -1;
        }

        *records = (Record *)malloc(count * sizeof(Record));
        if (*records == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            json_object_put(root);
            return -1;
        }

        for (size_t i = 0; i < count; ++i) {
            customPRNG(&seed, &(*records)[i].id);
            (*records)[i].id %= range;

            // Initialize metadata with a simple pattern
            snprintf((*records)[i].metadata, MAX_METADATA_LENGTH, "Data%d", i % 10);
        }

        // Shuffle records in place
        for (size_t i = count - 1; i > 0; --i) {
            size_t j = customPRNG(&seed, &(*records)[i].id) % (i + 1);
            Record temp = (*records)[i];
            (*records)[i] = (*records)[j];
            (*records)[j] = temp;
        }

        json_object_put(root);
        return 0;
    } else {
        fprintf(stderr, "Range not specified in config\n");
        json_object_put(root);
        return -1;
    }
}

void freeRecords(Record *records) {
    if (records != NULL) {
        free(records);
    }
}
