#include <string.h>
#include <time.h>
#include <errno.h>

typedef struct {
    int key;
    long offset;
} Record;

Record* create_records(int num_records, long min_offset, long max_offset) {
    if (num_records <= 0 || min_offset > max_offset) {
        return NULL;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Seed with current time for better randomness
    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % num_records + 1; // Unique key from 1 to num_records
        records[i].offset = min_offset + (rand() / ((double)RAND_MAX / (max_offset - min_offset)));
    }

    return records;
}

int validate_records(const Record *records, int num_records, long min_valid_offset, long max_valid_offset) {
    if (!records || num_records <= 0 || min_valid_offset > max_valid_offset) {
        return -1;
    }

    for (int i = 0; i < num_records - 1; ++i) {
        for (int j = i + 1; j < num_records; ++j) {
            if (records[i].key == records[j].key || records[i].offset < min_valid_offset || records[i].offset > max_valid_offset) {
                return -1;
            }
        }
    }

    return 0;
}

void free_records(Record *records, int num_records) {
    if (records) {
        free(records);
    }
}
