#define MAX_TRANSACTIONS 1000000

typedef struct {
    long id;
    int timestamp;
    char identifier[11];
} Transaction;

// Pseudo-random number generator for transaction IDs
long prng() {
    static unsigned long seed = time(NULL);
    return (seed = seed * 214013L + 2531011L) >> 16;
}

// Initialize transactions with unique IDs and sequential timestamps
void init_transactions(Transaction *transactions, int count) {
    for (int i = 0; i < count; ++i) {
        transactions[i].id = prng();
        transactions[i].timestamp = clock() / CLOCKS_PER_SEC * 1000 + i;
        snprintf(transactions[i].identifier, sizeof(transactions[i].identifier), "TX%06d", i);
    }
}

// Shuffle transactions randomly
void shuffle_transactions(Transaction *transactions, int count) {
    for (int i = count - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        Transaction temp = transactions[i];
        transactions[i] = transactions[j];
        transactions[j] = temp;
    }
}

// Example usage
int main() {
    Transaction transactions[MAX_TRANSACTIONS];
    init_transactions(transactions, MAX_TRANSACTIONS);
    shuffle_transactions(transactions, MAX_TRANSACTIONS);

    for (int i = 0; i < 10; ++i) { // Print first 10 transactions for demonstration
        printf("ID: %ld, Timestamp: %d, Identifier: %s\n",
               transactions[i].id, transactions[i].timestamp, transactions[i].identifier);
    }

    return 0;
}
