// Define the structure for records
typedef struct {
    int value;
} Record;

// Function to check if a number is prime
bool is_prime(uint32_t num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;
    for (uint32_t i = 5; i * i <= num; i += 6)
        if (num % i == 0 || num % (i + 2) == 0)
            return false;
    return true;
}

// Function to generate a unique prime number less than 1024
uint32_t get_unique_prime(uint32_t *used_keys, size_t used_count) {
    uint32_t candidate = 2; // Start from the smallest prime number
    while (true) {
        if (!is_prime(candidate)) {
            candidate++;
            continue;
        }
        bool is_used = false;
        for (size_t i = 0; i < used_count; ++i) {
            if (used_keys[i] == candidate) {
                is_used = true;
                break;
            }
        }
        if (!is_used) return candidate;
        candidate++;
    }
}

// Function to generate a random integer between 1 and 1000
int get_random_int() {
    static bool seeded = false;
    if (!seeded) {
        srand(time(NULL)); // Seed the PRNG with system time for simplicity
        seeded = true;
    }
    return rand() % 1000 + 1; // Random number between 1 and 1000
}

