    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for keys array
    *keys = (int *)malloc(count * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets and keys arrays
    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = i * sizeof(Record); // Example offset calculation
        (*keys)[i] = get_unique_prime(used_keys, i);
    }

    // Allocate memory for records array
    *records = (Record *)malloc(count * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records array with random integers
    for (size_t i = 0; i < count; ++i) {
        (*records)[i].value = get_random_int();
    }
}

// Function to clean up allocated memory
void cleanup(uint32_t *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    free(records);
}

