#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_KEYS 1024

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t lock;
    uint8_t used[MAX_KEYS];
    record *records;
    size_t count;
    size_t capacity;
} key_value_store;

key_value_store kv_store = { .lock = PTHREAD_MUTEX_INITIALIZER, .used = {0}, .count = 0 };

void initialize_key_value_store(size_t initial_capacity) {
    kv_store.capacity = initial_capacity;
    kv_store.records = (record *)calloc(initial_capacity, sizeof(record));
}

int add_record(int key, int value) {
    pthread_mutex_lock(&kv_store.lock);
    if (key >= MAX_KEYS || kv_store.used[key] || kv_store.count == kv_store.capacity) {
        pthread_mutex_unlock(&kv_store.lock);
        return -1; // Key out of range or already used
    }
    kv_store.records[kv_store.count].value = value;
    kv_store.used[key] = 1;
    kv_store.count++;
    pthread_mutex_unlock(&kv_store.lock);
    return 0;
}

void *read_input(void *arg) {
    int num, key;
    while (scanf("%d", &num) == 1) {
        if (num > 0 && num <= 1000) {
            for (key = 0; key < MAX_KEYS; key++) {
                if (add_record(key, num) == 0) break;
            }
            if (key == MAX_KEYS) {
                printf("Error: Unable to store record\n");
            }
        }
    }
    return NULL;
}

int find_largest_key_value() {
    int max_value = 0;
    for (size_t i = 0; i < kv_store.count; i++) {
        if (kv_store.records[i].value > max_value) {
            max_value = kv_store.records[i].value;
        }
    }
    return max_value;
}

int main() {
    initialize_key_value_store(1024);
    pthread_t input_thread;
    pthread_create(&input_thread, NULL, read_input, NULL);

    // Simulate processing
    sleep(5);

    int largest_value = find_largest_key_value();
    printf("Largest value: %d\n", largest_value);

    pthread_join(input_thread, NULL);
    free(kv_store.records);
    return 0;
}
