#define MAX_KEYS 1024

typedef struct {
    int value;
} Record;

int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

int generate_random_key() {
    int key;
    do {
        key = rand() % MAX_KEYS;
    } while (!is_prime(key));
    return key;
}

uint64_t get_secure_seed() {
    int fd = open("/dev/urandom", O_RDONLY);
    uint64_t seed;
    read(fd, &seed, sizeof(seed));
    close(fd);
    return seed;
}

void* allocate_and_initialize_memory(void* arg) {
    pthread_mutex_t *lock = (pthread_mutex_t *)arg;
    int *offsets = malloc(MAX_KEYS * sizeof(int));
    int *keys = malloc(MAX_KEYS * sizeof(int));
    Record *records = malloc(MAX_KEYS * sizeof(Record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(lock);

    // Initialize arrays
    for (int i = 0; i < MAX_KEYS; i++) {
        offsets[i] = i * sizeof(int); // Example offset calculation
        keys[i] = generate_random_key();
        records[i].value = rand() % 1001; // Random value between 1 and 1000
    }

    pthread_mutex_unlock(lock);

    // Print results for demonstration purposes
    printf("Offset: %d, Key: %d, Value: %d\n", offsets[0], keys[0], records[0].value);

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_t thread;

    if (pthread_create(&thread, NULL, allocate_and_initialize_memory, &lock) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        exit(EXIT_FAILURE);
    }

    return 0;
}
