#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void* initialize_arrays(int num_records, long offset_range_start, long offset_range_end, int key_range_start, int key_range_end) {
    if (num_records <= 0 || offset_range_end < offset_range_start || key_range_end < key_range_start) {
        return NULL; // Invalid input
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = offset_range_start + rand() % ((long)(offset_range_end - offset_range_start + 1));
        keys[i] = key_range_start + rand() % ((key_range_end - key_range_start + 1));

        records[i].value = keys[i];
    }

    // Function to free allocated memory
    void (*free_memory)() = ^{
        free(offsets);
        free(keys);
        free(records);
    };

    return (void*)free_memory;
}
