#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* create_records(size_t n, long* offsets, int* keys) {
    if (n == 0) return NULL;

    record* records = (record*)aligned_alloc(64, n * sizeof(record));
    if (!records) return NULL;

    offsets = (long*)aligned_alloc(64, n * sizeof(long));
    if (!offsets) {
        free(records);
        return NULL;
    }

    keys = (int*)aligned_alloc(64, n * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        records[i].value = rand();
        offsets[i] = i * 1024; // Example offset calculation
        keys[i] = i % 100;     // Example key generation
    }

    srand(time(NULL)); // Seed the PRNG for better randomness

    return records;
}

void free_records(record* records, long* offsets, int* keys) {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}
